window.RB_SHARDS=window.RB_SHARDS||{};window.RB_SHARDS[8]=[{"i":21003,"n":"טאב, יעקב יהודה מלעניאהנאווע","b":"רב בלעגיאהבנאווע-תרצה."},{"i":21004,"n":"טאבוך, וידאל מאזמיר","dt":"תלא - א תמוז","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":21005,"n":"טאביארז, אברהם אבא מאוסטרוב","bp":"תקצו","dt":"תרנז","b":"נכד ר אברהם אבלי פוסוואלר. אב\"ד אוסטרוב-פלך לומז'ה."},{"i":21006,"n":"טאביר, יצחק","f":"אפרים זלמן","k":"בעל מטל השמים","b":"רב בפוטילה, עלה לירושלים בשנת תרנו. חיבר \"מטל השמים\" לבוב תרנו."},{"i":21007,"n":"טאג'יר, שמואל מסופיה","b":"רב בסופיה-תרלו, גם בתקופת התורכים וגם לאחר שחרור בולגריה."},{"i":21008,"n":"טאג'ר - משפחה","b":"משפחה אשכנזית בסופיה-בולגריה."},{"i":21009,"n":"טאג'ר, אברהם משה מבולגריה","f":"משה שמואל","k":"בעל לה איסטוריה","b":"מעסקי התרבות בבולגריה. פרסם מאמרים בעתוני התקופה. חיבר ספרים בלאדינו."},{"i":21010,"n":"טאג'ר, יונה משה מירושלים","f":"יצחק","k":"המבי\"ט (המבי\"ת)","dt":"תרעא - יז חשון","dp":"ירושלים","b":"מחכמי ירושלים, כיהן כאב\"ד של עדת הספרדים בירושלים בין השנים תרלא - תרעא (ישבו אצלו הדיינים ר בן ציון קואינקה, אברהם ביג'איו, ר חיים אליה הלוי, ור אברהם חיים גאגין). בשנת תרלג בשליחות בטריפולי ובשנת תרנא בשליחות בתורכיה והיה גם בעיר \"מגדלים\"(=דרדנלים). תשובה ממנו נדפסה בספר \"ישמח לב\" לר שלום משה גאגין. חתם על מכתב שהתנגד לר נחמן בטיטו בענין המחלוקת על הרבנות. בנו ר שלמה היה רב בבוכרה בירות וירושלים."},{"i":21011,"n":"טאג'ר, יוסף מסופיה","bt":"תרלו","bp":"סופיה","dt":"תרצו - ל חשון","dp":"תל אביב","b":"עסקן ציוני בבולגריה, השתתף בועידה הציונית בפיליפופולי. פעל כנגד תכנית הלימודים של כי\"ח. עלה לארץ והתישב בתל אביב."},{"i":21012,"n":"טאג'ר, יעקב מסופיה","f":"יוסף","bt":"תרמד","bp":"סופיה","b":"פעיל ציוני בבולגריה, עלה לארץ-תרפב והתישב בתל אביב, ממיסדי המושב \"בית חנן\" שהוקם ע\"י יהודים מבולגריה."},{"i":21013,"n":"טאג'ר, יצחק מירושלים","f":"שלמה","dt":"תרה - ה שבט","dp":"ירושלים","b":"גבאי ביהכ\"נ ונזכר בלוח זכרון בבהכ\"נ איסטמבולים-תקצו. בנו - ר משה בן יצחק-ראב\"ד בירושלים."},{"i":21014,"n":"טאג'ר, משה מסופיה","f":"שמואל","k":"בעל ההגדה על התלמוד","bt":"תקצב","bp":"סופיה","dt":"תרעג - יג אד\"ב","dp":"קיוסטנדיל","b":"מחכמי סופיה, ורב זמני לפני בוא הרב ד\"ר גרינוולד, ולפני בוא הרב ד\"ר מרדכי עהרנפרייז. מקורב לשלטון התורכי, הקים בית מלאכה לאריגה עבור יתומות."},{"i":21015,"n":"טאג'ר, ציונה מיפו","b":"למדה ב\"בצלאל\"-תרפד בירושלים, ובפאריס. ציירת ביפו."},{"i":21016,"n":"טאג'ר, שלמה מירושלים","f":"יונה משה","bt":"תרכו או תרכד","bp":"ירושלים","dt":"תרצו - ט חשון","dp":"ירושלים","b":"מחכמי ירושלים, רב בטשקנד(=טשקנט)-בוכרה-תרעג, קוקנד, רב בבגדד-תרעב, ביירות-תרפא, דמשק-תרפג עד תרפט. בקי בשפות ובמדעים, פגש את הצאר הרוסי והשר סטוליפין-תרע - והצליח לשכנעם לבטל את גזירת הגירוש על יהודי טשקנט ובוכרה. מתורתו ב\"המאסף\", ו\"שאל האיש\"."},{"i":21017,"n":"טאוב ישראל בן שמואל אליהו","bt":"1849","dt":"ה'תרפ 1920","bk":[["דברי ישראל",""]]},{"i":21018,"n":"טאוויל, אהרן","k":"בעל מאסף לכל","b":"מחכמי ראשיד(מצרים), חיבר \"מאסף לכל המחנות\"-תס\"ה"},{"i":21019,"n":"טאווס, יעקב מפרס","f":"יוסף","k":"בעל תרגום התנ\"ך","b":"רב בבגדד-רצה-ש. תרגם את התורה לפרסית. נדפס עם תרגום רב סעדיה גאון, והעתקה ללטינית - בפוניגלוטה של לונדריס (די רוסי)."},{"i":21020,"n":"טאוריל, אברהם מגיברלטר","b":"מחכמי גיברלטר בזמן ר דוד כלפון, חתם על פס\"ד-תץ."},{"i":21021,"n":"טאוריל, יוסף מטיטואן","b":"מחכמי טיטואן-מרוקו-שנות ה-תק'-תר'."},{"i":21022,"n":"טאוריל, יעקב מטיטואן וגיברלטר","b":"מו\"ץ בטיטואן עם ר יצחק הלוי, חתם על פס\"ד-תמט, והיה בגיברלטר-תפו."},{"i":21023,"n":"טאוריל, יעקב ממרוקו","b":"חתם על פס\"ד-תרטז עם ר יצחק ן ואליד, ועוד."},{"i":21024,"n":"טאוריל, יצחק מטיטואן","f":"יוסף","bp":"טיטואן","dp":"פאריס","b":"מחכמי טיטואן - שנות ה-תר'."},{"i":21025,"n":"טאזארטי, א' משלוניקי","b":"מראשי קהלת שלוניקי-תקד, סירב לחתום אז מטעם הקהלה על ההסכם בין יהודי איטליה היושבים בשלוניקי לבין בני קהלת שלוניקי בענין הסדרת המס."},{"i":21026,"n":"טאזארטי, אברהם מספרד","f":"שלמה ן טאוורת","k":"בעל חוקת הדיינים","b":"מחכמי ספרד-ע', תלמיד הרשב\"א, חיבר \"חוקת הדיינים\" ובו שמועות ודינים מרבו הרשב\"א."},{"i":21027,"n":"טאזארטי, יהודה משירון","b":"מראשי קהלת שירון-שנות ה-ת'."},{"i":21028,"n":"טאזארטיס, משה ברוך משלוניקי","k":"המבי\"ט","dt":"תש..","b":"דרשן ומשורר ומורה בשלוניקי, וממיסדי חברת \"חובבי שפת עבר\"-תרס. חתם על שיריו - \"מביט\". נספה בשואה."},{"i":21029,"n":"טאטו, חיים","b":"מרבני איזמיר"},{"i":21030,"n":"טאיטצק, אברהם - הזקן","f":"שלמה","dt":"שב - יב תשרי","dp":"שלוניקי","b":"אחיו של ר יוסף. מחכמי שלוניקי, וחתם על הסכמה-רצג. בניו: ר שלמה, ר יוסף, ר שמואל."},{"i":21031,"n":"טאיטצק, אברהם - הנכד","dt":"שעד - טז אייר","dp":"שלוניקי","b":"מחכמי שלוניקי. נפטר צעיר."},{"i":21032,"n":"טאיטצק, דוד משלוניקי","dt":"תיח - ד אד\"א","dp":"שלוניקי","b":"מחכמי שלוניקי. הוא או זקנו נזכרו כמסייעים בהדפסת \"שארית יהודה\"."},{"i":21033,"n":"טאיטצק, חנניה משלוניקי","dt":"תכו - ח תמוז","dp":"שלוניקי","b":"תלמיד וחתן ר שמואל גאון. רב בשלוניקי. מתלמידיו: ר אברהם בן יעקב בוטון, ר אהרן בן יצחק ששון, ר יעקב בוטון."},{"i":21034,"n":"טאיטצק, יהודה משלוניקי","f":"שלמה בן יעקב משלוניק","k":"בעל שארית יהודה","b":"מחכמי שאלוניקי-של, רב בניקופול, וחזר לשלוניקי. הו\"ל מכתבי אחיו-ר שמואל טאיטצק, ומר יוסף טאיטצק - בשם \"שארית יהודה\"."},{"i":21035,"n":"טאיטצק, יהודה משלוניקי","dt":"תמו","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":21036,"n":"טאיטצק, יוסף מספרד ושלוניקי","f":"שלמה מספרד ושלוניקי","k":"בעל פורת יוסף","bt":"רל-רמח","bp":"ספרד","dt":"שיא - שכה","dp":"קושטא","b":"ממגורשי ספרד ופורטוגל עם משפחתו, אחיו - ר שמואל. תלמיד ר יעקב ן חביב, ר יעקב בירב בליסבון. הגיע לשלוניקי-רנח, ראש ישיבה בשלוניקי - הישיבה החשובה בזמנו, עבר לקושטא בהזמנת הרופא ר משה המון ועמד בראש הישיבה, נדד לכמה מקומות ובהם קושטא-רצא. מתלמידיו: ר משה אלשיך, ר יצחק משה ארויו, ר שמואל די מדינה, ר אליעזר אשכנזי, ר שלמה אלקבץ, ר יצחק אדרבי, האנוס ר שלמה מולכו. תשובות ממנו לרבים מחכמי דודו. חיבר גם פירוש לתנ\"ך. בנו ר שלמה-נפטר בחייו, חתנו - ר אברהם חזן שירש את כתביו שנדפסו בידי קרובו (לא בנו) ר יהודה בשם \"שארית יהודה. נספד ע\"י ר סעדיה לונגו. לפי רוזניס נפטר - בשנת שכה."},{"i":21037,"n":"טאיטצק, יוסף משלוניקי","f":"שמואל - כנראה","dt":"שלט - כא סיון","dp":"שלוניקי","b":"מחכמי שלוניקי, אחיו של ר יעקב ונכד ר שלמה."},{"i":21038,"n":"טאיטצק, יוסף משלוניקי","dt":"שמו - כד אדר","dp":"שלוניקי","b":"מחכמי שלוניקי. אולי נכדו של ר יוסף-רבה של שלוניקי."},{"i":21039,"n":"טאיטצק, יוסף משלוניקי","f":"אברהם - אולי","dt":"שנז - יב כסלו","dp":"שלוניקי","b":"גביר מחכמי שלוניקי. אחיו: ר שמואל, ר שלמה. היה במחלוקת עם יעקב עזרא-חתן אחיו בענין כרמים שתפס."},{"i":21040,"n":"טאיטצק, יעקב מספרד וברוסה","bp":"ספרד","b":"הגיע לפורטוגל-רנב, איטליה-רנז, רב בברוסה(=ברושה)-תורכיה. היה במחלוקת עם ר יצחק בן צדיק ן לב. אחיו של ר שלמה טאיטצק משלוניקי הראשון."},{"i":21041,"n":"טאיטצק, יעקב משלוניקי","f":"שמואל","b":"ר\"מ בק\"ק \"עץ חיים\" בשלוניקי-של על מקום אביו. חתם על הסכמות הקהל. בנו - ר שלמה. חתנו - אחיו - ר שמואל."},{"i":21042,"n":"טאיטצק, משה משלוניקי","b":"מחכמי שלוניקי. תלמיד ר חיים שבתי משלוניקי-המהרח\"ש, ור מרדכי קלעי."},{"i":21043,"n":"טאיטצק, שלמה מספרד ושלוניקי -א","b":"אחרי הגירוש הגיע מספרד לפורטוגל, רב בשלוניקי-רנז ובנו ר יוסף על מקומו אחריו, היה אחד מ-3 הרבנים שהנהיגו את העיר - חבריו: ר אליעזר השמעוני, ור יעקב ן חביב בעל \"עין יעקב\". נשאל מאת ר יעקב פיירו, ור אברהם סבע מאדריאנופול. עוד מבניו: ר שמואל, ר אברהם."},{"i":21044,"n":"טאיטצק, שלמה משלוניקי - הנכד","f":"שמואל","b":"נכד ר שלמה מספרד ושלוניקי. חתן אחיו - ר יעקב. רב בשלוניקי-שמ בערך, ונזכר בשו\"ת מהרשד\"ם. בניו: ר שמואל, ר יהודה בעל \"שארית יהודה\", ר דוד."},{"i":21045,"n":"טאיטצק, שמואל משלוניקי","f":"שלמה בן יעקב משלוניק","k":"בעל שו\"ת","dp":"מגניסיאה","b":"נינו של ר שמואל הזקן משלוניקי. רב ומלמד תורה בשלוניקי-שמ. רב במגניסיאה. חיבר שו\"ת וחדושים על הרמב\"ם. אחיו - ר יהודה הו\"ל מכתביו וכתבי רבני המשפחה - \"שארית יהודה\"."},{"i":21046,"n":"טאיטצק, שמואל משלוניקי","f":"יוסף","dt":"שסה - כ אב","dp":"שלוניקי","b":"נפטר צעיר."},{"i":21047,"n":"טאיטצק, שמואל משלוניקי - הזקן","f":"שלמה","bt":"רנג","dt":"שכב - יב תשרי","dp":"שלוניקי","b":"אחיהם של ר יוסף ור יהודה בעל \"שארית יהודה\" (כנראה בלבול עם נכדו ובאמת אחיו של ר יו\"ט). דיין בשלוניקי ורב בק\"ק \"עץ החיים\" על מקום אביו - יחד עם אחיו, ובנו ר יעקב על מקומו אחריו. חתם על \"הסכמות הקהל\", מתורתו בספר אחיו \"שארית יהודה\". חיבר שו\"ת ופירושים - בכת\"י. חתם על תקנות שונות עם אחיו ועם ר יוסף קארו שעבר בשלוניקי. נספד ע\"י ר סעדיה לונגו. בניו ר יעקב ור יוסף ור שלמה."},{"i":21048,"n":"טאיטצק, שמואל משלוניקי - הנכד","f":"שלמה בן שמואל","b":"חתן דודו ר יעקב טאיטצק."},{"i":21049,"n":"טאייר, יוסף","b":"דיין בפפד\"מ-תנ\"ה"},{"i":21050,"n":"טאייר, יעקב זאב הלוי מירושלים","f":"יוסף","k":"בעל אבני יעקב"},{"i":21051,"n":"טאכוי, יעקב","b":"רב באורמין-תק\"נ"},{"i":21052,"n":"טאכוי, משה יצחק מאיזנשטט","bp":"איזנשטט?","b":"דיין באייזנשטט-תרל, ור\"מ בישיבת ר עזריאל הילדסהימר. חתן ר דוד אלט-אייבניץ מקוברסדורף. תשובות ממנו בתוך \"חידושי ר עזריאל\", ובכתבי הרב מוירצבורג."},{"i":21053,"n":"טאלבי, דניאל משלוניקי","dt":"שעח","b":"מחכמי שלוניקי."},{"i":21054,"n":"טאלווי, מרדכי משלוניקי","b":"גביר בשנות הש'-ת', בנה אמת מים לטובת הקהלה."},{"i":21055,"n":"טאלוק, אהרן מירושלים","b":"עלה מקצמטינא לירושלים. בשליחות. על המשפחה בספרו של ר מ' אייזנבית - יהודי צפון אפריקה."},{"i":21056,"n":"טאלוק, מרדכי מאלגיר או קושטא","dt":"תקט - יח אב","dp":"ירושלים","b":"מחכמי אלגיר (ולפי גאון - גביר בקושטא). עלה לירושלים, והקים ישיבה \"גדולת מרדכי\" בראשות ר יונה נבון ור שם טוב גבאי."},{"i":21057,"n":"טאמשוב, משה בנימין מארה\"ב","k":"בעל מגדל תורה","b":"רב בארה\"ב-תרפה."},{"i":21058,"n":"טאניס, אברהם מאלקסוט","b":"תלמיד ר ישראל סלנטר. מייסד ור\"מ בסלובודקא, רב באלקסוט(=אלעקסאט). בנו - ר שמואל הלל שיינקער(=שנקר) מירושלים."},{"i":21059,"n":"טאניס, משה ליב מברזן","b":"רב בברזן-תריד."},{"i":21060,"n":"טאסק, מרדכי מפרשבורג","bt":"תקד","bp":"איטליה","dt":"תקצז - יב טבת","dp":"פרשבורג","b":"הגיע מטוסקא-איטליה, דיין וראב\"ד בפרשבורג-תקמז כ-50 שנה אצל ר משלם איגרא, ואצל החת\"ס - המזכירו ב\"ספר הזכרון\". חתם עם החת\"ס על תקנות ביה\"ס למלאכה שע\"י הקהלה-תקפא. חתניו - ר משה קנישע-אב\"ד ביינק ופרוינקירכן ובזיוו\"ש ר חיים קיצע בעל \"אוצר החיים\" מאירשא, ר שמואל דייטש בעל עבודת הקרבנות."},{"i":21061,"n":"טאפ","k":"ראה: רוגוזניצקי","b":"רב בנאליבסק"},{"i":21062,"n":"טאפאליע, ירחמיאל משה מסדאוונא","b":"פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר."},{"i":21063,"n":"טאפיה, יצחק מתונס","b":"גיסו של ר דוד בונאן. רב בקהילת פורטוגזים בתונס-תרנב, בזמן ר אליהו חי בורג'ל. היה במחלוקת עם ראשי הקהלה שהצרו את צעדיו."},{"i":21064,"n":"טאפירו, חיים","b":"חכם שלם-תקל\"ט"},{"i":21065,"n":"טאפירו, מאיר מארבאט","b":"רב בארבאט-בשנות ה-ת. חיבר דרשות על התורה בכת\"י."},{"i":21066,"n":"טאפירו, שלמה ממכנאס","f":"יוסף","b":"מחכמי מכנאס-תקי וסופר שטרות, וחתם עם ר יעקב בירדוגו, ר שלמה טולדנו, ר יעקב ן צור-תפז, ועוד. חתם-תקך עם ר מסעוד משאש."},{"i":21067,"n":"טאקסין, מנחם צבי","f":"אריה","k":"בעל עטרת צבי","b":"דרשן. חיבר גם \"אורח ישרים\", ועוד."},{"i":21068,"n":"טאקסין, מנחם צבי","f":"אריה","k":"בעל אורח לצדיק"},{"i":21069,"n":"טאראן, יוסף אהרן מארגנטינה","k":"בעל זכרון יוסף","b":"מו\"צ ושו\"ב במושבה זאנינפלד-ארגנטינה."},{"i":21070,"n":"טאריקה, אברהם ממצרים","dt":"תיב","dp":"מצרים","b":"רב באלכסנדריה, קהיר. מתורתו ב\"גנת ורדים\"."},{"i":21071,"n":"טאריקה, חזקיה שמואל מרודוס","k":"בעל שותא דינוקא","b":"מחכמי רודוס. חיבר גם \"שירה חדשה\" בלאדינו, חדושים על הש\"ס - בכת\"י. חברו של ר ר רפאל יצחק ישראל בעל \"בית היין\" שהדפיס את \"שותא דינוקא\"."},{"i":21072,"n":"טאריקה, ידידיה שמואל מרודוס","f":"יהודה","k":"בעל קידש ידיד","dt":"תקכט","b":"עבר עם אביו מכניאה-כרתים לדרדניל, ולרודוס, אב\"ד ברודוס-תקך. בנו - ר משה מצפת החזיק בחיבורו \"בן ידיד\" וצוה על בנו - ר יוסף - להדפיסו (נדפס בשלוניקי תקסו). חיבר גם \"חלקו של ידיד\", \"שיר ידידות\".","bk":[["בן ידיד [על רמב\"ם]",""]]},{"i":21073,"n":"טאריקה, יהודה מרודוס","bp":"מניאה-כרתים","dt":"תקכו - כו שבט","dp":"חברון","b":"מחכמי כניאה-כרתים, מגדלים(=דרדניל) עבר לרודוס, עלה לארץ-תקכה והתישב בחברון. בנו - ר ידידיה מרודוס."},{"i":21074,"n":"טאריקה, משה מרודוס","f":"שמואל","b":"רב ברודוס-יוון, אצל אביו הרב. עלה לצפת."},{"i":21075,"n":"טאריקה, משה משה","f":"ידידיה שמואל מרודוס","b":"מחכמי צפת, בשנת תקנה חתם עם חכמי צפת. בנו - ר יוסף - הדפיס את ספר זקנו \"בן ידיד\"."},{"i":21076,"n":"טארניפולר, ישכר בער מלבוב","b":"דיין בלבוב, חתם-תפא על פסק דין, ועוד בתור מנהיג מלבוב והגליל."},{"i":21077,"n":"טארסה, חיים שלמה מרודוס","k":"בעל פי שניים","dp":"תקנט","b":"רב ברודוס-תקן בערך בזמן ר אברהם הלוי מרודוס. חיבר גם שו\"ת \"חיים שנים\"."},{"i":21078,"n":"טבול, יוסף ממרוקו צפת ומצרים","k":"יוסף מערבי","dt":"שע - אחרי","b":"מחכמי מרוקו ולדעת רוזניס מחכמי טיבולי-איטליה, עלה לצפת ונמנה על חכמיה, חתם בשנת שפב על פסק דין בכפר בוקיעא (פקיעין) עם ר יוסף מטרני. היה חתנו של ר יום טוב צהלון, היה מבחירי תלמידי הארי ומוזכר בין התלמידים הראשונים. ר יוסף לא קיבל את מרותו של ר חייים ויטאל והורה את קבלת הארי בשיטה אחרת. תלמידו ר שמשון בק וכנראה למד אצלו משנת שלט. חיבר ספרים בקבלה בכתב יד. בסוף ימיו עבר למצרים לגור עם בנו ר יעקב שהיה גביר ושר ונהרג על ידי המושל שם."},{"i":21079,"n":"טבול, יעקב ממצרים","f":"יוסף הקדוש","dt":"שצא","dp":"מצרים","b":"שר-ג'יליבי במצרים-שפ על מקום ר אב\"א סכנדרי ור אברהם אלכולי על מקומו אחריו. נהרג עק\"ה."},{"i":21080,"n":"טבול, פנחס מאלגיר (אביטבול)","k":"בעל ויעמוד פנחס","bt":"תרס","dt":"תשכה","b":"תלמיד ר ישראל בן אהרן אביחצירא מבשאר-מרוקו, ושל ר מסעוד הכהן. רב בעין ספרא-אלגיר, אל באייד(=ג'יריוויל)-אלגיר, אלמעסכר. התכתב עם רבותיו ועם ר יצחק ור מאיר אביחצירא."},{"i":21081,"n":"טבור, יצחק יוסף מהמבורג","dt":"תקיח - ג אייר","dp":"אלטונא","b":"דיין מחכמי הקלויז ישן בהמבורג (שנוסד בהשפעת ר יונתן איבשיץ) יחד עם ר יצחק פרידברג ור ליב פפערישע. היעב\"ץ יצא כנגד פסק דין שלו ושל חברו ר משה פולק גם על תמיכתם בר יונתן איבשיץ במחלוקת הידועה."},{"i":21082,"n":"טביב מתימן","f":"אברהם","dt":"תרצה - יט אד\"ב","b":"עלה לארץ-תרסט והתישב בראשון לציון, פעל לעלית יהודי צפון תימן, שו\"ב ומו\"ץ לעדת תימן."},{"i":21083,"n":"טביב, אברהם מתימן","k":"בעל גולת תימן","bt":"תרנב","bp":"חידאן-תימן","b":"עלה לארץ והתישב בראשון לציון, שיבת ציון. פעיל בעניני יהודי תימן בארץ ויו\"ר התאחדות התימנים. חיבר גם \"שבי תימן\" ת\"א תרצג."},{"i":21084,"n":"טביב, שלמה מתימן","f":"יוסף","dt":"תשח - לפני","dp":"תימן","b":"רב ומקובל בגבל צבר - מחוז חוגריה-תימן - בתחילת המאה ה-20. חברו של המקובל ר דוד יעיש חדד. מתלמידיו ר חיים בן יחיא סינואני. חיבר שירים, ועוד, רוב כתביו אבדו."},{"i":21085,"n":"טביוב, ישראל חיים","k":"בעל עדן הילדים","bt":"1858","bp":"דרוויה-פלך וילנא","dt":"1920","b":"פרסם פיליטונים ב\"המליץ\". חיבר ספרי לימוד ובהם \"מורה לילדים\" וארשא תרנז, ועוד. חיבר גם \"אוצר המשלים והפתגמים\".","bk":[["אוצר המשלים והפתגמים",""]]},{"i":21086,"n":"טביומי-גוטנטאג, טוביה יהודה","k":"בעל טל לישראל","r":"רב בסוכוצ'ין וחבר מועצת גדולי התורה בפולין","bt":"תרמב","bp":"ריפין-פולין","dt":"תשיג - כד תמוז","b":"חסיד גור וסוכטשוב וידידו של האדמור בעל \"בית ישראל\" מגור. תלמיד בעל \"אגלי טל\". רב בסוכוצ'ין(=סוכאצין), עלה לארץ-תרצו וכיהן כרב בתל אביב. פרסם מאמרים ב\"אהל מועד\" - איזביצא - בילגוריי - תרפו, \"הבאר\" - זאמושץ-וארשא - תרפד, \"המגיד\" - סטמר תרפח-תרצט. חיבר גם \"ארץ טובה\", \"עטרת טוביה\", ועוד. פרסם מאמרים ב\"יבנה\" - לבוב תרפט, \"המגיד\" - סטמר תרפח.","bk":[["אבל כבד - הספד",""],["אמרי טל",""],["ארץ טובה – שו\"ת",""],["טל אורות – חקר דברי חז\"ל",""],["טל לישראל",""],["יקרא דחיי - הספדים",""],["מעשה טוביה",""],["עטרת טוביה – רמב\"ם",""]]},{"i":21087,"n":"טבל, צבי הירש מדינוב","f":"פנחס","k":"בעל ציון לנפש","b":"תלמיד ישיבת חכמי לובלין. ר\"מ בישיבת דברי חיים מקראקא. ר בווצלר וטרוענשטין-גרמניה. ניצל מהשואה. היגר לארה\"ב וכיהן כרב ור\"מ בניו יורק. חיבר \"ציון לנפש\" ניו יורק תשלו."},{"i":21088,"n":"טבלי מירושלים","b":"תלמיד ר יוסף אשכנזי. מחכמי ירושלים-שנות ה-ש'. בשליחות באירופה, ופגש את בעל התוי\"ט, נזכר אצל ר יצחק דנון בהקדמת \"ספר רזיאל הגדול\"."},{"i":21089,"n":"טבלי מנירנברג","b":"מגדולי חכמי אשכנז בנירנברג-ר\"כ"},{"i":21090,"n":"טבלין","b":"מגדולי חכמי ירושלים-ש\"ע"},{"i":21091,"n":"טבנקין, משה אהרן מאקלאנד","b":"פרסם מאמרים ב\"הפרדס\" - צאנז תרצא."},{"i":21092,"n":"טבצניק, נחום זאב מקריוואזר","f":"יוסף","bt":"תרכז","b":"רב בקריוואזר-פודוליה-תרנז. נסמך מאת: ר ישראל איזנשטין מניקולייב בעל \"עמודי אש\". חיבר חדושים על הרמב\"ם, ועל הלכות יין נסך - בכת\"י."},{"i":21093,"n":"טבצניק, קלמן","bt":"תרלג","dt":"תשיא - כ טבת","b":"רב באדעסה-תרס\"ה,עלה לא\"י-תרפ\"א"},{"i":21094,"n":"טבצ'ניקוב, משה שמואל","f":"מנחם מנדל","bt":"תרל","b":"מו\"צ בקראסניקאמונקא-פלך חרסון-תרנג."},{"i":21095,"n":"טבק שלמה יהודה בן פסח צבי","bt":"1832","dt":"ה'תרסז 1907","bk":[["תשורת ש\"י חלק א",""]]},{"i":21096,"n":"טבק, מאיר דוד מסיגט","f":"שלמה יהודה ל'-ערך שי","k":"בעל ברכת שדים-בכת\"י","bt":"תרי","dt":"תרצו - ב ניסן","b":"תלמיד האדמור משינאווא. רב בקרטשנוף, סיגט-תרסח על מקום אביו."},{"i":21097,"n":"טבק, שלמה יהודה ליב מסיגט","f":"פסח צבי","k":"בעל ערך שי","bt":"תקצב","bp":"סיגט","dt":"תרסח - יא טבת","dp":"סיגט","b":"מגדולי הפוסקים בדורו. תלמיד ר יקותיאל יהודה טיטלבוים בגורליץ, ובישיבת \"קול אריה\" במאד, ור יהודה מודרן בסיגט. חסיד הדברי חיים מצאנז. חתן הגביר ר מרדכי ישראל מקירווע, בזיוו\"ש חתן ר צבי אריה בעל \"אמרי בינה\". דיין בסיגט כ-50 שנה. חיבר גם \"תשורת שי\".","bk":[["ערך ש\"י","מפרשי שו\"ע"],["תשורת ש\"י","שו\"ת - אחרונים"],["תשורת ש\"י – שו\"ת",""]]},{"i":21098,"n":"טבק, שמואל","b":"פרסם מאמרים ב\"הדנו\" - נ\"י תרפה."},{"i":21099,"n":"טבקמן, יהודה יידל מראשקוב","f":"חיים","bt":"תרכה","b":"נסמך מאת: ר יהודה ליב לנדא בעל \"יד יהודה\". רב בשארגרד-פודוליה, רשקוב(=ראשקוב)-פודוליה-תרסט."},{"i":21100,"n":"טבר ראה גם טויבר","b":"נכד השל\"ה."},{"i":21101,"n":"טבראני, יהודה","f":"עלואן","b":"ראש ישיבת ירושלים בתקופה הגאונים במאה העשירית. לדעת בן יעקב \"אוצר הספרים\" סובר כי הוא זהה עם ר יהודה בן עלואן טבראני המוזכר על ידי הרד\"ק, והוא המוזכר ב\"אשכול הכופר\" ליהודה הדסי הקראי בשם \"יהודה בן עלואן הטברני, וכי בטעות התחלף עלן בעלי ושם האב עם הבן."},{"i":21102,"n":"טבריס, חיים (היימל)","bt":"1868","bp":"וילנא","dt":"1933","dp":"ריגה","b":"תלמיד ישיבת מייליס, וקלויז ר שאולקה בוילנא. מקורב למשכילים, פרסם מכתבים ב\"המליץ\" ובהם תקף את פרנסי וילנא. עבר לקובנא. פרסם ב\"הד ליטא\" זכרונות על וילנא."},{"i":21103,"n":"טבריסקי, אברהם יצחק מאמנשטירשצ","f":"איסר מסמרגון-פלך ויל","k":"בעל מחשבת אברהם","bt":"תרלא","dt":"תרצה - ז ניסן","b":"תלמיד ישיבת וולוזין. רב במנוסטריסנה(=אמנאשטירשציזנא)-פלך מוהילוב-תרנז, מגדיאל-תרצב. חיבר \"מחשבת אברהם\" - בכת\"י."},{"i":21104,"n":"טברסקי, אברהם","f":"ברוך דוד מקלינקוביץ","b":"מצאצאי ר זושא מאניפולי. חתן ר משולם זוסיא מאורעל (ליניץ)."},{"i":21105,"n":"טברסקי, אברהם דב מרחמיסטריבקה","f":"מנחם נחום מרחמיסטריב","k":"אדמור מרחמיסטריבקא","bt":"תרכה","bp":"רחמיסטריבקה","dt":"תשה - כט אב","b":"חתן ר אפרים זלמן ממציוב, אדמור מרחמיסטריבקא בירושלים על מקום אביו. בנו - ר אפרים."},{"i":21106,"n":"טברסקי, אברהם המגיד מטריסק","f":"מרדכי מטשרנוביל","k":"בעל מגן אברהם","r":"המגיד מטריסק","bt":"תקסו","dt":"תרמט - ב תמוז","b":"חתן ר יעקב אריה שפירא מקובאלי(=קאוועל). רב בטריסק.","bk":[["מגן אברהם - עה\"ת",""]]},{"i":21107,"n":"טברסקי, אברהם יהושע ה' מצודנוב","b":"רב בצ'ודנוב"},{"i":21108,"n":"טברסקי, אברהם יהושע השל","f":"משה דן מסקווירא","bt":"תרמח","dt":"תשכו","b":"חתן ר מרדכי מקראטי. רב ואדמור. עלה לארץ-תרצה. התקרב לציונות, ממיסדי חובבי ציון בסקווירא. נשיא ההסתדרות הציונית בקראטי. ציר בקונגרס הראשון בקיוב. פעיל גם בתקופת הקומוניסטים."},{"i":21109,"n":"טברסקי, אברהם יהושע השל","f":"יצחק מסקווירא","bt":"תרעה","dt":"תשן - סיון","b":"חתן ר פנחס שרייבר. נפטר ללא ילדים."},{"i":21110,"n":"טברסקי, אברהם יהושע השל מטשודנ","f":"מרדכי מלויאב","k":"אדמור מלויאב טשודנוב","bt":"תרך","dt":"תרעד - יח תמוז","dp":"אוטוואצק","b":"חתן ר יעקב מדלטין (קוריץ). אדמור בלויאב, טשודונוב. מכתב ממנו ב\"הפיסגה\"."},{"i":21111,"n":"טברסקי, אברהם יהושע השל ממאלין","f":"גדליה ממאלין","k":"אדמור ממאלין רדומישל","dt":"תרעט - כה אייר","b":"אדמו\"ר ממאלין רדומישל. חתן ר אלכסנדר סנדר רוקח. נהרג עק\"ה בפרעות ברוסיה (בקישינוב?), עם בנו - ר מרדכי"},{"i":21112,"n":"טברסקי, אברהם יהושע השל ממחנו","f":"יוסף מאיר ממחנובקה","k":"אדמור ממחנובקה","bt":"תרנה","dt":"תשמח - י תשרי","b":"חתן ר דוד אהרן מזאריק, עבר למוסקבה-תרצב, עבר לטשקנט. הוגלה לסיביר-5 שנים. קולגא-כשנתיים. עלה לארץ-תשכד וכיהן כאדמור בבני ברק"},{"i":21113,"n":"טברסקי, אברהם יהושע השל מסקויר","f":"יצחק מסקווער","b":"אדמו\"ר מסקווער"},{"i":21114,"n":"טברסקי, אברהם יהושע השל מסקויר","f":"יצחק מסקווירא","k":"אדמור מסקווירא","bt":"תקפו","dt":"תרמז - ג כסלו","b":"חתן ר שמואל אשכנזי-חתן ר יצחק מאיר מזינקוב (אפטא), ובזיוו\"ש חתן ר יוסף זילברפרב-חתן ר שלמה מסאווראן. אדמור בחיי אביו."},{"i":21115,"n":"טברסקי, אברהם מנחם נחום מחעלם","f":"משה יהודה ליב","dt":"תשב - יב אלול","dp":"קילץ","b":"נספה בשואה."},{"i":21116,"n":"טברסקי, אברהם מניו יורק","f":"אלעזר מפאלטישאן","bt":"תרעד","dt":"תשמד - יג שבט","b":"חתן ר מאיר איזיק דסקל."},{"i":21117,"n":"טברסקי, אהרן אלימלך שניאור זל","f":"מרדכי דב מהורנוסטיפל","k":"אדמור מקרוסנו","bt":"תרכד","dt":"תרפד - יט חשון","dp":"קראקא","b":"חתן ר משה מרוזוודוב. רב ואדמור באיגנטובקה-רוסיה, קרוסנו-תרסח."},{"i":21118,"n":"טברסקי, אהרן דוד","f":"משה מרדכי טברסקי","b":"רב בגורשקוב"},{"i":21119,"n":"טברסקי, אהרן מגרשקוב","dt":"תשא","b":"רב בגרשקוב"},{"i":21120,"n":"טברסקי, אהרן מטשרנוביל","f":"מרדכי מטשרנוביל","k":"אדמור מטשרנוביל","bt":"תקמז","dt":"תרלב - ח כסלו","b":"רב ואדמור בטשרנוביל. חתן ר גדליה מליניץ, ובזיוו\"ש חתן ר אהרן מטיטיוב נכד הבעשט. (ולפי אלפסי חתן ר צבי מקוריסטשוב חתנו של ר אהרן מטיטיוב). גבאי מעות ארץ ישראל. מגדולי האדמורים."},{"i":21121,"n":"טברסקי, אהרן מנחם נחום מקישנוב","f":"ברוך מאיר מאזארניץ","k":"אדמור אזרניץ קישינוב","dt":"תשא","b":"חתן ר משה מטשיטשליניק, ובזיוו\"ש חתן דודו ר מרדכי מלויאב. אדמור בקישינוב-תרעא. נספה בשואה."},{"i":21122,"n":"טברסקי, אהרן מסקווירא קיוב","f":"דוד מסקווירא","dt":"תרעט - כ אב","b":"חתן ר יצחק מבוהוש (רוזין). נפטר בזמן הפרעות הרעב והמגפות בקיוב (מלחמת האזרחים ברוסיה)."},{"i":21123,"n":"טברסקי, איסר","b":"דומ\"צ בסמרגן-תר\"מ"},{"i":21124,"n":"טברסקי, אלכסנדר מאיר","f":"פנחס מאוסטילה","dt":"תשג","b":"חתן ר שלום רקח האדמור מליביטשוב"},{"i":21125,"n":"טברסקי, אלעזר מפולטישאן","f":"שלמה מסקווירא","k":"אדמור מסקווירא","bt":"תרנג","bp":"בלז","dt":"תשלו - כא תמוז","dp":"ניו יורק","b":"נכד האדמור מבלז, גדל אצל זקנו ר יהושע מבלז, ואצל דודו ר ישכר דב. חתן ר מאיר מושקוביץ משאץ. אדמור מסקווירא בפאלטישאן-רומניה. עבר לבוקרשט בזמן השואה וניצל. היגר לניו יורק-תשט, וכיהן כאדמור. חיבר \"תפארת אלעזר\" ברוקלין תשמד. בנו ר אברהם, ונכדו ר שלום מאיר שכיהן על מקום זקנו אחריו."},{"i":21126,"n":"טברסקי, אפרים מירושלים","f":"אברהם דב","b":"נכד ר מנחם נחום מרחמיסטריבקה. מחכמי ירושלים."},{"i":21127,"n":"טברסקי, בן ציון חיים שלמה משלם","f":"יעקב ישראל ממילווקי","k":"אדמור מדנבר-ארה\"ב","bt":"תרפג","dt":"תשמב - כג תשרי","b":"מצאצאי ר זושא מאניפולי. חתן ר יוסף מפיסטבורג (נדבורנא). ערך את כתבי הקבלה של זקנו ר מרדכי דב מהורנסטיפל."},{"i":21128,"n":"טברסקי, בן ציון יהודה ליב מהור","f":"מרדכי דב מהורנסטייפל","k":"אדמור מהורנסטייפל","bt":"תרכח","dt":"תשיא - כח טבת","dp":"שיקגו","b":"נכד ה\"דברי חיים\" מצאנז, ור משולם זושא מאניפולי ור משולם זושא מטלאמיטש. חתן האדמור ר יצחק יואל מקאנטיקוזיווע (ליניץ). אדמור מהרונסטייפל על מקום אביו. ביקר בארץ-תרעד כדי להקים בה ישוב חסידי אולם לא הסתייע, ישב בקיוב-תרעה, כשחלה נוסף לו השם \"בן ציון\"-תרף, בפרעות ברח והתישב בקראקא, אנטורפן, עלה לירושלים-תרצו, יצא לאנטורפן לחסל את עניניו ואז פרצה המלחמה, ניצל מהשואה והגיע לשיקגו. עליו בספר \"מדור אל דור\". בניו - ר משה משולם זושא מקיוב, ור יעקב ישראל ממילווקי חתן האדמור מבובוב."},{"i":21129,"n":"טברסקי, ברוך אשר מטשרנוביל","f":"אהרן מטשרנובל","k":"אדמור מטשרנוביל","dt":"תרסה - כב סיון","b":"נכד(-אבי אמו) ר אהרן מטיטיוב-נכדו של הבעש\"ט. אדמו\"ר-תרלב על מקום אביו. חתן דודו ר משה מקוריסטשוב. אדמו\"ר-תרלב על מקום אביו יחד עם אחיו האדמו\"ר ר ישעיה משולם זושא."},{"i":21130,"n":"טברסקי, ברוך בן ציון מאומן","f":"מרדכי מלויאב","k":"אדמור מארה\"ב","bt":"תרלה","dt":"תשה - כב אלול","dp":"ארה\"ב","b":"חתן ר אליעזר מראדויל-אוסטילה (זלוטשוב). עבר לוארשא-במלחה\"ע ה-I, היגר לארה\"ב-תרפה. חתנו ר פנחס בן שאול שטאל מבאלטא."},{"i":21131,"n":"טברסקי, ברוך דוד מקלינקוביץ","f":"מרדכי דב מהורנסטיפל","k":"בעל ויברך דוד","bt":"תרלה","dt":"תרפו - כח כסלו","b":"אדמו\"ר בקלינקוביץ. מצאצאי ר זושא מאניפולי. חתן ר שלמה זלמינא מראשקוב. עבר לוינה-תרפב. עלה לארץ והתישב בתל אביב. הניח כתבים בהלכה ואגדה. בנו ר אברהם-חתן ר משולם זוסיא מרואעל (ליניץ)."},{"i":21132,"n":"טברסקי, ברוך מאיר מאזארניץ","f":"מנחם נחום מלויאב","k":"אדמור מאזארניץ","dt":"תרעא - ה אייר","dp":"מאהליב","b":"רב בזארינץ. חתן ר יעקב יצחק ממקרוב, ובזיוו\"ש חתן ר אברהם יהושע השל מליטשיניץ (ברדיטשוב)."},{"i":21133,"n":"טברסקי, ברוך מסטעפין","f":"מרדכי מקוריסטשוב","k":"אדמור מסטעפין","bt":"תרלט","bp":"טריסק","dp":"לובלין","b":"נכד האדמור מרדכי מטשרנוביל. חתן ר מאיר חיים מסטעפין ואדמור על מקומו אחריו. עבר לניו יורק אחר מלחמת העולם ה-I, חזר לסטעפין, לובלין-תרצו. מחותנו של ר ישראל הינוקא מסטולין - בנו ר משה הי\"ד היה חתן האדמור מסטולין. הסכים על \"בד קודש\" ניו יורק תרפו."},{"i":21134,"n":"טברסקי, גדליה ממאלין","f":"ישראל","k":"אדמור ממאלין טשרנובי","bt":"תקעח","dt":"תרסא - כב ניסן","b":"נכד ר אהרן מטשרנוביל מצד אמו וגדל אצלו. ומצד אביו נכד ר יצחק איזיק מדוברוונא, ונינו של ר נחמן מברסלב. חתן ר פנחס שפירא מסלאוויטא (אניפולי). זקנו האדמור מטשרנוביל הכתירו כאדמור."},{"i":21135,"n":"טברסקי, דוד","f":"פנחס מאוסטילה","dt":"תשג","b":"חתן ר נפתלי טיטלבוים מנירבאטור. נספה בשואה."},{"i":21136,"n":"טברסקי, דוד אהרן מזאריק","f":"יעקב אריה ליב מטריסק","k":"אדמור מזאריק","bt":"תרמב","dt":"תשג - כא תשרי","dp":"שדה לבן","b":"חתן ר יצחק מבוהוש. אדמור בזאריק-ליד בנדין-תרף, רב בטשנסטחוב."},{"i":21137,"n":"טברסקי, דוד יהודה ליב מקאזאטי","f":"אברהם יהושע השל מסקו","k":"אדמור מסקווירא-קזטין","dt":"תרפ - יב שבט","b":"חתן אחיו ר יוסף מאיר ממחנובקא. אדמור בקאזאטין. נהרג עק\"ה בפרעות."},{"i":21138,"n":"טברסקי, דוד יעקב","f":"מרדכי טברסקי"},{"i":21139,"n":"טברסקי, דוד יעקב מזיטומיר","f":"מרדכי מקוריסטשוב","k":"אדמור מזיטומיר","dt":"תשא - ט כסלו","b":"חתן ר ישראל מסקווירא."},{"i":21140,"n":"טברסקי, דוד מבוהוש-יאס","f":"מרדכי זוסיא מהוצאלאס","k":"אדמור מבוהוש","dt":"תרצד - כג כסלו","b":"חתן ר ישראל שלום יוסף מבוהוש. ניהל את הישיבה בבוהוש עם גיסו ר מנחם מנדל מבוהוש. אדמור בבוהוש על מקום חותנו יחד עם גיסו. בעל כשרון לציור."},{"i":21141,"n":"טברסקי, דוד מזלטיפולא","f":"יוחנן מרחמיסטריבקא","k":"אדמור מזלטיפולא","dt":"תרעה - יא טבת","b":"חתן ר אהרן מקרלין."},{"i":21142,"n":"טברסקי, דוד מטולנא","f":"מרדכי מטשרנוביל","k":"אדמור מטולנא-ברכת דו","r":"האדמו\"ר מטאלנא","bt":"תקסח","dt":"תרמב - ו-י אייר","b":"חתן ר ישראל אברהם מטשרני בן ר זושא מאניפולי. רב בואסילקובה(=וסליקוב), טולנא-תריד, ברודי. חיבר \"ברכת דוד\", \"מגן דוד\", \"קהילת דוד\".","bk":[["ברכת דוד- עה\"ת",""],["מגן דוד- עה\"ת",""],["קהלת דוד- עה\"ת",""]]},{"i":21143,"n":"טברסקי, דוד ממקרוב","f":"יעקב יצחק ממקרוב","dt":"תרסג - כד חשון","b":"חתן דודו זקנו ר אברהם מטריסק. רב במקרוב. (אצל אלפסי תאריך פטירתו שבט)."},{"i":21144,"n":"טברסקי, דוד מסקווירא","f":"יצחק מסקווירא","k":"אדמור מסקווירא","bt":"תרח","dt":"תרפ - טו כסלו","b":"חתן ר שלמה מסאווראן, ובזיוו\"ש חתן ר אליקים געץ מאוסטרהא."},{"i":21145,"n":"טברסקי, דוד מסקווירא","f":"משה דן מסקווירא","dt":"תרפ","dp":"קיוב","b":"חתן ר מרדכי מסקווירא."},{"i":21146,"n":"טברסקי, דוד מסקווירא","f":"יעקב יוסף מסקווירא","k":"אדמור מסקווירא ארהב","bt":"תשא","bp":"יאס","b":"חתן ר משה יהשוע מויזניץ. אדמור מסקווירא בניו יסקווירא-ניו יורק."},{"i":21147,"n":"טברסקי, דוד מסקווירא נ\"י","f":"יצחק מסקווירא","bt":"תרפב","b":"חתן ר יחיאל מיכל מטורקא-סטרטין. אדמור מסקווירא בניו יורק-תשא, והקים ישיבה. מומחה ברפואה."},{"i":21148,"n":"טברסקי, דוד מסקווער","f":"יצחק מסקווער","b":"אדמו\"ר מסקווער-תרמ\"ו"},{"i":21149,"n":"טברסקי, דוד מצנטחוב","dt":"תש","b":"רב בדארעק-טשנטחוב"},{"i":21150,"n":"טברסקי, דוד מרדכי מטולנא","f":"מנחם נחום מטולנא","k":"אדמור מטולנא בארה\"ב","bt":"תרמח","bp":"טולנא","dt":"תשיז - יז תשרי","dp":"ניו יורק","b":"נכד האדמור ר דוד מטולנא. נסמך מאת ר יצחק ירוחם דיסקין מטולנא. חתן ר שלמה זלמינא מרשקוב. רב בטולטשין, היגר לארה\"ב-תרעג וכיהן כאדמור מטולנא בארה\"ב."},{"i":21151,"n":"טברסקי, דוד מרחמיסטריבקא","f":"מנחם נחום מרחמיסט'","k":"אדמור מרחמיסטריבקא","bt":"תרלב","dt":"תשי - יג תמוז","b":"חתן ר אברהם יהושע השל מסקווירא, עבר לניקולייב. אדמו\"ר מרחמיסטריבקה בירושלים יחד עם אחיו - ר אברהם דב ואח\"כ עם בנו של אחיו ר אפרים."},{"i":21152,"n":"טברסקי, זאב וולף","f":"יעקב אריה מטוריסק","dt":"תשג","b":"אדמו\"ר מקאוולע"},{"i":21153,"n":"טברסקי, זאב וולף","f":"פנחס מאוסטילה","dt":"תשג","b":"חתן ר יהושע הלברטשם מדולינא. נספה בשואה."},{"i":21154,"n":"טברסקי, זאב מזלטיפולא לוביטש","f":"מרדכי יוסף","k":"אדמור מזלטיפול קראקא","b":"חתן ר יהושע מבלז. אדמור בקראקא. בנו יחידו ר יהושע-נספה בשואה."},{"i":21155,"n":"טברסקי, זאב מירושלים וחרמיסטרי","f":"יוחנן","k":"אדמור מרחמיסטריבקה","bt":"תריא","dt":"תרצז - כ סיון","dp":"ירושלים","b":"חתן ר ישעיה משולם זושא מטשרנוביל, ובזיוו\"ש חתן ר יעקב שמשון חודרוב מבאהפאלי. רב בטולצין, זלאטיפאלי, אדמור מרחמיסטריבקה, חותנו של ר מאיר הגר ממודזיץ, עלה לירושלים-תרצד-ז. בקי בפילוספיה יהודית, הניח כתבים בהלכה וחסידות, תשובות ממנו בעילום שמו. פרסם מאמר ב\"עיטור סופרים\" - וילנא תרמח (בעילום שמו) - והמאמר הובא ב\"שדי חמד\" לר חזקיה מדיני, \"קול תורה\" - ירושלים תרץ-תשז. מבניו: ר דוד חתן ר אברהם דב מרחמיסטריבקא."},{"i":21156,"n":"טברסקי, זאב מקובל","f":"יעקב אריה ליב מטריסק","k":"אדמור בוואהלין","bt":"תרמ","dt":"תשג","b":"חתן ר שלמה בן ציון מטשרנוביל."},{"i":21157,"n":"טברסקי, זושא","f":"אהרן מטשארנובל","b":"רב-שנת תר\"מ"},{"i":21158,"n":"טברסקי, חי יצחק מרחמיסטריבקא","f":"יוחנן מרחמיסטריבקא","k":"אדמור מרחמיסטריבקא","bt":"תרצא","b":"חתן ר יעקב יוסף מסקווירא. אדמור מרחמיסטריבקא בארה\"ב."},{"i":21159,"n":"טברסקי, חיים יצחק מלויאב","f":"אברהם יהושע השל","k":"אדמור מקיוב","bt":"תרמו","bp":"לויעב","dt":"תשג - כד ניסן","dp":"סיביר","b":"בן האדמור מטשודנוב. חתן ר יצחק ישעיה הלברשטם מטשכויב (צאנז). רב ואדמור בלויאב, קיוב-תרפג (בזמן הקומוניסטים) והוגלה לסיביר-תרצז - שם נפטר."},{"i":21160,"n":"טברסקי, חיים מנחם אברהם מלונדו","f":"יעקב אריה ליב מטריסק","bt":"תרעו","b":"בן האדמור מטריסק לונדון. חתן ר ליביש מחנטשין (לובלין)."},{"i":21161,"n":"טברסקי, חיים משה","dt":"תשג","b":"רב בקאוולא"},{"i":21162,"n":"טברסקי, חיים משה יהושע מטומשפל","f":"מרדכי דב מטומשפיל","k":"אדמור מטומשפיל ארה\"ב","bt":"תריז","dt":"תשיט - יא אלול","dp":"ארה\"ב","b":"חתן ר שמואל ליפסון מבלז-בסרביה, ובזיוו\"ש חתן ר יוסף מקוידנוב. אדמור בטומשפיל, קוידנוב. עבר לארה\"ב."},{"i":21163,"n":"טברסקי, חיים משה צבי מרחמיסטרי","f":"מרדכי דב מהורנסטיפל","bt":"תרכו","dt":"תרצד - כ כסלו","b":"מצאצאי ר זושא מאניפולי. אחיו של ר אהרן אלימלך האדמור מקרוסנא. חתן ר מנחם נחום מרחמיסטריבקא."},{"i":21164,"n":"טברסקי, חנוך הניך דב מאלסק","f":"אברהם יהושע השל","k":"אדמור ממאלין","bt":"תרמו","bp":"אלסק","dt":"תשלא - כב אלול","dp":"ירושלים","b":"בן האדמור מראדומישל. חתן ר יוסף ירושלימסקי מקוריץ וקישינוב. רב ברדומישל-תרעד על מקום אביו, אדמור במלינא-תרעט על מקום אביו. היגר לארה\"ב, וכיהן כרב בקהילת \"לב שמח\" בשיקגו כ-40 שנה, עלה לירושלים-תשכח."},{"i":21165,"n":"טברסקי, יהודה ליבוש","dt":"תשג","b":"רב בזאמאטשקיעלץ"},{"i":21166,"n":"טברסקי, יוחנן מהוריבישוב","f":"משה מרדכי טברסקי","dt":"תשג","b":"רב בהוריבישוב"},{"i":21167,"n":"טברסקי, יוחנן מטולנא","f":"דוד מרדכי מטולנא","k":"אדמור מטולנא במונטרי","bt":"תרסו","bp":"טולטשין-פלך פודוליה","b":"חתן ר משה לנגר מקוזובה-סטרטין. תלמיד ישיבת רבי יצחק אלחנן בניו יורק, ישיבת \"אהל משה\" בירושלים. נסמך מאת: ר יוסף חיים זוננפלד, ר פנחס רימלט מזולקווא. רב בניו יורק, אדמור במונטריאול-תרצד, עלה לירושלים. פעל לעזרה לפליטי השואה."},{"i":21168,"n":"טברסקי, יוחנן ממוזינא-לבוב","dt":"תשג","b":"אדמו\"ר במוזינא-לבוב"},{"i":21169,"n":"טברסקי, יוחנן ממוזשאי","f":"פנחס מאוסטילה","dt":"תשג","b":"רב במוזשאי (הונגריה). חתן ה\"עצי חיים\". נספה בשואה."},{"i":21170,"n":"טברסקי, יוחנן מרחמיסטריבקא","f":"דוד מרחמיסטריבקא","k":"אדמור מרחמיסטריבקא","bt":"תרסג","dt":"תשמב - כ כסלו","b":"חתן ר נחמן יוסף וילהלם. ניצל מהפרעות ברחמיסטריבקא, עלה לארץ והקים ישיבת \"מאור עינים\" בירושלים."},{"i":21171,"n":"טברסקי, יוחנן מרחמיסטריבקה","f":"מרדכי מטשרנוביל","k":"אדמור מרחמיסטריבקא","bt":"תקעו","dt":"תרנה - ד ניסן","b":"חתן ר פנחס מקאלק (שושלת זיטומיר)."},{"i":21172,"n":"טברסקי, יוסף מאיר ממחנובקא","f":"אברהם יהושע השל מסקו","k":"אדמור ממחנובקה","bt":"תרכ","dt":"תרעט - כט אב","b":"חתן ר מנחם נחום מטשרנוביל-לויאב. סייע להרבה יהודים בזמן מלחה\"ע ה-I.. רב במחנובקה-תרמ"},{"i":21173,"n":"טברסקי, יחיאל מיכל ממילווקי","f":"יעקב ישראל ממילווקי","k":"אדמור ממילווקי","bt":"תרצט","b":"מצאצאי ר זושא מאניפולי. חתן ר אלעזר מפאלטישאן (טשרנוביל). אדמור במילווקי על מקום אביו."},{"i":21174,"n":"טברסקי, יעקב","f":"אברהם יהושע העשל","b":"רב-שנת תר\"ע"},{"i":21175,"n":"טברסקי, יעקב אריה ליב מטריסק","f":"אברהם טברסקי","k":"אדמור מטריסק הורבישו","bt":"תרז","dt":"תרעח - כח אייר","dp":"הורבישוב","b":"חתן דודו ר יוחנן מרחמיסטריבקא. אדמור בטריסק, קאוולא, הורבישוב."},{"i":21176,"n":"טברסקי, יעקב אריה ליב מטריסק","f":"מרדכי זוסיא מהוצאלאס","bt":"תרמה","dt":"תשמ - כא תשרי","b":"חתן ר פנחס השל מזינקוב (אפטא). ברח בגלל הפוגרומים לוינה, אנטורפן, עבר ללונדון וכיהן כאדמור מטריסק-בחיי אביו. עלה לארץ וכיהן כאדמור בבני ברק. בניו ר חיים מנחם אברהם מלונדון, ר פנחס מלונדון."},{"i":21177,"n":"טברסקי, יעקב יוסף מסטניסלב","f":"מנחם נחום מרחמיסטר'","k":"אדמור מסטניסלב","bt":"תרל-ד","bp":"רחמיסטריווקא","dt":"תרצא - יג אייר","dp":"וינה","b":"חתן ר ישראל שלום יוסף מבוהוש, ובזיוו\"ש חתן ר נחום מרדכי פרידמן, ובזיוו\"ש חתן ר מתתיהו קטן אדמור סטניסלב. רב בסטניסלב על מקום חותנו. (לפי אלפסי - בזיוו\"ש חתן ר חיים אהרן מצורטקוב, ובזיוו\"ש חתן ר מתתיהו ממונסטרישץ (ברדיטשוב)). ביקר בארץ-תרפו. נפטר בחיי אביו."},{"i":21178,"n":"טברסקי, יעקב יוסף מסקווירא","k":"אדמור מסקווירא-קאלרש","bt":"תרנט","bp":"סקווירא","dt":"תשכח - ב ניסן","dp":"ניו סקוויר","b":"חתן האדמור פנחס טברסקי מאוסטילא. אדמור בסווירא-תרף על מקום אביו, יחד עם אחיו, עבר לקולוראש-בסרביה וכיהן כאדמור, בוקרשט, ניצל מהשואה, עבר לניו יורק-תשי, וכיהן כאדמור מסקווירא-קאלאראש בניו יורק, הקים עיר ניו סקוויר-תשיז במדינת ניו יורק. בנו ר דוד על מקומו אחריו. חתנו ר מרדכי הגר מויזניץ במונסי, ור יצחק טברסקי מרחמיסטריבקה בניו יורק. אחיו ר נחום מסקווירא בארה\"ב, ואחחינו ר אלעזר טברסקי האדמור מפאלטישאן."},{"i":21179,"n":"טברסקי, יעקב יצחק ממאקרוב","f":"מנחם נחום ממקרוב","k":"אדמור ממקרוב","dt":"תרנב - ל ניסן","b":"נכד החוזה מלובלין. חתן ר שמואל אברהם אבא מסלאויטא (קוריץ). מקובל, רב במאקרוב"},{"i":21180,"n":"טברסקי, יעקב יצחק ממאקרוב","f":"ישעיה ממקרוב","k":"אדמור ממקרוב בשיקגו","bt":"תרנו","bp":"מקארוב","dt":"תשה - ב סיון","b":"חתן ר יהושע השל ממונסטרישץ (שושלת ליניץ). אדמור ממקרוב(=מקארוב) בקיוב-תרעט על מקום אביו, עבר לשיקגו-תרפו וכיהן כאדמור ממקרוב בשיקגו."},{"i":21181,"n":"טברסקי, יעקב ישראל מהורנוסטיפ","f":"מרדכי מטשרנוביל","k":"אדמור מהורנסטייפל","r":"ספר שושנת העמקים כולל שני ספרים: עמק תפילה; עמק החכמה.","bt":"תקנד","dt":"תרלו - יג אלול","b":"חתן ר דב בר מלובאויטש האדמור האמצעי. חיבר \"עמק תפלה\" נדפס בתוך \"שושנת העמקים\". רב ואדמור בהורנוסטיפל, טשערקס(=טשרקאס). חיבר \"עמק תפלה\" ונכדו ר מרדכי דב על מקומו אחריו בהורנסטייפל והו\"ל את ספרו \"עמק תפלה\".","bk":[["שושנת העמקים (צ'רקאס)",""],["עמק התפילה \\ עמק תפלה",""]]},{"i":21182,"n":"טברסקי, יעקב ישראל מטשרנוביל","f":"שלמה שמואל מטשרנוביל","k":"אדמור מטשרנוביל","bt":"תרסב","bp":"טשרנוביל","dt":"תשמד - ח כסלו","b":"חתן ר יעקב יוסף מאורזיסטשוב (אוסטרהא). אדמור ממלא מקום אביו (בחייו) בזמן הקומוניסטים, עלה לארץ-תרצז (למשך כשנתיים), אדמור על מקום אביו (אחר פטירתו)-תרצח בניו יורק."},{"i":21183,"n":"טברסקי, יעקב ישראל ממילווקי","f":"בן ציון יהודה ליב","k":"אדמור ממילווקי","bt":"תרנט-סח","dt":"תשלג - י אב","dp":"מילווקי","b":"מצאצאי ר זושא מאניפולי. חתן ר בן ציון הלברשטם האדמור מבובוב. עבר לקראקא ומשם לארה\"ב-תרפה. אדמור במילווקי-תרפו."},{"i":21184,"n":"טברסקי, יעקב מליניץ","f":"אברהם יהושע השל מסקו","k":"אדמור מליניץ","dt":"תרפ","dp":"הייסין","b":"חתן ר מרדכי מקוריסטשוב. אדמור בליניץ."},{"i":21185,"n":"טברסקי, יצחק","f":"מרדכי מסקארישטוב","b":"רב-שנת תר\"ע"},{"i":21186,"n":"טברסקי, יצחק","f":"פנחס מאוסטילה","dt":"תשג","b":"התארס עם האדמור מלינסק. נספה בשואה."},{"i":21187,"n":"טברסקי, יצחק","f":"מרדכי יוסף מזלטיפולי","bt":"תרמ - אחרי","b":"חתן ר משה דן מסקווירא."},{"i":21188,"n":"טברסקי, יצחק אברהם משה מקוריסט","f":"דוד יעקב מזיטומיר","k":"אדמור מקוריסטשוב","bt":"תרסב","dt":"תשמב - יט כסלו","b":"עלה מרוסיה לארץ והתישב בבני ברק. האדמור האחרון מקוריסטשוב."},{"i":21189,"n":"טברסקי, יצחק אשר מבוסטון","f":"משלם זושא מטולנא","k":"אדמור מטולנא בוסטון","bt":"תרצא","b":"חתן ר יוסף דב סולוביציק."},{"i":21190,"n":"טברסקי, יצחק מבעלץ אזרניץ","f":"ברוך מאיר מאזארניץ","dt":"תשא - יד כסלו","dp":"טרנסדניסטריה","b":"רב באוזרניץ. חתן ר ישראל אשכנזי מאלסק. אדמור בבעלז(=בעלץ)-בסרביה. נספה בשואה."},{"i":21191,"n":"טברסקי, יצחק מלאיוב","dt":"תשג","b":"רב בלאיוב. בנו - ר משלם זוסיא מירושלים."},{"i":21192,"n":"טברסקי, יצחק מסקווירא","f":"משה דן מסקווירא","k":"אדמור מסקווירא בת\"א","bt":"תרמו","bp":"סקווידע-פלך קיוב","dt":"תשלח - כט אד\"א","b":"חתן ר אברהם יהושע השל מטשודנוב, ובזיוו\"ש חתן ר מרדכי גארסאן מקונסטנטין ישן (זלוטשוב). רב בסקווירא, היגר לארה\"ב-תרפו וכיהן כאדמור, עלה לארץ וכיהן כאדמור בתל אביב. יסד ברוסיה \"אגודת החיים\". בנו ר אברהם יהושע השל."},{"i":21193,"n":"טברסקי, יצחק מסקווירא","f":"מרדכי מטשרנובל","k":"אדמור מסקווירא","r":"אדמו\"ר הראשון מסקוירא","bt":"תקעב","bp":"תרמה","dt":"תרמה - יז ניסן","b":"חתן האדמור ר דן ב\"ר יצחק מרזיויל (שושלת זלוטשוב), ובזיוו\"ש חתן ר ישראל מרוזין, וביזוו\"ש חתן ר צבי מסקווירא-נכד הבעשט. רב ואדמור בסקווירא.","bk":[["ילקוט מאורי אור",""]]},{"i":21194,"n":"טברסקי, יצחק מסקווירא","f":"מרדכי מסקווירא","k":"אדמור מסקווירא","bt":"תרמט","bp":"סקווירא","dt":"תשא - ג אב","b":"חתן ר פנחס מקנטיקוזיבה (ליניץ). אדמור בסקווירא, קישינוב, היגר לניו יורק-תרפג, וכיהן כאדמור בניו יורק. ע\"ש ישיבת \"בית יצחק\" ו\"בארות יצחק\"."},{"i":21195,"n":"טברסקי, יצחק מסקווירא קשינוב","f":"דוד מסקווירא","k":"אדמור מסקווריא","dt":"תש..","dp":"טרנסדניסטריה","b":"חתן ר שלמה שמואל מטשרנוביל, אדמור בסקווירא, עבר לקיוב, קשינוב. נספה בשואה בטרנסיסטריה."},{"i":21196,"n":"טברסקי, יצחק נחום משפיקוב","f":"מרדכי משפיקוב","k":"אדמור משפיקוב","bt":"תרמח","bp":"שפיקוב","dt":"תשב","dp":"בלזיץ","b":"חתן המהרי\"ד האדמור מבלז. רב ואדמור בשפיקוב-תרעד על מקום אביו, הולשיץ, עזב את האדמורות-תרפט ועבר אל חותנו בבלז, דיין בבלז, רב בראווה-רוסקה-תרפז. נספה בשואה. בנו ר יואל."},{"i":21197,"n":"טברסקי, ישעיה מטשרנוביל","f":"משלם זושא מטשרנוביל","k":"אדמור מטשרנוביל ארהב","bt":"תשה","b":"חתן ר שלום מיכלוביץ מבורד (זלוטשוב). אדמור בארה\"ב."},{"i":21198,"n":"טברסקי, ישעיה ממקרוב","f":"יעקב יצחק ממקרוב","k":"אדמור ממקרוב","dt":"תרעט-פ -כב חשון","b":"חתן ר חיים מנחם מזינקוב (אפטא). אדמור במקרוב-תרנב, קיוב-תרעו. נודע בקולו המיוחד."},{"i":21199,"n":"טברסקי, ישעיה משלם זושא מטשרנ","f":"אהרן מטשרנוביל","k":"אדמור מטשרנוביל","dt":"תרמא - כח תמוז","b":"חתן דודו ר מנחם נחום ממקרוב, ובזיוו\"ש חתן ר פנחס בן ר שמואל מסאלויטא, ובזיוו\"ש חתן ר צבי מסקווירא. אדמור בטשרנויבל על מקום אביו."},{"i":21200,"n":"טברסקי, ישעיה משלם זישא מפשמ'","f":"פנחס מאוסטילה","dt":"תשג","b":"רב בפשמישל. חתן המהר\"א ותלמיד זקנו המהרי\"ד מבלז. נספה בשואה."},{"i":21201,"n":"טברסקי, ישראל מסקווירא","f":"יצחק טברסקי","b":"רב בסקווער-תר\"ס"},{"i":21202,"n":"טברסקי, ישראל מסקווירא","f":"יצחק מסקווירא","k":"אדמור מסקווירא","dt":"תרנב - כח אלול","b":"חתן דודו ר אברהם מטריסק."},{"i":21203,"n":"טברסקי, ישראל מקוזניץ ונ\"י","k":"בעל עיני ישראל","b":"רב בקוזניץ, ניו יורק-תרצז."},{"i":21204,"n":"טברסקי, ישראל מרדכי ממאלין","f":"גדליה ממאלין","k":"אדמור ממאלין","bt":"תרח","dt":"תרעא - כז אלול","b":"חתן ר יצחק מטיסמניץ (ברדיטשוב)."},{"i":21205,"n":"טברסקי, ישראל מרדכי מרחמיסטריב","f":"יוחנן מרחמיסטריבקא","k":"אדמור מרחמיסטריבקא","bt":"תרפט","dt":"תשסד","b":"חתן ר סנדר אורי מירושלים. אדמור מרחמיסטריבקא בירושלים-תשמב על מקום אביו."},{"i":21206,"n":"טברסקי, מאיר","f":"נחום טברסקי","dt":"תרעא - ה אייר","b":"רב בזארינץ"},{"i":21207,"n":"טברסקי, מנחם מנדל מוילנא","b":"דיין בווילנה-תקצ\"ח. חתן ר אליהו הלוי מוילנא."},{"i":21208,"n":"טברסקי, מנחם מנדל מוילנא","f":"מאיר","b":"חתן ר אליהו אלץ-גוט. דיין בוילנא. חתם בפנקס הגר\"א-תקצח."},{"i":21209,"n":"טברסקי, מנחם נחום","f":"משה ליב מחלם","bt":"1735","b":"נכד ר מנחם נחום מבריסק.","bk":[["מאור עינים","חסידות"]]},{"i":21210,"n":"טברסקי, מנחם נחום (פנחס?)","f":"יוחנן מרחמיסטריבקא","k":"אדמור מרחמיסטריבקא","bt":"תר-ג","dt":"תרצו-ז - כח שבט","dp":"ירושלים","b":"חתן הגביר ר זאב אוירבך נכד ר דוד מחמלניק-תלמיד הבעשט, ובזיוו\"ש חתן הגביר ר יעקב יוסף הורנשטין מברדיטשוב. אדמור ברחמיסטריבקא ליד אחיו ר מרדכי ועל מקומו אחריו עם אחיהם ר זאב. עלה לירושלים-תרפד."},{"i":21211,"n":"טברסקי, מנחם נחום אברהם מזלטיפ","f":"מרדכי יוסף מזלטיפולי","k":"אדמור מזלטיפולא ורשא","bt":"תרנד","dt":"תשד","b":"חתן ר יוסף מאיר ממחנובקא. רב בוארשא על מקום אביו. נספה בשואה (לפני שנרצח עם משפחתו אמר \"אנו יוצאים כולנו לעקידה כיהודים, אשרינו שזכינו לכך\")."},{"i":21212,"n":"טברסקי, מנחם נחום יוסף בן ציון","f":"מרדכי מקוריסטשוב","bt":"תריח","dt":"תרסט - כט כסלו","b":"חתן ר ישעיה משולם זושא מטשרנוביל, ובזיוו\"ש חתן ר דן מראדויל (זלוטשוב)."},{"i":21213,"n":"טברסקי, מנחם נחום מבריסק","f":"אברהם מטריסק","k":"אדמור מטריסק בבריסק","bt":"תקפט","dt":"תרמז - ד שבט","b":"חתן דודו ר דוד מטולנא. אדמור בבריסק בחיי אביו."},{"i":21214,"n":"טברסקי, מנחם נחום מטולנא טולטש","f":"מרדכי מטולנא","k":"אדמור מטולנא","dt":"תרכט - טז אייר","b":"חתן דודו ר משה מטשיטשילניק (סאווראן). אדמור בטולנא על מקום זקנו-מגיל 13, עבר לטולטשין. מבניו ר יוחנן מסאבין, ר יצחק, ר אברהם ור אהרן."},{"i":21215,"n":"טברסקי, מנחם נחום מטריסק וארשא","f":"יעקב אריה ליב מטריסק","k":"אדמור מטריסק וארשא","dt":"תשב","dp":"מאהליב","b":"חתן ר מרדכי משפיקוב, ובזיוו\"ש חתן ר ישכר דב בן יהושע השל מחודרוב (זידיטשוב). אדמור בוארשא. נספה בשואה."},{"i":21216,"n":"טברסקי, מנחם נחום מטשרנוביל","f":"צבי","k":"אדמור מטשרנוביל","r":"אדמו\"ר מטשרנוביל","bt":"תץ","dt":"תקנח - יא חשון","b":"חתן נכדת ר יצחק שפירא. תלמדי הבעשט, והמגיד ממזריטש. מגיד מישרים בנארינסק, פרוהובישט, טשרנוביל. חיבר \"מאור עינים\", \"ישמח לב\".","bk":[["מאור עינים",""],["ישמח לב (טשרנוביל)",""],["ישמח לב - אגדות הש\"ס",""],["מאור עינים – עה\"ת",""]]},{"i":21217,"n":"טברסקי, מנחם נחום מטשרנוביל","f":"אהרן מטשרנוביל","bt":"תקע","dt":"תרלא - כז שבט","b":"חתן ר ישראל מליטשניץ (ברדיטשוב), ובזיוו\"ש חתן דודו ר דוד הורדצקי-חתן ר מרדכי מטשרנוביל. נפטר בחיי אביו."},{"i":21218,"n":"טברסקי, מנחם נחום מלויאב","f":"משלם זושא מלויאב","bt":"תשב","b":"חתן ר אלחנן הלפרין. ראש ישיבת אביו בבני ברק."},{"i":21219,"n":"טברסקי, מנחם נחום ממקרוב","f":"מרדכי מטשרנוביל","k":"אדמור ממקרוב","bt":"תקסד","dt":"תריב - ז תשרי","b":"חתן ר יוסף מטורטשין (לובלין). מתורתו ב\"היחס מטשרנוביל וריזין\"."},{"i":21220,"n":"טברסקי, מנחם נחום ממקרוב","f":"דוד ממקרוב","k":"אדמור ממקרוב","bt":"תרלב","dt":"תרפה - טז אייר","dp":"מסצוסטס-ארה\"ב","b":"חתן ר אפרים זלמן ממציוב. עבר לארה\"ב."},{"i":21221,"n":"טברסקי, מנחם נחום מסקווירא מחנ","f":"דוד מסקווירא","k":"אדמור מסקווירא-מחנוב","bt":"תרם","dt":"תשו - יט סיון","b":"חתן ר יוסף מאיר ממחנובקא, ובזיוו\"ש חתן ר אברהם פנחס מקיניוב (אוסטרהא). ברח מהפרעות-תרפ לקיוב (שם איבד את רוב אחיו), עבר לקישינוב, ארה\"ב וכיהן כאדמור מסקווירא מחנובקה."},{"i":21222,"n":"טברסקי, מנחם נחום משפיקוב","f":"יצחק מסקווירא","k":"אדמור משפיקוב","dt":"תרמו - א ניסן","b":"חתן דודו ר דוד מטולנא."},{"i":21223,"n":"טברסקי, מרדכי","f":"דוד מטולנא","bt":"תרז","dt":"תרלז - ו תשרי","b":"חתן ר שלמה מסאווראן. בנו ר מנחם נחום. נפטר בחיי אביו."},{"i":21224,"n":"טברסקי, מרדכי","f":"דוד מסקווירא","bt":"תרכו","dt":"תרפ - ח חשון","b":"חתן דודו ר אברהם יהושע השל מסקווירא. נפטר בחיי אביו בזמן הפרעות הרעב והמגפות בקיוב (מלחמת האזרחים ברוסיה)."},{"i":21225,"n":"טברסקי, מרדכי דב מהורנוסטייפל","f":"משלם זושא אוירבוך מט","k":"אדמור מהורנוסטייפל","bt":"תר","dt":"תרסג - כג אלול","b":"מצאצאי ר זושא מאניפולי. גדל אצל זקנו מצד אמו ר יעקב ישראל מטשרקאס - לאחר פטירת אביו וקיבל את שמו - טברסקי. חתן ה\"דברי חיים\". אדמור בהורנוסטייפל-תרכג על מקום זקנו. רוב כתביו נשרפו. נדפס \"שושנת העמקים\" לובלין תרמד, \"חיבר לטהרה\" ברדיטשוב תרנח, \"עמק שאלה\" פיעטרקוב תרסו, ועוד."},{"i":21226,"n":"טברסקי, מרדכי זוסיא מהוצלאס","f":"מנחם נחום מבריסק","k":"אדמור מהוצאלאס יאסי","dt":"תרצט - כז אייר","b":"חתן ר יצחק מבוהוש (רוזין). אדמור בהוצאלאס-רוסיה, יאסי-רומניה והתפרסם כאדמור מרוסיה. מקובל."},{"i":21227,"n":"טברסקי, מרדכי יוסף מזלוטפול","f":"דוד מזלטופול","k":"אדמור מזלטיפולא","bt":"תרכג","dt":"תרפט","dp":"וארשא","b":"אדמו\"ר בזלאטיפאלי-תרע. חתן ר אברהם יהושע השל מסווירא. עבר לקיוב-תרפ בזמן הפרעות, וארשא."},{"i":21228,"n":"טברסקי, מרדכי ישראל מחאטין","f":"ברוך מאיר מאזארניץ","k":"אדמור מאזרניץ בחאטין","dt":"תשא - טו תמוז","b":"חתן ר אברהם יהושע השל מטשודנוב. אדמור מאזארניץ בחאטין-רומניה. נספה בשואה. בניו ר ייעקב יוסף מנ\"י-חתן ר אברהם יהושע השל מקופיטשניץ (אפטא), ר אהרן-חתן ר משה מרדכי מלובלין-נספה בשואה."},{"i":21229,"n":"טברסקי, מרדכי מאטל","f":"דוד מסקוויר","b":"רב בזלאטיפולי"},{"i":21230,"n":"טברסקי, מרדכי מוארשא","f":"דוד","k":"אדמור מזלטיפולי","b":"אדמו\"ר בזלאטיפולי,וורשה-תר\"נ. בניו: ר נחום מוארשא, ר זאב וולף, ר צבי אריה."},{"i":21231,"n":"טברסקי, מרדכי מטשרנוביל","f":"מנחם נחום מטשרנוביל","k":"אדמור מטשרנוביל","r":"אדמו\"ר מטשרנוביל","bt":"תקל","dt":"תקצז - כ אייר","b":"מגדולי האדמורים בדורו. חתן ר אהרן הגדול מקרלין, ובזיוו\"ש חתן ר דוד לייקס-לייקיס (לאה'קס) מבאר-תלמיד הבעשט. רב ואדמור בטשרנוביל. חיבר \"לקוטי תורה\".","bk":[["ליקוטי תורה – עה\"ת",""]]},{"i":21232,"n":"טברסקי, מרדכי מלויאב","f":"מנחם נחום מלויאב","k":"אדמור מלויאב","bt":"תרד","dt":"תרעא - יד כסלו","dp":"שדה לבן","b":"חתן ר שמואל אשכנזי-חתן ר יצחק מאיר מזינקוב. נסמך לאדמור ע\"י זקנו ר אהרן מטשרנוביל. רב בלוייב-תר\"מ. בנו ר אברהם יהושע השל. חתניו: ר אברהם יעקב פרידמן, ר אברהם שמואל פצניק, ר ישראל שמואל נייהוז."},{"i":21233,"n":"טברסקי, מרדכי מסקווירא נ\"י","f":"יצחק מסקווירא","k":"אדמור מסקווירא נ\"י","bt":"תרפד","b":"חתן ר שמואל דייטש מצפת ובוקרשט."},{"i":21234,"n":"טברסקי, מרדכי מקוזמיר","f":"אברהם מטריסק","k":"אדמור מוולדובקה","bt":"תר","dt":"תרעז - ח תמוז","dp":"קילץ","b":"חתן ר אשר מקרלין, רב ואדמור בוולדובקה-תרן, דומברובציה, חלם, לובלין, קוזמיר וקילץ. חיבר \"מאמר מרדכי\". תולדותיו ב\"גדולת מרדכי\"."},{"i":21235,"n":"טברסקי, מרדכי מקוריסטשוב","f":"משה מקוריסטשוב","k":"אדמור מקוריסטשוב","bt":"תרב","dt":"תרעו - כט שבט","b":"חתן דודו ר אברהם מטריסק. בניו ר משה חתן ר אפרים זלמן מרגליות ממאציוב, ר יצחק חתן ר משה בן פנחס בן משה מסלאויטא."},{"i":21236,"n":"טברסקי, מרדכי מקישינוב","f":"אברהם יהושע השל ממאל","dt":"תרעט - כה אייר","dp":"קישינוב?","b":"נהרג עק\"ה בפרעות באוקראינה יחד עם אביו - האדמור ממאלין."},{"i":21237,"n":"טברסקי, מרדכי מקריסטשוב","f":"משה טברסקי","b":"רב בקאריסטשוב-תר\"ס. חתן ר אברהם טברסקי . בניו: ר נחום יוסף, ר דוד יעקב ר יצחק ר משה. חתנו ר משה ליב מחעלם."},{"i":21238,"n":"טברסקי, מרדכי מרחמיסטריבקא","f":"יוחנן מרחמיסטריבקא","k":"אדמור מרחמיסטריבקא","bt":"תקצב-תר","dt":"תרף - יז אייר","dp":"ירושלים","b":"חתן ר חנינא ליפא מזיטומיר בן ר שמואל אברהם מסאלויטא (קוריץ), ובזיוו\"ש חתן דודו ר דוד מטולנא. עלה לירושלים-תרסה. אמן וחרט בכסף ונחושת. נרצח עק\"ה-ע\"י פורעים ערבים."},{"i":21239,"n":"טברסקי, מרדכי משפיקוב","f":"מנחם נחום משפיקוב","k":"אדמור משפיקוב","dt":"תרעד - יח ניסן","b":"אדמו\"ר בשפיקוב. חתן דודו ר יוחנן מרחמיסטריבקה. בנו ר יצחק נחום טברסקי. חתנו - ר מנחם נחום טברסקי."},{"i":21240,"n":"טברסקי, משה דוד מראשקוב","f":"מרדכי משפיקוב","k":"אדמור מראשקוב","dt":"תשב - כז תשרי","b":"חתן ר שלמה זלמנא מראשקוב."},{"i":21241,"n":"טברסקי, משה דן מסקווירא","f":"אברהם יהושע השל","k":"אדמור מסקווירא","dt":"תרפ - יג שבט","b":"חתן ר חיים יהודה מאיר חודרוב מברדיטשוב-חתן ר דוד מטולנא. אדמור בסקווירא-תרנ."},{"i":21242,"n":"טברסקי, משה זלמן מטשמישלא","f":"מנחם נחום מניעזין","dt":"תרעו - טו אדר","b":"נכד אדמור האמצעי, ונכד ר יעקב ישראל טברסקי מטשרקאס מצד אמו - ומכאן שמו \"טברסקי\". חתן ר שמשון אהרן מקלניבלאט."},{"i":21243,"n":"טברסקי, משה יהודה ליב מחעלם","f":"מנחם נחום מבריסק","k":"אדמור מחעלם אמרי מ\"י","r":"אדמו\"ר מספינקא ירושלים","bt":"תרלג","dt":"תרצז - כ תמוז","dp":"קילץ","b":"אדמו\"ר בחעלם-תרס. חתן ר מרדכי מקוריסטשוב, ובזיוו\"ש חתן ר פנחס מקונסטנטין. אחיו - ר מרדכי זוסיא מהוצלאס.","bk":[["אמרי מ\"י - עה\"ת ומועדים",""]]},{"i":21244,"n":"טברסקי, משה מטשרנוביל","f":"מנחם נחום מטשרנוביל","bt":"תקנח - לפני"},{"i":21245,"n":"טברסקי, משה מסטעפין","f":"ברוך מסטעפין","b":"נכד ר מאיר חיים מסטעפין. חתן ר אשר מקרלין."},{"i":21246,"n":"טברסקי, משה מסקווירא","f":"דוד מסקווירא","dt":"תרפ","b":"חתן ר יעקב אריה ליב מטריסק. נפטר עם משפחתו בזמן הפרעות הרעב והמגפות בקיוב (מלחמת האזרחים ברוסיה). נפטר ללא ילדים."},{"i":21247,"n":"טברסקי, משה מקרוסנו","f":"אהרן אלימלך שניאור","k":"אדמור מקרוסנו","bt":"תרנה","dt":"תשב-ג","b":"מצאצאי ר זושא מאניפולי. רב ואדמור בקרוסנו-תרפד על מקום אביו. חתן ר יחזקאל הכהן רבינוביץ מרדומסק. נספה בשואה."},{"i":21248,"n":"טברסקי, משה מקרסטשוב","f":"מרדכי מטשרנוביל","bt":"תקמט","dt":"תרכו - יח טבת","b":"חתן ר יעקב יוסף מאוסטרהא נכד ר ייבי, ובזיוו\"ש חתן ר צבי אריה מאליק. רב בקרסטשוב."},{"i":21249,"n":"טברסקי, משה מרדכי","f":"יעקב יצחק טברסקי","b":"רב בברהטשוב-תר\"ס"},{"i":21250,"n":"טברסקי, משה מרדכי מלובלין","f":"יעקב אריה ליב מטריסק","k":"אדמור מטריסק בלובלין","bt":"תרלז","dt":"תשג - ח אייר","b":"חתן ר ישראל מססטולין, ובזיוו\"ש חתן ר ברוך מאיר מאזארניץ. אדמור בלובלין-תרעח ונתפרסם בשם \"הטריסקאי\". מתורתו ב\"אהל משה\". נספה בשואה. בניו ר יוחנן מהורבישוב-חתן ר ישכר דב מבלז, ר אהרן דוד מגורשקוב-חתן דודו ר זאב מקובל, ר אברהם יצחק מלונדון-חתן ר אלתר ישראל שמעון מנובומינסק (נסכיז). חתנו ר מנחם צבי איכנשטין אדמור מטריסק בסט לואיס-ארה\"ב. חיבר \"אהל משה\"."},{"i":21251,"n":"טברסקי, משה מרדכי ממקרוב","f":"יעקב יצחק ממקרוב","k":"אדמור ממקרוב","bt":"תרג","dt":"תרפ - כ טבת","dp":"ברדיטשוב","b":"חתן ר יהושע מבלז. אדמור במקרוב, קודנינ, ברדיטשוב."},{"i":21252,"n":"טברסקי, משה משלם זוסיא מלוהין","f":"בן ציון יהודה ליב","k":"אדמור מקיוב","dt":"תרפ - ב שבט","b":"מצאצאי ר זושא מאניפולי. בן האדמור מהורנסטיפל. חתן ר שמחה ישכר בער ציעשינוב (צאנז). רב בלוהין, אדמור בקיוב. נחשב לעילוי בין נכדי ר מרדכי דב מהורנסטיפל."},{"i":21253,"n":"טברסקי, משה צבי מטולנא","f":"מנחם נחום טברסקי","k":"אדמור מטולנא בארה\"ב","bt":"תרנ","bp":"טולנא-פלך קיוב","dt":"תשלב - כה סיון","b":"חתן ר משולם זושא מקרילוביץ (אפטא), ובזיוו\"ש חתן ר שרגא פיביש מזלישטשיק (קוסוב). אדמור בטולטשין, סורוקה, עבר לארה\"ב-תרפד וכיהן כאדמור בפילדלפיה."},{"i":21254,"n":"טברסקי, משלם זושא מטולנא ארהב","f":"מנחם נחום מטולנא","k":"אדמור מטולנא בוסטון","bt":"תרנא","dt":"תשלב - כו אייר","b":"חתן ר ישעיה ברנשטין, היגר לארה\"ב-תרפט והתישב ברוקסברי-מסטשוסס, עבר לבוסטון. בנו ר יצחק אשר מבוסטון."},{"i":21255,"n":"טברסקי, משלם זושא מלויאב","f":"חיים יצחק ממוזיר","k":"אדמור מלויאב בני ברק","bt":"תרעז","dt":"תשמח - יז חשון","b":"תלמיד זקנו - האדמור מטשכוב, ישיבת לובאביץ, סנדז, קראקא, ועוד. חתן ר יעקב מרדכי ברנדווין. עלה לארץ-תרצד ולמד בישיבת \"מרכז הרב\" בירושלים, בתרצו עבר אל זקנו ר יצחק ישעיה מטשחויב. אדמור בבני ברק-תשיט. חיבר \"עץ אבות\"."},{"i":21256,"n":"טברסקי, משלם זושא מרוקסברי","b":"אחיהם של ר דוד מרדכי ור משה צבי, עבר עמם לארה\"ב."},{"i":21257,"n":"טברסקי, מתתיהו","f":"מנחם נחום משטיפנשט"},{"i":21258,"n":"טברסקי, נחום","f":"מרדכי טברסקי","b":"רב בוורשה-תר\"ע"},{"i":21259,"n":"טברסקי, נחום","f":"יצחק טברסקי","dt":"תרמו","b":"אדמו\"ר בשפיקוב"},{"i":21260,"n":"טברסקי, נחום","f":"אהרן טברסקי","bt":"תקע","dt":"תרלא - כד שבט","b":"רב בטשרנובל"},{"i":21261,"n":"טברסקי, נחום יוסף","f":"מרדכי טברסקי","b":"רב-שנת תר\"פ"},{"i":21262,"n":"טברסקי, נחום מלויאב מירופול","f":"ברוך בן ציון מאומאן","k":"אדמור מלויאב-מירופול","b":"חתן ר דוד ממירופול. אדמור מלויאב-מירופול בארה\"ב."},{"i":21263,"n":"טברסקי, נחום ממקרוב","f":"מרדכי","bt":"תקסד","dt":"תריב - א תשרי","b":"חתן ר יוסף מטרטשין בן החוזה מלובלין."},{"i":21264,"n":"טברסקי, נחום משה מקאוועל","f":"זאב וולף מרחמיסטריבק","k":"אדמור מקאוועל","dt":"תשג","dp":"קאוועל","b":"רב בקאוולא. חתן ר יעקב אריה ליב מטריסק. אחיו של ר יוחנן מרחמיסטריבקא. גיסו של ר חיים מאיר מויזניץ. נספה בשואה."},{"i":21265,"n":"טברסקי, נחמן יוסף","f":"זאב מרחמיסטריבקא","b":"חתן האדמו\"ר ר מרדכי הגר מויזניץ."},{"i":21266,"n":"טברסקי, ניסן יהודה ליב מקילץ","f":"דוד ממקרוב","k":"אדמור מקיעלץ-מקארוב","bt":"תרמג","dt":"תש-א - ו אייר","dp":"קראקא - ירושלים","b":"ממשפחת אדמורי צ'רנוביל. חתן ר ליביש מאירטשיק מאפטא. רב בפוקשווינצא, הוגלה ע\"י הרוסים במלחה\"ע ה-I, ואחריה רב בקיוב. עבר לפולין-תרפא והתישב בקילץ, אדמור מקוזמיר בקילץ על מקום חותנו, עבר לקראקא, זמושץ, רב ואדמור בקיעלץ על מקום דודו ר מרדכי מקוזמיר-קיעלץ. היגר לארה\"ב אחר מלחמת העולם ה-I, בהיותו בבולטימור-תרפד הסכים על \"בד קדש\". חזר לפולין. נספה בשואה."},{"i":21267,"n":"טברסקי, פנחס מאוסטילה","f":"מרדכי מרחמיסטריבקה","k":"אדמור מאוסטילה","bt":"תרם","dt":"תשג - יז-ט אייר","b":"חתן האדמור ר ישכר דב מבלז-המהרי\"ד ועבר אליו לבלז. הגיע לירושלים לביקור אצל אביו-תרף. רב ואדמור באוסטילה-תרפג, פשמישל-תרצב. נספה בשואה."},{"i":21268,"n":"טברסקי, פנחס מלונדון","f":"יעקב אריה ליב מטריסק","bt":"תרעח","b":"בן האדמור מטריסק לונדון. חתן ר מנחם מנדל סנדרוביץ."},{"i":21269,"n":"טברסקי, צבי אריה מברדיטשוב","f":"משה מרדכי ממקרוב","dt":"תרצח - כא אייר","b":"חתן ר יחיאל מקרילוביץ (אפטא)."},{"i":21270,"n":"טברסקי, צבי אריה מזלטיפולי","f":"מרדכי יוסף מזלטיפולי","k":"אדמור מצורטקוב","r":"אדמו\"ר מזלאטיפולי - טשורטקוב","bt":"תרן","dt":"תשכח - יח אב","b":"חתן ר ישראל פרידמן מצורטקוב. עבר עם חותנו לוינה בזמן מלחה\"ע ה-I. ניצל מהשואה (לאחר שנשלח לדכאו-תרצח) עלה לארץ-תרצט, סירב לאדמורות שנים רבות, אדמור מצורטקוב-תשיח על מקום גיסו ר שלמה מצורטקוב. חיבר \"הטוב והתכלית\" (נכתב בהשפעת חותנו כנגד דעות גיסו - ר מנחם נחום פרידמן מאיצקן-חתנו השני של ר ישראל מצורטקוב), ו\"אמונה ודעת\".","bk":[["אמונה ודעת",""],["הטוב והתכלית - עיונים",""],["הטוב והתכלית - עיונים, אמונה ודעת",""]]},{"i":21271,"n":"טברסקי, צבי אריה ממקרוב","b":"אדמו\"ר ממאקרוב-תר\"פ"},{"i":21272,"n":"טברסקי, שלום יוסף מטריסק ארה\"ב","f":"מרדכי זוסיא מהוצאלאס","k":"אדמור מטריסק בארה\"ב","bt":"תרמג","dt":"תשה - כה שבט","b":"חתן ר יהושע השל ממונסטרישץ (ליניץ), ובזיוו\"ש חתן ר יוסף דוד מבזילאיה (אפטא), עבר לארה\"ב-[תרפ..] וכיהן כאדמור מטריסק בארה\"ב."},{"i":21273,"n":"טברסקי, שלום יוסף משדה לבן","f":"מרדכי מלויאב","bt":"תרמא","dt":"תשג - ד תמוז","b":"חתן ר משה מרחמיסטריבקה."},{"i":21274,"n":"טברסקי, שלום מאיר מפאלטישאן ני","f":"אברהם מניו יורק","k":"אדמור מפלטישאן נ\"י","b":"אדמור מפלטישאן בניו יורק על מקום זקנו ר אלעזר מפלטישאן."},{"i":21275,"n":"טברסקי, שלום ממאלין","f":"אברהם יהושע השל","k":"אדמור ממאלין בארה\"ב","dt":"תשל - ו אייר","b":"בן האדמור מראדומישל. אדמור ממאלין בארה\"ב, עלה לארץ והתישב בחיפה."},{"i":21276,"n":"טברסקי, שלום מניו יורק","b":"פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":21277,"n":"טברסקי, שלמה","f":"ברוך אשר","b":"רב-שנת תר\"פ"},{"i":21278,"n":"טברסקי, שלמה בן ציון מטשרנוב","f":"ישעיה משלם זושא","k":"אדמור מטשרנוביל","bt":"תרל","dt":"תש - ה-ח תשרי","dp":"קיוב","b":"חתן הגביר ר שניאור זלמן חודרוב מברדיטשוב-חתנו של ר משה מאורזיסטשוב. אדמור בטשרנוביל - בגיל 13! על מקום אביו - ונקרא \"הינוקא מטשרנוביל\", עבר לארה\"ב וחזר. הגיע לארה\"ב אחרי מלחמת העולם ה-I, וחזר לאירופה. הסכים על \"צרור החיים\" - בילגוריי תרעג, \"תו יהושע\" ורשה תרנד."},{"i":21279,"n":"טברסקי, שלמה ממגרוב","f":"דוד","bt":"תרלג","bp":"סקווירא","dt":"תרפא","dp":"קיוב","b":"חתן רא\"ל רוקח מבלז. נהרג בפרעות בקיוב."},{"i":21280,"n":"טברסקי, שלמה מסקווירא","f":"דוד מסקווירא","bt":"תרלג","dt":"תרפא - ז אדר","dp":"קיוב","b":"חתן ר אריה ליב ממגרוב (בלז) נפטר בזמן הפרעות הרעב והמגפות בקיוב (מלחמת האזרחים ברוסיה) ויום היארצייט נקבע ל-ז אדר."},{"i":21281,"n":"טברסקי, שלמה שמואל מטשרנוביל","f":"ברוך אשר מטשרנוביל","k":"אדמור מטשרנוביל נ\"י","dt":"תרצו - כח אד\"א","dp":"ניו יורק","b":"חתן דודו ר ישעיה משולם זושא מטשרנוביל, ובזיוו\"ש חתן ר דן מראדויל השני (זלוטשוב). עבר לארה\"ב והתישב בניו יורק. בנו ר יעקב ישראל מצ'רנוביל."},{"i":21282,"n":"טברסקי, שמואל אברהם אבא ממקרוב","f":"משה מרדכי ממקרוב","k":"אדמור ממקרוב ויניפג","bt":"תרמה","dt":"תש - יד סיון","b":"חתן דודו ר דוד ממקרוב אדמור בויניפג-קדנה."},{"i":21283,"n":"טבשונסקי, יעקב מאסטרין","f":"שלמה מאיישישוק","k":"בעל אור השכל","bt":"תרלג","bp":"איישישוק","b":"תלמיד ישיבות סלובודקה, וולוזין, ותלמיד ר צבי הירש מה יפית מאיישישוק. חתן ר יעקב צבי שפירא בעל \"תפארת יעקב\". רב בנובידוואר ישן-מחוז לידא-תרן, אוסטרין-פלך וילנא על מקום חותנו. נסמך מאת: ר צבי הירש רבינוביץ, ר משה דנישבסקי. חיבר גם \"אמרי יעקב\", \"נוה יעקב\", ועוד. ר\"מ בקיבוץ בחורים בעירו. פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט."},{"i":21284,"n":"טגר, שלמה יהודה מסנוק","f":"נתן מסנוק","k":"בעל על הרי בתר","bp":"סנוק","dt":"תשנט","b":"חסיד ללוב. ניצל מהשואה. עבר ללונדון. חתן ר יצחק גרשון מצגר. חיבר \"על הרי בתר\" לונדון תשלה."},{"i":21285,"n":"טדינר, יצחק מרדכי מקמינקא","b":"רב בקמינקא-תרמו."},{"i":21286,"n":"טדישי אשכנזי, יצחק רפאל מאיטלי","k":"בעל ויען יצחק","bt":"תקפג","bp":"אנקונה","dt":"תרסח","b":"תלמיד ר אברהם דוד חי ויואנטי מאנקונה, רב בקורפו, אנקונה-תרלז על מקום רבו. ירש את ספרית רבו וממנה הו\"ל \"זרע יצחק\" שו\"ת הר\"ן, ועוד. חיבר \"ויען יצחק\" ונדפס בספר רבו - \"כתבי אברהם דוד חי\" טירנוי תרצב."},{"i":21287,"n":"טהאלינגרין, אליעזר מפוזנא","b":"רב בפוזנא."},{"i":21288,"n":"טהילא, אמאליא מוינה","k":"בעל דיא בילדונג דעס","b":"מנהלת בית ספר לבנות בברסלוי, וינה. חיבר ספרים בנושאי חינוך. חיברה גם: \"דאס צוזאמען וירקען פאן הויז אונד שולע (הבית ובית הספר ופעולתם זה על זה לטובת החינוך)."},{"i":21289,"n":"טהענען, שמשון מבארלאד","f":"משה מפולטישן","k":"בעל מדות חכמים","bt":"תריז","bp":"פאלטישען","b":"מצאצאי ר שמשון מאוסטרופולי. נסמך מאת: ר שבתי סגל מבוהוש, מו\"ץ בפאיעשט, רב בברלד(=בארלאד)-רומניה-תרמט. חיבר גם \"זיו השמש\", ועוד."},{"i":21290,"n":"טואה, עמרם מתלמסאן","f":"אלעזר","b":"מחכמי תלמסאן-אלגיר, ונזכר ב\"יכין ובועז\". בנו ר מרזוק, וקרובו ר אברהם ן טואה שנזכר בתשבץ."},{"i":21291,"n":"טוב ן, יצחק איזיק","b":"רב בוועטקא"},{"i":21292,"n":"טוב עלם, יוסף הספרדי","f":"אליעזר","bt":"צה","bp":"ספרד","b":"מחכמי ספרד, בשנת קלו היה בקנדיא (כרתים) שם העתיק את פירוש ר שלמה בן יעיש על האבן עזרא. נסע למצרים ואחר כך עלה לירושלים, עבר לדמשק ושם המריצו ר דוד בן יהושע הנגיד (מצאצי הרמבם) להשלים את עבודותו על האבן עזרא ולשם כך חזר לירושלים. פירושו נדפס בשם \"אהל יוסף\" אמשטרדם תפב, ואחר כך בשמו \"צפנת פענח\", כן חיבר ספר על חשבון תקופות ומולדות בכתב יד."},{"i":21293,"n":"טוב עלם, יוסף מצרפת","f":"שמואל","k":"בעל תקון שטרות","b":"מחכמי צרפת-ד'תתכ, מפרש, פוסק,פייטן, מרביץ תורה בלימורגש(=לימורג), אניוב(=אניו). נזכר אצל רש\"י, בעלי התוספות."},{"i":21294,"n":"טוב, עזריאל משקוד","f":"צבי הירש","b":"חתן ר אליעזר רבינוביץ ממינסק."},{"i":21295,"n":"טוב, צבי הירש משקוד","b":"גביר מחכמי שקוד. בנו ר עזריאל-חתן ר אליעזר רבינוביץ ממינסק."},{"i":21296,"n":"טובולונסקי, שלמה","f":"חיים","bp":"קלואריה-ליטא","b":"עו\"ד מפורסם, וקובע עתים לתורה. פטריוט פולני. פרסם מאמרים בעתוני התקופה. מקורב לר יצחק אלחנן ספקטור שנהג להתארח באחוזתו בימות הקיץ. זקנו של חיים ארלוזרוב."},{"i":21297,"n":"טובי, אברהם הלוי ממרוקו","b":"מחכמי ארבאט-מרוקו-תק'."},{"i":21298,"n":"טובי, אברהם משלוניקי","dt":"שלז","dp":"שלוניקי","b":"גביר עשיר מחכמי שלוניקי. שאלה ממנו לרשד\"ם."},{"i":21299,"n":"טובי, דניאל ממכנאס","b":"דיין במכנאס-שנות ה-תר', חתם עם ר יעקב בירדוגו בענין עזבון השר מרדכי אשריקי הי\"ד."},{"i":21300,"n":"טובי, יהודה משלוניקי","dt":"רצא","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":21301,"n":"טובי, יוסף מפאס","dt":"שה - אחרי","dp":"פאס?","b":"תלמיד ר משה חלאווה. רב בפאס, חתם על תקנות-שה, נזכר ב\"עץ חיים\" לר חיים גאגין."},{"i":21302,"n":"טובי, יעקב מאישקופיה","bp":"שלוניקי","b":"ש\"ץ באישקופיה-שנות ה-ש'."},{"i":21303,"n":"טובי, יצחק מדמשק","b":"רב בדמשק בעל ספריה גדולה."},{"i":21304,"n":"טובי, ישעיה ממכנאס","b":"מחכמי מכנאס."},{"i":21305,"n":"טובי, מאיר מצפת","b":"מחכמי צפת, בשנת תקפו בשליחות במרוקו."},{"i":21306,"n":"טובי, משה ממכנאס","dt":"תקפד - כסלו","b":"תלמיד ישיבת ר משה מאימראן במכנאס. מחכמי מכנאס, חתם על הסכמה-תקסד, ועל פס\"ד-תקף עם ר רפאל בירדוגו. נזכר ב\"משפטים ישרים\", וב\"שופריה דיעקב\"."},{"i":21307,"n":"טובי, רפאל אלעזר הלוי ממרוקו","k":"בעל פקודת אלעזר","bt":"תקפה","bp":"רבאט-מרוקו","dt":"תרמו - כב אד\"א","dp":"ירושלים","b":"מחכמי מרוקו, תלמיד ר סעדיה מארג'י. עלה לירושלים-תריח עם חבריו ר דוד ן שמעון - הצוף דב\"ש ור יוסף ארוואץ, דרך גיברלטר ומשם שלח שאלותיו לר יצחק ן וואליד - שהזכירו ב\"ויאמר יצחק\". ראש ישיבת עדת המערבים בירושלים, ותיקן תקנות רבות, והגן על מנהגי מרוקו בירושלים. בראש העדה-תרם על מקום חברו הצוף דב\"ש. בנו ר יעקב חי."},{"i":21308,"n":"טוביאנה, אברהם מאלגיר","f":"שלום","k":"בעל חסד לאברהם","dt":"תקנג","b":"רב ומקובל באלגיר-תקל בזמן ר יעקב בן נאים, ליוורנו. חיבר פירוש לתפלות בדרך הסוד והיה בראש חבורת מקובלים מאלגיר ששינו את נוסח התפלה לנוסח האר\"י. חיבר \"חסד לאברהם\", \"אשל אברהם\", \"בטרם בוקר\", ועוד. הו\"ל \"יכין ובועז\" ועוד. חלק מכתביו אבדו - ובהם \"עץ הדעת\", ועוד."},{"i":21309,"n":"טוביאנה, אליהו מאלגיר","dt":"תרע - אחרי","b":"פייטן, רב ודיין בקצמטינא, ראב\"ד על מקום ר אליהו עלוש שעלה לארץ. הסכים על \"כג\"ן הירק\", \"פתשגן הכתב\". פיוט ממנו ב\"שפתי רננות\"."},{"i":21310,"n":"טוביאנה, יעקב מאלגיר","k":"בעל מגיד ליעקב","dt":"תרי.. - בערך","b":"רב באלגיר, עבר לליוורנו. מדפיס-תקף ומגיה ספרים. חיבר \"מגיד ליעקב\" (כמובא ב\"לשון חכמים\"). בנו ר משה יהושע - מדפיס-תקצא עד תרכא."},{"i":21311,"n":"טוביאנה, יצחק מאלגיר","bt":"תקן","dt":"תרך - בערך","b":"רב ודיין בקצמטינא. נזכר בהקדמה ל\"ויגד לאברהם\" לר חיים חלימי, וב\"זבחים שלמים\". הניח כתבים רבים ומהם נדפס \"יפאר ענוים\" תל אביב תשמז."},{"i":21312,"n":"טוביאנה, מאיר מאלגיר","f":"אליהו מקצמטינא","dt":"תרעה","dp":"צרפת","b":"רב וסופר מקצמטינא. תרגם עם ר דוד הכהן - לערבית יהודית את \"עשיר ורש\" לר בן ציון אלקלעי ונדפס בשם \"עשיר ורש - אלעשיר ולאמזלוט\" ליוורנו תרסג. נהרג במלחה\"ע ה-I בחזית בצרפת."},{"i":21313,"n":"טוביאנה, מסעוד מאלגיר","bt":"תכ","dt":"תץ - בערך","b":"רב באלגיר, ומחותמי החרם נגד השבתאי נחמיה חיון. ונזכר ב\"מלחמה לה'\" לר משה חאגיז."},{"i":21314,"n":"טוביאנה, משה יהושע מליוורנו","f":"יעקב מאלגיר וליוורנו","b":"מדפיס בליוורנו - תקצא-תרכח."},{"i":21315,"n":"טוביאנה, נסים מתונס","b":"רב בסוסה-תונס-תרכו, עם ר חיים לומברוזו. נזכר ב\"הליכות עולם\" לר יעקב גדישא מג'רבא."},{"i":21316,"n":"טוביאנה, נתן מאלגיר","bt":"תקל","dt":"תר - בערך","b":"רב בקצמטינא. בית נכסת ע\"ש. נזכר ב\"ספר קהלת צפרו\" ירושלים תשלה."},{"i":21317,"n":"טוביאנה, רפאל מאלגיר","bt":"תקעה","dt":"תרם - בערך","b":"רב בקמצטינא. ר\"מ בישיבת \"עץ חיים\" בקצמטינא. מתלמידיו - ר אברהם חלימי. מתורתו ב\"יפאר ענים\" - תל אביב תשמז."},{"i":21318,"n":"טוביאנה, שלמה מתונס","f":"דוד","k":"בעל כרם שלמה","b":"הו\"ל תיקון הלולה רבה - ליוורנו תקעט."},{"i":21319,"n":"טוביאס, אברהם אבלי מפרצאווי","b":"רב בפרצאווי-תרלה, הסכים על חשק שלמה לר משה שלמה לוינזון."},{"i":21320,"n":"טוביאס, אהרן הרופא","bp":"פולין","dt":"תקמב","dp":"האזנפוט","b":"רופא, ישב גם בהאזנפוט-קורלנד. הניח כתבים בעניני רפואה."},{"i":21321,"n":"טוביאס, חיים מקשאנוב","f":"זלמן יקותיאל","bt":"תרמט","bp":"פודגורזע","dt":"תשג","b":"רב בברלין. ראש ישיבת רדמוסק בקשאנוב(=קרשנוב). פרסם חדושיו ב\"כתר תורה\". נספה בשואה. ספר זכרון לכבודו על ידי נכדו ר חיים - \"כל הכתוב לחיים\" ובו גם חדושי תורה ממנו. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט. מעורכי \"המאור\" - ברלין תרצג, \"המאור\" - תל אביב תרצה."},{"i":21322,"n":"טוביאס, שלום צבי משאוולן","f":"אברהם יהושע מפוקרוי","b":"ראש ישיבה בשאווילן-תרנז."},{"i":21323,"n":"טוביה","b":"מגדולי בעלי התוספות-ד'תתק\"ט"},{"i":21324,"n":"טוביה - מדפס בוילנא","f":"אברהם אבלי","b":"מדפיס בוילנא-תקנט עם שותפו ר אריה ליב בן טוביה."},{"i":21325,"n":"טוביה בועז מהאג","b":"גביר בהאג-תקלז, בזמן ביקור החיד\"א."},{"i":21326,"n":"טוביה האשורי","b":"חכם קדמון הנזכר אצל ר ששת הרופא בן יפת מחלב-ה'ן."},{"i":21327,"n":"טוביה הבקי הקראי","f":"משה האבל","k":"בעל וזאת התורה","b":"מחכמי הקראים הראשונים - שנות ה-ד'תר. חיבר פיוט \"טהור עין שפתי תפתח נא\"."},{"i":21328,"n":"טוביה הכהן הרופא נראל מאנוסקרי","f":"משה ירמיהו מנראל","k":"בעל מעשה טוביה","bt":"תיג","bp":"מיץ","dt":"תפט","dp":"ירושלים","b":"אביו היה רב בנראל בעל \"ברכת טוב\", בגזרות תח ברח לעיר מיץ וכיהן שם כרב, ולאחר פטירת אביו נישאה אמו לר שמשון בכרך (מוזכר בספר \"חוות יאיר\" שם כתוב כי ר טוביה היה אחי החורג). נסע עם אחיו הגדול ר אליעזר ללמוד בישיבת קראקא, נסע עם חברו ר גבריאל הרופא ללמוד רפואה באוניברסיטה של פרנקפורט, ואחר כך למד רפואה ותורה בפדובה יחד עם חברו ר גבריאל רופא אצל גדולי פדובה שהיו רופאים ותלמידי חכמים - ר יצחק חיים כהן מהחזנים, ור שבתי חיים מריני ור שלמה קוניאן. לאחר מיכן נסע לקושטא ושימש כרופאו של הסולטן. בשנת תפד עלה לירושלים. ר שמעון וולף ורטהיימר פנה אליו לירושלים ובקשו חוות דעתו כיצד להיטיב עם אנשי ירושלים. זקנו שבא מפולין - היה גיסו של בעל \"ראשית חכמה\". חיבר \"מעשי טוביה\" כדי לפתוח בפני עמו את שערי החכמות ובגלל טענות הגויים באוניברסיטה שהחכמה נטלה מן היהודים ונתנה לגויים. הספר זכה להסכמות רבות וביניהם ר שלמה קוניאן רבו של המחבר. אחיו חורגו - ר חיים יאיר בכרך בעל \"חוות יאיר\", שהביא בספרו כמה מחדושי ר טוביה."},{"i":21329,"n":"טוביה הכהן מטאפנר","b":"רב בטאפנר-הונגריה. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":21330,"n":"טוביה הכהן מסוקולוב","b":"רב בסוקולוב."},{"i":21331,"n":"טוביה הלוי מצפת","f":"אברהם","k":"בעל חן טוב","bp":"צפת","dt":"שעח","dp":"צפת","b":"ממנהיגי וחכמי ישראל בדור שלאחר \"הבית יוסף\", מקובל, תלמיד ר שלמה סאגיס, ותלמיד חבר של ר יוסף מיטרני, חיבר \"חן טוב\" ונציה שסה. חתם בין חכמי צפת בשנת שסח, תשובה ממנו בשות מהריט,"},{"i":21332,"n":"טוביה העובד המעתיק - הקראי","f":"משה","k":"בעל וזאת החיה","b":"חכם קראי - שנות ה-ד'תת. חיבר פיוטים ונמצאים בסדור הקראי ובהם \"אלקים מכל אומה אהבתנו\"."},{"i":21333,"n":"טוביה הצרפתי","dp":"צפת","b":"מחכמי צפת, בזמנו של ר נפתלי אשכנזי בעל \"אמרי שפר\" בשנים שס-שסב. ר טוביה נהרג בצפת"},{"i":21334,"n":"טוביה יצחק מוארשוי וירושלים","f":"אברהם","dt":"תקצח - יג סיון","dp":"ירושלים","b":"מחכמי ירושלים. חתנו - ר אליעזר מרדכי."},{"i":21335,"n":"טוביה מאמדור","b":"רב באמדור"},{"i":21336,"n":"טוביה מבורגוני","b":"מגדולי הפוסקים בתקופת הראשונים-ד'תתק\"פ"},{"i":21337,"n":"טוביה מוילנא","f":"ישראל","dt":"תקלז - ל תשרי","dp":"וילנא","b":"מראשי קהילת וילנא."},{"i":21338,"n":"טוביה מוילנא","f":"אריה אבלי רי\"ט","dt":"תקפב","dp":"וילנא","b":"מראשוני המדפיסים בוילנא יחד עם שותפו ר אריה ליב בן טוביה."},{"i":21339,"n":"טוביה מוילנא","f":"אורי","b":"דיין בוילנא, חתם-תץ עם ר יהודה מטיקטין."},{"i":21340,"n":"טוביה מוינה","b":"מגדולי בעלי התוספות-ד'תתקע\"א"},{"i":21341,"n":"טוביה מויענע","f":"אליהו","b":"מחכמי אשכנז בעיר ויענע (במדנית בורגונד), חברו של ר יצחק בן אברהם (הריצב\"א). חיבר פירוש לתורה, פיוטים. מתלמידיו - ר אברהם בן אפרים בעל ספר המצוות. נזכר במרדכי."},{"i":21342,"n":"טוביה מזאגר","b":"רב בזאגר"},{"i":21343,"n":"טוביה מזולקוא","f":"יצחק","b":"מחכמי זולקוא, חתם-תסה על תקנת הקהלה, חתם-תעד על פסק דין עם ר נתן מזולקוא, אליעזר ליפמן מלובלין, ועוד."},{"i":21344,"n":"טוביה מטולטשין וירושלים","f":"שלמה מטולטשין","b":"אביו ר שלמה מתלמידי הגרא שעלה לירושלים, לאחר פטירתו ובעקבות מכתב וירושה שקיבל מאביו על ר טוביה לירושלים, בדרכו נפל בידי שודדי ים ונמכר לעבד בתורכיה, שוחרר באופן פלאי ועלה לירושלים. חתנו - ר מרדכי (סלומון) בן ר אברהם שלמה צורף."},{"i":21345,"n":"טוביה מטרטקוב","b":"אב\"ד טרטקוב לפני ר יהושע השל באב\"ד - נזכר בשו\"ת \"צור יעקב\"."},{"i":21346,"n":"טוביה מירושלים","f":"דניאל","b":"מחכמי ירושלים, בשנת ד'תת (1040). חותם טוביה השלישי בחבורה בן דניאל החבר. היה מבית דינו של ר שלמה בן יהודה גאון. נמצא ברמלה שטר משנת ד'תתכה שחתום בו שלמה בר טוביה השלישי בחבורה וכנראה שהוא בנו."},{"i":21347,"n":"טוביה מירושלים","f":"יהודה ליב בן הגר\"א","dt":"תרכח - יד כסלו","dp":"ירושלים","b":"נכד הגר\"א. מחכמי ירושלים."},{"i":21348,"n":"טוביה ממגנצא או קאשטוריה","f":"אליעזר הגדול","k":"בעל לקח טוב","bt":"ד'תתי","bp":"קאשטוריא","b":"מגדולי החכמים הראשונים במגנצא-ד'תתס, ולדעת ר שלמה בובר - ישב בעיר קאשטוריה-בולגריה. חיבר \"לקח טוב\" - המכונה פסיקתא זוטרתא - ובו גם קורות הגזרות על בני ישראל בארצות אשכנז - ד'תתנו. חיבר גם פיוטים ובהם הסליחה \"אהיה אשר אהיה\". ב\"זכרון שלוניקי\" נכתב: תלמיד ר שמשון, רב בשלוניקי. חיבר פיוטים ולקח טוב, מתלמידיו ר מאיר בעל \"אור עינים\", ור יהודה - שהתנצר ונקרא ליאון מונגוס והיה בישוף בבולגריה."},{"i":21349,"n":"טוביה מסמבור","f":"ליפא מסאמבור","b":"רב בסאמבור-תר\"כ"},{"i":21350,"n":"טוביה מצרניגוב","b":"רב במינא(צרניגוב)-תר\"נ"},{"i":21351,"n":"טוביה מצרפת","b":"מחכמי צרפת ד תתקן-תתקע, מובא בסמק ובתשבץ קטן, כאשר נפטר הריצבא וציוה ר טוביה לקברו בטלית מצויצת וחלק עליו ר יעקב מפרוינץ. הגיע לארץ בשנת ד תתקע (1210) יחד עם ר יונתן מלוניל ור סעדיה. מוזכר בתוספות ובמרדכי. מתלמידיו ר אמרי בעל \"שערי דורא\", ורבינו פרץ, ובסמ\"ק מופיע \"ומורי ר טוביה חולק וכו\"."},{"i":21352,"n":"טוביה משערשוב","f":"אשר בן יצחק משארשוב","dt":"תרלה - יח אד\"ב","b":"מו\"צ בשארשוב. נספד מאת ר יהושע לאנג מסומיאץ."},{"i":21353,"n":"טוביס, יוסף מארה\"ב","k":"בעל זכרו יהודה ויוסף","b":"רב בארה\"ב-תרצט."},{"i":21354,"n":"טובלסקי, אהרן","f":"דוד","k":"בעל בית דוד - כת\"י","bt":"תרכט","b":"נכד ר מאטיא מקאלעהרקע. רב במזריצקה(=מעזעריצקע)-פלך קיוב-תרנב. נסמך מאת: ר משה מהרדישץ, ור ליב מקארסאן. חיבר תשובות וכללים בשם \"בית דוד\" - בכת\"י."},{"i":21355,"n":"טוגנהולד, זאב וולף מוילנא","f":"ישעיה ירוסלב","dt":"תרכד - ו אד\"ב","dp":"וילנא","b":"תלמיד בית המדרש למדעים בברסלוי. צנזור בוילנא וסבל מהלשנות לשלטונות (שהוא מיקל בצנזורה), וחיבר ספר להגן על מעשיו ולהגן על אמונת ישראל סופריו וחכמיו, חיבר גם \"תרצה\", אבענבילד ואטעס\", פועל צדק\", ועוד. בסוף ימיו מורה בביהמ\"ד לרבנים בוילנא."},{"i":21356,"n":"טוגנהולד, יעקב מוארשא","f":"ישעיה ירוסלב","k":"בעל מלין העברי","bt":"תקנד","dt":"תרלא - כט ניסן","dp":"וארשא","b":"צנזור בוארשא. חיבר ספרים ותרגם ספרים עבריים לפולנית. לתולדותיו ב\"מגיד משנה\" לחכם מרדכי ויסמן חיות."},{"i":21357,"n":"טוגענד, אריה ליב","b":"פרסם מאמרים ב\"הלבנון\" - גורליץ תרפח."},{"i":21358,"n":"טודסקו, הרמן מפרשבורג ווינה","bp":"פרשבורג","b":"בנקאי עשיר בוינה. תרם להקמת מוסד לילדים בפרשבורג-תרד ובו גם בי\"ס \"פרימער שוהלע\" - ביזמת אדולף ניישטט מראשי הריפורמים - ובגלל המחלוקת שהתעוררה בקהלה בעקבות טקס הפתיחה הריפורמי - ניסו הריפורמים בפעם הראשונה לפרוש מהקהלה."},{"i":21359,"n":"טודרוביץ, משה בצלאל מיפו","bt":"תרט","bp":"ליטא","dt":"תרסז","b":"עלה לארץ-תרנא והתישב ביפו, ממיסדי הת\"ת והישיבה, וסייע לר נפתלי הרץ הלוי רבה של יפו. בנו - ההסטוריון דוד תדהר."},{"i":21360,"n":"טודרוס הזקן מפליבנה-בולגריה","b":"רב בפליונא(=בפילבנה)-ליד סופיה, - שנות ה-ש' בערך עם חבריו ר זכריה ורנק אשכנזי, ואחיו ר דוד ורנק שהתישב בצפת."},{"i":21361,"n":"טודרוס הכהן מפודהייץ","f":"[דוד]","b":"רב בפודהייץ-תריח. נכד בעל הקצות."},{"i":21362,"n":"טודרוס הכהן מראש פינה","f":"יוסף אריה הכהן","bt":"תריא","bp":"רומניה","b":"תלמיד ישיבת מאנאטשי-רומניה. עלה לארץ והיה מנהל כולל רומניה בטבריה. רב בראש פינה-תרסה."},{"i":21363,"n":"טודרוס הנשיא מנרבונה","f":"קלונימוס","b":"גביר ונשיא בנרבונא-ה'ן. נזכר אצל המאירי. הסכים עם ר אבא מרי בן יוסף הירחי במחלוקתו עם הפילוסופים."},{"i":21364,"n":"טודרוס מארלדי(=ארלעס)-פרובנס","b":"מחכמי פרובאנס-ה'צז. תרגם את באור אבן רשד לספר ההלצה, ועוד."},{"i":21365,"n":"טודרוס מגירונא","f":"יצחק","k":"דון טודרוש איציק","b":"מחכמי ספרד,רב בגירונא,בתקופת הרשב\"א והרא\"ש"},{"i":21366,"n":"טודרוס מהורדנא","dt":"תנד - ה תשרי","dp":"הורדנא","b":"מחכמי הורדנא, מראשי הקהלה."},{"i":21367,"n":"טודרוס ממצרים","b":"רב במצרים ונזכר אצל ר חיים חברייא."},{"i":21368,"n":"טודרוס מנרבונא","f":"משה הפרנס","b":"מגדולי חכמי דורו בנרבונא-שנת ק'"},{"i":21369,"n":"טודרוס מסנטין צפת וטבריה","b":"מראשי הקהלה בצפת וטבריה, חתם-תקפט על שטר פשר."},{"i":21370,"n":"טודרוס מסניאטין וטבריה","b":"תלמיד ר זאב וולף מטשרני. עלה לארץ עם רבו וחתם על כתבי שליחות רבים."},{"i":21371,"n":"טודרוס מקאבילון-פרובאנס","k":"בעל שעורי ההרכבות","b":"רב בקבילון-פרובאנס-שנות ה-ק'."},{"i":21372,"n":"טודרוס מראסיין","b":"רב בראסיין"},{"i":21373,"n":"טודרוס מרובנא","f":"צבי","k":"בעל הלכה פסוקה","b":"המגיד ממזריטש הסכים על ספרו (זו ההסכמה היחידה של המגיד ממזריטש)."},{"i":21374,"n":"טודרוס מריטעווע","f":"אליהו ריטווער","b":"רב בריטעווע(=ריטובה) על מקום אביו. בנו ר אליעזר - נפטר בחייו, ונכדו ר יצחק איזיק אברך."},{"i":21375,"n":"טוואה ן, אברהם מאלגיר - הזקן","f":"יעקב","k":"בעל שו\"ת","bt":"רע","dt":"שמ","b":"מצאצאי הרמב\"ן והתשב\"ץ. דרשן, פייטן, פוסק וראש ישיבה באלג'יר-רע-שמ. חיבר שו\"ת ב-12 קונטרסים וקראם על טורי אבני החושן. מתלמידיו ר צמח בן שמעון דוראן. חיבר פיוטים שנכנסו לקרוב\"ץ מנהג אלגיר ובין פיוטים \"מי כמוך\" לפורים אדום. רוב תשובותיו אבדו בים בדרכו להדפיסם באיטליה, ומקצתם ב\"חוט המשולש\". בית כנסת על שמו היה קיים שנים רבות באלגיר."},{"i":21376,"n":"טוואה ן, אברהם מאלגיר - הנכד","f":"יהודה","bt":"של","dt":"ת","b":"מצאצאי התשב\"ץ. רב באלג'יר. העתיק את שו\"ת זקנו."},{"i":21377,"n":"טוואה ן, יעקב מאלגיר","f":"אברהם","bt":"רמ","dt":"שי","b":"רב באלגיר. העתיק מחזור תפילה ומסרו לבנו ר אברהם."},{"i":21378,"n":"טוואה ן, מרזוק מאלגיר","f":"עמרם בן אליעזר","bt":"רי","dt":"רפ","b":"תלמיד ר יהודה כלץ. רב בתלמסאן, בזמן ר שמעון בן הרשב\"ש שהזכירו ב\"יכין ובועז\". חיבר פיוטים בעברית וביהודית ערבית."},{"i":21379,"n":"טוויג, אברהם","f":"דוד","b":"דיין בבצרה-תק\"ס"},{"i":21380,"n":"טוויל, אהרן","f":"משה","k":"בעל מראי חיים","bt":"תרפו","bp":"חלב","dt":"תשמח - יז תמוז","dp":"ארץ ישראל","b":"חיבר \"מראי חיים\""},{"i":21381,"n":"טוויל, אהרן הכהן","f":"אליהו עלי","k":"בעל ישכר וזבולון","bp":"חלב","dt":"תרעו - כו סיון","dp":"ירושלים","b":"עלה לירושלים, חיבר \"יששכר וזבולון\""},{"i":21382,"n":"טוויל, אהרן מעזה","b":"סופר מחכמי עזה-תס."},{"i":21383,"n":"טוויל, חיים הרופא מקושטא","b":"רופא ומדפיס בקושטא-תעו אצל יעקב בן חיים."},{"i":21384,"n":"טוויל, חיים מחלב","f":"עזרא עלי הכהן","k":"בעל מצא חיים","bp":"חלב","dt":"תשב - יב טבת","b":"למד תורה בארם צובה, רב קהלת יוצאי חלב בניו יורק, עלה לירושלים-תרצז, דיין, חיבר \"מצא חיים\" דרשות"},{"i":21385,"n":"טוויל, חיים ממצרים","f":"משה","b":"רופא מחכמי מצרים. חתן ר אברהם הלוי בעל \"גינת ורדים\", וירש את רכוש חותנו ואת כתביו."},{"i":21386,"n":"טוויל, יצחק מטיבולי ושלוניקי","dt":"רצז - א ניסן","dp":"שלוניקי","b":"מחכמי שלוניקי. ממשפחה מאיטליה."},{"i":21387,"n":"טוויל, משה הכהן מירושלים","f":"אליהו","dt":"תרפז - ז אד\"ב","b":"מחכמי ירושלים, עסק בתורה מתוך הדחק עד שהתגלה מצבו לחבריו וניסו לעזור לו. נספד ע\"י ר יוסף ידיד הלוי."},{"i":21388,"n":"טוויל, משה מחלב","bt":"תרנו","bp":"חלב","dt":"תשלז","dp":"תל אביב","b":"רב בחלב וראש ישיבת \"דגל תורה\". מתלמידיו ר יצחק שחיבר, ר יצחק זעפרני ועוד. נלחם בביה\"ס תחכמוני שנפתח בחלב עד שנסגר. עלה לארץ."},{"i":21389,"n":"טוויל, משה עילי הכהן מחלב","dt":"תרע - י שבט","dp":"ירושלים","b":"מחכמי חלב, עלה לירושלים. נספד ע\"י ר יוסף ידיד ב\"שארית יוסף\"."},{"i":21390,"n":"טוויל, עזרא עלי הכהן מחלב","k":"בעל עט סופר","dt":"תרס - כז אד\"ב","dp":"חלב","b":"רב ודיין בחלב."},{"i":21391,"n":"טויב, אברהם מרדכי שלום מסאסוב","f":"יהודה צבי מרוזדול","k":"אדמור מסאסוב","bt":"תרלה","dt":"תרצז - כד אדר","b":"מצאצאי האדמור ר יצחק איזיק טויב מקאליב. חתן האדמור ר שלמה מייער מסאסוב. אב\"ד פמורן-תרסו. אדמור מסאסוב בלמברג-תרעט על מקום חותנו. רב ואדמור בסאסוב-תרפו. מלחין."},{"i":21392,"n":"טויב, אהרן צבי (לנדא) ממונקטש","dt":"תרמג - כ טבת","b":"תלמיד ר צבי הירש מזידיטשוב ור בעריש מאלסק. היה שו\"ב בכפר בריד, עבר למונקאטש. מצאצאיו ר עמרם טויב ממוז'אי-בריד בניו יורק."},{"i":21393,"n":"טויב, אהרן צבי מבני ברק","b":"רב שכונת קרית עמל."},{"i":21394,"n":"טויב, אליעזר","f":"יהודה יחיאל טויב","b":"רב בראזלא"},{"i":21395,"n":"טויב, אליעזר צבי מסמורזשע","f":"משה מקאליב","b":"רב בסמורזשע-תרצז. חתן ר אלתר ישכר ספרין האדמור מאלטשטט."},{"i":21396,"n":"טויב, אליעזר צבי מרוזדול","f":"יהודה יחיאל מרוזדול","dt":"תש..","b":"מצאצאי האדמור ר יצחק איזיק טויב מקאליב. חתן ר ישראל ניהויז מלמברג. נספה בשואה. פרסם מאמרים ב\"קבוצי בחורים\" - מארגרטן תרצג."},{"i":21397,"n":"טויב, אליעזר שלמה","f":"יחזקאל מקוזמיר","k":"אדמור מוולומין","b":"אדמו\"ר בוולומין"},{"i":21398,"n":"טויב, אליעזר שלמה מוואלמין","f":"אפרים מקוזמיר","k":"אדמור מקוזמיר בואלמי","bt":"תרל","dt":"תרצח - כג תמוז","b":"מצאצאי האדמור ר יחזקאל מקוזמיר. אדמור בוואלמין, עבר לוארשא בזמן מלחה\"ע ה-I. בעל כשרון נגינה. בנו ר יעקב אריה ראב\"ד ביבלונא."},{"i":21399,"n":"טויב, אפרים מקוזמיר","f":"יחזקאל מקוזמיר","k":"אדמור מקוזמיר","dt":"תרסד - ד אב","b":"חתן ר נתן דוד משידלובצא (שושלת פשיסחא). רב ואדמור בשינאווה, קוזמיר,בלוינא, נדרזין,יבלונא, פרגה. מתורתו בספר \"אמרי צבי\" לבנו ר ירחמיאל צבי משינאווא."},{"i":21400,"n":"טויב, דוד דוב מדוברזינק","k":"בעל בנין דוד","b":"מחסידי אלכסנדר, רב בדאברזניק-תרכ. פרסם מאמרים ב\"בית ישראל\" - לודז תרץ, \"כרם בית שמואל\" - פיעטרקוב תרצג."},{"i":21401,"n":"טויב, דוד צבי מואלמין","f":"אליעזר שלמה מואלמין","b":"מצאצאי האדמור ר יחזקאל מקוזמיר."},{"i":21402,"n":"טויב, דוד צבי מניישטט","f":"יחזקאל מקוזמיר","k":"אדמור מקוזמיר","bt":"תקסט","dt":"תרמג - ו תמוז","b":"מגדולי חסידי קוצק. סירב לאדמורות אחר פטירת אביו האדמור מקוזמיר, והחל לכהן אחר פטירת רבו האדמור מקוצק-תריט. חיבר \"חמדת דוד\"-\"קונטרס המועדים\". בנו יחידו ר משה יוסף נפטר בחייו - כה חשון תרכז.","bk":[["חמד צבי - אבות",""],["חמדת דוד - עה\"ת",""]]},{"i":21403,"n":"טויב, דוד שלמה מסטרי","f":"פנחס חיים מרוזדול","dt":"תש..","b":"מצאצאי האדמור ר יצחק איזיק טויב מקאליב. חתן דודו ר משה מקלאיב. נספה בשואה."},{"i":21404,"n":"טויב, חיים בנימין מזוואלין","f":"שמואל אליהו מזוואלין","k":"אדמור מזוואלין -ורשא","dt":"תרצא - כח טבת","b":"נכד האדמור ר יחזקאל מקוזמיר. עבר לווארשא וכיהן כאדמור שם."},{"i":21405,"n":"טויב, חיים יחזקאל מאוזרוב","f":"ישראל ממודזיץ","k":"אדמור מאוזרוב","dt":"תרצח - ג אב","b":"מצאצאי האדמור ר יחזקאל מקוזמיר. אדמור באוזרוב-תרץ. בנו היחיד ר צבי הירש - נספה בשואה."},{"i":21406,"n":"טויב, חיים ירחמיאל מזוואלין","f":"משה אהרן מזוואלין","k":"אדמור מזוואלין בורשא","dt":"תשב","dp":"גיטו וארשא","b":"חתן ר פנחס מקינצק (שושלת פשיסחא). אדמו\"ר בזיכלין בחיי אביו, מלאווה, אדמור חסידי זוואלין בוארשא אחר פטירת אביו. מנגן מופלא והלחין ניגונים רבים. נספה בשואה."},{"i":21407,"n":"טויב, חיים מקוזמיר","f":"יחזקאל מקוזמיר","b":"רב בקוזמיר-תר\"ל"},{"i":21408,"n":"טויב, חנוך הניך מלינסק","f":"יהודה יחיאל מרוזדול","dt":"יט תשרי","b":"רב בלינסק-תר\"צ. נספה בשואה."},{"i":21409,"n":"טויב, חנוך הניך מסאסוב","f":"אברהם מרדכי שלום","k":"בעל עיר חנוך - תשלח","dt":"תש..","b":"מצאצאי האדמור ר יצחק איזיק טויב מקאליב. רב בקרעצקי-תרפ.. רב ואדמור בסאסוב על מקום אביו, לצד אחיו ר יהודה האדמור מסאסוב."},{"i":21410,"n":"טויב, יהודה יחיאל מרוזדול ומרג","f":"פנחס חיים מרוזדול","k":"אדמור ממרגרטן רוזדול","bt":"תרמז","bp":"לינסק","dt":"תרצז - יט אב","dp":"גרוסוורדין","b":"מצאצאי האדמור ר יצחק איזיק טויב מקאליב. חתן ר משה דוד אשכנזי מסטניסלב-נינו של ה\"שר שלום\" מבלז. רב במארגרטן-תרעב, רב ואדמור ממרגרטין ברוזדול(=ראזלא)-תרצו על מקום אביו. חיבר \"פדה אברהם\", \"פדה יהודה\"', \"כתבי יהודה\", \"לב שמח\", ועוד. פרסם מאמרים ב\"קובץ מפרשי התורה\" - מארגרטן תרצג. בנו - האדמור מקאליב."},{"i":21411,"n":"טויב, יהודה מסאסוב פמורן","f":"אברהם מרדכי שלום","k":"אדמור מסאסוב","bt":"תרלה","dt":"תשא - ב תמוז","dp":"זלוטשוב","b":"מצאצאי האדמור ר יצחק איזיק טויב מקאליב. חתן ר יצחק מאיר מסאווראן. רב בפמורן על מקום אביו, אדמור מסאסוב-תרצז על מקום אביו. נספה בשואה."},{"i":21412,"n":"טויב, יהודה צבי","f":"יצחק אייזיק טויב","b":"רב-שנת ת\"ר"},{"i":21413,"n":"טויב, יהודה צבי מרוזדול","f":"שלמה מרוזדול","k":"אדמור מרוזדול","bt":"תרט","dt":"תרמו - א סיון","b":"מצאצאי האדמור ר יצחק איזיק טויב מקאליב. רב ברוזדול(=ראזלא)-תרם על מקום אביו. חתן ר אליעזר צבי ספרין מקומרנא."},{"i":21414,"n":"טויב, יהושע יחזקאל מניו יורק","f":"שאול ידידיה אלעזר","bt":"תרעג","dt":"תשיב - א סיון","dp":"ניו יורק","b":"בן האדמור ממודזיץ."},{"i":21415,"n":"טויב, יוסף מפפד\"א","f":"חיים","dt":"תנה - טז ניסן","b":"דיין מחכמי פפד\"מ-תע."},{"i":21416,"n":"טויב, יחזקאל מיאבלונא","b":"חובב א\"י,אדמו\"ר ביאבלונה-תר\"פ"},{"i":21417,"n":"טויב, יחזקאל מקוזמיר","f":"צבי הירש בן שלמה זלמ","k":"אדמור מקוזמיר","dt":"תרטז - יז שבט","b":"תלמיד החוזה מלובלין, המגיד מקוזניץ, היהודי הקדוש מפשיסחא, ור שמואל מקאריב. אדמור בקוזמיר-תקפז. מתורתו ב\"תפארת ישראל\" - וארשא-נ\"י-תל אביב תרצו, \"נחמד מזהב\" - הו\"ל ר משה דוד הכהן קליגסברג מקאלושין, וב\"תורת יחזקאל\"."},{"i":21418,"n":"טויב, יעקב אריה מיבלונא","f":"אליעזר שלמה מוואלמין","b":"מצאצאי האדמור ר יחזקאל מקוזמיר. ראב\"ד ביבלונא."},{"i":21419,"n":"טויב, יעקב דוד מוארשא","f":"ישראל ממודזיץ","dt":"תרפז","b":"חתן ר חיים שלמה פאסטאג. סירב לאדמורות אך החזיק בימ\"ד בוארשא ונחשב לרבם של חסידי מודזיץ בוארשא-תרפ."},{"i":21420,"n":"טויב, יעקב ירחמיאל מראדום","f":"שמואל אליהו מזוואלין","k":"אדמור מראדום","bt":"תרלד","dt":"תרצד","b":"נכד האדמור ר יחזקאל מקוזמיר. חתן ר לייב מאוזרוב. אדמור בראדום. הלחין מנגינות."},{"i":21421,"n":"טויב, יעקב מיבלונא","f":"משה יוסף-בן דוד צבי","k":"אדמור מקוזמיר ביבלונ","bt":"תרכא","dt":"תרף - ז אב","b":"מצאצאי האדמור ר יחזקאל מקוזמיר. נכד האדמור מקוזמיר-ניישטאט. רב ואדמור בניישטאט-תרמג על מקום זקנו, יבלונא, בזמן מלחה\"ע ה-I עבר לוארשא."},{"i":21422,"n":"טויב, יעקב נפתלי מנאוידואהר","f":"משה אהרן","k":"אדמור מנאוידואהר","dt":"תשב","dp":"טרבלינקה","b":"חתן ר יעקב משה תאומים אב\"ד נאוידואהר-נכד בעל חדושי הרי\"מ מגור. אדמור בנאוידואהר, עבר לוארשא-תרף. בעל תפלה ומלחין מחונן. נספה בשואה."},{"i":21423,"n":"טויב, יצחק איזיק מקאליב","f":"משה יחזקאל מסערענטש","k":"אדמור מקאליב","bt":"תקיא","dt":"תקפא - ז אד\"ב","b":"מטיב נגן. נתקרב לחסידות ע\"י ר לייב שרה'ס. תלמיד ר שמואל שמלקא מניקלשבורג, ור אלימלך מליזנסק. מראשוני מפיצי החסידות בהונגריה. רב בקאליב(=נאג'י-קאלו)-תקמא ורב גליל סאבולטש. חסידיו נקראו גם חסידי אשוואר. חיבר שירים בהונגרית שעברו מדור לדור ובהם \"קרא התרנגול\" - \"סולו קוקוש\", ועוד."},{"i":21424,"n":"טויב, יצחק איזיק משאמשון","bt":"תקפח","dt":"תרעב - א תמוז","b":"דומ\"צ בשאמשון"},{"i":21425,"n":"טויב, יצחק ליבוש","f":"משה חיים טויב","dt":"כא שבט"},{"i":21426,"n":"טויב, יצחק צבי ממודזיץ נ\"י","f":"ישראל ממודזיץ","b":"מצאצאי האדמור ר יחזקאל מקוזמיר. היגר לארה\"ב. יסד-תרפא חברת \"אדמת ישראל\" לרכישת אדמות בארץ ישראל."},{"i":21427,"n":"טויב, ירחמיאל צבי משיננא","f":"אפרים מקוזמיר","k":"בעל אמרי צבי","dt":"תרעו - כד תמוז","b":"מצאצאי האדמור ר יחזקאל מקוזמיר. אדמור מקוזמיר בפרגה-וארשא-תרסו."},{"i":21428,"n":"טויב, ישראל דוד ממודזיץ נ\"י","f":"יהושע יחזקאל","k":"אדמור ממודזיץ בנ\"י","bt":"תשד","b":"נכד האדמור ר שאול ידידיה אלעזר ממודזיץ. אדמור ממודזיץ בארה\"ב."},{"i":21429,"n":"טויב, ישראל דן ממודזיץ","f":"שמואל אליהו מת\"א","k":"אדמור ממודזיץ בישראל","b":"חתן ר שמאול אהרן שצדרוביצקי (שושלת קוברין). חבר מועצת גדולי התורה של אגו\"י. הקים ישיבה \"אמרי אש\" ע\"ש אביו. מתורתו ב\"מאמרי אוריתא\"."},{"i":21430,"n":"טויב, ישראל יצחק מלודז","b":"מרבני ישיבת חכמי לובלין"},{"i":21431,"n":"טויב, ישראל ממודזיץ","f":"שמואל אליהו מזוואלין","k":"אדמור ממודזיץ","bt":"תרט","dt":"תרפא - יג כסלו","b":"נכד ר יחזקאל האדמור מקוזמיר. חתן ר חיים שאול פרידמן מאוזרוב. אדמור בזוואלין-תרמח, רב ואדמור במודזיץ - וחסידיו רכשו עבורו ארמון. חיבר מאות מנגינות ובהם מנגיה לפיוט \"אזכרה\" שחיבר בזמן שעבר ניתוח ללא הרדמה. חיבר \"דברי ישראל\", \"כללי דאוריתא\"."},{"i":21432,"n":"טויב, לוי יצחק מפרגא","f":"מנחם דוד מפרגא","k":"אדמור מקוזמיר בפרגא","dt":"תשג","b":"מצאצאי האדמור ר יחזקאל מקוזמיר. חתן דודו ר ישראל יהושע תאומים. אדמו\"ר מקוזמיר בגיטו וארשא על מקום אביו. נספה בשואה. חיבר \"מחשבות לוי\"."},{"i":21433,"n":"טויב, מנחם דוד מפרגא","f":"אפרים מקוזמיר","k":"אדמור מקוזמיר בפרגא","bt":"תרלג","dt":"תשב - אב","dp":"וארשא","b":"חתן ר יעקב משה תאומים מנאוידואהר-נכד בעל חדושי הרי\"מ מגור. אדמור מקוזמיר בבלוינא, פרגא-וארשא-תרסו. תולדותיו ב\"הוד וגבורה\"."},{"i":21434,"n":"טויב, מנחם מנדל מקאליב","f":"יהודה יחיאל מרוזדול","k":"אדמור מקאליב","b":"מצאצאי האדמור ר יצחק איזיק טויב מקאליב. חתן ר פנחס מקעכניא (נדבורנא). עלה לארץ-תשכב והתישב בראשון לציון, עבר לבני ברק. מייסד \"בר בי רב דחד יומא\". חיבר \"קול מנחם\"."},{"i":21435,"n":"טויב, מנחם מנדל שלמה מקאליב נ\"","f":"משה מקאליב","k":"אדמור מקאליב","bt":"תרסא-ג","b":"מצאצאי האדמור ר יצחק איזיק טויב מקאליב. חתן ר ישכר דב רוקח (שושלת בלז) מלינסק. עבר לניו יורק וכיהן כאדמור מקאליב בניו יורק. הו\"ל ספר אביו \"עת רצון\" ונוסף משלו קונ' \"חקל תפוחין\" ניו יורק תשכא. בנו ר נפתלי אריה ליב - נפטר בחיי אביו."},{"i":21436,"n":"טויב, מרדכי מהומאנא","b":"דומ\"צ בהומאנא"},{"i":21437,"n":"טויב, משה אהרן מנאוידוואהר","f":"שמואל אליהו מזוולין","k":"אדמור מזוואלין","bt":"תקצז","dt":"תרעח - ד ניסן","b":"נכד ר יחזקאל מקוזמיר. אדמו\"ר בזוואלין על מקום אביו, עבר לנאוידואהר-ליד וארשא לאחר שריפה גדולה בזוואלין."},{"i":21438,"n":"טויב, משה חיים מזידיטשוב","f":"יצחק איזיק מקאליב","k":"אדמור מקאליב זידיטשו","bt":"תקן","dt":"תקצא - כז תמוז","dp":"רוזדול","b":"רב ברוזדול. חתן ר צבי הירש מזידיטשוב בעל \"עטרת צבי\". מבניו ר יצחק ליביש-חתן ר ישעיה שור מיאס."},{"i":21439,"n":"טויב, משה יהודה ליב מקוזמיר","f":"ירחמיאל צבי משיננא","k":"בעל דברי משה","dt":"תשב","dp":"טרבלינקה","b":"מצאצאי האדמור ר יחזקאל מקוזמיר. חתן ר משה אב\"ד טשמילוב. עבר לוארשא. בעל כשרון נגינה. נספה בשואה."},{"i":21440,"n":"טויב, משה מקאליב","f":"יהודה צבי טויב","bt":"תרל","dt":"תרצו - כ אייר","b":"רב בקאליב"},{"i":21441,"n":"טויב, משה מקאליב","f":"יהודה צבי מרוזדול","k":"אדמור מקאליב","dt":"תרצו - יט אייר","dp":"קאליב","b":"מצאצאי האדמור ר יצחק איזיק טויב מקאליב. חתן ר מנחם מנדל שלמה אבנד אב\"ד נמירוב. אדמור בקאליב-תרן. חיבר \"עת רצון\", \"תפארת משה\", ועוד."},{"i":21442,"n":"טויב, משה מקאליב ארה\"ב","f":"מנחם מנדל שלמה","b":"מצאצאי האדמור ר יצחק איזיק טויב מקאליב. חתן ר לוי יצחק קלוגהויפט מסטרליסק-לונדון."},{"i":21443,"n":"טויב, משה עזרא מטימישואר","f":"פנחס חיים מראזלא","bt":"תרנה","bp":"ראזלא","b":"חתן ר ברוך רובין מריזדוביץ. עבר עם חותנו לטימישואר - בזמן מלחמת העולם ה-I. והקים בימ\"ד חסידי לאחר פטירת חותנו-תרצו. נספה בשואה."},{"i":21444,"n":"טויב, משה עזרא מסאמאס אויוואר","f":"פנחס חיים מרוזדול","bt":"תרנה","dt":"תשד - ה סיון","b":"מצאצאי האדמור ר יצחק איזיק טויב מקאליב. חתן ר ברוך מגערלא (רופשיץ). נספה בשואה."},{"i":21445,"n":"טויב, פנחס חיים מרוזדול","f":"יהודה צבי","k":"אדמור מרוזדול","bt":"תרכז","bp":"קומרנא","dt":"תרצו - יא תשרי","dp":"ראזלא","b":"נכד האדמור מקומארנא ר אליעזר צבי ספרין. ונינו של ר יצחק איזיק טויב מקאליב - שהיה האדמור הראשון בהונגריה. תלמיד זקנו ר אליעזר צבי מקומרנא. נסע אל ר יחזקאל שרגא משינאבא. חתן ר אברהם חיים הוכרביץ מלינסק, רב ואדמור ברוזדול (=ראזלא) על מקום אביו-תרמו, ולאחר פטירת זקנו התפרסם ברבים כאדמור חשוב ומגדולי המקובלים. בזמן מלחה\"ע ה-I עבר למארגרטן אל בנו ר יהודה יחיאל וחזר-תרפג לראזלא. טבל כל יום ש\"י טבילות. קונטרס \"אבידת הפר\"ח\" ובו הספד עליו - מארגרטה תרצו - על ידי נכדו אי\"ש שלו\"ם, נכדו ר מנחם מנדל טאוב האדמור מקאליב - הוציא לאור את ספרו אהל מועד-תשלז, \"תורת חסד\", רוב כתביו אבדו בשואה. לתולדותיו ב\"אבדת הפרח\"."},{"i":21446,"n":"טויב, צבי מניישטט-יבלונה","f":"יחזקאל מקוזמיר","b":"אדמו\"ר בניישטט-יבלונה-תר\"ל"},{"i":21447,"n":"טויב, שאול אליעזר ידידיה ממודז","f":"ישראל ממודזיץ","k":"אדמור ממודזיץ","r":"האדמו\"ר ממודזיץ","bt":"תרמז","bp":"אוזארוב","dt":"תשח - טז כסלו","dp":"ירושלים","b":"חתן ר אברהם איגר מלובלין, ובזיוו\"ש חתן ר שאול הכהן שוורץ מסטובויץ, ובזיוו\"ש חתן אחיו ר חיים יחזקאל, ובזיוו\"ר חתן ר אשר מבוכניה. רב בראקוב-תרעח, קארטשוב-תרפב, אדמור ממודזיץ על מקום אביו-תרפא, עבר לאוטואצק-ליד וארשא-תרפט. ביקר בארץ כמה פעמים. ניצל מהשואה והגיע לארה\"ב דרך יפן-תשא. והקים את חסידות מודזיץ בניו יורק, עלה לארץ. בעל כשרון מוסיקלי וחיבר מנגינות רבות. חיבר \"אמרי שאול\". מבניו: ר יהושע יחזקאל. פרסם מאמרים ב\"תפארת ישראל\" - וארשא-נ\"י-תל אביב תרצו.","bk":[["אמרי שאול",""]]},{"i":21448,"n":"טויב, שלום ממרגרטן","f":"יהודה יחיאל מרוזדול","k":"בעל אבידת הפרח-תרצו","dt":"תשד - יא סיון","dp":"אושוויץ","b":"נכד ר יהודה יחיאל האדמור מרוזדול ומארגרטן. תלמיד ר שלמה זלמן ארנרייך בשאמלוי. חתן ר מאיר לייפר האדמור ממארוש-ואשארהי. נספה בשואה עם כל משפחתו. חיבר \"אבידת הפרח\" לתולדות זקנו. פרסם מאמרים ב\"קבוצי בחורים\" - מארגרטן תרצג."},{"i":21449,"n":"טויב, שלום מסאסוב","dt":"תשג","b":"רב בסאסוב"},{"i":21450,"n":"טויב, שלמה מרוזדול","f":"משה חיים מזידיטשוב","k":"אדמור מרוזדול","bt":"תקף","dt":"תרם - ג חשון","b":"נכד ר יצחק איזיק טויב מקאליב. חתן דודו ר יהודה צבי טויב-איכנשטין מרוזדול, רב ואדמור ברוזדול-תרח על מקום חותנו."},{"i":21451,"n":"טויב, שמואל אליהו מזוואלין","f":"יחזקאל מקוזמיר","k":"אדמור מזוואלין","dt":"תרמח - כו אייר","b":"חתן החסיד ר מתתיהו הכהן מוארשא-חתן ר נתקי שפילגלס. אדמו\"ר בזוואלין. בעל כשרון מוסיקלי. מתורתו ב\"דברי ישראל\" לבנו, ובקובץ \"תפארת ישראל\" (- מודזיץ)."},{"i":21452,"n":"טויב, שמואל אליהו ממודזיץ נ\"י","f":"יעקב דוד מוארשא","k":"אדמור ממודזיץ בנ\"י","dp":"ארה\"ב","b":"מצאצאי האדמור ר יחזקאל מקוזמיר. חתן ר אשר זליג משה זאלויסקי מפאליניץ. ניצל מהשואה ואחריה היגר לארה\"ב וכיהן כאדמור ממודזיץ בנ\"י. הו\"ל ספר זקנו \"דברי ישראל\". פרסם מאמרים ב\"תפארת ישראל\" - וארשא-נ\"י-תל אביב תרצו - ומהם יצירות עם תוי נגינה."},{"i":21453,"n":"טויב, שמואל אליהו ממודזיץ ת\"א","f":"שאול ידידיה אלעזר","k":"אדמור ממודזיץ-אמרי א","r":"האדמו\"ר ממודז'יץ","bt":"תרסה","dt":"תשמד - ד אייר","b":"מצאצאי האדמור ר יחזקאל מקוזמיר. חתן ר חיים משה כהן מוארשא-נכד האדמור מאפטא. עלה לארץ-תרצה והתישב בתל אביב. מיטיב נגן ומחבר מנגינות. חיבר \"אמרי אש\".","bk":[["אמרי אש",""],["מור מבשמים - תווי נגינה",""]]},{"i":21454,"n":"טויב, שמואל דוד מסטמר","f":"ישראל שלום מברגסאס","bt":"תרנז","bp":"ברגסאס","dt":"תש..","dp":"אושוויץ","b":"נכד ר אהרן צבי טויב האדמור מבריד-מונקטש. תלמיד בעל \"ערוגת הבשם\" בחוסט. חתן ר יעקב יחזיקה גרינוולד מחוסט - אחי רבו. ראש ישיבה בטור-טרבש-ליד סטמר, עבר למוזשאי. נספה בשואה."},{"i":21455,"n":"טויבמן, אהרן מברזנא","f":"חיים מברזנא","k":"אדמור מברזנא","dt":"תרפו - כג סיון","b":"חתן אחיו ר יחיאל מיכל מסלאויטא. אדמור מברזנא עם אחיו ר גדליה משה."},{"i":21456,"n":"טויבמן, גדליה משה מברזנא","f":"חיים מברזנא","k":"אדמור מברזנא","dt":"תשג","b":"חתן ר מרדכי מפרוסקרוב (ברדיטשוב). אדמור מברזנא עם אחיו ר אהרן. נספה בשואה."},{"i":21457,"n":"טויבמן, חיים מבראזנא - א","f":"יחיאל מיכל מליבישוב","k":"אדמור מברזנא","dt":"תרסח - ז כסלו","b":"חתן ר יצחק מברזנא (סטעפין). אדמור בברזנא על מקום חותנו."},{"i":21458,"n":"טויבמן, חיים מבראזנא - ב","f":"אהרן מברזנא","k":"אדמור מברזנא","dt":"תשג","b":"חתן ר יצחק מברזנא (סטעפין). אדמור בברזנא על מקום חותנו. נספה בשואה."},{"i":21459,"n":"טויבמן, יחיאל מיכל מסלאויטא","f":"חיים מברזנא","dt":"ו כסלו","b":"נכד ר יחיאל מיכל וינגרטן מיאנוב וליבישוב. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":21460,"n":"טויבנלפד, שמואל שמלקא ישכר דב","f":"משה מנחם","k":"בעל קדושת שמואל","bt":"תרצא","bp":"ירוסלב","dt":"תשמו","dp":"מונסי","b":"ניצל מהשואה. הגיע לארה\"ב וכיהן כרב במונסי. חתן ר יוסף בלייך ממונטריאול. חיבר \"קדושת שמואל\" מונסי תשמו."},{"i":21461,"n":"טויבנפלד, מאיר הכהן מקראקא","b":"רב בקראקא - תשובה אליו \"משיב שלום\"."},{"i":21462,"n":"טויבנפליגל, דוד מקויש","b":"מקובל,רב בקויש-תר\"כ"},{"i":21463,"n":"טויבר ישראל איסרל","bt":"1823","dt":"ה'תרסג 1903","bk":[["מקור ישראל",""]]},{"i":21464,"n":"טויבר, אברהם זאב מיענאקיעווא","f":"שרגא פיבוש מנאווא-קו","bt":"תרלו","b":"חתן ר אליהו יהודה ליב שוורדלוב. רב ושו\"ב ביענובקה(=יענאקיעווא)-פלך יקטרינסלב-תרס מחוז באכמוט."},{"i":21465,"n":"טויבר, אהרן הלוי מבאטורקעז","f":"יחיאל הלוי מלייפניק","k":"בעל יד אהרן","bt":"תקלח","bp":"לייפניק","dt":"תריז - ז חשון","dp":"סערדאהעל","b":"תלמיד ר ברוך פרנקל-תאומים מלייפניק, והחת\"ס. רב ביאהאנא-תקסז, באטורקעז-תקפא, התישב בסערדאהעל אצל בנו ר יחיאל. תשובה אליו ב\"חתם סופר\"."},{"i":21466,"n":"טויבר, אהרן הלוי-הנכד","b":"נכד ר אהרן הלוי מבאטורקעז. חתנו - ר יוסף בישיץ מסערדאוהל."},{"i":21467,"n":"טויבר, אפרים זלמן מזבלטוב","bt":"תקע","dt":"תרם","b":"נכד השל\"ה. רב בזבלטוב."},{"i":21468,"n":"טויבר, אריה מטרנופול","k":"בעל מחקרים ביבליוגרפ","bt":"תרלא","bp":"טרנופול","b":"עבר לזברז, למד בביהמ\"ד בברלין ולמד אצל משה שטינשניידר. עלה לירושלים-תרעד. ספרן בספריה הלאומית. וממיסדי הרבעון \"קרית ספר\", חיבר \"מחקרים ביבליוגרפים\" ירושלים תרצב. פרסם מאמרים ב\"הדביר\" - ירושלים תרעט, \"ירושלים\" - ירושלים תרמב-תרעט."},{"i":21469,"n":"טויבר, ברוך בנדיט","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":21470,"n":"טויבר, זרח מגלנטא","f":"אריה ליב טלטש טובר","dt":"תריג - טו ניסן","dp":"גלנטא","b":"תלמיד בעל שמן רוקח. דיין בגלנטא."},{"i":21471,"n":"טויבר, חיים מלייפניק","b":"מחכמי לייפניק,באבאני-תק\"פ"},{"i":21472,"n":"טויבר, חיים מראזניב","f":"[אפרים זלמן]","b":"רב בראזניב (ליד זבלטוב)."},{"i":21473,"n":"טויבר, יהושע מנאדי-קרש","f":"אהרן טובר","b":"רב בנאדי-קרש,טעטינג-תר\"ל"},{"i":21474,"n":"טויבר, יעקב מסלנט וירושלים","dt":"תרסג - כג תמוז","b":"מו\"צ בסאלאנט,עלה לירושלים"},{"i":21475,"n":"טויבר, יצחק איזיק מזבלטוב","f":"אפרים זלמן","bt":"תר","dt":"תרס","b":"רב בפוטילה-בוקובינה. עלה לארץ-תרן, והתישב בצפת וטבריה. חיבר פירוש למשנה בשם \"טל השמיים\" למברג תרנו."},{"i":21476,"n":"טויבר, ישראל איסר מעיר חדש","f":"זרח מגלנטא","k":"בעל אזרח רענן","bt":"תקפג","bp":"גאלאנטא","dt":"תרסד - יח תשרי","dp":"עיר חדש","b":"נכד ר ליב טעלטש-טויבר מגאלנטא. תלמיד החת\"ס, ור יחזקאל בנט מנייטרא, ור שלמה זלמן אולמן ממאקווא. חתן ר שלמה ליב קניג מעיר חדש (גלנטא)-תריג, רב בעיר חדש על מקום חותנו כ-50 שנה. חיבר \"מקור ישראל\" לתולדות זקנו בעל \"תרומת הדשן\", ועוד."},{"i":21477,"n":"טויבר, ישראל ממארמארוש","f":"יצחק איזיק","bt":"תרנד","bp":"פוטילה-בוקובינה","dt":"תשיט - ד טבת","dp":"ישראל","b":"גדל אצל דודו ר חיים וולף ביטמן בטשרנוביץ, לאחר שאביו עלה לארץ בגפו לאחר שאשתו נהרגה עק\"ה. תלמיד ישיבות פולין וליטא. חתן גיסו ר אפרים פישל ברטפלד, והיה מחכמי וולקאן, ומורה בגרוסורדין. רב בהאצג-תרצג וראש ישיבה. היה מטובי הנואמים והדרשנים, הראשון בטרנסילבניה שדרש בעברית ונתן שיעורים בעברית, וידע להתחבר גם עם חוגים רחוקים, ובהשפעתו החליטו החלוצים של ארגון \"דרור הבונים\" להכשיר את המטבח ולשמור שבת - כדי שהרב יוכל לבקרם. ניצל מהשואה, עלה לארץ-תשי והתישב בקרית ים."},{"i":21478,"n":"טויבר, מאיר מעיר חדש (קטשוביץ)","f":"יו\"ט ליפמן","k":"בעל עין מאיר","bt":"תקעו או תקעח","bp":"קאטשאן-מחוז טרנטשין","dt":"תרסא - טו כסלו","dp":"עיר חדש","b":"תלמיד החת\"ס, ור יעקב קופל קונשטט מוערבא. חתן ר בנימין שטיין מנאמסטא ועבר לשם. רב בעיר חדש וייסד שם בית מדרש."},{"i":21479,"n":"טויבר, מיכאל מפרשבורג","b":"מג\"מ בפרשבורג בחברה \"אגודת רעים\"-נוסדה תרסד."},{"i":21480,"n":"טויבר, משה הלוי מפרוינקירכן","f":"עזריאל מסערדאוהל","b":"חתן ר נחום גרינוולד מטשארנא-אחיו של בעל \"ערוגות הבושם\". מחכמי פרוינקירכן - לא שימש ברבנות."},{"i":21481,"n":"טויבר, מתתיהו מגעוויטש","b":"תלמיד השב\"ס. אב\"ד געוויטש (מהרין)-תרפה."},{"i":21482,"n":"טויבר, עזריאל מסערדאוהל","f":"יחיאל הלוי מסערדאוהל","k":"בעל העטרת","bt":"תרז","dt":"תרצא - ה אדר","dp":"סערדאוהל","b":"תלמיד הכת\"ס, ור מיכאל הופמן מסערדאוהל. בזזיוו\"ש חתן ר אבא חייא הירש מסערעד. מחכמי סערדאוהל. בנו - ר משה מפרוינקירכן."},{"i":21483,"n":"טויבר, קלמן","f":"צבי הכהן","bp":"וילנא","dt":"1902","dp":"וילנא","b":"תלמיד ביהמ\"ד לרבנים בוילנא. הצטרף לחוגי רש\"י פין, מאפו וש. שטרשון. רב ברזיצה-תרכה, מורה ומנהל בישיבת מייליס. מראשי ביהכ\"נ \"טהרת קדש\". חיבר סיפור היסטורי על האפיפיור אלחנן."},{"i":21484,"n":"טויבר, שמואל דוד מיאסי","b":"רב פעלים לישוב א\"י,רב ביאסי-תר\"מ"},{"i":21485,"n":"טויבר, שרגא","b":"רב-שנת תרמ\"ה"},{"i":21486,"n":"טויבר, שרגא פיבוש מנאווא-קובנא","b":"שו\"ב ומו\"ץ בנאווא-קובנא. בנו - ר אברהם."},{"i":21487,"n":"טויבש חיים בן שלום","dt":"ה'תרסח 1908","bk":[["חיים של שלום",""],["עטרת ישועה [ספרא דאגדתא]",""]]},{"i":21488,"n":"טויבש, אהרן משה","f":"חיים מסאסוב","r":"אב\"ד יאס והמדינה","bt":"ה'תקמז","dt":"ה'תריב","b":"רב בלמברג. הדפיס ספר השו\"ת של אביו.","bk":[["תועפות ראם [שו\"ת]",""],["הריסת משמרת",""],["קרני ראם - עה\"ת",""],["תועפות ראם – שו\"ת –, הריסת משמרת, קרני ראם - עה\"ת",""]]},{"i":21489,"n":"טויבש, אהרן משה מסניאטין","f":"יעקב","k":"בעל תועפות ראם","bt":"תקמז","bp":"למברג","dt":"תריב - יא תמוז","dp":"יאסי","b":"ידיד נפש ל\"ישועות יעקב\". חתן הגביר ר יצחק אייזיק וואהל מפרמישלא. רב בסניאטין-תרב, בנויהוד-תקצב, יאסי-תרב ובנו ר יעקב על מקומו אחריו. חיבר \"תועפות ראם\" זולקוא תרטו. התוכח בדפוס על רבה של יאסי ר יוסף לנדא שכתב כנגדו \"סיג לתורה\" ו\"משמרת לסייג\" ורא\"ם הדפיס כנגדו \"מודעא רבא\"."},{"i":21490,"n":"טויבש, אורי שרגא פיבל מיאסי","f":"שמואל שמלקא-חיי עולם","k":"בעל אורי וישעי","bt":"תר","bp":"אברטין","dt":"תרסח","b":"רב באוברטין, יאסי על מקום אביו. חתן דודו ר שלום מבוטושאן. חיבר \"מספד מר\" טשרנוביץ תרמה, \"אורי וישעי\" למברג תרמו."},{"i":21491,"n":"טויבש, אליהו יצחק מנ\"י","f":"נפתלי","k":"בעל לקוטי יצחק","b":"רב בניו יורק-תרסט. חיבר \"לקוטי יצחק\" ניו יורק תרפג, \"זכרון יצחק\" ניו יורק תרץ, ועוד."},{"i":21492,"n":"טויבש, אלכסנדר סנדר מוסלוי","f":"יעקב מיאסי","k":"בעל דרך כוכב מיעקב","bt":"תרא","dt":"תרעג","b":"תלמיד וחתן דודו ר יחיאל מיכל מוסלי. רב בוסלוי(=ואסלאי)-רומניה-תרל על מקום חותנו. חיבר \"שומר מצוות\" למברג, ועוד - בכת\"י. נסמך מאת: ר יצחק איזיק מקומורנא, קרובו ר חנינא ליפא מייזלש בעל \"פני יוסף\". בנו - ר אלתר-חתן ר שמריל אב\"ד מוסט."},{"i":21493,"n":"טויבש, אשר זליג מטלוסט","b":"רב בטלוסט."},{"i":21494,"n":"טויבש, חזקיה נחום מלבוב","f":"יצחק","bt":"תקף","dt":"תרל","dp":"לבוב","b":"רב בלבוב אצל ה\"ישועות יעקב\", רב בקולומיאה(=קאלאמייא)-תרט. אחיינו של ר משה טויבש מיאס בעל \"קרני ראם\"."},{"i":21495,"n":"טויבש, חיים מבוטושאן","b":"הסכים על \"בית ועד לחכמים\" - יאסי תרסט."},{"i":21496,"n":"טויבש, חיים מסאסוב","f":"שלום","k":"בעל חיים של שלום","bt":"תרז","dt":"תרסט - ו שבט","b":"חתן הגביר ר אברהם מרדכי. רב בסאסוב-תרך, דורוהוי-תרמו, בוטשאן-תרמט על מקום אביו. חיבר \"שו\"ת של שלום\" למברג תרנד, \"ספרא דאגדתא\" דרוהוביטש תרנו. הסכים על \"אהל יצחק\" - סטמר תרסג."},{"i":21497,"n":"טויבש, חיים צבי מוינה","f":"זכריה אידלשטין","k":"בעל ברכות התפלין","bt":"תרס","bp":"טשרנוליצה","dt":"תשכו","b":"אימץ את שם המשפחה של אמו. למד בבית המדרש לרבנים ובאוניברסיטה בוינה. רב באודסברג, וינה-תרצב, ציריך-תרצו, עלה לירושלים-תשכה. חתן ר יונה יוסף בלינד. ניצל מהשואה. חיבר \"ברכות התפלין\" וינה תרצו, ועוד. פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו. בנו - נתן נטע שדרשת הבר מצוה שלו נדפסה בשם \"זכרון דברים\" וינה תרצו."},{"i":21498,"n":"טויבש, יהודה ליב","f":"אהרן משה מסניאטין","b":"חתן ר יעקב שמואל רפפורט מלמברג (אחיו של שי\"ר) וגיסו של ר יעקב יוטס."},{"i":21499,"n":"טויבש, יוסף מויזניץ","b":"רב בויזניץ - תשובה אליו \"שאילת שלום\"."},{"i":21500,"n":"טויבש, יחיאל מיכל מוסלוי","f":"אהרן משה","bt":"תקעה","bp":"[למברג]","dt":"תרלה - ט תשרי","b":"רבה של וסלוי-תרח. חתנו - בן אחיו - ר אלכסנדר טויבש על מקומו אחריו."},{"i":21501,"n":"טויבש, יחיאל מיכל מסדיגורא","f":"שמואל שמלקא","k":"בעל שם עולם","bt":"תרה","dt":"תרסח","b":"חתן ר יוסף עזריאל ביליג מסדיגורא. רב בסדיגורא על מקום חותנו. חיבר \"שם עולם\" טשרנוביץ תרמז."},{"i":21502,"n":"טויבש, יעקב מזידיטשוב","f":"אהרן משה","k":"בעל ברכת יעקב","bt":"תקעב","dt":"תרן","b":"רב בזידיטשוב, יאסי-תרכח על מקום אביו. חתן ר יהודה צבי איכנשטין מרוזלא. חיבר \"ברכת יעקב\" - בכתב יד."},{"i":21503,"n":"טויבש, יעקב מיאסי","f":"אורי שרגא טויבש","b":"רב ביאסי-תר\"ס"},{"i":21504,"n":"טויבש, יעקב מסמבור","f":"יצחק","bt":"תקפט","dt":"תרלא","b":"רב בסמבור והקרייז, רישא."},{"i":21505,"n":"טויבש, יעקב שמואל מלונדון","b":"פרסם מאמרים ב\"המסילה\" - לונדון תשז."},{"i":21506,"n":"טויבש, יצחק איזיק מבוקרשט","f":"יחיאל מיכל מוסלוי","k":"בעל דברי שלום ואמת","bt":"תקצז","bp":"סניאטין","dt":"תרפא - יז תשרי","dp":"בוקרשט","b":"תלמיד זקנו ר אהרן משה בעל \"תועפות ראם\", ר יוסף באבד מטרנופול. רב בבארלד(בארלאד)-מולדובה-תרכב, בוקרשט-תרנא. חיבר ספר ברומנית \"דברי שלום ואמת\", \"נקם ברית\" בוקרשט תרסד (כנגד ר אהרן ב\"ק שהשיב לו \"נוקמת נקם ברית\") - שעורר פולומוס. פרסם מאמרים ב\"שמעתתי דרבנן\" - אודסה תרמז. היה מחלוקת בענין רבנות באראלד עם ר יעקב מאיר דייטשמן ועל כך יצא ספר כנגדו בשם \"הגו סיגם\" ור יצחק חיבר כנגד את \"העקב למישור\"."},{"i":21507,"n":"טויבש, יצחק איזיק מפאשקני","b":"פרסם מאמרים ב\"דבר בעתו\" - פאקש תרסט."},{"i":21508,"n":"טויבש, יצחק איזיק מפשקן","f":"שמואל שמלקא מיאסי","k":"בעל מנחת יצחק","bt":"תקצז","bp":"יאסי","dt":"תרעא","b":"נסמך מאת: ר ישעיה שור מיאס, ר משה תאומים בעל \"דבר משה\", אחיו - ר שלום מבוטשאן בעל \"שאילות שלום\". רב ברינזע, דראטשן-תרכט, פשקן(=פאשקאן)-רומניה-תרלג, חתן ר יצחק שמשון הורביץ מטשרנוביץ (אחר שגירשה פרסם חותנו \"אונס בגיטין\" כנגדו). חיבר \"מנחת יצחק - שפתי צדיקים\" למברג תרן."},{"i":21509,"n":"טויבש, יצחק ישכר מאטיניא","f":"יעקב","bt":"תר","dt":"תרעא","b":"רב באטיניא-תרכח. חתן ר צבי מבנדר."},{"i":21510,"n":"טויבש, יצחק מברוד","b":"פרסם מאמרים ב\"הלבנון\" - ירושלים-פאריס תרכג-תרמב."},{"i":21511,"n":"טויבש, מ' מאניש ניטקע","dt":"תקעו - יט תשרי","b":"מגדולי חכמי ווילנה"},{"i":21512,"n":"טויבש, משה מיאסי","k":"בעל קרני ראם","b":"רב ביאס. אחיו - ר יצחק, ואחיינו - ר חזקיה נחום מקולומיאה."},{"i":21513,"n":"טויבש, צבי הירש מאויהל","k":"הרמן טאובס","dt":"תשד","dp":"אושוויץ","b":"דיין, רב קהל סטטוס קוו באוהל. נספה בשואה. עליו בספר זכרון קהלת אוהעל (בהונגרית)."},{"i":21514,"n":"טויבש, שלום מנדבורנה","f":"שמואל שמלקא","k":"בעל שאילת שלום","bt":"תקפה","dt":"תרמט","b":"תלמיד זקנו ר אהרן משה מיאסי. חתן ר חיים רסלר מנדבורנה. רב בטירגול-פפראמאס - תרח, יאסי, בוטושאן-תרכב. חיבר \"שאילת שלום\" זולקוא תרכט."},{"i":21515,"n":"טויבש, שלמה מצי'ק סערעדא","dt":"תש..","b":"שו\"ב בצ'יק סערעדא. נספה בשואה. נזכר ב\"אפרקסתא דעניא\""},{"i":21516,"n":"טויבש, שמואל יצחק מבלגרד","f":"יחיאל טויבש","bt":"תקצז","dt":"תרפא - כט חשון","b":"רב פעלים,רב בבלגרד-תרכ\"ד,בוקרשט-תרנ\"ד"},{"i":21517,"n":"טויבש, שמואל שמלקא מיאסי","f":"אהרן משה - קרני ראם","k":"בעל אבל משה","bt":"תקסח","bp":"[למברג]","dt":"תרכה","b":"רב באברטין-תר, שיניבה(=שינאווי), יאסי-תריג על מקום אביו. חתן ר יחיאל מיכל (איכל) רוזנפלד מרווה. חיבר \"אבל משה\" למברג תריג, \"חיי עולם\" יאסי תרטז, ועוד. בניו: ר שלום, ר אורי שרגא, ר יצחק איזיק, ר שרגא פיבל. חתנו ר אריה יהודה מייזלש, ר מרדכי מנדבורנא. (באוצר הרבנים מופיע תאריך הפטירה ח אב תקמט - וזו טעות)"},{"i":21518,"n":"טויבש, שמואל שמלקא מיאסי","f":"אורי שרגא פיבל","bt":"תרכו","dt":"תרפו - יב אב","b":"חתן ר דוד דב לייטר מזוולוב. רב ביאסי-תרסח על מקום אביו, חתנו - ר יואל אשכנזי - על מקומו אחריו."},{"i":21519,"n":"טויבש, שמלקא מסדיגורא","f":"יחיאל טויבס","b":"דומ\"צ בסאדיגורא-תר\"ע"},{"i":21520,"n":"טויבש, שרגא פיבל משינאווי","f":"שמואל שמלקא טויבס","b":"רב בשינאווי"},{"i":21521,"n":"טויזנר, משה חיים","b":"ביבליוגרף. פרסם מאמרים ב\"היהודי\" - נ\"י תרצו."},{"i":21522,"n":"טויסיג, יחזקאל מירושלים","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":21523,"n":"טויסיג, ישראל ממטרסדורף","f":"דוד ישכר","k":"אדמור ממטרסדורף","bt":"תרמט","dt":"תשכח - ו-י תשרי","b":"תלמיד ישיבות פרשבורג, בעלעד, אונסדורף. נסמך כאדמור ע\"י ר ישעיה מקרסטור. עלה לארץ מאוסטריה-תרצח והקים ישיבת \"תפארת אהרן\". חיבר \"תפארת יוסף\", \"בית ישראל\". בנו ר יואל על מקומו אחריו, ובנו ר משה שמואל בראש הישיבה אחריו. עוד מבניו: ר אהרן בעל \"פרי נפש חיה\", ר יחזקאל. חתנו ר חיים ברים ראש ישיבת \"משכן יוסף\"."},{"i":21524,"n":"טויסיק, שלמה זלמן ממינכן","f":"שלום","k":"בעל נוה שלום","b":"מחכמי מינכן. חיבר גם מלאכת שלמה."},{"i":21525,"n":"טויסקי, אשר מוויצען","b":"חתניו - ר משה מרדכי דושינסקי, ור ירחמיאל הכהן קצבורג מאוזד."},{"i":21526,"n":"טויסקי, ליפמן מטשעטשע","b":"דומ\"צ בפעלעדיהאז-תר\"ל,רב בטשעטשע"},{"i":21527,"n":"טוך-פירר, צבי הירש","k":"בעל נחלת צבי","b":"מקובל,מגדולי חכמי קרקא-ת\"י"},{"i":21528,"n":"טוכמן, יעקב יצחק מטיטשין","b":"מחכמי טיטשין - תשובה אליו ב\"מנחת יחיאל\"."},{"i":21529,"n":"טוכמן, נפתלי מלאדאמער-הונגריה","b":"דומ\"צ בלאדעמער-הונגריה-תרכו."},{"i":21530,"n":"טוכנר, ישראל מדוברומיל","bp":"דוברומיל","b":"רב בדוברומיל. ההדיר את \"חי בן מקיץ\" לראב\"ע עם הקדמה ומבואות - פשמישל תרפה."},{"i":21531,"n":"טוכשניידר, ישראל קלמן","b":"פרסם מאמרים ב\"הלפיד\" - וארשא תרצז."},{"i":21532,"n":"טולדנו - משפחה","b":"משפחה מיוחסת שמקורה בטולידו במחוז קסיטליא-ספרד, לאחר הגירוש-רנב עברו לשלוניקי ומשם לפאס-מרוקו, ונאלצו לעזוב בזמן המאורעות ועברו למכנאס."},{"i":21533,"n":"טולדנו חביב בן אליעזר","bt":"1800","dt":"ה'תרל 1870","bk":[["תרומת הקדש",""]]},{"i":21534,"n":"טולדנו יעקב משה בן יהודה","bt":"1879","dt":"ה'תשכ 1960","bk":[["אוצר גנזים",""],["אפריון",""],["בת עמי",""],["ים הגדול",""],["מאורות",""],["משיב נפש",""],["פרק מעשה המת",""],["תולדות ישראל במארוקו",""],["ספר התמיד",""]]},{"i":21535,"n":"טולדנו, אברהם מטנג'יר","b":"מו\"צ בטנג'יר, חתם על פס\"ד-תקסז עם ר אברהם ישראל, ר מנחם נהון, ר משה ן צור ור שאול ישועה אביטבול. הסכים על מלאכת הקדש-תקסב. בנו - ר יוסף."},{"i":21536,"n":"טולדנו, אברהם ממכנאס","f":"עייאד בן חיים","b":"מחכמי מכנאס, נזכר ב\"ויאמר יצחק\", \"תקפו של יוסף\"."},{"i":21537,"n":"טולדנו, אברהם ממכנאס","b":"גביר מחכמי מכנאס-מרוקו, נאסר בעיר סאלי ונפדה ע\"י אחיו חיים."},{"i":21538,"n":"טולדנו, אברהם ממכנאס","f":"ברוך","b":"מחכמי מכנאס, מקורב למלכות עם אחיו ר חיים."},{"i":21539,"n":"טולדנו, אברהם משלוניקי","b":"דיין בשלוניקי-שנה."},{"i":21540,"n":"טולדנו, אליהו מצפת","b":"מחכמי צפת."},{"i":21541,"n":"טולדנו, אליעזר מליסבון","b":"מרבני לישבונה-פורטוגל, ובעל דפוס. לאחר הגירוש עבר הדפוס לשלוניקי ע\"י המגיה ר יהודה גדליה בעל \"מסורת הירושלמי\" ונדפס שם ש\"ס. נזכר ב\"עין יעקב\" בהקדמה."},{"i":21542,"n":"טולדנו, אליעזר ממכנאס","f":"חביב","k":"בעל מנחת עני","b":"רב במכנאס-תקע. חיבר \"מנחת עני\". בנו - ר חביב בעל \"פה ישרים\"."},{"i":21543,"n":"טולדנו, אליעזר ממכנאס","f":"משה","dt":"תסו","b":"מחכמי מכנאס."},{"i":21544,"n":"טולדנו, אליעזר ממכנאס","f":"יהודה בן חיים","b":"נגיד במכנאס. נזכר בשו\"ת מו\"צ ביעקב. אחיו - ר יוסף, ר חיים מסאלי, ר דניאל."},{"i":21545,"n":"טולדנו, ברוך אברהם","k":"בעל שאלו לברוך","bt":"תרן","bp":"מקנאס","dt":"תשמב - ד כסלו","b":"דומ\"ץ ור\"מ במקנאס, דיין-תש\"א, לעת זקנה עלה לא\"י, דרשן בחיפה, חיבר שו\"ת \"שאלו לברוך\""},{"i":21546,"n":"טולדנו, ברוך מטבריה","f":"יהודה","k":"תרגם אלמארשאד אלכאפי","bt":"תרב או תרמג","bp":"מכנאס או פקיעין","dt":"תרסא - ח אב","dp":"טבריה","b":"תלמיד ר יצחק הכהן ור משה מאיר חי אליקים. חתן ר יוסף דוד אבולעפיה מטבריה. מורה בפקיעין, דיין מחכמי טבריה, יצא לשליחות בתורכיה, ההדיר את פירוש מסכת כלה לר אברהם הירחי עם ביאורים והוספות ירושלים תרסו. תרגם לעברית את הספר אלמארשאד אלכאפי של ר תנחום הירושלמי. פרסם מאמרים ב\"ירושלים\" - ירושלים תרמב-תרעט, \"המליץ\". גילה בטבריה את קבר ר דוד נכדו של הרמב\"ם."},{"i":21547,"n":"טולדנו, ברוך ממכנאס","f":"יעקב","bt":"תצח-ט","dt":"תקעז-ט - ג תמוז","b":"פוסק, דיין ומו\"ץ במקנאס-תקמח יחד עם ר רפאל בירדוגו והיה מחלוקת ביניהם. חתם על הסכמה-תקסד עם ר שמואל ן ואעיש, ר פתחיה מרדכי בירדוגו, ועוד. הניח חדושים בכת\"י. אחיו של ר משה."},{"i":21548,"n":"טולדנו, ברוך ממכנאס וירושלים","f":"משה","bp":"מכנאס","dt":"תעב-ג - חשון","dp":"ירושלים","b":"תלמיד ר חביב. מחכמי מכנאס. היה גדול בתורה אך לא שימש ברבנות, חיבר פיוטים וקינות, עלה לירושלים-תעא, הרב י.מ. טולידנו פרסם בירושלם ח קינות ואגרות תנחומים על פטירתו של ר ברוך שמצא בכתב יד. (לפי מלכי רבנן נפטר - טבת תעב). ב\"לשון למודים\" אגרת תנחומים אליו מאת היעב\"ץ (ר יעקב ן צור) על פטירת אחיו ר דניאל. בניו - ר אברהם, ר חיים, ר משה? (לפי טולדנו-נר המערב נפטר בעשרה בטבת תעב)."},{"i":21549,"n":"טולדנו, ברוך ממרוקו","f":"יוסף בן דניאל","b":"נכד ר דניאל-ממגורשי ספרד, מחכמי מרוקו. בניו - יוסף, משה, פנחס, חיים, אברהם ויצחק."},{"i":21550,"n":"טולדנו, דוד ממכנאס","b":"דיין במכנאס, חתם-תקסב עם ר מימון ור מרדכי בירדוגו, ר משה טובי ור עזריה אסבאג."},{"i":21551,"n":"טולדנו, דניאל ממכנאס","f":"יהודה בן חיים","dt":"תקמו-לז - יד אב","b":"מו\"ץ במכנאס, נספד ע\"י ר אברהם מאנסאנו. בנו - ר משה בעל \"מלאכת הקדש\". (במלכי רבנן תאריך פטירתו - תקלז בעשרת ימי תשובה)."},{"i":21552,"n":"טולדנו, דניאל ממכנאס","f":"חיים בן דניאל","b":"מחכמי מכנאס. אחיו - ר חביב."},{"i":21553,"n":"טולדנו, דניאל ממכנאס - הנכד","f":"יוסף בן דניאל","dt":"תל - תמ","b":"מחכמי מכנאס, חברו של ר יעקב ששפורטש ויחד עם לחם בשבתאים, מיועצי המלך מולאי ישמעאל במכנאס. בניו - יוסף, משה, עייאד, חיים, אברהם, פנחס, יהודה, נחמיה."},{"i":21554,"n":"טולדנו, דניאל ממרוקו","f":"משה בן ברוך","dt":"תסו","b":"מחכמי מרוקו. ב\"לשון למודים\" מובאת אגרת תנחומים שנשלחה בפטירתו לאחיו ר ברוך."},{"i":21555,"n":"טולדנו, דניאל מספרד ומרוקו - א","f":"יוסף","b":"מגדולי חכמי ספרד, לאחר הגירוש-רנב עבר לשלוניקי ומשם למרוקו, מו\"ץ במכנאס, ראש ישיבה בפאס. בניו - ר יוסף ור חיים ממכנאס."},{"i":21556,"n":"טולדנו, ח' ממכנאס","f":"ברוך","b":"מחכמי מכנאס, נזכר ב\"תקפו של יוסף\"."},{"i":21557,"n":"טולדנו, חביב מטנג'יר","f":"חביב","b":"העתיק פירוש לתורה מקרובו ר חיים בן יעקב טולדנו בשנת תרסד."},{"i":21558,"n":"טולדנו, חביב ממכנאס","k":"בעל ארבעה טורי אבן","b":"מגדולי חכמי דורו,רב במכנס-תצ\"ז. אולי הכוונה לר חיים ולא חביב."},{"i":21559,"n":"טולדנו, חביב ממכנאס","f":"יוסף בן משה","k":"בעל מעגלי צדק","dt":"תקעט - ט תמוז","b":"נכד ר יעקב בן משה טולדנו ממכנאס (מצד אמו?). מחכמי מכנאס, העתיק ספר זקנו אהל יעקב בכתב ידו. קינה לזכרו ב\"קול יעקב\" למהר\"י בירדוגו."},{"i":21560,"n":"טולדנו, חביב ממכנאס - ב","f":"חיים","bt":"תיח","dt":"תעו - ח חשון","b":"חתן ר שמעיה מימרן. מו\"צ במכנאס ועסקן ציבור ודיין אצל אחיו ר משה, היה גם בסאלי-מרוקו. אחיו - ר משה, ר דניאל, ר יהודה. בניו - ר חיים, ר יצחק (יש אומרים שנפטר ללא ילדים). חיבר שו\"ת ופסקי דינים ואבדו."},{"i":21561,"n":"טולדנו, חביב ממכנאס - ג","f":"אליעזר","k":"בעל דעת קדושים","bt":"תקס","bp":"מרוקו","b":"חתן ר משה בן חיים טולדנו. רב במכנאס-תרב, נסע לגיברלטר לגייס כספים בשל הרעב במכנאס-תקפה, הדפיס ספריו באיטליה, חיבר \"בגדי קדש\", חיבר פירוש על ההגדה בשם \"דרך אמונה\" - \"פה ישרים\" - ליוורנו - ובהקדמה מספר את קורותיו שלו ושל משפחתו, ואת התלאות שעברו בעיר מולדתו. אחיו - ר אברהם ור יונה."},{"i":21562,"n":"טולדנו, חביב משלוניקי ופאס - א","f":"חיים בן דניאל","k":"ר חביב החסיד","b":"בא משלוניקי לפאס-שנות ה-ש', מו\"צ במכנאס, נגיד ומקורב למלכות."},{"i":21563,"n":"טולדנו, חיים ממכנאס","f":"יצחק","dt":"תקפז - כו תשרי","dp":"אלקצר-מרוקו","b":"מחכמי מכנאס. נזכר ב\"קול יעקב\"."},{"i":21564,"n":"טולדנו, חיים ממכנאס","f":"ברוך","dt":"תעה - לפני","b":"מחכמי מכנאס, מקורב למלכות עם אחיו ר אברהם, פדה את אחיו אברהם שנאסר בפאס ע\"י השליט."},{"i":21565,"n":"טולדנו, חיים ממכנאס","f":"חביב בן חיים בן דניא","b":"מחכמי מכנאס. בניו - ר משה, ר חביב, ר יהודה."},{"i":21566,"n":"טולדנו, חיים ממכנאס - א","f":"דניאל מספרד","b":"דיין ומו\"ץ במכנאס-שנות ה-ש'. אחיו - ר יוסף, בנו - ר חביב."},{"i":21567,"n":"טולדנו, חיים ממכנאס - ב","f":"חביב","k":"בעל שערי חכמה","dt":"תמב - לפני","b":"מחכמי מכנאס-תלד. בניו - דניאל, יוסף, משה, ברוך. ב\"נר המערב\" ליעקב משה טולדנו מביא שחיבר \"שערי חכמה\" אולם ב\"מלכי רבנן\" מוכיח שר חביב בן ר חיים טולדנו העתיק את הספר בכתב ידו-תלט, אולם הספר אינו מאביו אלא מחכם אשכנזי."},{"i":21568,"n":"טולדנו, חיים ממכנאס - ה","f":"יוסף","k":"בעל טוב טעם - בכת\"י","bp":"מקנאס","dt":"תרח - יג תמוז","dp":"פאס","b":"רב במכנאס, חיבר ביאורים ופירושים, נכלא ע\"י מושל פאס - יחד עם ר יוסף בירדוגו בעל \"השרשים\", ונפטר לאחר חודשיים בכלא. בנו - ר עייאד."},{"i":21569,"n":"טולדנו, חיים ממכנאס-ג - מהרח\"ט","f":"משה","k":"בעל פסקי מהרח\"ט","bt":"תנ","bp":"מקנאס","dt":"תקט - סיון-אחרי","b":"דיין במכנאס, אב\"ד-תפז על מקום ר משה אדהאן. ירש-תף את דודו העשיר ר חיים בן ברוך טולדנו ויכל להתפנות ללימוד התורה, חיבר \"ארבעה טורי אבן\" על שו\"ע."},{"i":21570,"n":"טולדנו, חיים מסאלי - ד","f":"יהודה בן חיים","k":"בעל שו\"ת מהר\"ט","bt":"תס","dt":"תקמג - יא שבט","dp":"סאלי?","b":"תלמיד ר משה בירדוגו. חתן אחיו - ר יוסף (אשתו שמחה נפטרה-תפז ללא ילדים) וחיבר קינה על פטירת אשתו. רב במכנאס, סאלי-תקיג עם ר יעקב ביבאס. חתם-תקט במכנאס עם ר חיים בן משה, אחיו - ר יעקב טולדנו, ור מרדכי בירדוגו. חיבר גם את רשימת הנפטרים חכמי המערב בין השנים תעד - תקלג."},{"i":21571,"n":"טולדנו, ידידיה","f":"אברהם","k":"בעל יד ידידיה","dt":"תשג - ו אד\"א","dp":"מכנאס","b":"חיבר \"יד ידידיה\""},{"i":21572,"n":"טולדנו, יהודה","f":"אליהו הנביא","b":"בניו - ר חיים, ר חביב, ר אליעזר - ונכדו ר משה בעל \"מלאכת הקדש\"."},{"i":21573,"n":"טולדנו, יהודה (הדוס) ממכנאס","f":"מאיר","k":"בעל אמרי בינה","bt":"תקט-מ","bp":"מכנאס","dt":"תקפ - טו ניסן","b":"רב במכנאס-מרוקו, ספרא רבא, בלשן. חיבר \"אמרי בינה\", על פירוש רש\"י לתורה ועוד ספרי פירושים חידושים לש\"ס ושו\"ת. העתיק בכתב ידו ספרי קדמונים, ואת מגלת היחס של משפחת טולדנו, והעתיק עם תוספות את רשימת הנפטרים רבני המערב לקרובו ר חיים בן יהודה טולדנו."},{"i":21574,"n":"טולדנו, יהודה הדוס ממכנאס","f":"חביב","bt":"תקסח","dt":"תקצג","b":"תלמיד ר יקותיאל בירדוגו, למד עם ר יצחק עמאר."},{"i":21575,"n":"טולדנו, יהודה מטבריה","f":"יעקב","bt":"תרח","bp":"מכנאס","dt":"תרפד - כה אב","dp":"טבריה","b":"מחכמי טבריה - עלה בשנת תרכב, כמה פעמים בשליחות במרוקו. בשנת תרסד נשיא הקהלה הספרדית בטבריה. אחיו הגדול ר שלמה היה גם הוא רב בטבריה ונפטר בדרכו בשליחות הקהלה."},{"i":21576,"n":"טולדנו, יהודה ממכנאס","f":"חיים","dt":"תפט - ד תמוז","b":"רב במכנאס-מרוקו. בניו - ר אליעזר, ר יוסף, ר חיים, ר דניאל. אחיו - ר יהודה שחיבר את תעודת היחס של משפחת טולדנו."},{"i":21577,"n":"טולדנו, יהודה ממכנאס","b":"מראשי קהלת מכנאס, חתם-תרי עם ר חביב בן יולי הלוי."},{"i":21578,"n":"טולדנו, יהודה ממכנאס - ג","f":"יעקב","k":"בעל שדה צופים","dt":"תקסד - יא ניסן","b":"מחכמי צפון אפריקה, רב במכנאס, חיבר \"שדה צופים\" על הנביאים. אחיו - ר משה, ר ברוך."},{"i":21579,"n":"טולדנו, יוסף מטולדו-ספרד - א","b":"מחכמי ספרד. אביו של ר דניאל מפאס."},{"i":21580,"n":"טולדנו, יוסף מטנג'יר","f":"אברהם","b":"מחכמי טנג'יר-מרוקו-שנות ה-תק'."},{"i":21581,"n":"טולדנו, יוסף מירושלים","dt":"תקכ - יט אייר","dp":"ירושלים","b":"מחכמי ישיבת ר אברהם מיוחס בירושלים-תקיח. אולי הוא שהיה מסאלי והיה אצל ר כליפא בן מלכא באגאדיר."},{"i":21582,"n":"טולדנו, יוסף ממכנאס - ב","f":"דניאל","b":"מו\"ץ במכנאס-שנות ה-ש'. (אביו ר דניאל הגיע משלוניקי למרוקו). אחיו - ר חיים."},{"i":21583,"n":"טולדנו, יוסף ממכנאס - ג","f":"יהודה","dt":"תעג - כ כסלו","dp":"מכנאס","b":"מחכמי מכנאס. נפטר צעיר."},{"i":21584,"n":"טולדנו, יוסף ממכנאס - ד","f":"משה","dt":"תקמח - ד אלול","b":"רב במכנאס. חיבר פירוש על רש\"י לתורה. בנו - ר חביב."},{"i":21585,"n":"טולדנו, יוסף מסאלי-מרוקו","b":"מחכמי סאלי-מרוקו-שנות ה-ת'. אולי הוא שעלה לירושלים והיה חברו של ר כליפא בן מלכא."},{"i":21586,"n":"טולדנו, יעקב מטבריה","b":"חתם-תקצא על כתב שליחות ר יהודה נחמד מטעם קהלת טבריה, עם ר אלעזן ן דנאן, ר שמואל בכר אלקלעי, ר משה שמחון, ועוד."},{"i":21587,"n":"טולדנו, יעקב מליסבון","b":"רב בליסבון-תרכ\"ט-תרס\"ח"},{"i":21588,"n":"טולדנו, יעקב ממכנאס","dt":"תקכג","b":"נכד(-בן בתו) ר יעקב מלכא מפאס. דיין במכנאס-תפג."},{"i":21589,"n":"טולדנו, יעקב ממכנאס","f":"ברוך","dt":"תקכו","b":"מחכמי מכנאס. נזכר ב\"קול יעקב\" לר יעקב בירדוגו."},{"i":21590,"n":"טולדנו, יעקב ממכנאס-מהרי\"ט","f":"משה בן ברוך ממכנאס","k":"בעל אהל יעקב","dt":"תקלא - אייר","dp":"מכנאס","b":"תלמיד ר משה בירדוגו-המשבי\"ר. דיין אצל רבו יחד עם אחיו - ר חיים. ראב\"ד במכנאס-תקי כ-40 שנה יחד עם אחיו ר חיים ועם ר מרדכי בירדוגו. היה מחלוקת כנגדו בעיר מכנאס מכמה מתנגדים שניסו למנות דיינים ושוחטים מטעמם. (היה חכם נוסף בשם זה שהתכתב עם החיד\"א והוא שהו\"ל \"מלאכת הקדש\"-תקסג)."},{"i":21591,"n":"טולדנו, יעקב משה מטבריה","f":"יהודה","k":"בעל נר המערב","bt":"תרם","bp":"טבריה","dt":"תשכא - כד תשרי","b":"חוקר תולדות ישראל מחכמי טבריה-תרנח, הקים בי\"ס בפקיעין, סייע ברכישת אזור קבר הרמב\"ם, בזמן מלחה\"ע ה-I גורש מהארץ ושהה בקורסיקה עם גולים רבים מטבריה. קיבל הצעה לכהן כראב\"ד בקהיר, דיין בטנגי'ר, ראב\"ד בקהיר, אלכסנדריה. חיבר גם \"תולדות ישראל במרוקו\". הציע להרצל להחליף את תכנית אוגנדה במרוקו. רב בטנג'יר, קהיר, אלכסנדריה, תל אביב, שר הדתות. פרסם מאמרים ב\"אוצר החיים\" - דעווא תרפה, \"בית הכנסת\" - תל אביב תשו, \"הדביר\" - ירושלים תרעט, \"ירושלים\" - ירושלים תרמב-תרעט, \"סיני\" - ירושלים תרצז, \"הפוסק\" - תל אביב תש-תשיד, \"קול תורה\" - ירושלים תרץ-תשז."},{"i":21592,"n":"טולדנו, יצחק ממדריד","k":"בעל רקיע עגול","b":"רב במדריד-ס'. חיבר \"רקיע עגול ורקיע ישר\"."},{"i":21593,"n":"טולדנו, יצחק ממכנאס","b":"מחכמי מכנאס-שנות ה-תק'. בנו - ר חיים ממכנאס."},{"i":21594,"n":"טולדנו, יצחק ממכנאס","f":"חביב בן חיים בן דניא","b":"מחכמי מכנאס. בניו - ר חביב, ר משה, ר חיים."},{"i":21595,"n":"טולדנו, יצחק משלוניקי","f":"שמואל","dt":"רפו - אב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":21596,"n":"טולדנו, יצחק משלוניקי - א","dt":"תכה","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":21597,"n":"טולדנו, יצחק משלוניקי - ב","dt":"תמד - י כסלו","dp":"שלוניקי","b":"רב בשלוניקי וראש ישיבה-תכד. בן למשפחה מיוצאי טולידו. מתלמידיו - ר יוסף דוד."},{"i":21598,"n":"טולדנו, יצחק נסים ממכנאס","k":"בעל ויזרע יצחק","bt":"תרכב","bp":"מכנאס","b":"מחכמי מכנאס. ביקר בארץ ישראל. ספרו \"ויזרע יצחק\" נדפס בתוך \"פי חכמים\"."},{"i":21599,"n":"טולדנו, לוי ממכנאס","f":"פנחס","dt":"תסז - אחרי","b":"מחכמי מכנאס-תסז."},{"i":21600,"n":"טולדנו, מאיר מטבריה","f":"יהודה","bt":"תרנט","bp":"טבריה","dt":"תרפט - כג אב","dp":"צפת","b":"למד בפריז, התישב בצפת ועסק בעריכת דין. נהרג עק\"ה בפרעות."},{"i":21601,"n":"טולדנו, מאיר ממכנאס - א","dt":"תקסד","b":"רב במכנאס. חתן ר משה טולדנו בעל \"אדמת קודש\" וערך את ספר חותנו וקיצרו בשם \"מלאכת הקודש\" - ליוורנו תקסג. בנו היה ר יהודה טולדנו."},{"i":21602,"n":"טולדנו, מאיר ממכנאס - ב","bt":"תרמו","bp":"מכנאס","dt":"תשי - יד אדר","b":"תלמיד ר שלמה בן עמארא ממכנאס. נמנה על חכמי \"עץ חיים\"-תרעב. מתלמידיו - ר יצחק חזן בעל \"יחוה דעת\". מתורתו נלקט לספר \"מאיר עינים\" ונדפס בתוך \"פי חכמים\" תשס."},{"i":21603,"n":"טולדנו, מימון מסאלי","b":"מחכמי סאלי, עמד לדין-תפו בענין פרעון כתובת אשתו שנפטרה."},{"i":21604,"n":"טולדנו, משה מגיברלטר","b":"מחכמי גיברלטאר, חתם על שאלה-תצט עם ר דוד כלפון ור משה ביטאן."},{"i":21605,"n":"טולדנו, משה ממכנאס","f":"חיים","bt":"תג","dt":"תפג - כב אד\"ב","b":"אב\"ד במכנאס-תמ על מקום אביו, וכיהנו אצלו הדיינים ר יוסף בהתית, אחיו ר חביב טולדנו, ר אפרים אלבאז, נפטר ללא בנים. תשובות ממנו ב\"דברי מרדכי\", ועוד. אחיו גם - ר יהודה."},{"i":21606,"n":"טולדנו, משה ממכנאס","f":"יעקב-מהרי\"ט","k":"בעל אהל משה","bt":"תפח","dt":"תקלח - יז אלול","b":"תלמיד דודו ר חיים טולדנו, ואביו ר יעקב-מהרי\"ט. רב במכנאס. חיבר גם \"מגיני שלמה\", וחדושים על הש\"ס, ודרושים. בנו - ר יוסף ערך ספרי זקנו המהרי\"ט."},{"i":21607,"n":"טולדנו, משה ממכנאס","f":"דניאל בן יהודה","k":"בעל אדמת קדש","bt":"תפד","dt":"תקלג - יג טבת","b":"דיין במכנאס. גיסו של ר משה טולדנו בן המהרי\"ט. אחיינו וחתנו - ר יוסף בן משה בן המהרי\"ט (ר יהודה טולדנו), חתנו - ר מאיר טולדנו הו\"ל את ספרו בשם \"מלאכת הקדש\". . אחד מ'בית דין של שלשה במכנאס' (ר שלמה בן אליעזר טולדנו, ר משה בן דניאל טולדנו, ר יקותיאל בן מרדכי בירדוגו). ארבעה מבניו ובתו מתו במגפה וכן אשתו הראשונה."},{"i":21608,"n":"טולדנו, משה ממכנאס וראבאט","f":"חיים","b":"מו\"ץ במכנאס, ראבאט, חתם-תרב על מכתב לרבני פאס, היה גם בטנג'יר-תרכד."},{"i":21609,"n":"טולדנו, משה ממרוקו","f":"ברוך בן יוסף","b":"בנו השני (מתוך 6) של ר ברוך. מחכמי מרוקו. בניו - ר דניאל, ר ברוך, ר חיים, ר יעקב."},{"i":21610,"n":"טולדנו, נסים מטבריה","f":"יהודה","bt":"תרמט","bp":"טבריה","dt":"תרפז - יב שבט","dp":"טבריה","b":"מחכמי טבריה, ופעיל צבור. בניו: ר יעקב משה, ר ברוך."},{"i":21611,"n":"טולדנו, עייאד ממכנאס","b":"מחכמי מכנאס. בנו - ר אברהם."},{"i":21612,"n":"טולדנו, פנחס ממכנאס","f":"ברוך בן יוסף","b":"מחכמי מכנאס-תר, ונזכר ב\"לשון לימודים\". חיבר חדושים בכת\"י."},{"i":21613,"n":"טולדנו, פנחס ממכנאס","f":"דניאל","dt":"תסא","b":"מחכמי מכנאס, נפטר צעיר ור דניאל בהלול נתמנה ע\"י ר חביב טולדנו לאפוטרופוס על ילדיו - מאיר ודניאל."},{"i":21614,"n":"טולדנו, רפאל ברוך ממרוקו","f":"יעקב ממראקש","r":"אדמו\"ר מראדומסק","bt":"תרן","bp":"מכנאס","dt":"תשלא - יח חשון","dp":"בני ברק","b":"מקובל מחכמי מרוקו. השם רפאל נוסף לו בהיותו חולה בילדותו. תלמיד ר חיים בירדוגו, ר חיים משאש, ור יוסף אלקובי. חתן ר שלום עמאר ממכנאס. דיין במכנאס על מקום אביו ויסד חברת \"שובו בנים\" להשיב בנים תועים ליהדותם. איבד את רכושו בפרעות שהיו כנגד היהודים. למד בכולל אברכים שהקים ר זאב הלפרין - הכולל הראשון במרוקו. ממיסדי חברת \"דובב שפתי ישנים\" להוצאת ספרי קדמונים. עלה לארץ והתישב בחיפה ובבני ברק. חברו - ר יוסף משאש. חיבר קיצור שלחן ערוך.","bk":[["קיצור שלחן ערוך",""]]},{"i":21615,"n":"טולדנו, רפאל מטבריה","b":"מרבני טבריה-תרמ\"ח"},{"i":21616,"n":"טולדנו, רפאל ממכנאס","b":"מו\"ץ במכנאס-שנות ה-ת' בזמן מהרח\"ט. חתם על תשובה עם ר סעדיה ן דנאן, ור יהודה עוזיאל."},{"i":21617,"n":"טולדנו, רפאל ממכנאס","b":"סופר דווקני במכנאס, ונעים זמירות."},{"i":21618,"n":"טולדנו, שאול שמואל ממכנאס","b":"דיין במכנאס. חתם עם ר שמואל ואעיש-תקסז, ועם ר רפאל ור מימון בירדוגו. וחתם-תקף עם רבני מכנאס."},{"i":21619,"n":"טולדנו, שלמה ממכנאס-מרוקו","k":"בעל יקהל שלמה","b":"מחכמי מכנאס-מרוקו, חברו של ר שלום משאש רבה של ירושלים."},{"i":21620,"n":"טולדנו, שלמה ממכנאס-מרוקו","f":"אלעזר או אליעזר","k":"בעל פסקי מהרש\"ט","dt":"תקמט - יד טבת","b":"מחכמי מכנאס, תלמיד ר יעקב טולדנו. דיין עם ר רפאל ברדוגו. תשובות ממנו ב\"שופריה דיעקב\". חתם עם ר יקותיאל בירדוגו, ור משה מאמימראן, ור רפאל בירדוגו. תלמידיו ר משה מאימראן מזכירו בשיטה לבבא מציעא. נספד ב\"רב פנינים\" לר רפאל בירדוגו. אחיו - ר חביב. אחד מ'בית דין של שלשה במכנאס' (ר שלמה בן אליעזר טולדנו, ר משה בן דניאל טולדנו, ר יקותיאל בן מרדכי בירדוגו)."},{"i":21621,"n":"טולדנו, שלמה ממרוקו וטבריה","f":"יעקב","bt":"תקצה","bp":"מאכנס","dt":"תרלז - אלול","dp":"תאזא-מרוקו","b":"מחכמי מכנאס, עלה לטבריה-תריח וכיהן כדיין. בשליחות במרוקו ונפטר בשליחותו. חיבר שו\"ת ודרושים בכת\"י."},{"i":21622,"n":"טולדנו, שלמה מפאס","dt":"תקמט - יד טבת","b":"מרבני פאס"},{"i":21623,"n":"טולדנו, שמואל מאמאסיה-תורכיה","b":"מחכמי אמאסיה(=מסיא)-תורכיה-רסה."},{"i":21624,"n":"טולדנו, שמואל ממרוקו","b":"רב במכנאס, וראב\"ד - בשנות ה-תר'. בנו ר אברהם ונכדו ר ברוך בעל \"שאלו לברוך\"."},{"i":21625,"n":"טולדנו, שמואל מקומירגינה","b":"גביר בקומירגינה. תרם לת\"ת בשלוניקי-שנד."},{"i":21626,"n":"טולוזא די, וידאל (יום טוב)","k":"בעל מגיד משנה","bp":"טולוסא","dt":"קיז","b":"תלמיד הרשב\"א. מגדולי חכמי ספרד, רב בטולוזה-קן. חיבר פירוש \"מגיד משנה\" על ה\"יד החזקה\" לרמב\"ם. חיבר גם פירוש בערבית על תועלת ההגיון לחכם אבוחימד בן אלגאזלי, וחיבור לאיוב שנמצא בספריית ר דוד אופנהיים (ואבד?)."},{"i":21627,"n":"טולוזי, שמואל מלאריסה","b":"רב בלאריסה - בדור שלאחר הגירוש."},{"i":21628,"n":"טולון די, אשטרוק מקושטא","b":"מדפיס בקושטא, עם ר דוד נחמיאש-רע ואח\"כ עם ר שמואל ריקומין-רעב."},{"i":21629,"n":"טולטשינסקי, מיכאל מאודסה","bt":"תריב","bp":"אודסה","dt":"תרסה - תמוז","b":"הו\"ל עתון באודסה - \"אדעס נאוואסטי\", \"איזוועסטי נאראד דומי\". עבר לפריז והו\"ל \"פאריז גאזעטא\" - העתון הראשון בפריז בשפה הרוסית. חיבר ספר לתולדות העיר אודסה - ונפטר בטרם סיימו."},{"i":21630,"n":"טולידו די, אברהם מקושטא","k":"בעל קומפאס די יוסף ה","b":"מחכמי קושטא, חיבר בלדינו \"קופמאס די יוסף הצדיק\" - קושטא תצב."},{"i":21631,"n":"טולידו די, אהרן מקושטא","k":"בעל דברי חפץ","bt":"תס","bp":"קושטא","b":"תלמיד ר חיים אליהו פיפאנו. גביר, רב בקושטא, דרשן, חיבר \"דברי חפץ\" ונדפס בעזרת נכדיו - ר יום טוב, ר אברהם, ור אהרן."},{"i":21632,"n":"טולידו די, חיים מקושטא","k":"בעל חיים מדבר","b":"מחכמי קושטא-תקמ. חיבר \"חיים מדבר\" ביאורים על שו\"ע."},{"i":21633,"n":"טולידו די, חיים מקושטא","f":"אליעזר-משנת אליעזר","b":"חיבר הקדמה לספר אביו \"משנת רבי אליעזר\" יחד עם אחיו ר יוסף."},{"i":21634,"n":"טולידו די, משה מאדרינופול","b":"גביר באדרינופול-שנות ה-תר', עבר לקושטא."},{"i":21635,"n":"טולידו די, סימן טוב מקושטא","f":"אליעזר-משנת אליעזר","b":"רב וראש ישיבה בקושטא-תרלה."},{"i":21636,"n":"טולידו, אליעזר מקושטא","k":"בעל משנת דרבי אליעזר","bt":"תקל - בערך","dt":"תרח-כב","dp":"קושטא","b":"נכד ר אהרן די טולידו. תלמיד ר אליהו עניו. פוסק, דיין בקושטא, חתם-תקצד עם ר חזקיה רפאל הכהן ור חיים משה פריסקו-השני. אב\"ד. בניו ר חיים ור יוסף חיברו הקדמה לספרו \"משנת רבי אליעזר\", הו\"ל ספר רבו \"קונטריס דבר אליהו\" ונדפס בסוף ספרו \"משנת רבי אליעזר\", וכן חיבר גם \"קונטרס הזכרונות\" ונדפס בסוף ספרו. בניו גם ר מנחם, ר סימן טוב."},{"i":21637,"n":"טולידו, יוסף","f":"אליעזר-משנת רבי אליע","b":"חיבר עם אחיו הקדמה לספר אביו."},{"i":21638,"n":"טולידו, משה מירושלים","b":"מחכמי ירושלים, בשנת שפט בשליחות בקורפו."},{"i":21639,"n":"טולייל, יחיא מטיטואן-מרוקו","b":"חתם על שטר-תקצח."},{"i":21640,"n":"טולילא, יעקב מאלגיר","f":"ישועה","b":"רב בתלמסאן-שץ, ונזכר בשטרות."},{"i":21641,"n":"טוליראט, ברוך מירושלים","b":"מחכמי ירושלים-סוף שנות ה-תק',"},{"i":21642,"n":"טומקין, דוד","k":"בעל ויברך דוד","bt":"תרכג","dt":"תרפג","b":"רב בפיעטרקוב-תרע\"ג"},{"i":21643,"n":"טומשוב, אלכסנדר מסלוצק","dp":"תרצט","b":"בנו - ר משה בנימין מארה\"ב."},{"i":21644,"n":"טומשוב, משה בנימין מסלוצק","f":"אלכסנדר יהושע","k":"בעל תקון גטין","bt":"תרלח","bp":"סלוצק","b":"תלמיד ר ברוך בר ליבוביץ, ישיבות סלוצק וסלובודקא, ר איסר זלמן מלצר ונסמך ממנו. חתן ר צבי יעקב אופנהיים מקלם בעל \"גאון צבי יעקב\", ובזיוו\"ש חתן ר יעקב יוורעיסקי. רב בסלוצק-תרע, ניו יורק-תרעו. עורך \"יגדיל תורה\" - סלוצק-בריסק תרסט - יחד עם רבו - ר איסר זלמן מלצר - והמשיכו בניו יורק, ור יחזקאל אברמסקי המשיך להוציאו בסלוצק עם ר שלמה יוסף זוין. עורך \"יגדיל תורה\" - נ\"י תרפה. חיבר גם \"אבני שהם\". פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז, \"היכל התורה\" - נ\"י תרצג, \"כנסת ישראל\" - וילנא תרץ, \"המסלה\" - נ\"י תרצו, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז, \"שערי ציון\" - ירושלים תרפא."},{"i":21645,"n":"טונגלאג, ישראל מרדכי מוארשא","k":"בעל אבל כבד","b":"דיין ומו\"ץ בוארשא. חיבר הספד על כמה גדולים - בשם \"אבל כבד\" - וארשא תרמט."},{"i":21646,"n":"טוען, נחום","f":"אליהו אלץ-גוט","dt":"תרמד - יב חשון","b":"פרסם מאמר ב\"המגיד\", הדפיס סדר תנאים להתקשרות חתן וכלה ובו יצא כנגד שמשי הקהלה והיה מחלוקת כנגדו על כך."},{"i":21647,"n":"טופלר, ירחמיאל משה מסאדנווא","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":21648,"n":"טוקו, אליהו"},{"i":21649,"n":"טוקיירא, יצחק מאזמיר","bp":"קושטא","b":"רב באזמיר-שפ בערך."},{"i":21650,"n":"טוקצינסקי, חיים שלמה מפתח תקוה","k":"בעל שאלו שלום ירושלי","dt":"תרפז-ח","dp":"פתח תקוה","b":"עלה לארץ, והתישב בפתח תקוה, וכיהן כמגיד. חיבר גם \"החנוך הישראלי\" בהסכמת הרב קוק, ור משה קלריס מטבריה, \"דברי שלמה\"."},{"i":21651,"n":"טוקצינסקי, יחיאל מיכל מירושלים","f":"אהרן","k":"בעל גשר החיים","bt":"תרלב","bp":"ליחוביץ","dt":"תשטו - ז ניסן","b":"חתן ר בנימין בן שמואל סלנט. בקי,גדול בהוראה,מו\"צ בירושלים-תרנ\"ז. מחבר לוח א\"י. פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא, \"ועד חכמים\" - ירושלים תרפג, \"המאסף\" - ירושלים תרנו, \"המסלה\" - נ\"י תרצו, \"סיני\" - ירושלים תרצז, \"קול ישראל\" - ירושלים תרפא - ירחון חדו\"ת מאת \"צעירי אגודת ישראל בירושלים\", \"קול תורה\" - ירושלים תרץ, \"תורה מציון\" - ירושלים תרנה-תרסה, \"תלפיות\" - נ\"י תשד.","bk":[["קיצור דיני ומנהגי א\"י (גרימ\"ט)",""]]},{"i":21652,"n":"טוקצינסקי, יצחק מפיאנטניצא","f":"מאיר","bt":"תרכו","dt":"תרצו - כג אלול","b":"רב בוואנסוס-מחוז שצוצין, פיאנטצינא-פלך לומזה, מרבני ירושלים-תרפה."},{"i":21653,"n":"טוקצינסקי, משה","dt":"תשמח","b":"מנהל ישיבת סלובודקה בבני ברק. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"כנסת ישראל\" - סלובודקה - ירושלים תשא."},{"i":21654,"n":"טוקצינסקי, ניסן אהרן מירושלים","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":21655,"n":"טור, אריה ליב מוואלפא","f":"גבריאל מלובעשאוו","b":"חתן ר חיים אב\"ד וואלפא. אב\"ד וואלפא על מקום חותנו. בנו ר דב בר מנוברדוק."},{"i":21656,"n":"טור, גבריאל מלובשוב","b":"מצאצאי בעל \"באר הגולה\". חתן ר יעקב סו\"ד מלובאשוב-מצאצאי בעל הט\"ז - ומכאן השם \"טור\" (ע\"ש טורי זהב)."},{"i":21657,"n":"טור, חיים מקרליץ","f":"דב בר מנווהרדוק","b":"אב\"ד קרליץ, ר\"מ בוילנא. אחיו של ר משה."},{"i":21658,"n":"טור, יעקב יהודה","f":"משה בן דב בר מנווהרד","dt":"תרי - טז אדר","b":"חתן ר אריה ליב קניגסברג-בן ר שמואל אהרן אפשטין. בנו - ר נפתלי זאב וולף מוילנא."},{"i":21659,"n":"טור, נפתלי זאב וולף מוילנא","f":"יעקב יהודה בן משה","k":"בעל אהל משה","bt":"תקצז","bp":"וילנא","dt":"תרמה - טו סיון","dp":"וילנא","b":"חתן הגביר ר מרדכי כהן קאנש מוארשא. סופר משורר ומשכיל. משיריו ב\"כנסת ישראל\" לשפ\"ר. בקי בשפות."},{"i":21660,"n":"טורא, אברהם מארה\"ב","f":"יצחק מניו-פורט","dt":"תקפב","dp":"בוסטון","b":"פרנס מראשי קהלת ניופורט-ארה\"ב, נדבן. אחיו - יהודה."},{"i":21661,"n":"טורא, יהודה מאמריקה","f":"יצחק מניו-פורט","bt":"תקלה","bp":"ניו פורט-רוד איילנד","dt":"תריד - יט טבת","dp":"ניו אורליאנס-ניו פורט","b":"גביר, פרנס, ונדבן, עבר לניו אורליאנס, בית הכנסת בניו פורט - שאותו החזיק - נקרא ע\"ש. תרם לכעשרים קהלות ברחבי ארה\"ב, והחזיק 17 מוסדות חנוך וחסד. בצוואתו הניח סכומים רבים לצדקה ובהם לטובת עניי ירושלים בידי מונטיפיורי, ונבנתה שכונה לעניים בירושלים בשם בתי טורא - ימין משה."},{"i":21662,"n":"טורא, יצחק מניו-פורט-אמריקה","b":"רב בניו-פורט. בנו - הגביר הנדיב ר יהודה."},{"i":21663,"n":"טוראצינו, שלמה מירושלים","b":"מקובל בירושלים-שנות ה-ש'-ת', ונזכר אצל ר דניאל פינצי ב\"באר עשק\"."},{"i":21664,"n":"טוראק, יצחק יעקב מקחובקה","f":"יהושע","bt":"תרלב","b":"תלמיד ישיבת וולוזין, כולל קובנא. חתן ר ברוך הכהן מלעבעדאווא. רב בקאחובקה(=קאחאווקא)-פלך טבריא-תרס\"א. נסמך מאת: ר צבי הירש רבינוביץ מקובנא, ר ישראל איזנשטט בעל \"עמודי אש\". הסכמה ממנו ל\"פרחי חמד\" לר מתתיהו בן מתתיהו הלוי."},{"i":21665,"n":"טורבוביץ זאב וולף","bt":"1840","dt":"ה'תרפא 1921","bk":[["זיו משנה",""],["ראש פינה",""],["שיר ידידות",""],["תפארת זיו",""]]},{"i":21666,"n":"טורבוביץ, אהרן יהושע","f":"שבתי","k":"בעל מגילת שבתי","b":"נאסר בעלילת הדם בדובנא-תקפט יחד עם בני משפחתו ובראשם ר שבתי טורבוביץ. וחיבר על כך \"מגילת שבתי\" - נדפסה ע\"י דובנוב ב\"לוח אחיאסף\". אביו של ר זאב וולף מקרוז'."},{"i":21667,"n":"טורבוביץ, זאב וולף מקרוז'","f":"אהרן יהושע-מגילת שבת","k":"בעל ראש פינה","bt":"תרו","bp":"קרלין","dt":"תרפא","b":"חסיד קרלין. רב בסויסלוביץ(=ססלאוויטש)-פלך מינסק-תרכו, קלעצק-פלך מינסק-תרלה, וואלפא-פלך גרודנא-תרלט, קרוז'-(=קראז)-פלך קובנא-תרמה. היה רב חסידי ומקובל גם על המתנגדים בעירו. חיבר גם \"עטרת זיו\", \"תפארת זיו\", ועוד. אביו ר אהרן יהושע נתפס בעלילת הדם של דובנא-תקפט וכתב על כך \"מגלת שבתי\" ע\"ש ראש המשפחה ר שבתי טורבוביץ שנתפס בעלילת הדם. בנו - ר צבי הירש בעל \"ארזי לבנון\", חתנו - ר יוסף אביגדור.","bk":[["תפארת זיו – שו\"ת",""]]},{"i":21668,"n":"טורבוביץ, צבי הירש מאמדור","f":"זאב וולף מקרוז'-ראש","k":"בעל אור צהיר","r":"מו\"ץ באמדור","dt":"תשב - ג חשון","b":"רב באמדור, עלה לארץ-תרצד והתישב במגדיאל.","bk":[["אור צהיר – רמב\"ם",""]]},{"i":21669,"n":"טורטוש, אברהם ברוך","bp":"מרוקו?","b":"תלמיד ר חיים בן עטר ועלה עמו לירושלים בשנת תקיח."},{"i":21670,"n":"טורטוש, שלמה מירושלים","b":"מחכמי ירושלים, בשנת רפה מינה הנגיד את ר שלמה כאפוטרופוס על בתו וכן של היתום אברהם בן הנגיד. נזכר בשות \"באר עשק\"."},{"i":21671,"n":"טורטשי, אברהם הרופא","b":"חיבר ספר רפואה-רן שתורגם ללטינית ועם הוספה מהרופא עזריה בן יוסף בן אבא מרי בופולי, הספר מבוסס על חיבורו של הרופא הערבי אבן אל זהארי."},{"i":21672,"n":"טוריאל, אביגדור מירושלים","f":"מנחם?","dt":"תקעט?","dp":"ירושלים?","b":"מחכמי ירושלים. הסכים על \"מים שאל\" - תקנז."},{"i":21673,"n":"טוריאל, שלמה","f":"שמעון","k":"בעל אשת נעורים","b":"ממקובלי צפת, חיבר פירוש לספר יצירה בשנת שכב בשם \"אשת נעורים\" בכתב יד."},{"i":21674,"n":"טוריס, ברוך משלוניקי","b":"מדפיס בדפוס חיים אברהם בן שבתי נחמה וסעדי הלוי-תקנח."},{"i":21675,"n":"טוריס, שמעון משלוניקי","b":"רופא צבאי בשלוניקי-תרס."},{"i":21676,"n":"טוריץ, שרגא פיבוש מיהנישקעל","f":"מרדכי","bt":"תרלב","b":"רב ביהנישקל(=יהנישקעל)-פלך קובנא-תרסה."},{"i":21677,"n":"טוריקע די, בער מצרפת","f":"יצחק בער","bt":"תקד","bp":"נאנסי","dt":"תקפח","b":"תלמיד ר אברהם יעקב הכהן פרל בלורין-צרפת. חבר בסנהדרין של נפוליאון. חבר באסיפת העם מטעם מחוז לוריין. חיבר ספרים בצרפתית ובהם ספר להגן על התלמוד."},{"i":21678,"n":"טורם, ישראל יעקב מבילקמין","f":"מנחם מנדל מרימנוב","bt":"תקל","dt":"תקפז - ט שבט","b":"חתן ר פנחס אייזנטל מגניווישוב. רבה של בילקמין - אך סירב לאדמורות."},{"i":21679,"n":"טורם, מנחם מנדל מרימנוב","f":"יוסף","k":"אדמור מרימנוב","r":"נכתב על ידי תלמידו בעל המראה יחזקאל","bt":"תקה","bp":"ניישטט","dt":"תקעה - יט אייר","b":"רב בפריסטיק, רימנוב-תקנה והיה שם אדמור. חיבר \"מנחם ציון\" טשרנוביץ תריא, \"עטרת מנחם\" בילגוריא תרע, ועוד.","bk":[["מנחם ציון","חסידות"],["שפתי צדיקים","חסידות"],["ילקוט מנחם",""],["שפתי צדיקים - דרוש",""],["שפתי צדיקים - דרוש, ילקוט מנחם , מנחם ציון",""],["מנחם ציון - ילקוט מנחם (רימנוב)",""]]},{"i":21680,"n":"טורם, נתן יהודה אריה ליב","f":"מנחם מנדל מרימנוב","k":"בעל אילה שלוחה","dt":"תרו - ו ניסן","b":"חתן ר זלמן הכהן גוטוירט מישיניצה. ויתר על האדמורות לרצ\"ה. חיבר \"אילה שלוחה\" - מתורת ר נפתלי מרופשיץ וקצת מחדושיו שלו."},{"i":21681,"n":"טורמינו, אליהו מאזמיר","dt":"תקמא - כח אב","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":21682,"n":"טורמן, אלתר מנדבורנה","b":"רב בנדבורנה-תרצא - תשובה אליו \"מנחת יחיאל\"."},{"i":21683,"n":"טורמן, פנחס מטרנטון","bp":"איוונוביץ-פלך מינסק","b":"מחכמי וילנא. היגר לארה\"ב וכיהן כרב בטרנטון-ניו ג'רסי."},{"i":21684,"n":"טורנהים, אלעזר מאיר מואלברזש","f":"יעקב משה מואלברוש","k":"אדמור מואלברזש","dt":"תרפט - ד אדר","b":"התישב בזדונסקוואלא-תרפד."},{"i":21685,"n":"טורנהים, יעקב משה מואלברזש","f":"ישכר דב בריש הכהן","k":"אדמור מואלברזש","bt":"תקצה","dt":"תרעח - יד כסלו","b":"תלמיד ר מאיר יחיאל ממוגלניצא, ר שלמה מרדומסק, ר אברהם ישכר מרדומסק. רב ואדמור בואלברז על מקום אביו. נהג להתפלל רוב היום וסיים שחרית לקראת השקיעה. התפרסם באוסף הכנריות הגדול שהחזיק בביתו. לתולדותיו בקונטרס \"ואלברז בתפארתה\" בתוך \"אהל ישכר\"."},{"i":21686,"n":"טורנהים, ירחמיאל שלום מואלברזש","f":"אלעזר מאיר מואלברזש","k":"אדמור מואלברזש","dt":"תשב - אלול","b":"אדמור מזאלברזש בזדונסקאוואלא על מקום אביו. הוגלה ללודז בזמן השואה. נספה בשואה."},{"i":21687,"n":"טורנהים, ישכר דב בריש מוולברז","f":"משה מפיעטרקוב","k":"אדמור מואלברזש","r":"אדמו\"ר מולברוז'","bt":"תקסג","dt":"תרלח - א חשון","dp":"פיעטרקוב","b":"חתן ר אברהם צבי מוואלבארזש. תלמיד ר חיים מוואלברום, ר חיים מאיר יחיאל ממוגלניצא (שושלת קוזניץ) ור אלעזר מקוזניץ. רב ואדמור בוולבורג(=ואלבארזש)-תרכב. נחשב לבעל מופת. חיבר \"עבודת ישכר\", \"סדר הזמנים\", ועוד. מתולדותיו ב\"אהל ישכר\". בנו - ר שלמה יצחק מירושלים.","bk":[["עבודת יששכר – עה\"ת",""]]},{"i":21688,"n":"טורנהים, עקיבא מאיר מליקיווא","f":"ישכר דב בריש הכהן","k":"אדמור מואלברזש ליקיו","r":"אדמו\"ר מולברוז'","bt":"תרג","dt":"תרעט - א חשון","b":"תלמיד ר יעקב צבי מפוריסוב (שושלת פשיסחא). אדמור במיכוב, ליקיווא. חיבר \"דברי העם\".","bk":[["דברי העם",""]]},{"i":21689,"n":"טורנהים, צבי מברזיל וב\"ב","f":"יאיר אלימלך","b":"נכד ר עקיבא מאיר מליקיווא האדמור מואלברזש. התגורר בברזיל, עלה לארץ והתישב בבני ברק והקים כולל ע\"ש אדמורי ואלברזש, הו\"ל ספרי אבותיו."},{"i":21690,"n":"טורנהים, שלמה יצחק מירושלים","f":"ישכר בער מוולברוז","dt":"תרעו","b":"בן האדמור מוולברוז', עלה לירושלים-תרלד ופעל להקמת שכונה בירושלים-תרמ, ליד שער שכם."},{"i":21691,"n":"טורנו, שמעון מצפת","b":"מגדולי מקובלי צפת-ת\"ל"},{"i":21692,"n":"טורנובסקי, ישראל יצחק משה","f":"זאב בן שלמה","k":"בעל אמת ואמונה"},{"i":21693,"n":"טורני, מאיר מטריטש","b":"דיין בטריטש-תקס אצל ר לוי פולק מטריטש ונזכר בספרו \"עמודי שיטים\". הסכים על \"ספר החינוך\" - ברין תקנח עם ר לוי פולק, ור סנדר גענזל. חתנו - ר אליעזר שטרסר."},{"i":21694,"n":"טורנר, משה מנעשאווא","b":"רב בנעשאווא-תק\"צ"},{"i":21695,"n":"טורנר, שמואל זנויל מפמורן","k":"בעל דרך חיים","b":"חסיד סטרטין. רב בפמורן-תקצד. חיבר \"דרך חיים\" (שארית יהודה) ניו יורק תשלא."},{"i":21696,"n":"טורץ, יצחק מחיפה","f":"מרדכי","bt":"תרנד","bp":"זאסלי-פלך וילנא","b":"תלמיד ישיבת וולוזין, סלובודקה, כנסת בית יצחק, מיר. חתן רב\"ד ליבוביץ ונסמך ממנו ומאת: ר משה מרדכי אפשטין. רב בקרמצ'וג-תרף, וילנא, לוקישוק, קמניץ ליטובסק, עלה לארץ-תרצה וכיהן כרב ב\"בת גלים\" בחיפה. חיבר חדושים בגפ\"ת - בכת\"י."},{"i":21697,"n":"טורצ'ין, אלעזר צדוק מירושלים","f":"יצחק יונה","k":"בעל מתנה מועטת","b":"מחכמי ירושלים."},{"i":21698,"n":"טורצין, חיים אהרן מירושלים","f":"יצחק יונה טורצין","dt":"תשלב","b":"מגדולי מרביצי תורה בירושלים. פרסם מאמרים ב\"תבונה\" - ירושלים תשא."},{"i":21699,"n":"טורצין, יצחק יונה","f":"צדוק","dt":"תשד - כ כסלו"},{"i":21700,"n":"טורצין, ניסן מצירין","f":"צדוק","dt":"תרעה - יא שבט","b":"רב בצירין-פלך נוברדוק."},{"i":21701,"n":"טורצקי, שמואל","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":21702,"n":"טורקר, אברהם מרדכי מדוברומיל","k":"אדמור מדוברומיל","b":"תלמיד ר מנחם מנדל מרימנוב, ור נפתלי צבי מרופשיץ. רב בדוברומיל, החל לנהוג באדמורות."},{"i":21703,"n":"טורש, דובריש","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":21704,"n":"טיאנו, יצחק משה משלוניקי","b":"גביר בשלוניקי-תריז ונמנה על שבעת טובי העיר."},{"i":21705,"n":"טיאנו, רפאל משלוניקי","dt":"שלב - ב סיון","dp":"שלוניקי","b":"מחכמי קהלת איטליה בשלוניקי."},{"i":21706,"n":"טיאר, יצחק מטריפולי","bp":"טריפולי-לוב","dt":"תקף","b":"רב באלגיר. תשובה ממנו ב\"משכנות הרועים\", והסכים על \"שער שלמה\"-תקעז (נדפס בתרלח)."},{"i":21707,"n":"טיבה - משפחה","b":"משפחה יוצאת העיר טיבה(=תבין)-יון."},{"i":21708,"n":"טיבה, חיים יעקב מניש","f":"יעקב מקיוסטנדיל","b":"דיין בניש-תקנח יחד עם ר יהודה ן עלי בעל \"קמח סולת\"."},{"i":21709,"n":"טיבה, יעקב מסופיה וקיוסטנדיל","bp":"סופיה","b":"תלמיד ר שלמה שלם בסופיה. ר\"מ בסופיה ודיין-תקיט (עם ר דוד בן אהרן), רב בקיוסטנדיל-שנות ה-תק'."},{"i":21710,"n":"טיבה, שמואל משלוניקי","dt":"שעח - ד טבת","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":21711,"n":"טיבואה, יעקב מאזמיר","b":"מדפיס באזמיר אצל ר דוד חזן-תצג."},{"i":21712,"n":"טיבי, משה מתונס","b":"דיין בתונס. חתם אחרי הראב\"ד ר אליהו חי בורגל-תרנח, על תשובה לר\"מ זקן מאזוז מג'רבא."},{"i":21713,"n":"טיבי, שלמה מסוסה-תונס","dt":"תרצג - י תמוז","b":"בנו - חיים הנציחו בספר \"אוהב משפט\"."},{"i":21714,"n":"טיבלום, דוד מאוטואצק","dt":"תש..","b":"נודע כאחד מגאוני פולין. מראשי ישיבת \"תומכי תמימים\" בוארשא. אדמור-תרצח לאחר פטירת ר יוסף מפילוב - רבים מחסידי פילוב עברו אליו. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":21715,"n":"טיברג, יחיאל יוסף","b":"חתן ר דוד טויב מדאבזינסק בעל \"בנין דוד\". בנו ר יהודה משה טיבר-דנציגר."},{"i":21716,"n":"טיגירה, יצחק עמנואל שיניאור","f":"דינא טיגירה די סטמוש","dt":"תנה","b":"גביר עשיר, בן למשפחת אנוסים בהמבורג, הגיע עם אביו שהיה קונסול ספרד בפלנדריה וחזר ליהדות, וקיבל את השם אברהם. מקורב למלכת שבדיה. החזיק ישיבה בהמבורג ובין אנשיה ר יעקב ששפורטש. מתומכי שבתי צבי. ניסה לבטל את גזירת הגירוש מוינה-תל לבקשת ר גרשון אשכנזי בעל עבודת הגרשוני. ר יהודה ליאון הקדיש לו את ספרו - ספר תהלים בתרגום פורטוגזי."},{"i":21717,"n":"טיגר, זלמן יאקל הכהן מוילנא","f":"מרדכי צבי","bt":"תקצ","bp":"וילנא","dt":"תרנו - כז תשרי","b":"נכד הנגיד ר יואל בן וולף הכהן טיגר מוילנא. חתן גביר מסמרגון וקיבל סמיכה מר ליבלי שפירא אב\"ד סמרגון. חזר לוילנא והיה מגיד שיעורים. דיין בוילנא."},{"i":21718,"n":"טיגרמן, יוסף מאיר מנייהייזל","bt":"תריז או תרלד","dt":"תשד - כו סיון","b":"תלמיד הכת\"ס. רב בנובוק-תרלו, נייהייזל-תרמא. גיסו של ר יעקב שפירא מטארצל. חתנו - ר אריה ליב ליכטיג מהמבורג."},{"i":21719,"n":"טיגרמן, יצחק מבעקעש-טשאבא","f":"יוסף מאיר מנייהייזל","dt":"תשד - ח תמוז","b":"תלמיד הדעת סופר. חתן ר שלמה זלמן קליין מגאווע. רב גאווע-תרעג על מקום חותנו, טיסא ליק(=טיסאלוק), בעקעש-טשאבא-תרפח. נספה בשואה."},{"i":21720,"n":"טיוולי, ברוך מאיטליה וירושלים","f":"מרדכי","b":"מתלמידי ה\"בית יוסף\"-שט\"ו"},{"i":21721,"n":"טיוולי, יוסף יעקב חי מפדובה","b":"מחכמי פדובה-תקצג."},{"i":21722,"n":"טיוולי, מרדכי מירושלים ניקופול","f":"ברוך","bt":"שך","bp":"טיוולי-איטליה","dt":"שצה - בערך","b":"לאחר הגירוש באיטליה עלה לירושלים עם אביו, לאחר פטירת אביו נדד במקומות שונים ובהם דמשק - שם פגש את ר ישראל נג'ארה שנתן לו מכתב המלצה, רב בניקופול."},{"i":21723,"n":"טיוולי, משה מאלכסנדריה","b":"תלמיד ר עזוז בן שמעון נחמני באלכסנדריה. מחכמי אלכסנדריה-שלג וחתם על פסק מהריב\"ל עם ר עזוז נחמני, ר משה הכהן, ור אברהם בון דיאה. חתם-שכט על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא."},{"i":21724,"n":"טיטבסקי, ניסן מקאדימא","f":"אפרים צבי","k":"בעל עצי עדן","bt":"תרכו","b":"נכד ר משה ספקטור מוארחיווקא, מצאצאי ר חיים בן בצלאל-אחי המהר\"ל. רב בסטניסלבציק(=סטאניסלאווטשיק)-פודוליה-תרנה, קדימא(=קאדימא)-פודוליה-תרנח. חיבר \"עצי עדן\" - בכת\"י."},{"i":21725,"n":"טיטולבוים, דוד ממזריטש-ליטא","f":"שלמה","k":"בעל דבש תמר","b":"מחכמי מזריטש-ליטא."},{"i":21726,"n":"טיטל, צבי הירש","b":"דומ\"צ באנטרדם-תרי\"ח"},{"i":21727,"n":"טיטלבוים (שיף), צבי הירש","f":"יצחק","b":"מחכמי פרמישלא ואחר כך זבורוב שבהגר. בנו הישמח משה וחתנו החליפו שמם מפיש לטיטלבוים."},{"i":21728,"n":"טיטלבוים חיים צבי בן חנניה יום טוב ליפה","bt":"1880","dt":"ה'תרפו 1926","bk":[["עצי חיים",""]]},{"i":21729,"n":"טיטלבוים יקותיאל יהודה בן אלעזר ניסן","bt":"1808","dt":"ה'תרמג 1883","bk":[["אבני צדק",""]]},{"i":21730,"n":"טיטלבוים מאייר, יואל מקירלהאז","f":"חנוך הניך דב מקרצקי","k":"בעל דברי יואל","bt":"תרעג","bp":"סאסוב","dt":"תשמו - כו תמוז","b":"שינה שמו ממאייר לשם אמו טיטלבוים. חתן ר יוסף לעווי מקירלהאז. רב על מקום חותנו ועמד בראש ישיבה שם. ניצל מהשואה. היה רב בסטמר אחר השואה. הגיע לניו יורק-תשז והיה שם רב. בזיוו\"ש חתן ר חיים יצחק אייזק הלברשטם מסלטפינה. הוציא לאור ספרי אביו \"עיר חנוך\". אחיהם של ר חנניה יו\"ט ליפא מאייר טיטלבוים, ור יצחק מאיר מאייר מקרצקי."},{"i":21731,"n":"טיטלבוים, א' שמואל","f":"אריה ליב טטיטלבום","bt":"תרמח","b":"אדמו\"ר מקלבסוב בארה\"ב"},{"i":21732,"n":"טיטלבוים, אביגדור","k":"רב בפיבניטשנע","dt":"תשא","b":"רב בפיבניטשנע"},{"i":21733,"n":"טיטלבוים, אביגדור מצאנז","f":"אברהם חיים","bt":"תרס","dt":"תשג","b":"חתן ר שלום הלברשטם מפיקעלי. רב בצאנז(=סנדז). נספה בשואה."},{"i":21734,"n":"טיטלבוים, אברהם אהרן מקולבסוב","f":"יקותיאל יהודה מסיגט","k":"אדמור מקולבסוב","bt":"תקפו","dt":"תרע - יב אלול","b":"חתן ר יחיאל רובין מקולבסוב. נסמך מאת: ר ליפא מייזליש בעל שו\"ת מהרא\"ל, ר נחום ראובן מרישא. רב ואדמור בקולבסוב(=קאלבסוב)-תרכב על מקום חותנו (בתמיכת הדברי חיים וכנגד חסידי דזיקוב - והייתה מחלוקת גדולה בענין זה). ספר לזכרו ובו צוואתו \"הספד מר\" למברג תרעא."},{"i":21735,"n":"טיטלבוים, אברהם חיים מקרעניץ","f":"משה דוד מלאפוש","dt":"תשא","b":"חתן ר אריה ליבוש הלברשטם מגריבוב. רבה של קרעניץ-תרסז. נספה בשואה."},{"i":21736,"n":"טיטלבוים, אברהם יעקב מקופטשינץ","f":"ישראל מרדכי","bt":"תרנח","dt":"תשכט","b":"רב בוינה. היגר לארה\"ב ושימש שם ברבנות, בנו ר שלמה על מקומו בקווינס."},{"i":21737,"n":"טיטלבוים, אברהם מטרנוב","f":"יקותיאל יהודה מטרנוב","bt":"תרסח","b":"תלמיד ישיבת בובוב. תלמיד ר צבי הירש מייזלש שהשיב לו ב\"בנין צבי\"-תרפו."},{"i":21738,"n":"טיטלבוים, אהרן","f":"יקותיאל יהודה מטרנוב","bt":"תרסט","b":"תלמיד ישיבת בובוב."},{"i":21739,"n":"טיטלבוים, אהרן","f":"חנניא יו\"ט ליפא","b":"בנו של האדמור מוואלובא-נירבאטור בנ\"י. חתן ר צבי הירש מייזלש מוייצען."},{"i":21740,"n":"טיטלבוים, אהרן מדוברומיל","b":"רב בדוברומיל-תרפה."},{"i":21741,"n":"טיטלבוים, אהרן מדרוהוביטש","f":"נחום צבי מדרוהוביטש","k":"אדמור מדרוהוביטש","b":"אדמור בדרוהוביטש על מקום אביו."},{"i":21742,"n":"טיטלבוים, אהרן מוולובה ונירבטו","f":"ישראל יעקב יוקל","k":"בעל תהלות אהרן","bt":"תרמא","bp":"ברבשט","dt":"תשד - ג סיון","dp":"אושוויץ","b":"חתן ר שמואל באב\"ד מסנדובה, רב בוולובה-תרסה - לצד אביו ועל מקומו אחריו-תרפד, נירבטוב-תשב על מקום אחיו - ר נפתלי. נספה בשואה. חיבר \"פסק בית דין\" תשג."},{"i":21743,"n":"טיטלבוים, אהרן מטילטש","f":"אברהם חיים מקרניץ","dt":"תש..","b":"רבה של טיליטש, קרניץ על מקום אביו. נספה בשואה."},{"i":21744,"n":"טיטלבוים, אהרן מטשנסטקוביץ","f":"יהושע חיים מטשנסקובי","k":"אדמור מטשנסטקוביץ","bt":"תרעג","bp":"טשנסקוביץ","dt":"תשס","b":"רב בטשנסקוביץ-תרצז על מקום אביו, היגר לניו יורק-תרצח וכיהן כאדמור מטשנסקוביץ על מקום אביו. חתן רא\"ל טיטלבוים מקולבסוב."},{"i":21745,"n":"טיטלבוים, אהרן מירושלים","f":"יעקב יצחק","bt":"תרנא","bp":"ירושלים","b":"תלמיד ישיבת תורת חיים בירושלים. חתן ר שמחה בן ברוך מנדלבוים. נסמך מאת: ר חיים ברלין, ראי\"ה קוק. מו\"ץ בירושלים (נתמנה ע\"י ר שאול חיים הורוביץ מדוברובנא), בשליחות הועד הכללי בראשות ר חיים ברלין בארה\"ב ורב בסט לואיס על מקום רד\"ב אברמוביץ (שנשלח לשם מירושלים - וחזר). חבר בועד העזרה ליהודי אירופה בזמן מלחה\"ע ה-I, ואחריה, סייע רבות ליהודי ארץ ישראל. מראשי המזרחי."},{"i":21746,"n":"טיטלבוים, אהרן ממונרו","k":"בעל זבח פסח","b":"רב קרית יואל במונרו-ארה\"ב."},{"i":21747,"n":"טיטלבוים, אהרן מניו יורק","bt":"תרנא","dt":"תשי - ב אלול","b":"רב פעלים לחיזוק התורה וישוב הארץ,רב בברוקלין-תרפ\"ב,חזר לירושלים"},{"i":21748,"n":"טיטלבוים, אליהו בצלאל מטעטש","f":"יקותיאל יהודה-ייטב ל","k":"אדמור מטעטש","bt":"תרי","bp":"גורליץ","dt":"תרעח - כט אב","dp":"טעטש","b":"חתן ר פנחס יוסף הגר מקוסוב. רב בפוליאן-ריסקווא(=פוליען-ריסקובה)-תרלה, טעטש-תרמג על מקום אחיו ושם גם אדמור, בניו: ר משה על מקומו אחריו בטעטש, ר חיים מטעטש."},{"i":21749,"n":"טיטלבוים, אליעזר מטיטשין","b":"רב בטיטשין-תרמח."},{"i":21750,"n":"טיטלבוים, אלכסנדר שמואל מארה\"ב","f":"אריה ליבוש","k":"אדמור מקולבסוב","bt":"תרסח","bp":"רישא","dt":"תשם - ג תמוז","b":"חתן ר דוד הורביץ האדמור מפשצלוב. הגיע לניו יורק ושימש כרב ואדמור מקולבסוב על כסא אביו, ובנו ר דוד על מקומו אחריו."},{"i":21751,"n":"טיטלבוים, אלעזר ניסן מסיגט","f":"משה-ישמח משה","k":"אדמור מדרוהוביטש","bt":"תקמו-ח","dt":"תרטו","b":"חתן ר אהרן מחודרוב-תלמיד ר אלימלך מליזנסק. רב בסיגט-תקצד לבקשת אביו, ועזב בגלל מחלוקת - בענין שוחט שלא ציית לרב וחסידי קוסוב סייעו בידו כנגד הרב, רב במונקטש, הוזמן לאויהעל על מקום אביו אך שלח לשם את בנו הייטב לב, רב ואדמור בדרוהוביטש-תר והיה שם אדמור. ליקוטי תורתו ב\"זכרון אלעזר\" ניו יורק תשמג."},{"i":21752,"n":"טיטלבוים, אלעזר ניסן מסיגט","f":"משה יוסף מאויהל","b":"נפטר צעיר."},{"i":21753,"n":"טיטלבוים, אפרים דב","f":"יצחק מהוסקוב","b":"חתן ר אלימלך רובין מיברוב. בנו ר מרדכי דוד אדמור בבאר שבע."},{"i":21754,"n":"טיטלבוים, אריה ליב מקרעשוב","f":"ירוחם","bt":"תר","dt":"תרפא","b":"רב ואדמור בקרשוב, רודניק(=רידניק)-תרעב. חתן ר ברוך הלברשטם מגורליץ."},{"i":21755,"n":"טיטלבוים, אריה ליבוש מקולבסוב","f":"יחיאל מקולבסוב","k":"אדמור מקולבסוב","bt":"תרמח","bp":"מושציסק","dt":"תשא - כט שבט","b":"נסמך מאת: ר משה באב\"ד מלבוב, ר נתן לוין מרישא. חתן ר חיים יונה הלפרין מרישא. חסיד גיסו ר אלעזר הלפרין מרישא (שושלת ליזנסק). רב בקולבסוב-תרעא על מקום אביו. היגר לארה\"ב-תרפא וכיהן כרב ואדמור מקולבסוב."},{"i":21756,"n":"טיטלבוים, אשר ישעיה מבליגרד","bt":"תרי","dt":"תש","b":"חתן הרב רובין מבליגרוד. אב\"ד בליגרד-תרל על מקום חותנו, לימנע-תרלו, דרבן-רומניה. נספה בשואה."},{"i":21757,"n":"טיטלבוים, בנימין מרודניק","f":"אריה ליבש","bt":"תרנא","dt":"תשכא","b":"רב בקרעשוב על מקום אביו, רודניק-תרעב, עבר לארה\"ב-תרצג (בגלל מחלוקת בקהלה) ושינה שמו להלברשטם (שם אמו) - רב בלוס אנגלס. חתן ר יעקב אפשטין מאוזרוב."},{"i":21758,"n":"טיטלבוים, ברכיה מאויהל","f":"משה יוסף מאויהל","bt":"תרלד","dt":"תרעז - יב ניסן","dp":"בודפשט","b":"חתן רצ\"א שפירא מבלוזוב. רב באוהל על מקום אביו - אך לא ישב שם אלא אצל חותנו בבלוזוב (על כך היתה מחלוקת בין רבני המשפחה לבין ה\"מנחת אליעזר\" ואביו - נדפסו מקצתם בחוברת פולמוס. במלחה\"ע ה-I עבר לבודפשט."},{"i":21759,"n":"טיטלבוים, גדליה אשר מקלוש","dt":"תש..","b":"חתן ר יוסף באב\"ד מקלוש. רב בקלוש על מקום חותנו-תרץ. נספה בשואה."},{"i":21760,"n":"טיטלבוים, דב ברל מקופיטשניץ","b":"רב בקופיטשיניץ, לוזאן-בוקובינה. ממשתתפי \"אהל מועד\"."},{"i":21761,"n":"טיטלבוים, דוד יצחק מערדא-בעניע","b":"נכד ר משה יוסף פלגמן מהעדילא-מאדע. בנו - ר שמעון מטארנאליא, ור חיים יהודה ליב מפוטנאק. חתנו - ר פנחס יעקב זלצר מהעדילא-מאדע."},{"i":21762,"n":"טיטלבוים, דוד מעטשעד","f":"אברהם אהרן","k":"בעל דברי דוד","bt":"תרל","bp":"קולבסוב","dt":"תשד","dp":"אושוויץ","b":"חתן ר שמעון מרילוס מירוסלב. רב בירוסלב, רבה של עטשעד-תרסד והקים שם ישיבה בראשות בנו ר אברהם אהרן. חיבר \"דברי דוד\" מישקאלץ תשג. נספה בשואה."},{"i":21763,"n":"טיטלבוים, דוד מפרמישלא","f":"ברכיה מאויהל","k":"אדמור מפרמישלא","bt":"תרן","dt":"תשב","b":"אדמור בפרמישלא. חתן ר נפתלי הורביץ ממעליץ. נספה בשואה."},{"i":21764,"n":"טיטלבוים, דוד שלמה","b":"תשובה אליו ב\"דברי חיים\"."},{"i":21765,"n":"טיטלבוים, זלמן ליב מסיגט","b":"רב בסיגט, הקים ישיבה ובראשה כיהן הדיין ר זלמן גרוס ובה למדו גם הכשרה מקצועית והיו בה 25 מכונות אריגה."},{"i":21766,"n":"טיטלבוים, חיים אלעזר מטשנאד","f":"שלמה בן יוקל מסטריזו","bt":"תרן","bp":"סטריזוב","dt":"תשא-ב","dp":"קמניץ-פודולסק","b":"חתן ר רפאל גרוס מברבשט, דיין בטשאנד ורב לחסידי סיגט-סטמר בטשאנד, רב בגרוסורדין-תרצט וחתנו ר משה ליב ליכטאג על מקומו אחריו בטשאנד. נספה בשואה."},{"i":21767,"n":"טיטלבוים, חיים יהודה מקאבא","f":"דוד יצחק מערדא-בעניע","bt":"תרלז","bp":"בערדא-בעניע","dt":"תשד - כ סיון","b":"תלמיד השב\"ס. ור נפתלי שוורץ מהעדילא-מאדע. חתן ר מאיר טננבוים מפוטנאק. רב בפוטנאק לצד חותנו. רב בקאבא-תרסט. רבה האחרון של פוטנאק-תרץ על מקום חותנו. נספה בשואה."},{"i":21768,"n":"טיטלבוים, חיים יוסף מדינוב","f":"ישראל יעקב יוקל","dt":"תשה - א אב","dp":"סיביר","b":"חתן ר נחמיה ויינברגר. רב בדינוב. נספה בסיביר לשם ברח מהשואה."},{"i":21769,"n":"טיטלבוים, חיים יעקב מלימנוב","f":"משה יוסף מאויהל","bt":"תרלד","dt":"תרצד - כא חשון","dp":"בובוב","b":"רבה של טשנסקוביץ, לימנוב-תרסח. חתן ר שלמה מבובוב, ובזיוו\"ש חתן ר מנשה טיטלבוים נכד הישמח משה."},{"i":21770,"n":"טיטלבוים, חיים מבריגל","dt":"תשג","b":"נכד ה\"ישמח משה\". חתן ר טוביה אב\"ד בריגל. רב בבריגל על מקום חותנו. קיים ישיבה בביתו גם בזמן הכיבוש הנאצי. נספה בשואה."},{"i":21771,"n":"טיטלבוים, חיים מהעדילא-מאדע","b":"חתניו - ר שמואל בנימין שיפר מאלשא-קובין, ור שבתי אלטמן מבודפשט."},{"i":21772,"n":"טיטלבוים, חיים מזקליטשין","b":"רב בזקליטשין."},{"i":21773,"n":"טיטלבוים, חיים מטעטש","f":"אליהו בצלאל מטעטש","dt":"תשד - ו סיון","dp":"אושוויץ","b":"חתן ר יעקב פנט מרעטיאג. רבם של חסידי סיגט בטעטש. נספה בשואה."},{"i":21774,"n":"טיטלבוים, חיים מנפולומיץ","f":"יוסף מנפולמיץ","b":"רב בנפולומיץ, דיין בקראקא. בנו ר מנחם צבי רב בנפולומיץ על מקומו."},{"i":21775,"n":"טיטלבוים, חיים צבי מסיגט","f":"חנינה יום טוב ליפא","k":"אדמור מסיגט","r":"אב\"ד ור\"מ סיגוט","bt":"תרם","bp":"טעטש","dt":"תרפו - ו שבט","dp":"קליינורדין - סיגט","b":"מחשובי האדמורים בהונגריה. חתן ר שלום אליעזר הלברשטם מראצפרט בנו של ה\"דברי חיים\" מצאנז. חסיד אדמורי צאנז ובלז. רב ואדמור בסיגט-תרסד על מקום אביו ור\"מ בישיבה. חיבר \"עצי חיים\" סיגט תרפז.","bk":[["עצי חיים - עה\"ת, מועדים, מקוואות, ושו\"ת",""]]},{"i":21776,"n":"טיטלבוים, חנניה יום טוב","f":"חנוך הניך","k":"אדמור מסאסוב-ארה\"ב","bt":"תרסה","dt":"תשכו","dp":"טבריה","b":"חתן דודו ר יואל מסטמר. רב בסטמר ור\"מ בישיבה ליד חותנו. עלה לארץ-תשד, הגיע לניו יורק-תשח והיה שם רב ואדמור מסאסוב. עלה לארץ והיה רב בקרית ישמח משה."},{"i":21777,"n":"טיטלבוים, חנניה יום טוב ליפא","f":"אהרן מואלאווע הי\"ד","k":"בעל לבושי יום טוב","bt":"תרעב","bp":"וולובה","dt":"תשמג - טז טבת","b":"רב בוולובה לצד אביו. חתן ר ישראל צבי רוטנברג האדמור מקאסאן, ובזיוו\"ש חתן ר נחום אפרים מטורנא (שושלת צאנז). רב בקאסאן לצד חותנו וראש ישיבה, רב בנירבאטור, ניצל מהשואה ואחריה היגר לארה\"ב וכיהן כאדמור מוואלובא-נירבאטור. חיבר \"לבושי יו\"ט\" - נ\"י תשל. בניו: ר נחום אפרים, ור אהרן. (אצל וונדר מופיע שנספה בשואה - והוא טעות). קרובו ר אריה ליב טיטלבוים מקולבסוב. פרסם מאמרים ב\"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא."},{"i":21778,"n":"טיטלבוים, חנניה יום טוב ליפא","f":"יקותיאל יהודה-ייטב ל","k":"אדמור מסיגט","r":"אב\"ד סיגעט","bt":"תקצו","bp":"סטרופקוב","dt":"תרסד - כט שבט","b":"חסיד צאנז. חתן ר מנשה רובין מרופשיץ, וביזוו\"ש (היתר מאה רבנים) חתן דודו ר יואל אשכנזי מזלוטשוב. רב בטעטש-תרכד, סיגט-תרמג רב ואדמור על מקום אביו. חיבר \"קדושת יום טוב\" מארמרוש תרסה. מראשי המחנה החסידי בארגון הקהלות האורטודוכסי, והיה במחלוקת עם ר אריה ליב ליפשית מסאנטוב שנבחר לראש הארגון. פרסם מאמרים ב\"תל תלפיות\" - וייצען תרנב-תרעד.","bk":[["קדושת יום טוב – עה\"ת",""],["קדושת יום טוב",""]]},{"i":21779,"n":"טיטלבוים, טוביה מבריגל","f":"מנשה","b":"רב בבריגל על מקום אביו-תרלז."},{"i":21780,"n":"טיטלבוים, טוביה מטורנא","f":"נפתלי","b":"חתן ר נפתלי חיים הלברשטם מגורליץ."},{"i":21781,"n":"טיטלבוים, יהודה מיבורניק","f":"ברכיה מאויהל","k":"אדמור מפרוכניק","bt":"תרן","dt":"תשב","b":"חתן ר נפתלי צבי הלברשם מגלוסק. אדמור מפרוכניק בפשוורסק-אחר פטירת זקנו האדמור ר צבי אלימלך שפירא מבלוזוב. רב ביבורניק. נספה בשואה."},{"i":21782,"n":"טיטלבוים, יהושע חיים מטשנסקובץ","f":"שמואל מגורליץ","k":"אדמור מטשנסוקוביץ","dt":"תשכא - ט סיון","b":"גדל אצל זקנו ר אברהם הורביץ משנדישוב (שושלת רופשיץ). רב בטשנסקוביץ. היגר לארה\"ב והיה שם אדמור מטשנסוקיבץ. בניו ר אהרן ור שמואל על מקומו כאדמורים בארה\"ב."},{"i":21783,"n":"טיטלבוים, יהושע מאמסנא","dt":"תשב","b":"חתן ר נתן דוד הולנדר מאמסנא. רב באמסנא. נספה בשואה."},{"i":21784,"n":"טיטלבוים, יהושע מבריגל","b":"רב בבריגל, תשובה אליו ב\"מנחת יחיאל\"."},{"i":21785,"n":"טיטלבוים, יואל מסטמר","f":"חנניה יו\"ט-קדושת יו\"","k":"אדמור מסטמר-ויואל מש","bt":"תרמז","bp":"סיגט","dt":"תשלט","b":"חתן ר אברהם חיים הורביץ מפלנטש, ובזיוו\"ש חתן ר אביגדור שפירא מפשיטיק האדמור מטשנסטוכוב. התישב בסטמר אחר פטירת אביו וכיהן כאדמור עוד לפני גיל 18, רב באורשיווא-תרעא והמשיך לשהות חלק מזמנו בסטמר, קרולי-תרפה (לאחר שעבר לסטמר היתה מחלוקת והקהילה החסידית התפלגה - חלק בחרו בר אברהם אביש הורביץ והחלק השני בר שמואל גרוס), סטמר-תרצד (נבחר בתרפט אך בגלל מחלוקת נדחתה הכהונה) וראש ישיבה שם. מתנגד לציונות. ניצל מהשואה ועלה לירושלים עבר לניו יורק-תשז וכיהן שם כרב ואדמור מסטמר, הצליח לשקם את קהלתו והיתה לאחת הגדולות באמריקה, הקים עבור החסידות את מונרו - קרית יואל. אחיינו ר משה מסיגט על מקומו אחריו. חתניו ר יקותיאל יודא טיטלבוים הי\"ד מסיגט, ונכדו ר חנניה יו\"ט ליפא מאיער מסעמיהאל וניו יורק. חיבר \"ויואל משה\" ועוד. פרסם מאמרים ב\"לקט ששנ\"ה\" - סטמר תרצד.","bk":[["ויואל משה",""]]},{"i":21786,"n":"טיטלבוים, יוסף","f":"שמואל טייטלבום","b":"רב בניפולומיץ-תר\"ס"},{"i":21787,"n":"טיטלבוים, יוסף דוד מסאסוב","f":"חנניא יו\"ט ליפא","b":"חתן ר דוד משה רוזנבוים מקרטשניף. רב ואדמור ב\"קרית ישמח משה\" על מקום אביו."},{"i":21788,"n":"טיטלבוים, יוסף יהושע מליטוביסק","b":"רב בליטוביסק-תריז."},{"i":21789,"n":"טיטלבוים, יוסף מנפולומיץ","f":"שמואל מגורליץ","bt":"תרן","dt":"תרץ","b":"מצאצאי ר משה בעל \"ישמח משה\". חתן ר יחזקאל שרגא פרנקל תאומים מקלסני-ויליצקה. רב בניעפולומיץ(=ניעפאלאמיטץ)-תרלד. בנו ר יעקב על מקומו אחריו."},{"i":21790,"n":"טיטלבוים, יוסף מקולבסוב","b":"רב בקולבסוב. אחיו של ר צבי הירש שהיה אביו של הישמח משה."},{"i":21791,"n":"טיטלבוים, יחיאל מקולבסוב","f":"אברהם אהרן מקולבסוב","k":"אדמור מקולבסוב","bt":"תרכח","dt":"תשב - כב תמוז","dp":"רישא","b":"חתן ר אריה ליביש הלוי רוזנפלד ממושציסק. רב ואדמור בקולבסוב-תרע. חיבר הספד על אביו נדפס תרעא. נספה בשואה. בנו ר אריה ליבוש רב קהילת קולבסוב בניו יורק."},{"i":21792,"n":"טיטלבוים, יעקב","dt":"תשד","b":"רב בקאבא. חתן ר משה קליין מגרוסורדין"},{"i":21793,"n":"טיטלבוים, יעקב מנפולומיץ","f":"[יוסף]","b":"רב בנפולומיץ על מקום אביו. נכד לכמה אדמורים."},{"i":21794,"n":"טיטלבוים, יצחק מברדיוב","f":"אלעזר","bp":"ליסקא","dt":"תש..","b":"רב בברדיוב-תרפה. נכד אחותו של הישמח משה. נספה בשואה. פרסם מאמרים ב\"מפתח החיים\" - אונגואר-פרשבורג-מונקטש - תרפב, \"עמק הלכה\" - באטארקס תרפא."},{"i":21795,"n":"טיטלבוים, יצחק מברטפלד","dt":"תשד","b":"דומ\"צ בברטפלד"},{"i":21796,"n":"טיטלבוים, יצחק מהוסקוב","f":"מרדכי דוד מסטוטשין","k":"אדמור מהוסקוב","bt":"תרכח","dt":"תשד - ד סיון","dp":"אושוויץ","b":"חתן ר יוסף אליהו לנגנויער מהוסקוב. רב בהוסקוב-תרנו על מקום חותנו. בזמן מלחה\"ע ה-I ברח להונגריה וכיהן כאדמור במישקולץ ובאונגוואר. בניו ר אפרים דב ור מאיר על מקומו אחריו בהוסקוב."},{"i":21797,"n":"טיטלבוים, יצחק מוואלאווע","f":"אהרן מוואלאווע","dt":"תשב - כח ניסן","dp":"מחנה עבענזע","b":"מרבני וולאווע"},{"i":21798,"n":"טיטלבוים, יצחק מפמורן","b":"רב בפמורן-תרעא, תשובה אליו שות מהר\"ש."},{"i":21799,"n":"טיטלבוים, יצחק מרישא","f":"ישראל יעקב יוקל","dt":"תשב - ג אב","dp":"רישא","b":"מחכמי רישא. חתן ר יהודה ליבר מבלוזוב. נספה בשואה."},{"i":21800,"n":"טיטלבוים, יקותיאל יהודה מאויהל","f":"משה דוד ממדיאר לפוש","k":"אדמור מאויהל צאנז ני","dt":"תשלג - ו כסלו","b":"חתן ר נפתלי מקשאנוב (שושלת צאנז). כיהן כאדמור בארה\"ב."},{"i":21801,"n":"טיטלבוים, יקותיאל יהודה מטרנוב","b":"חתן האדמור מויליפולי. רב בטרנוב."},{"i":21802,"n":"טיטלבוים, יקותיאל יהודה מסיגט","f":"אלעזר ניסן מסיגט","k":"אדמור מסיגט-הייטב לב","r":"אב\"ד קראקא","bt":"תקסח","bp":"אויהל","dt":"תרמג - ו אלול","b":"מגדולי האדמורים בדורו. גדל אצל זקנו בעל \"ישמח משה\" באוהל. נמנע מללמוד בישיבת החת\"ס בגלל לבושו החסידי - ולימים הצטער על כך. חתן ר משה דוד אשכנזי מטאלטשווא וצפת בעל \"תולדות אדם\". רב בסטרופקוב-תקצג, רב באויהל(=ערלוי)-תרא על מקום זקנו ה\"ישמח משה\" ובתנאי שלא ינהג אדמורות - ומתנגדיו טענו שלא עמד בתנאי ומסרו את דינו לשלטונות שגירשוהו-תרז. רב בגורליץ-תרז, דרוהוביטש-תרטז על מקום אביו יחד עם ר אליהו הורושובסקי שנבחר גם הוא בינתים, רב בסיגט-תריח על מקום ר יוסף שטרן, למרות שרובה חסידי קוסוב-ויזניץ (ומאז קרוב ל-90 שנה של רבנות המשפחה שם) וראש ישיבה שם - (הישיבה החסידית הראשונה בהונגריה ואולי בכלל). חיבר גם \"אבני צדק\".","bk":[["ייטב לב (סיגעט)",""],["ייטב לב",""],["ייטב פנים",""],["ייטב פנים, ייטב לב",""]]},{"i":21803,"n":"טיטלבוים, יקותיאל יהודה מסיגט","f":"חיים צבי-עצי חיים","k":"אדמור מסיגט","bt":"תרעב","dt":"תשד - כה-ח אייר","dp":"אושוויץ","b":"רב ואדמור בסיגט על מקום אביו בגיל 14, כאשר בהלווית אביו הגיש לו פתקא ר שאול בראך אב\"ד קארולה. קרובו ר יקותיאל יהודה גרוס הובא מברבשט כדי ללמדו דרכי הוראה ואדמורות. חתן דודו ר יואל טיטלבוים - בעל \"ויואל משה\", ובזיוו\"ש חתן דודו ר זושא בן שלום אליעזר הלברשטם מראצפרט. סייע לפליטים בזמן השואה. בימיו שקטה המחלוקת בין חסידי ויזניץ לחסידי סיגט. נספה בשואה."},{"i":21804,"n":"טיטלבוים, ירוחם מטרנוב","f":"משלם זלמן יונתן","bt":"תקפג","dt":"תרנט","dp":"ירושלים","b":"נכד בעל \"אריה דבי עילאי\" וה\"ישמח משה\"-מצד אמו. חתן ר מאיר כהנא מטשטשעוויץ. אביו ממשפחת ליפשיץ וקיבל את שם זקנו הישמח משה. רב בטורנא-תרלו, עלה לארץ."},{"i":21805,"n":"טיטלבוים, ירחמיאל","f":"משה יוסף מאויהל","b":"חתן ר יעקב צבי מפוריסוב (שושלת פשיסחא). נפטר צעיר"},{"i":21806,"n":"טיטלבוים, ישראל יעקב מגורליץ","f":"שמואל בן אלעזר ניסן","k":"בעל היטב איטיב-ייט\"ב","bt":"תר","dt":"תרפד -טו-ב אלול","b":"גדל אצל זקנו בדרוהוביטש. חתן דודו בעל \"ייטב לב\", ועבר עם חותנו לסיגט. רב בכפר ברבשט-תרכב על מקום חותנו, וחתנו ר רפאל גרוס על מקומו אחריו, וחתנו ר רפאל גרוס על מקומו אחריו, רב בגורליץ-תרמט על מקום אביו, ואלאווע-מארמרוש-תרנד ובנו ר אהרן על מקומו אחריו, וכיהן כ-30 שנה והיה גם רב של המחוז וניהל ישיבה שהיתה מכינה לישיבת סיגט. רוב כתביו אבדו בשואה ונדפס מהשאר \"היטב איטיב\" ניו יורק תשלב. בניו: ר משה דוד ממדיאור לאפוש, ר נפתלי מנירבאטור, ר יצחק מרישא, ר חיים יוסף מדינוב, ר שלמה מגורליץ, ר מנחם מנדל מירושלים. חתם שמו - ייט\"ב."},{"i":21807,"n":"טיטלבוים, ישראל מרדכי","b":"חתן נינת ר אלעזר מטופורוב. היה גבאי של האדמור יצחק מאיר השל מקופיטשיניץ-תרסח והדפיס שלשלת יוחסין לכבוד רבו."},{"i":21808,"n":"טיטלבוים, מאיר מהוסקוב","f":"יצחק מהוסקוב","k":"אדמור מהוסקוב","dt":"תשד - ד סיון","dp":"אושוויץ","b":"אדמור בהוסאקוב על מקום אביו."},{"i":21809,"n":"טיטלבוים, מאיר מקמפנא","f":"חיים","b":"רב בקמפנא, טשען-תרצו."},{"i":21810,"n":"טיטלבוים, מנחם מנדל","f":"ישראל יעקב יוקל","dp":"ירושלים","b":"עלה לירושלים והיה מחכמיה."},{"i":21811,"n":"טיטלבוים, מנחם מנדל","b":"פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט."},{"i":21812,"n":"טיטלבוים, מנחם צבי מנפולומיץ","f":"חיים מקראקא","b":"רב בנפולומיץ על מקום זקנו. נספה בשואה."},{"i":21813,"n":"טיטלבוים, מנשה מבריגל","dt":"תשג","b":"רב בבריגל"},{"i":21814,"n":"טיטלבוים, מנשה מבריגל","f":"נחום צבי מדרוהוביטש","dt":"תרסה - כט אייר","b":"חתן ר טוביה ליפשיץ מבריגל-תרמד. ר\"מ בישיבת בובוב בבריגל. (בוונדר תאריך הפטירה תרצט)."},{"i":21815,"n":"טיטלבוים, מנשה מטורנא","f":"נפתלי מבריגל","bt":"תרע","bp":"טורנא","dt":"תשג","b":"תלמיד ר מאיר ארק ור אלקנה זוברמן מיורדנוב. תלמיד ישיבת בובוב בטורנא. נכד הדברי חיים. רב בטרנוב. נספה בשואה."},{"i":21816,"n":"טיטלבוים, מרדכי","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":21817,"n":"טיטלבוים, מרדכי דוד מדרוהוביץ","f":"נחום צבי מדרוהוביטש","k":"בעל דמתה לתמר","dt":"תרף - כסלו","dp":"צפת","b":"רב בסטיטשין ודרוהוביץ על מקום אביו, חתן ר חנינא הורביץ מאולינוב. עלה לצפת-תרסב. חיבר \"דמתה לתמר\" ונדפסו כמה דפים ממנו."},{"i":21818,"n":"טיטלבוים, מרדכי דוד מהוסקוב","f":"אפרים דב בן יצחק","k":"אדמור מהוסקוב ב\"ש","b":"חתן ר יוסף מאיר כהנא מספיקנא-ירושלים. ניצל מהשואה, עלה לארץ דרך מחנות באירופה וקפריסין. התישב בבאר שבע שם פתח בית מדרש ומכהן כאדמור מהוסקוב בבאר שבע."},{"i":21819,"n":"טיטלבוים, משה דוד מלפוש","f":"ישראל יעקב יוקל מואל","bt":"תרטו","bp":"דרוהוביטש","dt":"תרצה - כא אד\"ב","b":"גדל אצל זקנו-אבי אמו בעל \"ייטב לב\" בסיגט. חתן ר אריה ליב הלברשטם מטורנא ודוקלא-נכד ה\"דברי חיים\". רב בלאפוש-ליד דעש-תרמה במשך כ-50 שנה וראש ישיבה שם, וחתנו ר אהרן גרוס על מקומו אחריו. ביקר בארץ-תרע, והסכים להקמת חוות הכשרה על ידי \"פא\"י\" בלאפוש. הו\"ל את כתבי זקנו - \"ישמח משה\" וכתב את תולדותיו, והו\"ל את ספרי זקניו בעל \"ייטב לב\" ו\"ישמח משה\" עם הערות ממנו. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"לקט ששנ\"ה\" - סטמר תרצד."},{"i":21820,"n":"טיטלבוים, משה יוסף מאויהל","f":"יקותיאל יהודה-ייטב ל","r":"אב\"ד אוסטראה ופפד\"מ","bt":"תרה","dt":"תרנז - כד טבת","b":"חתן ר דוד הלברשטט מקשנוב. רב זבורוב בהגר, סטרופקוב, ואוהל. הניח חבורים שלא נדפסו ונכדו ר יקותיאל יהודה מייזליש הוציא לאור את ספרו \"מילי דמיטב\" ניו יורק. בניו: ר ירחמיאל, ר אלעזר ניסן, ר חיים יעקב מלימנוב. חתנו - ר יהודה ליב ארליך.","bk":[["מילי דמיטב",""]]},{"i":21821,"n":"טיטלבוים, משה יוסף מבוקובסק","dt":"תש..","b":"ראב\"ד בוקובסק - פשמישל. נספה בשואה."},{"i":21822,"n":"טיטלבוים, משה מבאליגרד","dt":"תשד","b":"רב בבאליגרד"},{"i":21823,"n":"טיטלבוים, משה מבוקובסק","b":"רב חסידי דינוב בבוקובסק לפני השואה."},{"i":21824,"n":"טיטלבוים, משה מטעטש","f":"אליהו בצלאל מטעטש","b":"אב\"ד בטעטש על מקום אביו. נפטר צעיר."},{"i":21825,"n":"טיטלבוים, משה ממושציסק","k":"אדמור ממושציסק","dt":"תשג","b":"חתן ר חיים נחום הלברשטם. רב ואדמור במושציסק על מקום חותנו. נספה בשואה."},{"i":21826,"n":"טיטלבוים, משה מסאנוק","f":"ברכיה מאויהל","k":"אדמור מסאנוק"},{"i":21827,"n":"טיטלבוים, משה מסיגט ונ\"י","f":"חיים צבי-עצי חיים","k":"אדמור מסיגט-סטמר","bt":"תרעה","bp":"סיגט","b":"לאחר שנתייתם גדל אצל דודו ר יואל בעל \"ויואל משה\", ואצל זקנו האדמור ר שלום אליעזר הלברשטדם בראצפרט. חתן דודו זקנו ר חנוך הניך מאיר (מייער) מקרעצקי, ועבר לשם וניהל את ישיבת חותנו. רב בזענטא-תרצט (סופחה מיגולסביה באותה שנה). ניצל מהשואה ואחריה חתן ר אהרן טיטלבוים מואלאווע וניר באטור, וכיהן כרב בסיגט. היגר לניו יורק, וכיהן כרב ואדמור מסיגט והקים בימ\"ד \"עצי חיים\". אדמור מסטמר על מקום דודו ר יואל-תשלט, הקים את \"קרית יואל\" בירושלים. חיבר \"ברך משה\". בנו ר אהרן רבה של קרית יואל במונרו, וראש ישיבת סטמר."},{"i":21828,"n":"טיטלבוים, משה משינאווא","f":"צבי הירש שיף מזברוב","k":"בעל ישמח משה","r":"דיין בפרעמישלא, ואח\"כ אב\"ד בשינאווא, ואח\"כ רב ואב\"ד דאויהעל","bt":"תקיט","bp":"פרמישלא","dt":"תרא - כח תמוז","b":"נמסר שביקר אצל הגרא בהיותו בר מצוה. תלמיד דודו ר יוסף מקולבסוב, ואצל דודו-אחי אמו ר אברהם אריה ליב מסטריזוב בעל \"דרישת ארי\". בהשפעת חתנו ר אריה ליביש מוישניצא נסע אל החוזה מלובלין. ר משולם איגרא אמר עליו \"משה אמת ותורתו אמת\". חתן הגביר ר ניסן (יתכן שהיה דודו). רב בפרמישלא, רב בשינאווא על מקום ר שמלקא הורביץ שעבר לניקלשבורג, רב באויהל(=ערלוי)-תקסח והיה שם אדמור-תקעה, חילק גם קמיעות שעוררו מחלוקת. חיבר \"ישמח משה\" למברג תרט, ועוד, את שמו \"טיטלבוים\" בחר ע\"פ הפסוק \"צדיק כתמר יפרח\". בין המבקשים את ברכתו - קושוט לאיוש - לימים מנהיג המרד ההונגרי-1948. מתלמידיו ר אליעזר ניסן מסיגט. חתנו - ר אריה ליב ליפשיץ מוישנביץ בעל \"אריה דבי עילאי\".","bk":[["השיב משה - שו\"ת",""],["ישמח משה – תנ\"ך",""],["מעין טהור",""],["תפלה למשה - תהילים",""],["ישמח משה",""],["תפלה למשה - תהילים, השיב משה - שו\"ת , ישמח משה – תנ\"ך, מעין טהור, יין הרקח – גיטין",""]]},{"i":21829,"n":"טיטלבוים, משה שמחה מגריבוב","b":"דיין בביטש ובוישיניצה."},{"i":21830,"n":"טיטלבוים, משלם זלמן הכהן מבריג","f":"אריה ליב-אריה דבי עי","k":"בעל בגדי כהונה","b":"נכד ר משה טיטלבוים בעל \"ישמח משה\" - ומכאן שמו (שם אביו ואחיו טוביה - ליפשיץ). רב בבריגל-תרל. הסכים על הפסק של ר ברוך עוזר מהמבורג כנגד הריפורמים. בניו - ר ירוחם, ר טוביה ליפשיץ."},{"i":21831,"n":"טיטלבוים, משלם מבאליגרד","b":"אב\"ד באליגרד-תרפט."},{"i":21832,"n":"טיטלבוים, נחום אפרים","f":"חנניא יו\"ט ליפא","b":"בנו של האדמור מוואלובא-נירבאטור בנ\"י. חתן ר שמואל שמלקא מסוליצא (שושלת רופשיץ)."},{"i":21833,"n":"טיטלבוים, נחום צבי מדרוהוביטש","f":"אלעזר ניסן מסיגט","k":"אדמור מדרוהוביטש","b":"חתן ר מרדכי דוד אונגר מדומברובה. אדמור בדרוהוביטש-תרמב. בניו ר מרדכי דוד מסטוטשין ודרוהוביטש, ר מנשה, ור אהרן."},{"i":21834,"n":"טיטלבוים, נפתלי מנירבאטור","f":"ישראל יעקב יוקל מואל","bt":"תרכז","dt":"תרצח - ג אלול","dp":"בודפסט","b":"נכד ה\"ייטב לב\". חתן דודו ר משה יוסף טיטלבוים באויהל. רב בקהלת היראים בנירבאטור-תרנא."},{"i":21835,"n":"טיטלבוים, נפתלי מעטשעד","f":"דוד מעטשעד","k":"אדמור מקולבסוב","bt":"תרנה","dt":"תשלא - ו תשרי","b":"חתן ר יצחק ראובן ליפשיץ מטשרנא-דונייעץ. רב בעטשעד על מקום אביו. ניצל מהשואה ואחריה התישב בניו יורק ונקרא האדמור מקולבסוב ועטשעד."},{"i":21836,"n":"טיטלבוים, שלמה מבלוזוב","b":"מחכמי בלוזוב. חתן ר שמעון טוביה מינץ."},{"i":21837,"n":"טיטלבוים, שלמה מבליגרד","f":"אשר ישעיה מבליגרד","dt":"תש..","b":"רב בבליגרד על מקום אביו, דוברומיל-תרצב על מקום חותנו ר אברהם מרדכי רימלט. נספה בשואה."},{"i":21838,"n":"טיטלבוים, שלמה מגורליץ","f":"ישראל יעקב יוקל","bt":"תרלה","dt":"תשב - ב אלול","b":"רב בגורליץ. חתן רמי\"ל שפירא מסטריזוב. נספה בשואה."},{"i":21839,"n":"טיטלבוים, שלמה מדארויבן","b":"רב בדארויבן-רומניה. פרסם ב\"אהל מועד\", ובמאספים שונים."},{"i":21840,"n":"טיטלבוים, שמואל מארדד","f":"אהרן מואלאווע","bt":"תרס","b":"תלמיד בעל \"עצי חיים\" בסיגט, ר יואל טיטלבוים בקרולה. חתן ר יואל כץ מארדד. רב בניגרשד-תרצב על מקום חותנו זקנו. נספה בשואה."},{"i":21841,"n":"טיטלבוים, שמואל מגורליץ","f":"אליעזר ניסן מסיגט","bt":"תקעד","dt":"תרמט - ט חשון","b":"חסיד צאנז. נכד הישמח משה. חתן הגביר ר מנחם מנדל הורביץ מסקול. רב בגורליץ-תרטז בהוראת הדברי חיים כ-40 שנה. בניו ר יוסף מ נפולומיץ, ר נפתלי מגורליץ, ר אהרן מגורליץ, ר אריה ליביש באויהל."},{"i":21842,"n":"טיטלבוים, שמואל מגורליץ","f":"שלמה","dt":"תשב","b":"רב בגורליץ. חתן ר נפתלי חיים הלברטשם. נספה בשואה."},{"i":21843,"n":"טיטלבוים, שמואל מטשנסטקוביץ","f":"יהושע חיים מטשנסקובי","k":"אדמור מטשנסטקוביץ ני","bt":"תרף","bp":"טשנסקוביץ","b":"תלמיד ישיבת עץ חיים-בובוב, \"תורה ודעת\" בניו יורק, ר שלמה היימן בניו יורק. רב ואדמור בניו יורק-תשג. חתן ר נפתלי חיים הלברשטט מגורליץ."},{"i":21844,"n":"טיטלבוים, שמואל מניגרשט","f":"אהרן טייטלבום","dt":"תשד","b":"רב בניגרשט-תרצ\"ב. חתן ר יואל כץ מערדעד"},{"i":21845,"n":"טיטלבוים, שמואל מראדום","dt":"תשג","b":"רב בראדום"},{"i":21846,"n":"טיטלבוים, שמואל צבי משפדבורז","f":"ישכר בער ואלאנאוור","k":"בעל הנשאר בציון","dp":"לודז","b":"רב בפשדבורז. חתנו - ר נח גד וינטרופ הו\"ל את ספרו \"הנשאר בציון\" ירושלים תשג."},{"i":21847,"n":"טיטלבוים, שמעון מטארנאליא","f":"דוד יצחק","bt":"תרלט","bp":"ערדא-בעניע","dt":"תשד - כד סיון","dp":"אושוויץ","b":"תלמיד השב\"ס, ור נפתלי שורץ מהעדילא-מאדע. חתן ר ניסן יהודה מרמורשטין מטארנאליא. מחכמי טארנאליא ועמד בראש חברת ת\"ת. חתנו - ר יונה בנימין בייניש קליין מברגסאז."},{"i":21848,"n":"טיטש, עזריאל מטרנופול","b":"דיין בטרנופול. מוזכר בשו\"מ."},{"i":21849,"n":"טייאר, אפרים מטריפולי","f":"דוד (ואולי הוא זקנו)","dt":"תקפח - י סיון","dp":"טבריה","b":"מקובל, אב\"ד בטריפולי, עלה לארץ והתישב בטבריה. נזכר ב\"ויקרא אברהם\" לר אברהם אדאדי, ויש דעות חלוקות בענין יחוסו - יש אומרים שהוא נכדו של ר דוד ולא בנו, ותאריך פטירתו - יש אומרים תקן-נא (ר יוסף ילוז), ויש אומרים תקפג (ר אברהם אדאדי), ויש אומרים תקפח (גבריאל רוקח)."},{"i":21850,"n":"טייאר, דוד מטריפולי","f":"שבתי","bt":"תנ","bp":"תונס","dt":"תקכג - כג אדר","dp":"צפת","b":"מקובל, גדול בתורה, אב\"ד טריפולי, עלה לארץ. נזכר ב\"ויקרא אברהם\" לר אברהם אדאדי, ב\"השומר שבת\" ליוורנו תרט, ועוד."},{"i":21851,"n":"טייאר, הלל מטריפולי","bt":"תקך","dt":"תקף - בערך","b":"רב בטריפולי. נזכר בפנקס בי\"ד טריפולי."},{"i":21852,"n":"טייאר, יהודה מטריפולי","f":"נסים","bt":"תף","dt":"תקע - בערך","b":"רב בטריפולי. חתם על תקנת הגאבילה-תקלח, ותקנת ההשבון. נזכר ב\"מעשה רוקח\" ליוורנו תרכב, וב\"השומר אמת\" ליוורנו תרט."},{"i":21853,"n":"טייאר, יוסף (סאסי) מלוב","f":"שלום","bt":"תרסז","dt":"תשמה","dp":"ישראל","b":"רב ומלמד תשב\"ר ודרשן בכומס-לוב, מצראתה-לוב, עלה לארץ והתישב בנתניה."},{"i":21854,"n":"טייאר, יוסף מטריפולי","f":"אפרים","bt":"תרסט","dt":"תשלז","dp":"ישראל","b":"תלמיד ר ציון ביתאן. רב ומלמד תשב\"ר בטריפולי, עלה לארץ והתישב ברעננה."},{"i":21855,"n":"טייאר, יוסף מלוב","bt":"תקף","dt":"תרן - בערך","b":"רב בדרנה-לוב-תרי. נזכר אצל נחום סלושץ ב\"מסעי בארץ לוב\", הקדמה להגדת \"גאולת ה'\" ליוורנו תרכד."},{"i":21856,"n":"טייאר, יעקב מטריפולי","bt":"שס","dt":"תל - בערך","b":"רב בטריפולי ויסד ישיבה-תך הנקראת על שמו - בישיבה היתה ספריה חשובה - המוזכרת בפנקס קהלת טריפולי. הרב הראשון במשפחתו הידוע בטריפולי."},{"i":21857,"n":"טייאר, יצחק מטריפולי ואלגיר","bp":"טריפולי - כנראה","dt":"תקף","b":"רב באלגיר. תשובה ממנו ב\"משכנות הרועים\". הסכים על \"שער שלמה\"."},{"i":21858,"n":"טייאר, רפאל (פריג'א) מטריפולי","bt":"תרעג","dt":"תשנב","dp":"ישראל","b":"מחכמי טריפולי, עלה לארץ והתישב בבני ברק. הו\"ל ספרים וכתבי עת בנושא יהודי לוב - יחד עם ר פריג'א זוארץ."},{"i":21859,"n":"טייאר, שבתי מאלגיר","b":"דיין באלגיר. נזכר ב\"אשכבתא דרבנן\" לליל כפור."},{"i":21860,"n":"טייאר, שבתי מטריפולי","k":"בעל הפיוט מי כמוך","bt":"תל","dt":"תפה-תק","b":"רב ופייטן בטריפולי. חיבר פיוט \"מי כמוך\" לזכר נס \"פורים אשריף\" - כג טבת תסד, ויהודי לוב קוראים את הפיוט בשבת שלפני כג טבת. אביו של ר דוד שהיה דיין בטריפולי אצל ר מסעוד חי רקח."},{"i":21861,"n":"טייאר, שלום מטריפולי","bt":"תקן","dt":"תרך - בערך","b":"סופר דווקני בטריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":21862,"n":"טייאר, שלום מלוב","k":"בעל דברי שלום - כת\"י","dt":"תרצה","b":"רב בכומס-לוב-תרמה עד תרצה. חיבר חדושים לתורה בשם \"דברי שלום\", תרגם \"תורת הזבח\" לערבית יהודית. עליו ב\"גנזים\" ת\"א 1969."},{"i":21863,"n":"טייב, אברהם מתונס","k":"בעל חיי אברהם","dt":"תקא","b":"דיין בתונס-תפ או תקפא (אולי חכמים שונים באותו השם?), ורב ראשי. מתורתו ב\"בני יוסף\" לר יוסף טנוג'י, חיבר הגהות וחדושים לסדר קדשים."},{"i":21864,"n":"טייב, אברהם מתונס","f":"יוסף בן יצחק","b":"נכד ר יצחק בעל \"חקת הפסח\", הו\"ל ספר זקנו \"חקת הפסח\", \"ווי העמודים\" (לאחר שאביו נפטר באמצע ההדפסה)."},{"i":21865,"n":"טייב, דוד מתונס","b":"מרבני תונס, סופר, דיין"},{"i":21866,"n":"טייב, ז'ק יעקב מתונס","k":"בעל שפת ציון","b":"מורה לעברית בביה\"ס \"אור תורה\" בתונס. חיבר ספר ללימוד השפה בשם \"שפת ציון\" תונס תשד."},{"i":21867,"n":"טייב, חיים מתונס","k":"בעל דרך חיים","b":"מחכמי טוניס,חיבר \"דרך חיים\" על הש\"ס"},{"i":21868,"n":"טייב, יצחק חי מתונס","k":"ר חיי טייב לא מת","bt":"תקד","bp":"תונס","dt":"תקצו - יט אייר","dp":"תונס","b":"בן דודו של ר יצחק טייב בעל \"ערך השלחן\". מחכמי תונס. רוב חיבוריו נשרפו ומאלה ששרדו נדפס \"חלב חיטים\". נקרא בשם \"לא מת\" בגלל מעשה שקרה לאחר פטירתו (שם ספרו - נוטריקון - חכם יצחק טייב לא מת). לתולדותיו - ר מאיר מאזוז בהקדמת מהדורה חדשה לספרו.","bk":[["חלב חיטים",""]]},{"i":21869,"n":"טייב, יצחק מתונס","f":"בנימין","k":"בעל ערך השלחן","bt":"[תקיג]","dt":"תקץ","dp":"תונס","b":"תלמיד ר יוסף זרקא ור שלמה אלפסי מתונס בעל \"משחא דרבותא\". רב ודיין בתונס-תקסג, ואב\"ד- על מקום ר דוד גג'. חיבר \"חקת הפסח\", \"ווי העמודים\" ועוד. בניו ר יוסף שנפטר בחייו-תקפט, ור משה. נכדו ר אברהם בן יוסף - הו\"ל את ספרו."},{"i":21870,"n":"טייב, משה מתונס","f":"יצחק-ערך השלחן","b":"מחכמי תונס, ערך והגיה ספר אביו אחר פטירתו-תקץ, אך נפטר בטרם סיים."},{"i":21871,"n":"טייב, שמואל מתונס","k":"בעל איילת השחר","dp":"טבריה","b":"מחכמי תונס - בשנות ה-תר', תלמיד ר שלמה דאנה. רב במהדייה, נזרת, מוכנין, עלה לארץ והתישב בטבריה. חיבר גם \"כנפי שחר\", \"שמן הטוב\", ועוד."},{"i":21872,"n":"טייבלום, חיים אלתר מירושלים וא","f":"יצחק","k":"בעל הגיוני חיים","b":"רב בירושלים, ניו יורק."},{"i":21873,"n":"טייטל, צבי הירש מאינטרדם","b":"רב באינטרדאם - באמצע המאה ה-19. נזכר ב\"שער צדק\"."},{"i":21874,"n":"טייטש, חנדלי מפרשבורג","f":"מנדל","dt":"תצז - טז תשרי","dp":"פרשבורג","b":"מחכמי פרשבורג."},{"i":21875,"n":"טייטש, מרדכי","b":"רב בפאלין-תפ\"ה"},{"i":21876,"n":"טייכטל, ישכר שלמה מפישטיאן","f":"יצחק","k":"בעל אם הבנים שמחה","bt":"תרמה","bp":"נאדי-האלאס - הגר","dt":"תשה - י שבט","b":"חתן ר יעקב יוסף גינז מבוסרמין, ובזיוו\"ש חתן ר דוד פרידמן מצעלים. רב בקוסטולאני, רב וראש ישיבה בפישטיאן. נספה בשואה. חיבר \"משנה שכיר\" ברדיוב תרפד, \"אם הבנים שמחה\" בודפסט תשג, ועוד. נכדו - ר מאיר ברנדסופר - רב העדה החרדית בירושלים. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב, \"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"הכוכב\" - מונקטש-נ\"י תרצה, \"עמק הלכה\" - באטארקס תרפא, \"קהילת יעקב\" - זבארוב-סלובקיה תרפה."},{"i":21877,"n":"טייכטל, שלום מפיעשטני","f":"ישכר שלמה","b":"פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":21878,"n":"טייכטל, שמואל דב מאנטורפן","b":"דיין באנטורפן-תרצט אצל ר מרדכי רוטנברג."},{"i":21879,"n":"טייכמן, נפתלי מואלאווע","b":"פרסם מאמרים ב\"החיים\" - לונדון תש, \"הנשר\" - טירנוי תרצג-תשד."},{"i":21880,"n":"טייכר, אברהם יעקב מזמושץ","f":"גרשון","bt":"תקסד","bp":"תרכז","b":"רבה של זמושץ. חתן ר משה נפתלי קצנלבויגן מקרעשוב."},{"i":21881,"n":"טייכר, אלימלך","k":"בעל שערי עזרא","dt":"תרפ - כג אב","b":"מגדולי חכמי קרקא"},{"i":21882,"n":"טייכר, אליעזר יצחק מזמושץ","f":"גרשון","bt":"תקסה","dt":"תרם","b":"רב בזמושץ, אולינוב-תרלו על מקום אביו."},{"i":21883,"n":"טייכר, אליעזר מדרוהוביטש","f":"יצחק","bt":"תקכ","dt":"תקף","b":"מחכמי דרוהוביטש, חתן ר יושיע רישיווער מדרוהוביטש."},{"i":21884,"n":"טייכר, אלתר מקולומיאה","b":"מדפיס בקולומיאה עם בנו ר שמעון. הוציא לאור \"אור צדיקים\" - ליקוטי חסידות מחסיד אחד - קולומיאה תרמו."},{"i":21885,"n":"טייכר, אריה ליב מטרניגרד","f":"אברהם יעקב","bt":"תקצט","dt":"תרצה","b":"רב בזמושץ על מקום אביו, טשכויב, טרניגרד-תרכז. חתן רצ\"ה מקאריב."},{"i":21886,"n":"טייכר, גרשון מאולינוב","f":"אליעזר","bt":"תקם","dt":"תריז","b":"רבה של אולינוב-תקפז. חתן ר אלעזר מרוזוודוב (אשתו האריכה ימים כ-125 שנה - עלתה לירושלים)."},{"i":21887,"n":"טייכר, יוסף משה מזלין","f":"גרשון מאולינוב","k":"בעל שערי עזרה","bt":"תקסג","bp":"טורקא","dt":"תרמח - כז כסלו","b":"נכד ר יצחק חריף מסמבור. תלמיד ר אשר מרופשיץ. רב באולינוב על מקום אביו?, טשיטש-תקצח, זלין(=זאלען)-ליד לנצוט, פרמישלא-תרך. חתן ר מרדכי זאב מדרוהוביטש. חיבר \"שערי עזרה\" למברג תרכו, ועוד. בנו ר צבי אלימלך מקראקא. חתנו - ר דוד צבי טבל זעהמאן הי\"ד."},{"i":21888,"n":"טייכר, יוסף משה מטרניגרד","f":"אריה ליב","bt":"תרלה","dt":"תשג","b":"רב בטרניגרד על מקום אביו. נספה בשואה."},{"i":21889,"n":"טייכר, יוסף נפתלי","f":"מרדכי צבי טייכר","b":"רב בטרניגרד-תר\"צ"},{"i":21890,"n":"טייכר, מרדכי צבי מזמך","f":"אריה ליב","bt":"תרם","bp":"לובלין","dt":"תשב","b":"רב בלשצוב, זאמעך, טרניגרד לצד אביו. חתן ר אשר זלקא ליפינר מגרודזיסק. נספה בשואה. הוציא לאור \"פני יצחק\" לזקנו ר יצחק חריף."},{"i":21891,"n":"טייכר, משה נפתלי מטרניגרד","dt":"תשג","b":"רב בטרניגרד"},{"i":21892,"n":"טייכר, פנחס אליעזר מקרקוביץ","b":"רבה של קרקוביץ. מחדושיו בסוף שו\"ת \"פני יצחק\"."},{"i":21893,"n":"טייכר, צבי אלימלך מקראקא","f":"יוסף משה מזעלין וקרק","k":"בעל פלפולא חריפתא","bt":"תר","dt":"תרף","b":"רב בקראקא ובהונגריה. חיבר \"מעשה הצדקה\" פרמישלא תרלד, \"פלפולא חריפתא\" קראקא תרעב, ועוד. פרסם מאמרים ב\"המפלפל\" - קראקא תרעג."},{"i":21894,"n":"טייכר, צבי מטרניגרד","dt":"תשג","b":"רב בטרניגרד"},{"i":21895,"n":"טייכר, שלמה מאיר מגלוגוב","f":"גרשון","b":"רב בגלוגוב-תרכז."},{"i":21896,"n":"טייכר-לוריא, א' יצחק מאולינוב","b":"רב באולינוב"},{"i":21897,"n":"טייץ, אהרן מדווינישיק","dt":"תשא","b":"רב בדווינישיק"},{"i":21898,"n":"טייץ, אלחנן זאב מארה\"ב","f":"אברהם בנימין","b":"תלמיד ישיבות ריגא, סלובודקא, טלז. חתן ר ברוך דוד ויצמן מניו יורק. נסמך מאת: ר יוסף ויסמנוביץ מסלובודקא, רא\"י בלוך מטלז, רמ\"מ ז\"ק מריגא. רב בולדמרפילס-לטביה-תרצב, הגיע לארה\"ב וכיהן כרב בקהלת \"אהבת ישראל\" בניו יורק-תרצו, קהלת \"עדת ישורון\". חברת אגודת הרבנים באמריקה, עסקן צבור."},{"i":21899,"n":"טייץ, אליעזר מוילנא","f":"ראובן טיקאצין","bp":"הורדנא","dt":"תריד - ו כסלו","dp":"ברודי","b":"תלמיד ישיבת ר עקיבא איגר בפוזנא - כונה טייץ על שום לבושו כמנהג האשכנזים (דייטש). חתן ר אברהם שמואל עליאש מוילנא ועבר לשם. ר\"מ בישיבת מיילס והיה שני לר מרדכי מלצר. לאחר כמה שנים-תר עבר לערים אחרות."},{"i":21900,"n":"טייץ, דב בר","b":"רב-שנת תר\"מ"},{"i":21901,"n":"טייץ, יהודה מוילנא","f":"גבריאל","dt":"תקנב - ל שבט","dp":"וילנא","b":"דיין בוילנא."},{"i":21902,"n":"טייץ, יצחק איזיק מטווער","bt":"תרכד","dt":"תרפט - יב שבט","b":"רב בטווער-פלך קובנא-תרסב, עלה לירושלים."},{"i":21903,"n":"טייץ, יצחק מטלז","b":"רב בטלז"},{"i":21904,"n":"טייץ, מנדל מיאנוב","dt":"תשג","b":"מרביץ תורה ביאנובה"},{"i":21905,"n":"טייץ, משה מראסיין","dt":"תשג","b":"רב בראסיין"},{"i":21906,"n":"טייץ, פנחס מרדכי מארה\"ב","f":"אברהם בנימין","bt":"תרסח","bp":"סובאט","b":"תלמיד דודו ר אליהו עקיבא מפולטובה, ישיבת מיר, פוניבז, סלובודקא, ריגא. נסמך מאת: ר אברהם יצחק בלוך מטלז, ר יוסף זוסמן מסלובודקא. יסד ישיבה בליוונהוף ועמד בראשה, עורך בטאון אגודת ישראל בליטא-לטביה \"אידישע שטימע\". הגיע לארה\"ב-תרצד בשליחות ישיבת טלז. חתן ר אלעזר מאיר פרייל מאליזבט, רב באליזבט-ניו ג'רסי על מקום חותנו, ויסד שם ישיבה \"יבנה\" מהראשונות מחוץ לניו יורק. פעיל צבור, ובהצלה בזמן השואה."},{"i":21907,"n":"טייץ-רבינוביץ, אברהם בנימין","f":"דב בער רבינוביץ","bt":"תרלג","bp":"פיאנטניצא-ליד לומזא","dt":"תשיז","b":"לאמר שנתייתם למד אצל אחיו ר אליהו עקיבא רבינוביץ מפולטובה, ודודו האדר\"ת. חתן ר משה שפירא מדארגאווע בעל \"תבואות שמש\". רב בסובט(=שובאץ)-קורלנד-תרנח, ליוונהוף-תרעט, ניצל מהשואה ע\"י בנו-תשא והגיע לארה\"ב. הו\"ל ספרי אביו \"דבר אמת\". פרסם מאמרים במאספי תורה, מתשובותיו בספרי חותנו. בניו: ר דב יוסף מחדרה, ר אליהו דוד, ר פנחס מאליזבט-ניו ג'רסי, ר אלחנן זאב מניו יורק. חתנו - ר ישראל מעהל מדרגאווע - נספה בשואה עם משפחתו."},{"i":21908,"n":"טיך, שמואל","k":"אדמור מפשמישל","b":"מחכמי ירושלים. חיבר \"אוצר אמת\" ניו יורק תשלט."},{"i":21909,"n":"טיכברג, שלום מפרימישלן","b":"רב בפרימישלן-תריח."},{"i":21910,"n":"טיכנר, ישכר דב מטרנוב","f":"אהרן","k":"בעל יד האמונה","bt":"תרנו","dt":"תשב","b":"מחכמי טרנוב. רב בניו יורק. הוציא לאור \"אגרת הרמב\"ן\" עם תרגום אידיש ופירוש \"יד האמונה\" וינה תרעט."},{"i":21911,"n":"טילדוא די, אליעזר","b":"מרבני קושטא-תק\"ס"},{"i":21912,"n":"טיליא, אליעזר משלוניקי","dt":"של - ח כסלו","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":21913,"n":"טיליאס, רפאל מחברון","f":"דוד","b":"מחכמי חברון-שנות ה-תק'. נספד מאת דודו - ר נסים חיים שלום מרגונטו."},{"i":21914,"n":"טיליו, אבטליון ממודנא","f":"אברהם שלמה","k":"בעל ספר הפזמונים","b":"חיבר-תקעח פזמונים לכבוד חתונת אפרים נחמני ומזל סרודיו במודנא."},{"i":21915,"n":"טיליו, אטליון יצחק משה","b":"חיבר פיוטים-תקעט."},{"i":21916,"n":"טיליו, יהודה מקושטא","b":"רב בקושטא-שנות ה-ש'."},{"i":21917,"n":"טיליו, יוסף מפיליפופולי","b":"רב בפיליפופולי-שנות ה-ש'."},{"i":21918,"n":"טיליו, לוי מקושטא - א","b":"חתן ר אברהם אליגרי. רב בקושטא-שפ. נזכר בספר חותנו \"לב שמח\"."},{"i":21919,"n":"טיליו, לוי מקושטא - ב","b":"מחכמי קושטא-שנות ה-ת'."},{"i":21920,"n":"טילס, בנימין מרדכי משניפישוק","f":"דוד יהודה ליב משניפי","bt":"תקסז","dt":"תרלו-ב - ה שבט","dp":"וילנא","b":"חתן דודו-אחי אמו ר יעקב זלקינד, ובזיוו\"ש חתן ר בער חעלימער (אלמנת ר יעקב נחום בן ר יצחק שמעון אפשטין). מו\"צ בשניפישוק-תקצו על מקום ר אליעזר אליהו דייכס, ועל מקום אביו, ור שמואל מרדכי ראשקעס על מקומו אחריו. דיין בוילנא-תרט, ומו\"ץ-תרכז, מנהל ביהמ\"ד של הגביר ר יהודה אפאטוב ואחראי על קרן הצדקה שלו. בוחן תלמידים בישיבת מיילס וגבאי בביהמ\"ד הגר\"א."},{"i":21921,"n":"טילס, דוד יהודה ליב משניפישוק","f":"דב בער מאנטאקאליע","dt":"תקצה - א אייר","dp":"שניפישוק","b":"גיסו של הגביר ופרנס שניפישוק ר יעקב משהלע'ס זאלקינד'ס. מו\"ץ בשניפישוק על מקום ר פנחס בעל \"מגיד צדק\". ור אליעזר אליהו דייכס על מקומו אחריו."},{"i":21922,"n":"טילקי, משה מליוורנו","f":"גרשון","b":"תשובה ממנו ב\"שמש צדקה\"."},{"i":21923,"n":"טימסטית, ראובן ממרוקו","k":"בעל מחנה ראובן","bt":"תרמא","bp":"כפר מזגיטא-מרוקו","dt":"תשט","dp":"כפר סמנגורט-מרוקו","b":"רב ומקובל במרוקו. תלמיד ר סעדיה בן דוד ויוסף בכפר טיילית=תילית - מחוז דרעא במרוקו, תלמיד ר שלמה אפנג'ר בעל \"כרם שלמה\" מכפר כיתאווא, יחד עם חברו ר שלום אביסרור בעל \"נתיבות שלום\". נשא אישה שניה בהסכמת אשתו שהיתה עקרה. בנו ר ישעיה, חתנו - אחיו ר יעיש. חיבר גם \"אמרות טהורות\", \"דודאי ראובן\" ו\"מנוחת שלום\" שנדפסו ע\"י נכדו ר עמרם בן יעיש. חתם-תרס בערך על תקנה של השד\"ר ר מסעוד אדהאן."},{"i":21924,"n":"טימסטית, שמעון ממרוקו","dt":"תשסא - ב שבט","dp":"ירושלים","b":"מחכמי מכנאס ור\"מ בישיבה, עלה לארץ וכיהן כרב במושב יערה, ר\"מ בישיבת \"בית שמואל\" בירושלים."},{"i":21925,"n":"טימפלו, שלמה רפאל יהודה ליאון","k":"בעל הלכה למשה מסיני","b":"חיבר \"הלכה למשה מסיני\" אמשטרדם."},{"i":21926,"n":"טימר, יחיאל מיכל רבי יוזפס","k":"בעל סדר גיטין","dt":"תכא","b":"דיין בקראקא אצל התוי\"ט ור השל מקראקא."},{"i":21927,"n":"טינטנר-אוסטרליץ, בירך אברהם","f":"גבריאל","bt":"תקנד","bp":"אויסטרליץ","dt":"תרלה","b":"תלמיד החת\"ס. רב בסעמניץ, סקאליץ. תשובה אליו ב\"חתם סופר\"."},{"i":21928,"n":"טיסר, שלמה מברטש","b":"סופר ומחכמי ברטש-תרנא."},{"i":21929,"n":"טיעץ, צבי מאינוורצלב","b":"פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":21930,"n":"טיפנברון, צבי נפתלי ממליץ","dp":"סיביר","b":"מחכמי מליץ - ממשתתפי \"אהל מועד\". בנו ר אשר ישעיה והיגר לאנטורפן."},{"i":21931,"n":"טיץ מרדכי פינחס בן בנימין אברהם","bt":"1908","dt":"ה'תשנה 1995","bk":[["מפתח של גאולה",""]]},{"i":21932,"n":"טיקטין, אברהם מברסלוי וגלוגא","f":"גדליה מטיקטין","k":"בעל פתח הבית","dt":"תקפ-א - כב טבת","dp":"ברסלוי","b":"תלמיד גיסו ר מרדכי מגרידץ שאצלו גדל אחר שנתייתם. רב בשורזניץ, גלוגא-תקע על מקום אביו?, ברסלוי-תקעד. נספד ב\"אבל יחיד\" לר משה קראניק מגלוגא. בניו: ר שלמה זלמן מברסלוי, ר יצחק מברסלוי, ר משה מברסלוי."},{"i":21933,"n":"טיקטין, גדליה טייקס מלונשטיץ","f":"אברהם מנחם","k":"בעל אמונת חכמים","b":"רב בטיקטין-תק, לונטשיץ, גלוגא ובנו ר אברהם בעל \"פתח הבית\" על מקומו אחריו. חיבר גם \"באר התורה\", \"תורת קטן\"."},{"i":21934,"n":"טיקטין, גדליה מברסלוי","f":"שלמה זלמן טיקטין","bt":"תקסח","dt":"תרמו - ז אב","b":"רב בברסלוי-תרג על מקום אביו. הספד עליו ב\"תורה מציון\" - ירושלים תרנה-תרסה - מאת הרשל\"צ ר יעקב שאול אלישר."},{"i":21935,"n":"טיקטין, דוד מירושלים","dt":"תרפד- ב ניסן","b":"מגדולי חכמי ירושלים"},{"i":21936,"n":"טיקטין, זאב מחברון","k":"ר' וועלוול חריף","b":"מחכמי חברון-תק\"ס"},{"i":21937,"n":"טיקטין, טודרוס יוקל","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":21938,"n":"טיקטין, יהודה אשכנזי","f":"שמעון טרוויש מפפד\"מ","k":"בעל באר היטב האחרון","dt":"תקח - ד-ח תמוז","dp":"קניגסברג","b":"נכד ר שניאור טרוויש מפפד\"מ. דיין בטיקטין. אחד המחברים של \"באר היטב\" על השו\"ע. אולי הוא שהיה ראב\"ד בוילנא אצל ר יהושע השל, וחתם-תפח עם ר צבי הירש בן ישכר בער הלוי."},{"i":21939,"n":"טיקטין, יצחק מברסלוי","f":"אברהם - פתח הבית","b":"אב\"ד ברסלוי על מקום אביו ואחיו - ר שלמה זלמן."},{"i":21940,"n":"טיקטין, מנחם דוד","k":"בעל הגהות על הריף","b":"רב בטיקטין-ש\"נ"},{"i":21941,"n":"טיקטין, משה מברסלוי","f":"אברהם - פתח הבית","b":"רב בברסלוי. מתורתו ב\"פתח הבית\" לאביו."},{"i":21942,"n":"טיקטין, שלמה זלמן מברסלוי","f":"אברהם - פתח הבית","dt":"תרג - יח אדר","dp":"ברסלוי","b":"אב\"ד ברסלוי ובנו ר גדליה על מקומו אחריו, נאבק נגד הריפורמים."},{"i":21943,"n":"טיקטין, שמואל אפרים מירושלים","bt":"תרלח","bp":"ירושלים","b":"תלמיד הישיבות עץ חיים ודגל התורה. עוזרו של זאב יעבץ, וכן סייע לבן יהודה בכתיבת המילון. היגר לארה\"ב. החל בכתיבת אנציקלופדיה רבנית."},{"i":21944,"n":"טיקטינסקי, אברהם ממיר","bt":"תקנה","dt":"תקצה","b":"ר\"מ במיר"},{"i":21945,"n":"טיקטינסקי, אברהם ממיר","f":"חיים יהודה ליב","bt":"תרטו","bp":"מיר","dt":"תרצא","dp":"מינסק","b":"ר\"מ בישיבת מיר-תרמד-תרסו על מקום אביו. לאחר שהתעוור מסר את הנהגת הישיבה לר אליהו ברוך קמאי. בקי גם בדקדוק עברי. הניח חדושים בכת\"י."},{"i":21946,"n":"טיקטינסקי, חיים יהודה ליב ממ","f":"שמואל ממיר","bt":"תקפד","bp":"מיר","dt":"תרנט - יט ניסן","dp":"וארשא","b":"ראש ישיבת מיר-תרי-תרנט, ובנו - ר אברהם על מקומו אחריו. היה לו דרך מיוחדת בלימוד הפשט, וגדולי תורה היו באים לשמוע את שיטתו בלימוד. (לתולדותיו ב-\"רבותינו שבגולה\"). חתנו (בזיוו\"ש) - ר אלכסנדר משה לפידות מראסיין."},{"i":21947,"n":"טיקטינסקי, חיים ליב ממיר","f":"אברהם ממיר","dt":"תרנג - יז ניסן","b":"מרביץ תורה,ר\"מ במיר-תר\"י"},{"i":21948,"n":"טיקטינסקי, יצחק יעקב מארה\"ב","k":"בעל באר יצחק","b":"רב בניו יורק. חיבר \"באר יצחק\" נ\"י תרעט, \"עקבי יצחק\" נ\"י תרעג."},{"i":21949,"n":"טיקטינסקי, שמואל ממיר - הזקן","b":"ממייסדי ישיבת מיר-תקעח וראש הישיבה, ובנו ר חיים ליב על מקומו אחריו-תרי."},{"i":21950,"n":"טיקטינסקי, שמואל ממיר - הנכד","f":"חיים ליב ממיר","dt":"תרמג","b":"ר\"מ וראש ישיבה במיר בחיי אביו, נפטר צעיר בחיי אביו. עליו ב'תולדות הגאון ר חיים יהודה ליב'-וארשא תרסב, וב'רבותינו שבגולה'."},{"i":21951,"n":"טיקטינר, יהודה ליב מוילנא","f":"שמחה","k":"בעל שלמי שמחה","b":"רב בזאגר-תקמ, וילנא. חתנו - ר דוד בן אברהם קצנלנבוגן מוילקוביסק."},{"i":21952,"n":"טיקטינר, מאיר הכהן מהורדנא","f":"דובער","dt":"תרה - יח אלול","dp":"הורדנא","b":"מחכמי הורדנא, תמך בר תנחום בזמן המחלוקת על רבנות הורדנא."},{"i":21953,"n":"טיקטינר, מאיר מבלטרמאנץ","b":"רב בבלטרימנץ-תרך, בירך את ר שמשון קלמן הכהן - אביו של ר מאיר שמחה הכהן מדוינסק - בבן שיאיר את העולם בהלכה."},{"i":21954,"n":"טיקטינר, רבקה","k":"בעלת מינקת רבקה","b":"חברה ספר \"מינקת רבקה\" קראקא שעח."},{"i":21955,"n":"טיראדה, יעקב מאמשטרדם","b":"מאנוסי ספרד, הגיע לאמשטרדם עם 10 משפחות יהודיות וחזר ליהדות באמצעות ר משה אורי הלוי אשכנזי, יסד את קהלת יוצאי ספרד באמשטרדם ובנה את בית הכנסת הראשון באשטרדם - \"בית יעקב\"-שנח."},{"i":21956,"n":"טיראנצינו, חזקיה","f":"נתנאל","b":"תשובה ממנו ב\"פחד יצחק\""},{"i":21957,"n":"טיראנצינו, שלמה","b":"נזכר ב\"באר עשק\"."},{"i":21958,"n":"טיראצינו, שלמה מירושלים","b":"מחכמי ירושלים, והיה מהסובלים בפרעות אבן פארוך-שפה. (מקור שם המשפחה - עיר באראגון ספרד)."},{"i":21959,"n":"טירהויז, יעקב מפודוולוטשיסק","f":"נפתלי הירץ","k":"בעל עקבי יעקב","bt":"תרל","dt":"תשג","b":"חתן ר אליקים גצל מלכוביץ. חסיד הוסיאטין מחכמי פודוולוטשיסק ואיש עסקים. נספה בשואה. חיבר \"עקבי יעקב\" בילגוריא תרצח. פרסם מאמרים ב\"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא."},{"i":21960,"n":"טירהויז, נפתלי הרץ מגלינא","b":"חסיד הוסיאטין. רב בגלינא, וולוטשיסק-תרמד, ובנו ר ענזיל על מקומו אחריו."},{"i":21961,"n":"טירי, שלום מתימן","b":"מחכמי צנעא, חתם עם חכמי הישיבה על תקנות - תרמב-תרמו."},{"i":21962,"n":"טירמוזו, שמואל מאזמיר","b":"מחכמי אזמיר-שנות ה-ת'."},{"i":21963,"n":"טירמישי, דוד משלוניקי","dt":"שפג - כב אלול","dp":"שלוניקי","b":"ר\"מ בשלוניקי. מתלמידיו - דון יעקב בן דון משה יחיא."},{"i":21964,"n":"טירנא, יצחק איזיק","k":"בעל ספר מנהגים","bt":"1370?","dt":"רל","b":"תלמיד ר אברהם קלויזנר מוינה, מהר\"ש מוינה, ומוהר\"ר אהרן הקדוש מוינה. ר\"מ בפרג, פרשבורג, רב בטירנו. נזכר במהרי\"ל אודות גט שסידר-קפא. חיבר \"ספר מנהגים\" ונציה שעו, ונדפס עם הגהות ר ליזר חזן. מתשובות הרמ\"א נראה כי נוהגים אחריו יותר מהמהרי\"ל.","bk":[["מנהגים [טירנא]","הלכה ומנהג - ראשונים"],["מנהגי הרב זלמן יענט","הלכה ומנהג - ראשונים"]]},{"i":21965,"n":"טירנו, מתתיהו נסים מאיטליה","f":"יעקב ישראל","k":"בעל שפת אמת","bt":"תקה","bp":"אנקונא","b":"מחכמי איטליה, רב בפירנצה, אורבינו, טיניגליה, פיסארו-תקס. בתקופתו היו מלחמות נפוליאון באיטליה והיו גזרות רבות ליהודים, וחיבר שירים על הצלת הקהלות ושימשו בימי פורים המיוחדים לקהלות השונות, וגם הוא נאסר ושוחרר באותו הזמן. קרובו של ר דניאל טירני בעל \"עיקרי הד\"ט\". חיבר גם \"שפת אמת\", \"מדבר מתנה\" ועוד."},{"i":21966,"n":"טירנויאר, זאב וולף הלוי","k":"בעל טל אורות-תשטו","bt":"תרמב","dt":"תשך","dp":"צפת","b":"תלמיד ר יהודה גרינוולד, דיין בשאמלוי, שאמקוט, רב בהומורוד-סטמר, רגאט, לעספיץ, שאץ. ניצל מהשואה ואחריה עלה לצפת והתגורר אצל חתנו ר אהרן לייפר האדמור מנדבורנא בצפת."},{"i":21967,"n":"טירני, אברהם מאפשטני","f":"דניאל","k":"בעל קנה אברהם","b":"רב באפשטני (פולין). חיבר \"קנה אברהם\" פיורדא תצח."},{"i":21968,"n":"טירקהיים, יצחק","k":"בעל גבעת שאול","b":"דרשן-תק\"ע"},{"i":21969,"n":"טירקל, אליעזר ליפא מטרנופול","f":"ישראל מנחם","bt":"תרטז","bp":"טרמבובלה","dt":"תרצט","b":"חסיד הוסיאטין, סוחר ומחכמי טרנופול."},{"i":21970,"n":"טירקל, דוד בר מניו יורק","f":"אהרן ירוחם פישל","k":"בעל שירי דוד","bt":"תרלח","bp":"כפר באראווקא - פודוליא","b":"עבר עם משפחתו למאהלוב-פאדאלסק, והתחבר עם מנחם נחום ליטינסקי, וישראל יוסף סירקיס ולמד עברית ולמודים כלליים. עבר לארה\"ב והתישב בפילדלפיה-תרס. חיבר \"שירי דוד\" ניו יורק תרסד."},{"i":21971,"n":"טירקל, יעקב מסכודניצה","f":"שרגא פיבל","bt":"תרס","bp":"טרנופול","dt":"תשג","b":"חתן ר אברהם בקנרוט מסכודניצה. מחכמי סכודניצה. נספה בשואה."},{"i":21972,"n":"טירקל, ישראל מנחם מטרמבובלה","f":"מנחם אלתר","bt":"תקץ","dt":"תרנב","b":"מחכמי טרמבובלה."},{"i":21973,"n":"טירקל, מרדכי זאב וולף מבוצאץ","f":"ישראל מנחם","bt":"תרה","bp":"טרמבובלה","dt":"תרפט","dp":"וינה","b":"רב בבוצאץ."},{"i":21974,"n":"טירקל, שמואל מטרנופול","f":"אליעזר ליפא","b":"חתן ר אברהם יוסף בקנרוט מסכודניצה. מחכמי טרנופול."},{"i":21975,"n":"טירקל, שרגא פיבל","f":"אליעזר ליפא","b":"חסיד הוסיאטין, תושב טרנופול. חתן ר יעקב ויידנפלד מהרימלוב. נספה בשואה."},{"i":21976,"n":"טירקלש, שלמה הירש מבודשפיץ","b":"נכד ר שלמה מוניא מבלגרד ורויסטיץ. רב בבודשפיץ. הסכים על \"השתערות מלך הנגב..\" - אמשטרדם תצז."},{"i":21977,"n":"טירר, אהרן זליג מדורהוי","f":"יעקב פנחס מדורהוי","k":"אדמור מדורהוי","dt":"תרצג - כט שבט","b":"נינו של ר חיים טירר מטשרנוביץ. חתן ר אפרים הדיין מהרלו."},{"i":21978,"n":"טירר, חיים מטשרנוביץ","f":"שלמה","k":"בעל סדורו של שבת","bt":"תקכ או תקל","bp":"בוצאץ","dt":"תקעו - כז כסלו","dp":"צפת","b":"מצאצאי הב\"ח וה\"חלקת מחוקק\", נכד ר רפאל מייזלש בעל \"תוספת שבת\". תלמיד המגיד ממזריטש, המגיד מזלוטשוב, ור אברהם דוד בעל \"ברכת דוד\" מבוצ'אץ. רב בקריפטש-תקמח (וגורש משם), קוזובה, טשרנוביץ-תקמו, גליל בוקובינה-תקן, בוטושאן-תקסז וחתניו ר אהרן מבוטושאן ור יצחק איזיק מבוטושאן על מקומו אחריו, קישינוב, מוהילב-תקעב ובנו ר יעקב יוסף על מקומו אחריו במוהליב. עלה לצפת-תקעג. חיבר גם \"באר מים חיים\" סדילקוב תקף, \"ארץ החיים\" טשרנוביץ תרכא, ועוד. חיבר הקדמה לספר \"גליא רזא\" לר אברהם תלמיד הארי. עלה לצפת בשנת תקעג (ולדעת פרומקין תקלז או סמוך לכך), בספר \"בית קומארנא\" מסופר מעשה שקרה עמו ועם בנו (שסטה מדרכו ואביו קרבו עד שחזר בתשובה). יש שרשמו תאריך פטירתו תקעג או תקעז."},{"i":21979,"n":"טירר, יחיאל מיכל מדורהוי","f":"יעקב יוסף ממאהליב","k":"אדמור מדורהוי","dt":"כג תשרי","b":"נכד ר חיים טירר מטשרנוביץ. חתן ר אליעזר זאב מבוצאץ. רב ואדמור בדורהוי."},{"i":21980,"n":"טירר, יעקב יוסף ממאהליב","f":"חיים מצ'רנוביץ","dt":"תרכו - טז אב","b":"חתן ר יצחק מקאליס-בן ר משה חיים אפרים מסדילקוב. רב במאהליב על מקום אביו."},{"i":21981,"n":"טירר, קלמן קלונימוס","f":"חיים מצ'רנוביץ","b":"חתן ר אברהם יהושע השל מאפטא. בספר \"בית קומארנא\" מסופר מעשה שקרה עמו - שסטה מדרכו ואביו קרבו עד שחזר בתשובה."},{"i":21982,"n":"טיש, זאב וולף","b":"תשובה אליו ב\"ברכת אברהם\"."},{"i":21983,"n":"טכורש אלכסנדר סנדר גדליה","bt":"1860","dt":"ה'תשח 1948","bk":[["המבחן",""],["עטרת חן",""],["תפארת האדם",""]]},{"i":21984,"n":"טכורש, אלכסנדר גדליה מסלופצי","f":"אברהם יצחק מולאצלאוע","k":"בעל עטרת חן","b":"שו\"ב בסלופצי, ניישבה, ולצלבק, עלה לארץ וכיהן כרב ושו\"ב בכפר חטים-ליד טבריה, עבר לבני ברק. חיבר גם \"המבחן\" - וארשא תרס."},{"i":21985,"n":"טכורש, כתריאל אפרים פישל","f":"אלכסנדר גדליה","bt":"תרנז","bp":"נישאבה","b":"תלמיד ישיבת \"עץ חיים\" בוולוצלבק, ותלמיד מהרי\"ל קובלסקי, מהרש\"י וינגוט מקובל, רי\"ז לבנטל מפולטוסק, ועוד. עלה לארץ-תרצד וכיהן כרב בשכונת שפירא בתל אביב. מראשי תנועת הפועל המזרחי. פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו. סופר חרדי."},{"i":21986,"n":"טל שלמה","bt":"1909","dt":"ה'תשנח 1998","bk":[["סדור רנת ישראל",""]]},{"i":21987,"n":"טל, טוביה מהאג ונידה-הולנד","dt":"תרנח","b":"רב הפלך בנידה-הולנד-תרנ, רב ראשי בהאג-תרנה."},{"i":21988,"n":"טל, צדוק מאוטרכט","f":"משה טוביה טל","dt":"תשטו - יד כסלו","b":"רב פעלים לחזוק היהדות,רב ראשי באוטרכט-תרע\"ח,רב ראשי של הולנד-תש\"ה"},{"i":21989,"n":"טלבי, יהודה ליאון מבלגרד","bt":"תרלח","bp":"בלגרד","b":"אספן אמנות, עלה לארץ-תרצד והתישב בתל אביב, נפטר ללא ילדים. נדב את האוסף למוזיאון תל אביב."},{"i":21990,"n":"טלושקין ניסן","bt":"1880","dt":"ה'תשל 1970","bk":[["התורה והעולם",""],["טהרת מים",""]]},{"i":21991,"n":"טלושקין, ניסן מדוקאר וניו יורק","f":"משה יצחק בן דוד","k":"בעל טהרת המים","bt":"תרמא-ב","bp":"בוברויסק-פלך מינסק","dt":"תשל - כא אד\"ב","b":"תלמיד ישיבות בוברויסק, קורסאוו, סלוצק. נסמך מאת: ר שמואל משה שפירא, ר יוסף באקשט, רש\"ן שניאורסון. חתן ר משה צ'רני מדוקאר. רב בדוקאר-תרסב על מקום חותנו, פוכוויץ-פלך מינסק-תרפא, היגר לארה\"ב וכיהן כרב בקהלת \"בני יצחק\" בניו יורק-תרפה. פרסם מאמרים ב\"מגדל תורה\" - נ\"י תרפה. עורך \"המסלה\" - נ\"י תרצו, \"תלפיות\" - נ\"י תשד."},{"i":21992,"n":"טלטש, הירש מניקלשבורג","b":"רב בניקלסבורג-תרט\"ו"},{"i":21993,"n":"טלטש, שלמה ממורביה","b":"גביר במורביה. חתניו - ר אריה ליב פוקס מועספרים, ר בער אופנהיים מפרשבורג, ר משה אריה ליב מבאזינג, ר אריה ליב טלטש-טויבר משטמפן."},{"i":21994,"n":"טלטש-טויבר, אריה יהודה ליב","f":"חיים","bt":"תקיב","bp":"ראדנין-בוהמיה","dt":"תקץ - כא חשון","dp":"גלנטא","b":"מצאצאי בעל תרומת הדשן. תלמיד ר זרח אידליץ בעל \"אור לישרים\" והגן על רבו מפני ר מאיר ברבי שביקר בפרג. חתן הגביר ר שלמה טלטש. רב בשטמפן-תקסז על מקום ר לוי פולק, גלנטא-תקמו (כנראה צ\"ל תקסז) על מקום ר יואל גוטליב, ור אהרן פשקס על מקומו אחריו. נזכר אצל החת\"ס שהשיב לו ולחבריו ר ישעיה מיאקא ור יוסף מסערער. בניו - ר איצק וולף, ר זרח, חתנו - ר חיים האס, ר מרדכי."},{"i":21995,"n":"טלר, אברהם מרזפניק","b":"מחסידי הדברי חיים ואח\"כ בובוב."},{"i":21996,"n":"טלר, אהרן זאב מפריסטיק","f":"פנחס","bt":"תרמה","bp":"לונק ליד פריסטיק","dt":"תשלח","b":"רב בסטרופקוב. ניצל מהשואה ועלה לארץ-תשח, התישב בפתח תקוה וממיסדי בית המדרש \"דברי חיים\" לחסידי צאנז."},{"i":21997,"n":"טלר, יחזקאל מסיאטין","b":"רב בסניאטין-תרכד."},{"i":21998,"n":"טלר, יחזקאל משלם מניר-מאדע","f":"אליהו מקאמארן","dt":"תרמה","dp":"ניר-מאדע","b":"תלמיד החת\"ס. נכד ר פנחס הטרשטין-רפפורט מסטמר. רב בקאמארן, ניר-מאדע-תרטז."},{"i":21999,"n":"טלר, ישראל הלוי מרחובות","f":"יהודה","k":"בעל מבט חפשי בדקדוק","b":"מורה ברחובות."},{"i":22000,"n":"טלר, משה צבי מזרשין","b":"רב בזרשין-תרפב."},{"i":22001,"n":"טלר, צבי אלעזר מבוריסלב","k":"בעל קול אלקים","b":"מורה לעברית בבית הספר של הברון הירש בבוריסלב, מורה בבאטושאן. פרסם מאמרים ב\"הבונה\" - לבוב תרסד."},{"i":22002,"n":"טלר, שמעון מטוכוב","b":"מחכמי טוכוב."},{"i":22003,"n":"טלשבסקי, אהרן מסעמיאנאווקא","f":"לוי יצחק מנאסווקא","k":"בעל מפתח שפתי","bt":"תרלח","b":"ממשפחת הגר\"א, ונכד(-אבי אמו) ר אברהם מאיר מבוברויסק-מחסידי חב\"ד. חתן ר אברהם מסלוצק-חתנן ר איסר-נכד הגר\"א. תלמיד ישיבת בוברויסק. רב בסמינובקה(=סעמיאנאווקא)-פלך פולטובה-תרסד. נסמך מאת: רד\"צ חן מצרניגוב, ר יצחק שלמה יואל מראוונא, ר ליב האפט מקאנטאפ. חיבר \"מפתח שפתי\" - בכת\"י."},{"i":22004,"n":"טלשבסקי, לוי יצחק מנאסאווקא","k":"בעל דבר הלכה","b":"ממשפחת הגר\"א, ומצאצאי אחיו של ר מנדל חאראמיצר. רב בכמה קהלות, נאסאווקא-תרמ. חיבר גם \"מי מרום\" - בהלכות מקואות."},{"i":22005,"n":"טמערליש, יעקב","f":"נתן נטע שפירא","b":"רב בלובלין"},{"i":22006,"n":"טמערליש, יעקב מורמייזא ולובלין","f":"אליעזר","k":"בעל ספרא דצניעותא די","bt":"שן - בערך","bp":"וורמיזא","dt":"תכז","b":"מאפטא. מכונה גם ר יעקב אשכנזי. חתן ר אברהם חיים פולק מגדולי המקובלים, מרביץ תורה בלובלין, קרמניץ, וורמייזא, וינה (ישב בתענית 40 שנה) בנו ר אליעזר הו\"ל את ספר אביו. מתלמידיו: ר\"ש קיידנובר בעל \"ברכת הזבח\", ר גרשון אשכנזי בעל \"עבודת הגרשוני\", ר מאיר שטרן, ר מאיר איזנשטט בעל \"נר למאור\", ועוד. חיבר גם חדושים ופירושים לתנ\"ך לש\"ס ולזהר. (לפי ניפי-גירונדי - אחיו של ר שבתי בס משורר בעל \"שפתי ישנים\"."},{"i":22007,"n":"טמפלר, אהרן יוסף מרזפניק","f":"ברוך","k":"בעל רבי הזהב","bt":"תרל","dt":"תש","b":"חתן ר דוד שאול גולדברג מרזפניק. רב ברפניק על מקום אביו. חיבר \"רביד הזהב\" פיעטרקוב תרצב."},{"i":22008,"n":"טמפלר, אפרים מבריגל","f":"ברוך פרייזינגר","k":"בעל אגרת הטיול","bt":"תרכה","dt":"תש","b":"חתן הגביר ר אלכסנדר זושא בלויגרונד. רב בבריגל. הדפיס \"ספר החיים\" עם פירוש \"רבבות אפרים\" קראקא תרפג, חיבר \"אגרת הטיול\" בילגורי תרצז."},{"i":22009,"n":"טמפלר, אריה זאב מטוכוב","f":"ליב וולף","b":"רב בטוכוב."},{"i":22010,"n":"טמפלר, ברוך מבריגל","b":"מחכמי בריגל. רב ברזפניק."},{"i":22011,"n":"טמפלר, דב בריש","f":"מרדכי","k":"בעל פקודת הצדיקים","bt":"תרכה","b":"חיבר \"פקודת הצדיקים מדובר טוב\" קראקא תרמד."},{"i":22012,"n":"טמפלר, זכריה מפיסטין","b":"רב בפיסטין-תרעג."},{"i":22013,"n":"טמפלר, חיים פנחס מטורנא","b":"רב בטורנא. חתן ר מאיר מלטר מטורנא."},{"i":22014,"n":"טמפלר, יצחק מקראקא וקיעלץ","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":22015,"n":"טמפלר, פנחס מדמביץ","k":"אדמור מבריגיל דמביץ","b":"תלמיד ר נפתלי צבי מרופשיץ, נסמך לאדמורות בידי הדברי חיים מצאנז. אדמור בבריגיל, דמביץ, חתנו ר יהודה פכטר על מקומו אחריו."},{"i":22016,"n":"טמקין, יהודה הכהן","f":"שמואל רפאל","k":"בעל שרביט הזהב","b":"ר\"מ בבירעזין, מינסק."},{"i":22017,"n":"טמקין, מנחם דוד","dt":"תרפג - ט חשון","b":"רב בפיעטרקוב. פרסם מאמרים ב\"אסיפת חכמים\" - מלניץ תרפח.","bk":[["ויברך דוד",""]]},{"i":22018,"n":"טמרזון, מאיר מסטאוושין","f":"אברהם","bt":"תרכב","b":"תלמיד זקנו ר צבי מפלאצק-תלמיד רע\"א. חתן ר ליב מואלצלאוועק. רב בסוקולסקי(=סקילסקי)-מחוז קאליש-תרנח, סטאוושין-פלך קאליש-תרסה."},{"i":22019,"n":"טמשוב, משה בנימין","k":"מבי\"ט, בעל אבני שהם","bt":"תרלח","dt":"תשכ","b":"רב פעלים,רב בברוקלין-תרע\"ב,ברונזוויל"},{"i":22020,"n":"טמשוואר, גרשם","dt":"תקצז - ב אד\"ב","b":"בסוף ימיו-תקצד רב באופן ישן"},{"i":22021,"n":"טנא, שמשון","b":"מו\"צ בקומרנא-ת\"ר"},{"i":22022,"n":"טנא, שמשון מקומרנא","b":"חסיד ר מאיר מפרמישלן. רב בקומרנא."},{"i":22023,"n":"טנביצקי, שלמה","b":"פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא, \"תבונה\" - ירושלים תשא-תשח."},{"i":22024,"n":"טנוג'י, אהרן הכהן מתונס","f":"יצחק חיים דוד","k":"בעל לב אהרן","b":"דיין בתוניס וצפאקס, חיבר \"לב אהרן\""},{"i":22025,"n":"טנוג'י, דוד הכהן מתונס","b":"מרבני תונס"},{"i":22026,"n":"טנוג'י, יהודה הכהן מירושלים","f":"שמואל","k":"בעל פירוש על הרמבם","dt":"תע","dp":"ירושלים","b":"מחכמי ירושלים תלמיד חבר של ר חזקיה די סילוה, מתשובותיו בספרי חכמי דורו. היה רב בישיבת \"בית יעקב\", ראשון לציון-תסז. חיבר פירוש על הרמב\"ם שלא נדפס. מתלמידיו ר ישראל מאיר מזרחי. כנראה שהוא החותם על כתב שליחות ר אברהם אירגאס ור חיים חזן בשנת תסד. דיין אצל ר אברהם יצחקי."},{"i":22027,"n":"טנוג'י, יהודה ממצרים","f":"ישמעאל","bp":"ירושלים","dt":"תי - אחרי","b":"התישב עם אביו במצרים. בנו - ר שמואל."},{"i":22028,"n":"טנוג'י, יוסף הכהן מתונס","k":"בעל בני יוסף","b":"רב בתונס, איטליה. חיבר \"בני יוסף\" - ליוורנו."},{"i":22029,"n":"טנוג'י, יצחק חיים דוד הכהן","k":"בעל תורת המלך","dt":"תרז - א סיון","dp":"תונס","b":"רב בתונס-תקץ, ורב ראשי על מקום ר יצחק טייב בעל ערך השלחן. בניו ר אליהו ור אהרן שהיה דיין בתונס וצפאקס בעל \"לב אהרן\". חיבר ספרים רבים בכת\"י ורובם אבדו, מתוך הנשאר נדפס \"תורת המלך\" ג'רבא תשה."},{"i":22030,"n":"טנוג'י, ישועה הכהן מירושלים","dt":"תקנו","dp":"ירושלים","b":"מחכמי תונס-תקל - אולי הוא שהיה בא כח היהודים בפני הביי של תונס ושר הכספים שלו, יסד דפוס בתונס והדפיס \"זרע יצחק\"-תקכה, עלה לירושלים. נספד בספר \"חיים וחסד\"."},{"i":22031,"n":"טנוג'י, ישמעאל הכהן ממצרים","k":"בעל ספר הזכרון","b":"הגיע מתונס למצרים, ראש הרבנים בקאהיר-שג. חתם-שכט על מכתב התמיכה בדון יוסף נשיא. לפי רוזניס עלה לירושלים ועבר למצרים עם בנו ר יהודה."},{"i":22032,"n":"טנוג'י, ישראל הכהן","b":"דיין בסוסה(תוניס)-תר\"מ"},{"i":22033,"n":"טנוג'י, פנחס הכהן מטבריה","f":"דוד","bt":"תקעד-ז","bp":"מוכנין-תונס","dt":"תרס - כה תשרי","dp":"טבריה","b":"מחכמי תונס, עלה לטבריה-תרמב. חיבר קונטרס על כל מאמרי \"מפני מה\" המופיעים בתלמוד. השאיר חבורים רבים בכתב יד."},{"i":22034,"n":"טנוג'י, שמואל הכהן מירושלים","dt":"תע","dp":"ירושלים","b":"מחכמי ירושלים, בשנת תנח בשליחות במרוקו, בשנת תס חתם עם חכמי ירושלים. בשנת תסז התמנה ל\"ראשון לציון\" על מקום ר אברהם ריויגו שנסע לאיטליה ור אברהם יצחקי על מקומו אחריו. דיינים אצלו - ר אברהם גטניו, ר יוסף קונקי, ר שמשון גומץ פאטו, ובנו - ר יהודה טנוג'י, והסכימו על \"מאורות נתן\"."},{"i":22035,"n":"טנזי, אברהם","b":"מקובל"},{"i":22036,"n":"טנזי, שלמה ממראקש","b":"מחכמי מראקש."},{"i":22037,"n":"טנלס הנדל, יצחק מוינה","k":"בעל נר יצחק","b":"דומ\"צ בווינה-ת\"ר"},{"i":22038,"n":"טננבוים, א' מוינה","b":"פרסם מאמרים ב\"היכל התורה\" - מיר-נוברדוק תרצה."},{"i":22039,"n":"טננבוים, אבנר מארה\"ב","f":"צבי הירש","bt":"1848","bp":"שירווינט","dt":"1913","dp":"ניו יורק","b":"סופר, מקורב לרא\"ב הכהן גוטלובר, ולשלום אברמוביץ (מנדלי מוכר ספרים). היגר לארה\"ב-1887 ופרסם ב\"אידיש טאגעבלאט\", ועוד. עורך \"מבשרת ציון\". חיבר עשרות ספורי מסעות בסגנון עממי. פרסם ביוגרפיות של גדולי ישראל ב\"מארגן ז'ורנאל\"."},{"i":22040,"n":"טננבוים, אברהם אבוש מקרסטיר","f":"יום טוב ליפמן","k":"הו\"ל שו\"ת הרי\"ף","bp":"בובוב","b":"התייתם בילדותו וגדל אצל אביו חורגו ר ירמיה רוזנבוים ממטרסדורף. בזיוו\"ש חתן אחיו חורגו - ר יואב מסטנוב. הגיע מגליציה לכהן כרב בקרסטור(=קרסטיר)-תקס, סיקס-הונגריה-תקעה. גורש ע\"י שלטונות הונגריה ועזב עם כמה מחסידיו. הביא לדפוס \"שו\"ת הרי\"ף\" וינה תקנד."},{"i":22041,"n":"טננבוים, אברהם יעקב ממישקולץ","f":"משה מוערפעלעט","bt":"תרמג","bp":"וערפעלעט","dt":"תשד","dp":"אושוויץ","b":"תלמיד השב\"ס, והדעת סופר. חתן ר יהודה קרמר מטעלעגד. רב במישקולץ (פעלשא-וארוש). נספה בשואה. בנו - ר שרגא צבי בעל \"נר צבי\"."},{"i":22042,"n":"טננבוים, אהרן מזקראטשין","f":"יהודה טננבום","dt":"תקפו - כד חשון","b":"רב בזקראטשין"},{"i":22043,"n":"טננבוים, אריה ממעליץ","b":"מחכמי מעליץ - ממשתתפי \"אהל מועד\"."},{"i":22044,"n":"טננבוים, בנימין זאב וולף מוורר","k":"בעל רחובות הנהר","dt":"תרלג - ב אלול","b":"חתן ר שרגא פיבש פרנקל בעל תלת גוונין. רב בסנדרא(=סאנדרו-מחוז בורשוד)-תקפא וראש ישיבה, ובנו ר שרגא צבי על מקומו אחריו, וארפלט-תרז על מקום ר יהושע וארפלט ור משה טננבוים על מקומו אחריו. חיבר \"פלגי מים\", \"רחובות הנהר\" - (אחרי שבחור מהישיבה טבע בנהר - קילל את הנהר שישנה מהלכו)."},{"i":22045,"n":"טננבוים, בצלאל מארה\"ב","b":"פרסם מאמרים ב\"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":22046,"n":"טננבוים, דוד שלמה מזלישטשיק","b":"מחכמי זלישטשיק-תריד."},{"i":22047,"n":"טננבוים, זליג משרנצק","f":"יחיאל מיכל מראדזין","k":"בעל ניצוצי אור","dt":"תרז - ז שבט","b":"נכד ר יחיאל מיכל מנמירוב. תלמיד ר ברוך ממזבוז, ר חיים מטשרנוביץ, ר משה מפשעוורסק, ר משולם זושא מאניפולי ועוד. שו\"ב בשרנצק, עבר לקאליש."},{"i":22048,"n":"טננבוים, חיים מוארשא","f":"יעקב יהודה מנאדרזין","k":"בעל רעיוני תורה","bt":"תרכא","dt":"תרצא - ה אייר","b":"חתן הגביר ר מנדל בלושטין מויסקוט. תלמיד ר דב בריש מביאלא (שושלת טשכנוב), ודודו ר שמעון מסקרנויץ. אדמור בנאדרזין-תרס, אדמור בוארשא-תרפז על מקום דודו ר שמעון האדמור מוארקי. חיבר \"רעיוני התורה\", והגהות על ספר אביו \"ישרש יעקב\"."},{"i":22049,"n":"טננבוים, יהודה ליב","f":"יעקב טננבום","b":"רב בריטשוואל-תק\"מ"},{"i":22050,"n":"טננבוים, יונה","f":"מלכיאל צבי-דברי מלכי"},{"i":22051,"n":"טננבוים, יונה הלוי","f":"מלכיאל - דברי מלכיאל"},{"i":22052,"n":"טננבוים, יוסף מקשאנוב","f":"שלמה יחזקאל","b":"רב בקשאנוב בזמן ר זושא ור אלימלך כשגרו שם."},{"i":22053,"n":"טננבוים, יחזקאל דוב","b":"חתן ר שמואל יצחק לנדא האדמור מטשכנוברב בויסקיט"},{"i":22054,"n":"טננבוים, יעקב יהודה מנאדרזין","f":"נתן נטע","k":"אדמור מוארקי נאדרזין","r":"אדמו\"ר מנאדרזין","bt":"תקצד (באו' תרכז","dt":"תרמו - ה כסלו","b":"חתן ר מרדכי מנחם מנדל מוארקי. תלמיד חותנו זקנו ר יצחק מוארקי, ור דב בריש מביאלא, אדמו\"ר בנאדרזין אחר פטירת רבו מביאלא. התפרסם בחומרתו בענין בשר בחלב. חיבר \"ישרש יעקב\".","bk":[["ישרש יעקב – יבמות",""]]},{"i":22055,"n":"טננבוים, יעקב מבובוב","b":"רב בבובוב-תקכח."},{"i":22056,"n":"טננבוים, יעקב מטאליא ופוטנוק","f":"זאב וולף-רחובות הנהר","k":"בעל נהרי אפרסמון","bt":"תקצב","bp":"סענדרא","dt":"תרנז - כח כסלו","b":"אחיו של ר שרגא צבי מטשאט. רב בטאליא-תריח, טשאטה(=מזו-צ'אט)-תרכט, וורפלעט-תרלג, רב וראש ישיבה בפוטנוק(=פיטנוק), ובנו ר מאיר על מקומו אחריו, ובנו ר מנחם מפילעק עבר למלא את מקום אחיו בטאנרא. מתורתו ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":22057,"n":"טננבוים, יעקב מליזנסק","b":"רב בליזנסק-תק\"י"},{"i":22058,"n":"טננבוים, יצחק מפומרן","b":"מחכמי פמורן-תרסז."},{"i":22059,"n":"טננבוים, ישכר","f":"אהרן טננבום","b":"ראב\"ד בפרגה-תר\"מ"},{"i":22060,"n":"טננבוים, ישעיה קלונימוס מגארוא","b":"רב בגארוואלין. פרסם מאמרים ב\"בית מאיר\" - אוסטרובצה - פיעטרקוב - תרצא, \"כרמנו\" - אלכסנדר-לודז תרצג."},{"i":22061,"n":"טננבוים, ישראל מחרסקוב","b":"מחכמי חרסקוב-תרנח. פרסם מאמרים ב\"מגד ירחים\" - סיגט תרנח."},{"i":22062,"n":"טננבוים, מאיר מפוטנאק","f":"יעקב מפוטנאק","k":"בעל אמרי מאיר","bt":"תריז","dt":"תרפח - א אב","b":"חתן ר אהרן ביכלר מפילעק. רב בפילעק(=פילק)-תרמב, טורנא, פוטנאק(=פוטנוק)-תרנז על מקום אביו. חתנו ר חיים יהודה ליב טיטלבוים על מקומו אחריו-תרץ. מתורתו בשם \"לוית אור\" בתוך \"אילת השחר\" לזקנו. חתנו גם - ר שמואל בנימין יונגרייז."},{"i":22063,"n":"טננבוים, מאיר צבי הירש מבריגל","b":"גביר מחכמי בריגל - מחותנו של הדברי חיים (השיא בתו לר משה בן יחזקאל משינאווא)."},{"i":22064,"n":"טננבוים, מלכיאל צבי הלוי מלומז","k":"בעל דברי מלכיאל","b":"מגדולי חכמי דורו, רב בלומזא-תרס. תשובה ממנו ב\"מציון תצא תורה\" - זאמושט תרפט, \"הפסגה\" - וילנא-וארשא-פיעטרקוב תרנה. בנו - ר יונה."},{"i":22065,"n":"טננבוים, מנחם מנדל מויזבניק","b":"חותנו של ר משה יחיאל אפשטין בן ר אברהם שלמה מאוזרוב."},{"i":22066,"n":"טננבוים, מנחם מנדל מטארנא","f":"יעקב - נהר אפרסמון","bt":"תרט-כב","dt":"תשד - ג סיון","dp":"אושוויץ","b":"חתן דודו ר שרגא צבי טננבוים בעל נטע שורק ממעזא-טשאטה. מקובל וגם כתב קמיעות. רב בפילעק-תרן, טארנא(=טורנא)-ליד קאשוי-תרנט. חתנו - ר שמעון נייפלד מדיאש-דיאר. פרסם מאמרים ב\"וילקט יוסף\". מתורתו בספר אביו. נספה בשואה."},{"i":22067,"n":"טננבוים, מרדכי מנחם","dt":"תשג","b":"מרבני פולין"},{"i":22068,"n":"טננבוים, משה מוארפלט","f":"שרגא צבי ממעזא-טשאטא","bt":"תרי","dt":"תרעו - טו שבט","b":"תלמיד זקנו ר בנימין זאב מוערעפעלט בעל \"פלגי מים\". חתן ר מרדכי היימן מטשעניעטע. רב וראש ישיבה בוורפלט(=וארפלט)-תרלג על מקום זקנו, וחתנו ר פישל שולומון על מקומו אחריו. נסמך מאת: ר דוד דייטש מבאלאשא בעל \"גורן דוד\", ר יעקב מפיטנאק, ר יוסף וייס מערלוי. בנו - ר אברהם יעקב, עוד מחתניו: ר מנחם יוסף דייטש משאלבא, ר שרגא ואקטאר."},{"i":22069,"n":"טננבוים, משה מסעפשי","k":"בעל מסעות משה","dt":"תשד","b":"רב בירושלים, מילדוי-סעפשי."},{"i":22070,"n":"טננבוים, משה מפוטנוק ומילדוי","f":"מנחם","b":"דומ\"צ בפוטנוק, רב במילדוי-תרעה."},{"i":22071,"n":"טננבוים, פנחס מנחם מפביאניץ","b":"פרסם מאמרים ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":22072,"n":"טננבוים, שלום ברוך מסטרופקוב","b":"רב בסטרפקוב-תרל\"ו"},{"i":22073,"n":"טננבוים, שלמה ברוך מסטרופקוב","k":"בעל חדושי רשב\"ט","bt":"תקסה","dt":"תרנא - ה אד\"א","b":"תלמיד ר נפתלי צבי מרופשיץ. ראב\"ד בסטרופקוב."},{"i":22074,"n":"טננבוים, שלמה מנדרזין","f":"יעקב יהודה טננבום","dt":"תרסג - טו שבט","b":"אדמו\"ר בנדרזין-תרמ\"ו"},{"i":22075,"n":"טננבוים, שמואל","dt":"תשד","b":"דומ\"צ בטארנא"},{"i":22076,"n":"טננבוים, שמריה מברנוב","f":"יקותיאל זלמן","b":"רב בברנוב."},{"i":22077,"n":"טננבוים, שרגא צבי מגרוסורדין","b":"חתן ר משה קליין מגרוסורדין. רב בגרוסורדין, בני ברק."},{"i":22078,"n":"טננבוים, שרגא צבי ממאזא-טשאט","f":"זאב וולף-רחובות הנהר","k":"בעל נטע שורק","bt":"תקפו","dt":"תרנד-ז - ד אדר","b":"חתן ר אברהם יעקב ראזע מקאשוי. מגדולי חכמי דורו, רב בסענדרא(=סאנדרו)-תרח על מקום אביו, מעזא-טשאט(=מזו-צ'אט)-תרלד וראש ישיבה, חתנו ר יהודה אלטמן על מקומו אחריו. מתורתו ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":22079,"n":"טננבלט, אברהם חיים מלובלין","b":"פרסם מאמרים ב\"מציון תצא תורה\" - זאמושט תרפט."},{"i":22080,"n":"טננהויז, משה מבוצאץ","b":"רב בבוצאץ-תר."},{"i":22081,"n":"טננצופ, אורי מסטרונא","b":"רב בססרונא(=סטארוניא) שליד סטניסלב-תרעד. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":22082,"n":"טנצר, אברהם אבא מריגליץ","f":"נחום צבי הירש","bt":"תרי","dt":"תרפג","b":"חתן ר יעקב יצחק מיבוניטש. רב בריגליץ-תרנט על מקום אביו. בנו ר יעקב יצחק על מקומו אחריו."},{"i":22083,"n":"טנצר, נחום צבי הירש מריגליץ","f":"יוסף","k":"אדמור מריגליץ","bt":"תקף","dt":"תרנה","b":"רב בריגליץ-תרכט על מקום חותנו - ר טוביה גוטמן. כיהן כאדמור בהשפעת הדברי חיים."},{"i":22084,"n":"טנצר, נפתלי הרץ סגל","b":"רשם הגהות על הספר שלחן ערוך-מגיני ארץ - וינה תקסח."},{"i":22085,"n":"טנקל, נטע מאינטורק","dt":"תשג","b":"רב באינטורק"},{"i":22086,"n":"טסלר, ירמיה מקלויזנבורג","f":"חיים אלתר מדעש","k":"בעל זכור ואל תשכח","dt":"תשלט - יג טבת","dp":"ירושלים","b":"מחכמי ומראשי הקהלה בקלויזנבורג. ניצל מהשואה, ואחריה חזר לקלויזנבורג, עלה לירושלים והתישב בקטמון. חיבר \"זכור ואל תשכח\" ירושלים תשיז - ומספר גם על נסיונות ההצלה של האדמורים מסטמר ומקלויזנבורג."},{"i":22087,"n":"טעביל מרוטסוויילר","b":"אין פרטים."},{"i":22088,"n":"טעבן - משפחה","b":"משפחה ידועה בפרשבורג. מקור המשפחה בוינה, ומשם עברו לעיר טעבן(=טעהבן) שעל גבול אוסטריה הונגריה ומכאן מקור שמם, ומהם התישבו בפרשבורג. במשך כמה דורות היו מראשי ופרנסי קהלת פרשבורג."},{"i":22089,"n":"טעבן, אברהם אהרן מפרשבורג","b":"חתם על תקנות הח\"ק בפרשבורג-תקס."},{"i":22090,"n":"טעבן, אברהם דוד מפרשבורג","b":"מחכמי פרשבורג. חתם על תקנות ר מאיר ברבי-תקכח."},{"i":22091,"n":"טעבן, אברהם מנדל (יעקב) מפרש","f":"מנדל מפרשבורג?","k":"בעל מי באר","dt":"תקכח - י אדר","dp":"פרשבורג","b":"פרנס ושתדלן מחכמי פרשבורג-תצד. עסק במסחר. בניו - ר יעקב קופל מנדל (שויתר למען אביו על מקומו שהיה שמור לו בבית הקברות), ר מנחם מנדל."},{"i":22092,"n":"טעבן, אברהם מפרשבורג","b":"גביר עשיר. ראש הקהלה בפרשבורג והראשון שנשא בתואר הרשמי \"ראש מדינה\". חתנו - ר מרדכי איבשיץ בנו של ר יונתן איבשיץ. בזמן המחלוקת תמך בר יונתן וכנגדו תמך ר מנדל לייטסדורף (גיסו של עקיבא עמדן הזקן) בר יעקב עמדין - הדבר גרר מחלוקת גם בענין מינוי ר עקיבא איגר הזקן לראב\"ד בפרשבורג-תקיח."},{"i":22093,"n":"טעבן, אברהם משטמפן","f":"קויפמן","b":"מחכמי שטאמפי-תקו. בתו - פעסל וחתנו - ר שמואל ומהם משפחת פעסעלס בשטמפן."},{"i":22094,"n":"טעבן, בנימין וולף מפרשבורג","f":"הירש","bt":"תצג","dt":"תקסט - כו אדר","dp":"פרשבורג","b":"אחיינו של ר קופל טעבין?. מראשי קהלת פרשבורג. חתם על תקנות ר מאיר ברבי-תקכח, ומונה ע\"י ר מאיר בצוואתו לאפוטרופוס על נכסיו, הו\"ל חדושי מהר\"ם ברבי. מוהל במשך 55 שנה ורשם בפנקס מילה את קורותיו (מל גם את ר עקיבא איגר בפרשבורג). היה ראש המשלחת אצל הקיסר-תקמג בענין גזירת המלבושים וגילוח הזקן - והצליח לבטל את הגזירה (כך מופיע בפנקסו -בספרים מיוחס הדבר לקרובו ר קופל טעבן). נספד ע\"י החת\"ס. חתניו: ר משה ליב יפה ונכדו ר צבי הרש - המוהל, ר זלמן ליב גרינספלד-ראב\"ד קיצע. בין החותמים על תקנות ר משה לבוב בעניני השחיטה-תקטו - ואולי הוא חכם אחר באותו השם."},{"i":22095,"n":"טעבן, דוד מפרשבורג","f":"מנחם מנדל","k":"פרשבורג","dp":"תקפח - א אייר","b":"מחכמי פרשבורג."},{"i":22096,"n":"טעבן, יחיאל מפרשבורג","b":"חתם על תקנות הח\"ק בפרשבורג-תקס."},{"i":22097,"n":"טעבן, יעקב מפרשבורג","b":"מראשי קהלת פרשבורג. חתם על תקנות ר מאיר ברבי-תקכח."},{"i":22098,"n":"טעבן, יעקב צבי מפרשבורג","b":"מחכמי פרשבורג. בין החותמים על תקנות ר משה לבוב בעניני השחיטה-תקטו."},{"i":22099,"n":"טעבן, יעקב קופל מפרשבורג","f":"אברהם מפרשבורג","bt":"תצב","bp":"פרשבורג","dt":"תקנט - כה אב","dp":"פרג","b":"פרנס קהלת פרשבורג-תקלב, שתדלן ומנהיג במדינת הונגריה ונציגה בפני השלטונות. היה ראש המשלחת אצל הקיסר-תקמג בענין גזירת המלבושים וגילוח הזקן - והצליח לבטל את הגזירה, ובגזירת הגיוס-תקמז-ט (בהצלחה חלקית) במשלחת השתתפו גם ר יוסף דייטש מרויסניץ, אהרן לבוב מניקלשבורג, ור נפתלי רוזנטל ממאהר. השתתף במשלחת-תקנא יחד עם ר מרדכי בנט מניקלשבורג אצל הקיסר, נפטר מיד לאחר פגישתו האחרונה עם הקיסר שבה התמוטט מחמת התרגשותו. לתולדותיו גם ב\"קהלה מפוארה\" - גליון לדוגמא שהוציא ר שמואל בטלהיים בפרשבורג תרעג."},{"i":22100,"n":"טעבן, יצחק דב-דוד מפרשבורג","f":"הירש","b":"מחכמי פרשבורג. חתם על תקנות ר מאיר ברבי-תקכח, ותקנות הח\"ק תקכה."},{"i":22101,"n":"טעבן, ישכר בער מפרשבורג","f":"מרדכי מפרשבורג","bp":"פרשבורג","dt":"תקצח - בערך","b":"תלמיד החת\"ס. (ואינו ר מרדכי בן יחיאל טעבן שנפטר בפרשבורג תרב)."},{"i":22102,"n":"טעבן, מנדל מפרשבורג","f":"וולף","b":"מחכמי פרשבורג. חתם על כתב מנוי רבנות לחת\"ס-תקסז."},{"i":22103,"n":"טעבן, מנדל מפרשבורג - א","f":"דוד","b":"מחכמי פרשבורג. חתם על תקנות ר מאיר ברבי-תקכח."},{"i":22104,"n":"טעבן, מנדל מפרשבורג - ב","f":"דוד","dt":"תקסט - כב תשרי","dp":"פרשבורג","b":"מראשי קהלת פרשבורג-תקסז, חתם על כתב מנוי הרבנות לחת\"ס-תקסז."},{"i":22105,"n":"טעבן, מנחם מנדל מפרשבורג","f":"אברהם","dt":"תקפה - כו תשרי","dp":"פרשבורג","b":"מחכמי פרשבורג. יסד ביכנ\"ס ונקרא ע\"ש \"זיידענשוהל\". חתנו - ר יחיאל מיכל קיצע בעל \"שלמי נדבה\". הו\"ל ספר הישר לרבנו תם. אחיו של השתדלן ר יעקב קופל. נזכר עם אחיו ע\"י ר ישראל בעל \"אור חדש\" - המספר כיצד עזרו לו בשעת צרתו."},{"i":22106,"n":"טעבן, מרדכי מפרשבורג","b":"מקורב לחת\"ס בפרשבורג. אביו של ר ישכר בער - תלמיד החת\"ס."},{"i":22107,"n":"טעבן, שלמה מפרשבורג","f":"קופל","dt":"תקנה - ד שבט","dp":"פרשבורג","b":"מחכמי פרשבורג. חתם על תקנות הח\"ק-תקכה."},{"i":22108,"n":"טעוועל, צבי הירש מקראקא ונ\"י","k":"בעל ציון לנפש","b":"רב בקראקא, ניו יורק-תשיז."},{"i":22109,"n":"טערקעס, אלדי מצרפת","bt":"תקמב","bp":"מיץ-צרפת","dt":"תרכב","dp":"פאריס","b":"בקי בחשבון ומדעים, פרופסור במיינץ. בקי בחכמת ישראל, תרגם ספרי קדש לצרפתית, פרסם מאמרים בחכמת ישראל."},{"i":22110,"n":"טפט, יעקב צבי מרדלוב","f":"יואל","dp":"דומברובה","b":"רב בדומברובה. חתן ר עקיבא אפרים שטייגר."},{"i":22111,"n":"טפט, שלמה זלמן מקראקא","b":"גבאי בביהמ\"ד \"רבי אברהמלה - אנשי אמת\" בקראקא-תרצה."},{"i":22112,"n":"טפיך, יעקב הכהן מליזנסק","b":"הגיע מליזנסק וכיהן כרב ברוה-רוסקה."},{"i":22113,"n":"טפל, יוסף","f":"אריה","bt":"תרמד","bp":"שנדישוב","b":"חתן ר דוד שיף. רב בשנדישוב, ברלין. חיבר ספר תולדותיו - בכתב יד."},{"i":22114,"n":"טפליץ, ישראל זליג הלוי","f":"יהודה ליב","bt":"תרח","bp":"קרטגינה-פלך קובנא","b":"תלמיד דודיו-אחי אביו ר ליפא ור אליהו, ותלמיד ישיבת וילקומיר אצל ר ישראל נפתלי, קיבוץ לידא, איישישוק, וילנא. רב בשקוד-תרלה, ליבאווא(=ליבאו)-קורלנד-תרמב (והתפרנס ממסחר), היגר לארה\"ב וכיהן כרב בדולוטה-ארה\"ב-תרסה. נסמך מאת: ר מרדכי מלצר מלידא, ר בצלאל הכהן מוילנא, ר אליהו ברוך קומאי ממיר. בניו: דוד אליהו ושלמה צבי הירש משיקגו, חתנו - ר בן ציון אליטא מליבאווא."},{"i":22115,"n":"טפליצקי, יהודה יידל","f":"יעקב","bt":"תרב","b":"רב בואזנעסעסק-פלך חרסון-תרכט."},{"i":22116,"n":"טפליצקי, יצחק מואזענסענסק","f":"שלמה","k":"בעל קול צופיך","b":"רב בואזנעסענסק-פלך חרסון."},{"i":22117,"n":"טצרנצטאפקה, צבי אהרן","f":"חנוךהעניך טשרנצטשפקה","dt":"תרצ - כט תמוז","b":"רב בגאלין"},{"i":22118,"n":"טקלס, מרדכי","dt":"תקג - כו סיון","b":"ראב\"ד בברלין"},{"i":22119,"n":"טקסין מנחם צבי בן אריה","bt":"1850","dt":"ה'תרעח 1918","bk":[["אור תורה",""],["אורח חיים",""],["אורח ישרים",""],["אורח לצדיק",""],["אמונה ודעת",""],["הגיון לבר מצוה",""],["ידיעות הטבע שבתלמוד",""],["סדר הגדה של פסח נחלת צבי ילקוט מנחם",""],["עטרת חכמים",""],["עטרת צבי",""],["צבי תפארת",""]]},{"i":22120,"n":"טקסר, ישראל משה מטשארני","f":"גדליהו","k":"בעל פרי משה - כת\"י","bt":"תרכ","b":"מצאצאי ר זאב קיציס. תלמיד ישיבת מיר. רב בטשארנא(=טשארנע)-פלך חרסון-תרס. נסמך מאת ר יצחק אלחנן מקובנא, ר יוסף דב סולוביציק. חיבר שו\"ת ודרוש בשם \"פרי משה\" - בכת\"י."},{"i":22121,"n":"טראב מסלתון, אליהו","b":"דמשק-ת\"ר, חיבר \"ויעל אליהו\""},{"i":22122,"n":"טראב מסלתון, יהודה חיים","f":"עזרא","k":"בעל שארית יהודה","bt":"תרלב","bp":"דמשק","dt":"תשה - כח טבת","b":"דרשן,אב\"ד במצרים,חיבר \"שארית יהודה\"","bk":[["וזאת ליהודה","שו\"ת - אחרונים"],["שארית יהודה","שו\"ת"]]},{"i":22123,"n":"טראב מסלתון, מרדכי","f":"יוסף","k":"בעל דורש טוב","bt":"תרלו - יז שבט","bp":"דמשק","dt":"תשיט - כא אד\"א","b":"הגיע לניו יורק-תרף וכיהן כרב, יסד את חברת \"אחי-עזר\". בנו ר ציון הו\"ל \"דורש טוב\" מתורת אביו."},{"i":22124,"n":"טראב מסלתון, עזרא הכהן","f":"אליהו","k":"בעל ספר עזרא","bt":"תריא","bp":"דמשק","dt":"תרף - כח שבט","b":"רב בדמשק על מקום אביו. חיבר גם \"ויאמר עזרא\", ועוד. עלה לטבריה. בנו ר יהודה בעל \"ויאמר יהודה\".","bk":[["שערי עזרה","שו\"ת - אחרונים"]]},{"i":22125,"n":"טראב, יעקב הכהן מביירות","f":"יוסף","k":"בעל בית יעקב","b":"גדול בנגלה ונסתר,ראב\"ד בבירות(לבנון)"},{"i":22126,"n":"טראב, עזרא הכהן","f":"אליהו","k":"בעל מלי דעזרא"},{"i":22127,"n":"טראבולוס, דוד מירושלים","f":"צדיק","dt":"תרעא - ז אלול","dp":"ירושלים","b":"רב ביינישר, עלה לירושלים."},{"i":22128,"n":"טראבלוס, דוד","dt":"תרעא - ז אלול","b":"מרבני יינישר, עלה לירושלים"},{"i":22129,"n":"טראבלוס, צדיק מירושלים","b":"מחכמי ירושלים. נכדו של ר חיים אברהם גאגין (=אג\"ן)."},{"i":22130,"n":"טראבלסי, חיים","k":"בעל ראה חיים","dt":"תשלד - א אדר","dp":"צפת","b":"מחכמי הדיג'ת(תוניס),עלה לא\"י-תש\"ך,חיבר \"ראה חיים\" על הזוהר","bk":[["ראה חיים",""]]},{"i":22131,"n":"טראבסלי, יעקב מפטרץ","dt":"שמח - ז אדר","b":"גביר מראשי קהלת פטרץ. בנו - משה."},{"i":22132,"n":"טראטשר, אברהם דוד","b":"נכד הבעשט, ור מנחם נחום מטשרנוביל."},{"i":22133,"n":"טראך, אברהם משטמפן","f":"יצחק","bp":"שיטצען?","dt":"תקצא - ז ניסן","dp":"שטמפן","b":"חתן ר נתן מן אורהולץ משטמפן. מו\"צ בשטמפן. חתם-תקנג על מינוי ר שלום אולמן לרבה של שטמפן. בנו - ר יצחק נפטר בחיי אביו."},{"i":22134,"n":"טראך, יצחק משטמפן","f":"אברהם","bp":"שטמפן","dt":"תקע - כ אד\"א","dp":"שטמפן","b":"נכד(-אבי אמו) ר נתן מן אורהולץ משטמפן. מחכמי שטמפן. נפטר בחיי אביו."},{"i":22135,"n":"טראך, שמואל משה מפפד\"מ","b":"מראשי קהילת פפד\"מ-תקך, ונמנה על קבוצת הרבנים שמילאו את מקומו של ר יעקב יהושע בעל ה\"פני יהושע\"."},{"i":22136,"n":"טראנה, אפרים משלוניקי","dt":"שעז - יד אלול","dp":"שלוניקי","b":"נהרג ליד שלוניקי בדרכו מיריד דולייא-שפח עם רבים מישראל."},{"i":22137,"n":"טראנה, יהודה משלוניקי","dt":"שעז - יד אלול","dp":"שלוניקי","b":"מהרוגי דולייא."},{"i":22138,"n":"טראנטו, יום טוב","b":"מגדולי רבני קושטא,עלה לירושלים"},{"i":22139,"n":"טראנטו, משה מקושטא","dt":"תרמד","dp":"ירושלים","b":"גביר מחכמי קושטא, עלה לירושלים. נוסח מצבתו מאת ידידו הסופר בני\"ם."},{"i":22140,"n":"טראנפיל, מאיר מאושינגה","k":"בעל מאור קטון","b":"חיבר \"מאור קטון\" פיורדא."},{"i":22141,"n":"טראצינה, משה מפיררה","b":"רב בפיררה בזמן הרמ\"ע. תשובה ממנו ב\"פחד יצחק\". תשובה ממנו - בכת\"י שפב."},{"i":22142,"n":"טראצקי, אליהו דב מיוריעווקע","k":"בעל מאמר דבר הקרבנות","b":"רב ביוריעווקע-פלך יקטרינוסלב"},{"i":22143,"n":"טרב, אליהו הכהן מדמשק","b":"רב בדמשק-תר\"י"},{"i":22144,"n":"טרבוט, אברהם רפאל מירושלים","f":"עזריאל","b":"ראש ישיבה בפיזרו, עלה לירושלים-רפ. כתב מכתב לר אברהם מפירושא. לדעת פראוור \"לקורות אגרות ירושלמיות\" (ירושלים שנה א ג-ד). האגרת נכתבה בצפת בין רפב לרפג."},{"i":22145,"n":"טרבוט, בנימין","b":"מגדולי חכמי דורו-ש\"צ"},{"i":22146,"n":"טרבוט, יחיאל זאב מאיטליה - ב","f":"עזריאל (או נתנאל)","b":"רב באיטליה-שלד, ראש ישיבה באלמארקה-ש\"צ. חיבר שו\"ת. נכד ר יחיאל טארבוט צרפתי קולון, ונכדו של ר יוסף קולון מאיטליה."},{"i":22147,"n":"טרבוט, יחיאל מאיטליה ולוב - א","k":"בעל וראיתם - בכת\"י","dt":"שכט","dp":"כפר ידדר-ליד מצראתה-לוב","b":"נכד ותלמיד מהר\"י קולון מאיטליה. רב באיטליה, עבר ללוב וכיהן כרב במצראתה-לוב. נזכר אצל החיד\"א ונקרא בשם \"יחיאל טראבוטו צרפתי קולון\". חיבר שו\"ת \"וראיתם\" - בכת\"י."},{"i":22148,"n":"טרבוט, מנחם מאיטליה","f":"פרץ","b":"רב באיטליה בזמנו של הרא\"ם. בנו - ר פרץ."},{"i":22149,"n":"טרבוט, נתנאל מאיטליה","f":"לוי מירושלים","b":"מחכמי איטליה, הסכים על ספר האגור - נפולי רנא."},{"i":22150,"n":"טרבוט, נתנאל ממודנא","f":"בנימין","b":"רב במודנא-תכ. דודו של הרב אי\"ש ג\"ר. תשובה ממנו ב\"כנף רננים\", ו\"עפר יעקב\" וב\"דבר שמואל\" חתום עם ר יהודה פוייטי. מצאצאי ר יחיאל טרבוט."},{"i":22151,"n":"טרבוט, עזריאל מאיטליה","f":"יחיאל","dt":"שכט","b":"רב באסקולי-איטליה. מגדולי חכמי איטליה בדורו."},{"i":22152,"n":"טרבוט, פנחס מפיררה","f":"מנחם","b":"רב בפיררה בזמן ר יוסף פיס. נזכר ב\"פחד יצחק\" בדין חליצה והסכים על דברי ר ישמעאל חנינא."},{"i":22153,"n":"טרבוט, שמואל ממנטובה","dt":"תקצה","dp":"מנטובה?","b":"גביר במנטובה. לאחר פטירתו נדב סכום גדול להקמת חברת \"הכנסת כלה\" במנטובה (שפעלה גם בתרנז בזמן ר ישעיה הלוי)."},{"i":22154,"n":"טרבוטו צרפתי קולון, י","f":"בנימין טרבוטו","b":"מגדולי חכמי איטליה-שנת ש'"},{"i":22155,"n":"טרביטש, אפרים מפרשבורג","b":"מחכמי פרשבורג. חתם על כתב מנוי רבנות לחת\"ס-תקסז."},{"i":22156,"n":"טרביטש, חיים מפרשבורג","b":"דיין בפרשבורג. חתנו - ר חיים חזן מפרשבורג-חותנו של ר יהודה ליטש-רוזנבוים."},{"i":22157,"n":"טרביטש, יונתן מטימישואר","f":"יהודה","dt":"תקיח - יב שבט","b":"דיין ורב בטימישואר-תק על מקום ר יחונן בן ישעיה, וישב כדיין גם בקרלסבורג. נבחר לרב הכולל בטרנסילבניה-תקיב אך לבסוף לא קיבל את התפקיד."},{"i":22158,"n":"טרבסלי, נסים מג'רבה","k":"בעל אם הבנים שמחה","bp":"ג'רבא","dt":"תשנו - טז סיון","dp":"טבריה","b":"מחכמי ג'רבא, עלה לארץ וכיהן כרב במושב תלמים."},{"i":22159,"n":"טרגאן, אברהם מירושלים","dt":"תריב - יד תשרי","b":"רב בירושלים"},{"i":22160,"n":"טרגאן, בן ציון מירושלים","f":"יוסף רפאל","k":"בעל אלף בית","bt":"תרל","bp":"ירושלים","b":"תלמיד \"דורש ציון\" בירושלים, עבד בבית הדפוס של אליעזר בן יהודה. פרסם מאמרים בעתון \"ההשקפה\", רכש את בית הדפוס של בן יהודה יחד עם שלמה ישראל שיריזלי, ונסים מבורך, עבר לאלכסנדריה ועסק בהוראה."},{"i":22161,"n":"טרגאן, חיים דוד שבתי מירקדו","k":"חד\"ש - חיים דוד שבתי","dt":"תרנ","dp":"ירושלים","b":"מחכמי ירושלים, דיין בקהיר, חזר לירושלים."},{"i":22162,"n":"טרגאן, יוסף יחיאל מירושלים","f":"רפאל אפרים?","dt":"תקף - י חשון","dp":"ירושלים","b":"מחכמי ירושלים, דיין אצל ר יעקב משה עייאש, בשנת תקעד חתם על תקנת חלב גויים עם ר יקיר מרדכי גירון, חתם-תרי עם חכמי ישיבת \"מגן דוד\".. על מצבתו כתוב נפטר במבחר ימיו. אולי הוא החזן שנזכר ב\"זכרון ירושלים\"."},{"i":22163,"n":"טרגאן, יוסף מירושלים","b":"מחכמי ירושלים, בשליחות בקושטא-תפז עם ר ישראל מאיר מזרחי."},{"i":22164,"n":"טרגאן, יעקב","b":"חכם ומקובל. מתורתו ב\"עבודת ישראל\" לר ישראל קמחי. חיבר פירוש לתנ\"ך."},{"i":22165,"n":"טרגאן, רפאל אפרים מירושלים","dt":"תקמז - יג אדר","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":22166,"n":"טרגאנו, אלברט משלוניקי","b":"רופא בשלוניקי-תרס."},{"i":22167,"n":"טרדיאולה, דוד - הנכד","f":"שמואל","dt":"תג","dp":"ירושלים","b":"מחכמי ירושלים, מוזכר ב\"חרבות ירושלים\" כאחד מהסובלים מצרות אבן פארוך, הכניס עצמו במאסר במקום אביו ונפדה בכסף רב לאחר עינויים קשים, בשנת שפז נסע אביו ר שמואל לקושטא להשתדל להוריד את אבן פארוך מגדולתו והצליח בשליחותו."},{"i":22168,"n":"טרדיאולה, דוד מצפת","b":"סוחר בצפת. נזכר בשו\"ת מבי\"ט. אולי בנו - ר שמואל מירושלים, ונכדו ר דוד."},{"i":22169,"n":"טרדיאולה, משה","b":"מחכמי ירושלים, בשנת תכו בשליחות בצפון אפריקה."},{"i":22170,"n":"טרדיאולה, שמואל מירושלים","f":"דוד","b":"מחכמי ירושלים, בשנת שפה סבל מפרעות אבן פארוך, בשנת שפז בשליחות בקושטא להשתדל להוריד את הצורר אבן פארוך מגדולתו והצליח בשליחותו. בשנת שצא בשליחות באיטליה ואמשטרדם, התקבל כרב בקהילת \"בית ישראל\" וחזר לירושלים. בנו - ר דוד."},{"i":22171,"n":"טרדיה, יצחק משלוניקי וירושלים","b":"תלמיד ר מרדכי קלעי. מחכמי שלוניקי-שנות ה-ת', עלה לירושלים."},{"i":22172,"n":"טרדיול, יצחק יחיאל ממנטובה","b":"תשובה ממנו ב\"פלגי מים\" לאסור המקוה ברוויגו-שסו."},{"i":22173,"n":"טרוג'אס, משה מסידרוקאפסי","bp":"שלוניקי","b":"גביר בסידרוקאפסי-תורכיה, תרם לת\"ת בשלוניקי - שמא."},{"i":22174,"n":"טרוויש, אבא יוסף הכהן מוולקניק","f":"עוזר מוילנא","k":"בעל חבל יוסף","dt":"תרג","b":"תלמיד ר מרדכי מלצר מלידא. חתן ר פסח הכהן מסמרגון. דרשן ורב בוולקניק(=אלקניק)-פלך וילנא. חיבר גם \"כערכך הכהן\" והוא הספד על ר בצלאל הכהן מוילנא. סייע לרבו בהוצאת ספרו \"תכלת מרדכי\". אחיו - ר הלל דוד מוילקי בעל \"ונגש הכהן\"."},{"i":22175,"n":"טרוויש, אברהם דוד משה מרוהטין","k":"אד\"מ","b":"רב ברוהאטין-ת\"ק. חיבר \"מרכבת המשנה\"."},{"i":22176,"n":"טרוויש, אברהם מאיטליה","b":"נכד ר יוסף טרוויש. מחכמי סוראז-איטליה. נזכר בשו\"ת מהרי\"ק."},{"i":22177,"n":"טרוויש, אברהם משלוניקי וצפת","f":"שלמה","k":"בעל ברכת אברהם","bt":"רל","bp":"מנטובה","dt":"רצה","b":"מצאצאי רש\"י שגלו מצרפת לאיטליה-סו, קרובו של הרא\"ם (גם הוא מצאצאי רש\"י). מחכמי איטליה, מלמד ברוביקה-ליד פיררה, התישב באישקופיה-רסה ולימד שם תורה, רב בשלוניקי, אדרינופול, היה רב בסופיה וניצל בנס בשנת רסה, ואלונה(=אבילונא)-אלבניה, אישקופיה-רסה, קושטא והיה מקורב לשר משה המון הרופא שאף למד אצלו ובביתו חיבר את ספרו \"ברכת אברהם\"-רפד - נדפס בונציה שיב. בערוב ימיו עלה לצפת ואחר כך לירושלים ועסק ברפואה. חלופי אגרות ותשובות בינו לבין רבים מגדולי דורו (וביניהם ר יוסף קארו, ר אליהו מזרחי ועוד). בניו: ר שלמה - נפטר בחיי אביו, ר יוסף, ר חזקיה. ספרו היה כנראה הראשון שנדפס עם הסכמות. היה מתומכי ר שלמה מולכו."},{"i":22178,"n":"טרוויש, אברהם צרפתי","f":"גרשון","k":"בעל פירוש למערכת האל","b":"מקובל, תלמיד ר שלמה מולכו. חיבר פירוש על \"מערכת האלקות\" לרבינו פרץ, והגהות על פירוש ר יאודה חייט - בכת\"י, הגהות על \"שערי אורה\" - ד ניסן שלב."},{"i":22179,"n":"טרוויש, אהרן אליעזר ליזר","b":"תלמיד ר יהודה אסאד. רשם את חדושי רבו."},{"i":22180,"n":"טרוויש, אליעזר מאלזאס","f":"שמואל בן יוסף","b":"מצאצאי ר מתתיהו טרוויש. רב בשלעטשטט בעלזאס-רמ. חיבר פירוש על \"שערי דורא\" - בכת\"י, ונזכר בשו\"ת מהר\"ם מינץ. יש אומרים כי היה רב באיטליה ולא באלזס. בנו - ר נפתלי הרץ. חתניו (כנראה) ר מנוח אבי ר אליעזר מוורמייזא, ר משה עבערליס מקראקא-בנו של ר עבער אלטשולר מפרג."},{"i":22181,"n":"טרוויש, אליעזר מקראקא ופפד\"מ","f":"נפתלי בעל נפתולי אלק","k":"בעל יסוד שירים","bt":"רנה","dt":"שכג-ז - בערך","b":"נכד ר אליעזר מעטשטאט(=שלעטשטט). חתן משפחת טויסקי מפרג. עסק במסחר עם דודו-בעל אחות אביו-הגביר ר משה עבערלס והגיע לקראקא. מגדולי חכמי דורו, קרוב למלכות ומונה ע\"י המלך פרדיננד כאחד מ-3 הרבנים שאחראים לבחירת פרנסים ורבנים בפרג-שיח, ר\"מ בקראקא-רצא, ראש ישיבה ורב בפפד\"מ-שה על מקום אביו, ור אברהם נפתלי הרץ הלוי על מקומו אחריו. תשובה ממנו בשו\"ת הרמ\"א אודות המחלוקת בין ר שמעון גינצבורג ושותפו ר נתן שאטן הכהן ותמך בר נתן כנגד ר יצחק איזיק מגינצבורג ורוב החכמים שתמכו בר שמעון. נתבקש ע\"י ר יוחנן בן יוסף טריווש-רבה של ונציה, לחוות דעתו במחלוקת הגט מפרג. מתלמידיו ר דוד גנץ בעל \"צמח דוד\". חתנו ר העלמן (אחיו של ר בצלאל-אבי המהר\"ל). חתם על פסק דין בפפד\"מ-שכד."},{"i":22182,"n":"טרוויש, בנימין מארטה-יון","f":"מתתיהו או בנימין","k":"בעל בנימין זאב","bt":"רמה","bp":"פאדובה","dt":"שטו","b":"מצאצאי ר יוחנן רבה של צרפת-קנה, תלמיד ישיבות איטליה אצל ר יהודה מינץ, ור נתן., מחכמי ונציה, הגיע עם אביו לארטא, וכיהן כראש קהלת קורפו בארטא, קורפו-רץ (אולי הכוונה לקהלת קורפו בארטא), ונציה-רצא, חזר לארטא-רצח. מגדולי הפוסקים, אב\"ד ארטא-יון, טריקולה-רצט, ועוד קהילות ביון. חיבר \"שו\"ת בנימין זאב\", הרבה מהתשובות בעניני מסחר ועגינות, חתנו ר שמואל קלעי מארטא. התיר עגונה עם חבריו ר אברהם בן מנחם רוסו, ושבתי בן משה, ועל כך היה מחלוקת כנגדו מר דוד הכהן-מהרד\"ך, וכמה מגדולי הדור ובהם ר יוסף טאיטצק הצדיקו את ר בנימין."},{"i":22183,"n":"טרוויש, דב בר מזאגר ווילנא","f":"יהודה טריווש","k":"בעל רביד הזהב","bt":"תפד","bp":"וילנא","dt":"תקסד - כא תשרי","b":"אב\"ד זאגר, דיין ורב בוילנא ור אבלי מפוסבול(=פאסוואהל) על מקומו אחריו. חיבר גם \"שיר חדש\"."},{"i":22184,"n":"טרוויש, הירש נפתלי","k":"בעל הדרת קדש","b":"חיבר ביאור לתפלה בשם \"הדרת קדש\"."},{"i":22185,"n":"טרוויש, הלל דוד הכהן מווילקי","f":"עוזר מוילנא","k":"בעל ונגש הכהן","bt":"תרא","bp":"וילנא","dt":"תרסא - ד סיון","dp":"ווילקי","b":"רב בווילקי-תרלב, עורך עתון \"הפסגה\"-תרנה וחתנו ר אברהם זקהיים עוזר לצדו, בהשתתפות ר אברהם זקהיים. פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן, ועוד. עורך \"הפסגה\" - וילנא-וארשא-פיעטרקוב תרנה. בנו ר קלמן רב בנ\"י."},{"i":22186,"n":"טרוויש, זאב וולף מוילנא","f":"יעקב","b":"דיין בוילנא, חתם-תקח עם הראב\"ד ר יהושע השל."},{"i":22187,"n":"טרוויש, חיים מדורינבורג","b":"מגדולי חכמי אשכנז,רב בדורינבורג-ש\"ל"},{"i":22188,"n":"טרוויש, חיים מפרשבורג","b":"ראב\"ד בפרשבורג"},{"i":22189,"n":"טרוויש, חנוך זונדל מוילנא","f":"יצחק מקופישוק","dt":"תקעב - טז אלול","dp":"וילנא","b":"חתנו של ר אריה ליב גינצבורג המכונה ר ליב כתבן מוילנא. גיסו של ר חיים מוולוזין. גילה את רמאות החסידים שעברו בקהילות גרמניה ואמרו שהגר\"א התחרט על רדפו את החסידות."},{"i":22190,"n":"טרוויש, יהודה משאדעווע","f":"יצחק מקופישוק","b":"רב בשאדעווע(=סאדווע)-תק. בנו ר דב בער בעל רביד הזהב."},{"i":22191,"n":"טרוויש, יהונתן מטימישואר","b":"רב בטעמעשוואר-ת\"ק"},{"i":22192,"n":"טרוויש, יוחנן מפיררה","f":"יוסף","k":"בעל קמחא דאבישונא","bt":"רנ","dt":"שיז","b":"מגדולי חכמי איטליה. רב בפירארה, מודנא, מגיה בונציה - הגיה את השאלתות, המכילתא, ספרי, ועוד. נזכר אצל ר שלמה עתיה בהקדמת פירושו לתהלים. חיבר \"קמחא דאבישונא\". אולי הוא המחבר \"זבחי צדק\" על הלכות שחיטות למרדכי. תשובה ממנו בשו\"ת מהרמא\"י - משנת ש\"י, להגן על הרב מ\"ן מהביקורת כנגדו על ענין גט."},{"i":22193,"n":"טרוויש, יוחנן מצרפת","f":"מתתיהו","dt":"קפט - ט אב","b":"מגדולי רבני צרפת הקדמונים, רב בפריס על מקום אביו ומדינת צרפת בהסכמת המלך. היה במחלוקת עם ר ישעה אשטרוק בן אבא מארי (תלמיד אביו) שהקים ישיבה ללא רשותו בצרפת (בהסכמת ר מאיר בן ברוך הלוי מאשכנז) ור יוחנן פנה לרבני ספרד ובהם הריב\"ש לבטל את סמיכת ר ישעיה. לאחר גירוש צרפת-קנה יצא לאיטליה ונזכר שם אצל ר משה בן יצחק די ריאטי ב\"מקדש מעט\". בנו - ר יוסף שהיה דור 13 לרבנות."},{"i":22194,"n":"טרוויש, יוסף","f":"מתתיהו טריוש","dt":"קנא","b":"מגדולי התורה בזמנו"},{"i":22195,"n":"טרוויש, יוסף אליהו","k":"בעל דין וחשבון","bt":"1855","bp":"וילנא","dt":"1940","dp":"וילנא","b":"פרסם ב\"השחר\", \"המליץ\", \"השלוח\", ועוד. תרגם ספרים לעברית. חיבר גם \"מקרא מפורש\", ועוד."},{"i":22196,"n":"טרוויש, יוסף יוזל מפרנקפורט","b":"רב בפפד\"מ"},{"i":22197,"n":"טרוויש, יוסף מירושלים","b":"מחכמי ירושלים, בשנת תקא חתם על כתב שליחות ר אברהם בן אשר ור יצחק זרחיה אזולאי."},{"i":22198,"n":"טרוויש, יוסף ממרסיליא","f":"יוחנן","k":"ר' יוסף טריוש הגדול","bt":"סה","b":"מצאצאי ר יהודה מפאריס. רב במרסיליא-צרפת-ה'קג. נזכר אצל הריב\"ש, הרשב\"ץ. בנו - ר מתתיהו מפאריס."},{"i":22199,"n":"טרוויש, יוסף מסאבילייאנו","b":"רב בסאבילייאנו. תשובה ממנו ב\"נחלת יעקב\"."},{"i":22200,"n":"טרוויש, יעקב חיים מפרשבורג","f":"אפרים הלוי","b":"מחכמי פרשבורג. מחותמי החרם-תקיא כנגד מוציאי לעז על ר יונתן איבשיץ."},{"i":22201,"n":"טרוויש, יצחק","b":"תלמיד ר אליעזר אשכנזי - והו\"ל את ספרו \"מעשי השם\" וכתב לו הקדמה."},{"i":22202,"n":"טרוויש, יצחק גרשון מצפת ונציה","f":"מרדכי גרשון","k":"בעל שלום אסתר","bt":"שלב","bp":"צפת","dt":"תז - אחרי","dp":"צפת","b":"תלמיד ר יוסף קארו ור משה אלשיך בצפת, עבר לקושטא ואח\"כ לאיטליה-של והתישב באנקונה, רב בונציה-שך לצד ר אביגדור ציווידאל ומראשי ישיבת בית הכנסת הגדולה, ומגיה ראשי בדפוס ונציה. מתלמידיו ר נתנאל טרבוט ממודנא. עסק בהדפסת ספרים ובהגהה בדפוס ונציה. חזר לצפת-שפו או תו, ועל מקומו בונציה כיהן ר יהודה אריה ממודנא. תשובות ממנו ב\"נחלת יעקב\" לר יעקב אלפרון, ובשות מהריט\"ץ ועוד. חיבר \"שלום אסתר\", ועוד. חתם ראשון בגזרת רבני ונציה כמובא בשו\"ת מהר\"ם ריקנטי האחרון. נזכר בשו\"ת מהרי\"ט"},{"i":22203,"n":"טרוויש, יצחק מקופישוק","f":"שניאור מפפד\"מ","b":"רב בקופישוק-תע. בניו ר יהודה ר נחום, ר חנוך זונדל."},{"i":22204,"n":"טרוויש, ישראל חזקיה מפדובה","b":"תלמיד הרמח\"ל. דיין אצל ר יעקב חזק בפדובה."},{"i":22205,"n":"טרוויש, מאיר מהרם מאויבן","bt":"תקעג","bp":"לאשברין","dt":"תרמו - כו תשרי","dp":"אויבן","b":"תלמיד החת\"ס. חתן ר רפאל אהרן קנפלר מטיניע ועבר לשם, ובזיוו\"ש חתן ר יוסף דב רבנוורצל מאויבן. רב באויבן ובפעסט. ממיסדי ארגון הקהלות האורטודוכסיות בארץ הגר ועמד בראשו."},{"i":22206,"n":"טרוויש, מנחם אליקום משולם מויל","f":"יחיאל","b":"רב בוילנא, שאל-שיז את המהרש\"ל."},{"i":22207,"n":"טרוויש, מנחם מזלצבורג","k":"בעל אורח מישרים","b":"רב בזולצברג-תר\"י"},{"i":22208,"n":"טרוויש, מרדכי מוילנא","f":"שניאור שו\"ב","k":"בעל תשועת עולמים-כתי","dt":"תקצט - כד אייר","dp":"וילנא","b":"חתן ר יחיאל בעה\"ק. מורה בבית הגביר ר הרש קלצקי בוילנא. חיבר שיר חזיון בשם \"תשועת עולמים\". מקורב לחכמי וילנא. נפטר צעיר בן 25. מאמרים ממנו ב\"הכרמל\" ועוד ובהם \"החנוטים יהוידע והראה\", ועוד. (לתולדות משפחת טרוויש - ד\"ר בריל - יאהרבוך, פפד\"מ 1876)."},{"i":22209,"n":"טרוויש, משה מאיפסולה","f":"יעקב","b":"רב באיפסולה-שנות ה-ת'."},{"i":22210,"n":"טרוויש, משה מונציה","b":"רב בונציה בזמן הרמ\"ז, ומלמד בישיבת ר יום טוב ואלהאוזן. תשובה אליו ב\"דבר שמואל\". אחד משבעת הרבנים שנשלחו לבדוק את נתן העזתי."},{"i":22211,"n":"טרוויש, מתתיהו מפאריס","f":"יוסף ממרסיליא","b":"מרביץ תורה, רב הכולל של פאריס וצרפת-קכ-קמה. חתנו - ר שמואל שפירא משפיירא."},{"i":22212,"n":"טרוויש, נחום (מנחם) מניקלשבורג","k":"בעל שלום ירושלים","bt":"תקלט","bp":"פרג","dt":"תרב-ל - כז תמוז","dp":"ניקלשבורג?","b":"רב בפרוסטיץ-תקפו, ניקלשבורג והמדינה-תקץ. חיבר גם \"קובץ\" על הרמב\"ם, שו\"ת ר נחום טריביטש. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":22213,"n":"טרוויש, נחום מוילנא","f":"יצחק","b":"ראב\"ד בוילנא-תקמא."},{"i":22214,"n":"טרוויש, נפתלי הרץ מפפד\"מ","f":"אליעזר מאלטשטט-אלזס","k":"בעל נפתולי אלקים","dt":"רצא - שטז","b":"מקובל, ש\"ץ ואב\"ד בפפד\"מ-רס ובנו ר אליעזר על מקומו אחריו. חיבר פירוש בדרך הקבלה על התפילות - טיהנגן שך (ומשם נראה שהיה ממאמיני ר שלמה מולכו ודוד הראובני וחשב שהגאולה קרובה לבוא), חיבר ביאור לפירוש התורה של רבנו בחיי. אבי המשפחות - טריבש(=טרוויש), דרייפוס, טרעפעס, צבי (אחד מבניו שעבר לפולין קרא לעצמו הירש ע\"ש אביו הירץ ומכאן בהמשך צבי)."},{"i":22215,"n":"טרוויש, צבי הירש מירושלים","f":"זאב וולף","b":"דיין בוילנא-תקמב, מחכמי ירושלים, (אולי הוא שנזכר אצל ר אברהם דנציג ב\"שערי צדק\" - שעלה לירושלים עם ר סעדיה."},{"i":22216,"n":"טרוויש, קלמן מוילקי","b":"רב בוילקי. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז."},{"i":22217,"n":"טרוויש, קלמן מנ\"י","f":"הלל דוד מווילקי","k":"בעל בעקבות הפסגה","bt":"תרמב","dt":"תשיא","dp":"ניו יורק","b":"רב באסטוריה-ארה\"ב-תרע."},{"i":22218,"n":"טרוויש, רפאל אורי מקסאלי","b":"מחכמי קסאלי, חתם-תעו על פסק דין."},{"i":22219,"n":"טרוויש, רפאל יוסף מפיררה","f":"יוחנן","b":"רב בפיררה -שמ - בזמן ר משה פרובנצאל. תשובה ממנו ב\"פחד יצחק\"-שלג. תשובה ממנו בכת\"י - בענין חכירת מכס עם נוכרים וחלוקת שכר שבת."},{"i":22220,"n":"טרוויש, רפאל מירושלים","f":"ברוך","k":"בעל צח ואדום","r":"רב בויקנא וראב\"ד טשרנוביץ","dt":"תקלג - ט אלול","dp":"ירושלים","b":"תלמיד ר אליהו הכהן בעל \"שבט מוסר\". מחכמי ירושלים, עלה לפני שנת תק, היה ממשפחת ר אברהם צרפתי בעל \"ברכת אברהם\". החיד\"א מביא ממנו בספריו שמועות ששמע ממנו כשלמד אצלו בילדותו. חיבר \"צח ואדום\" קושטא תק, \"דגול מרבבה\". (בארזי הלבנון תאריך פטירתו ג אב תקה).","bk":[["צח ואדום",""]]},{"i":22221,"n":"טרוויש, רפאל מקושטא","b":"מדפיס בקושטא עם שותפיו יהושע מזרחי ויוסף אלקלעי, הדפיסו \"חדושי גטין\"-תעא."},{"i":22222,"n":"טרוויש, שמואל חזקיה מפדובה","f":"מיכאל","b":"מחכמי פדובה, מבני החבורה של הרמח\"ל."},{"i":22223,"n":"טרוויש, שמעון מפפד\"מ","f":"שניאור מפפד\"מ","b":"סו\"ד בפפד\"מ-תס. בנו - ר יהודה טיקטין בעל באר היטב."},{"i":22224,"n":"טרוויש, שמעון מפרשבורג","dt":"תקסא - טז ניסן","b":"דיין בפרשבורג-תקכח אצל ר מאיר ברבי."},{"i":22225,"n":"טרוויש, שניאור מפרנקפורט","f":"יוסף יוזל מפפד\"מ","b":"מחכמי פרנקפורט-תך. בניו - ר יצחק מקופישוק, ר שמעון מפפד\"מ."},{"i":22226,"n":"טרוויש-צרפתי, אברהם משלוניקי","dt":"שי - יב ניסן","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":22227,"n":"טרוטיל, שלמה מספרד","dt":"רנג","b":"מחכמי ספרד, תלמיד ר יצחק קנפנטון."},{"i":22228,"n":"טרוטנר, אברהם מטירנוי","b":"תלמיד ר שמואל דוד אונגר בישיבת טירנוי. פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי, \"משא ומתן\" - טירנוי תרצא."},{"i":22229,"n":"טרוי, יצחק מסמבור - א","f":"[צדוק]","b":"רב בסמבור-תרלה."},{"i":22230,"n":"טרוי, יצחק מסמבור - ב","b":"ראב\"ד בסמבור-תר\"ס"},{"i":22231,"n":"טרויא, יצחק משלוניקי","b":"מחכמי שלוניקי-סוף שנות ה-ש', עלה לירושלים."},{"i":22232,"n":"טרויב, אברהם שמעון מקידאן","f":"יצחק איזיק מקידאן","k":"בעל באר אברהם","r":"רב בקיידאן","bt":"תקעא-ה","bp":"קידאן","dt":"תרלד - כח טבת","dp":"קידאן","b":"נכד(-אבי אמו) ר ישראל גורדון מוילנא. חתן ר בנימין זאב טרויב משאוולי שעזב בגלל מחלוקת והתיישב ליד חתנו בקידאן, לא רצו להתפרנס מרבנות ולכן רכשו אחוזה בשם \"ראדיק\" ליד אוטיאן וניהלו את המשק כשהם עטופים בטלית ותפלין. אולם לבסוף נאלץ לפנות לרבנות וכיהן כרב בקידאן על מקום ר רפאל יו\"ט ליפמן הלפרין בעל \"עונג יו\"ט, ובנו ר זלמן על מקומו אחריו. נחשב למומחה בדיני ממונות והוזמן כבורר בדינים מסובכים, עזר לזקנו שכיהן כרב בוילנא. פרסם מאמרים בעתונות וכתב כנגד יל\"ג בענין התקונים בדת. הניח חדושים בכת\"י.","bk":[["באר אברהם","מפרשי רמב\"ם"],["באר אברהם – רמב\"ם",""],["הגהות וחידושי רבי אברהם שמעון טויב - על הבה\"ג -",""]]},{"i":22233,"n":"טרויב, אריה ליב מבויסק","f":"זלמן שמחה טרויב","b":"חתן ר יחזקאל רבינר מבויסק. רב בבויסק-תרמ."},{"i":22234,"n":"טרויב, בנימין וולף ממגנצא ופפד","f":"אלכסנדר","dt":"תעב - כה אב","dp":"פפד\"מ","b":"מחכמי פפד\"מ. רב במגנצא."},{"i":22235,"n":"טרויב, בנימין זאב משאוויל","dt":"תרכט","dp":"קידאן","b":"אב\"ד שאוויל, עבר לקידאן. הסכים על ש\"ס סלאויטה-תקצה, נזכר ב\"זכרון יעקב\" שאלה ממנו לר יעקב בנדטמן מבויסק. חתנו - אחיינו ר אברהם שמעון טרויב מקידאן."},{"i":22236,"n":"טרויב, דוד מפפד\"מ","f":"אלכסנדר","dt":"תקכד - ז כסלו","dp":"פפד\"מ","b":"מחכמי פפד\"מ."},{"i":22237,"n":"טרויב, זלמן","f":"מאיר","bt":"1896","bp":"פוניבז","dt":"1965","dp":"חיפה","b":"עסקן ציבור. מזכיר מערכת \"ייאוורייס, מזכיר הועד הציוני של גליל מוסקבה. מנהל \"תרבות\" בליטא-1922. ציר בקונגרס הציוני. עלה לארץ-1936."},{"i":22238,"n":"טרויב, זלמן שמחה מקידאן","f":"אברהם שמעון מקידאן","bt":"תקץ","dt":"תרעא","b":"היה בקי גם במדעים מתמטיקה ושפות. רב בקרוק-מחוז קידאן-תרלב, ועוזר לאביו הרב בקידאן, רב בקידאן-תרלד על מקום אביו. בנו ר אריה ליב."},{"i":22239,"n":"טרויב, חיים מאיר הכהן מדלטין","f":"אברהם הכהן","bt":"תקכ","bp":"דלטין","dt":"תרב - יג כסלו","b":"חתן ר מרדכי שטרן מסלישט. דיין ורב בסיגט-תקנד, דילאטין-גליציה-תקס."},{"i":22240,"n":"טרויב, יצחק איזיק מקידאן - א","f":"כתריאל","k":"בעל גאון עולם","b":"מחכמי קידאן-תקנח. חיבר \"גאון עולם\" ובו הספד על הגר\"א, \"יקרא דשכבי\" ובו הספד על אביו ואמו. ירש את דודיו(-אחי אביו) ר סנדר, ר ליב מינדן מהמבורג."},{"i":22241,"n":"טרויב, יצחק איזיק מקידאן - ב","f":"שלמה זלמן מקידאן","b":"מחכמי קידאן. בניו - ר אברהם שמעון-אב\"ד קידאן, ר משה כתריאל מלודז."},{"i":22242,"n":"טרויב, ישראל מיכל","bt":"1858","bp":"קיידאן","dt":"1926","dp":"ברלין","b":"נכד ר אברהם שמעון טרויב, ור אבלי מפוסוואל. תלמיד ישיבות ליטא. פרסם מאמרים ב\"המליץ\", \"המגיד\". היגר לדרום אפריקה, והו\"ל \"הכוכב\"-1903. חזר לרוסיה והתישב בטלז."},{"i":22243,"n":"טרויב, מאיר הכהן מקאליש","b":"פרסם מאמרים ב\"חדרי תורה\" - קראקא תרפו."},{"i":22244,"n":"טרויב, משה כתריאל מלודז","f":"יצחק איזיק מקידאן","dt":"תרם","b":"מחכמי לודז. אחיו - ר אברהם שמעון מקידאן."},{"i":22245,"n":"טרויב, צבי הירש","f":"מאיר ממנהיים","b":"הסכים על \"מקור חיים\" תריט (אולי המסכים הוא אביו)."},{"i":22246,"n":"טרויב, שלמה זלמן מקידאן - א","f":"כתריאל מקידאן","b":"מחכמי קידאן. בנו - ר יצחק איזיק. אחיו - ר יצחק איזיק בעל \"גאון עולם\"."},{"i":22247,"n":"טרויב, שלמה זלמן מקידאן - ב","b":"פרסם מאמרים ב\"ישורון\" - ברלין תרף."},{"i":22248,"n":"טרויב-וייל, אברהם מאלטונא","f":"אלכסנדר סנדר","dt":"תקם - יב כסלו","dp":"אלטונא","b":"תלמיד ר יונתן איבשיץ בפרג, ממנהיגי קהלת אלטונא. ר יונתן הביאו להעיד שעוד בהיותו בפרג החרים בכתב את השבתאים."},{"i":22249,"n":"טרויבע, אברהם אבלי חריף מקאליש","f":"יחיאל מיכל הכהן מלוס","bt":"תצח","bp":"לוסק","dt":"תקסט - טו שבט","dp":"קאליש","b":"חתן דודו-אחי אביו - ר בנימין זאב וולף הכהן מלוסק. נכד ר איצק גאלדעס, ור אברהם אבלי. רב בקאליש-תקכז - 42 שנה (בהמלצת ר ישראל יונה לנדא בעל \"מעון הברכות\"). הסכים על ספר קרובו ר אלעזר \"שמן רוקח\" - תקמח, \"מגדנות אלעזר\" - תקנב. בניו - ר בנימין וולף, ר איצק, חתנו - ר שלמה זלמן מקלעטשעוו וזלוטשוב."},{"i":22250,"n":"טרויבע, אפרים מקראקא","f":"אליהו","bt":"תרפג","bp":"קראקא","b":"חסיד בלז ותלמיד ר מיכלה זולקוור בבלז. ניצל מהשואה ועלה לארץ-תשו, משמש האדמור מבלז. חתן ר יצחק איזיק מנהיים."},{"i":22251,"n":"טרויבע, חיים יחיאל מקאליש","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":22252,"n":"טרויגט, אברהם ליבר הכהן מטורנא","b":"רב בטורנא, חתן ר יעקב צבי יולס בעל \"מלא הרועים\". הוציא לאור את ספרי חותנו."},{"i":22253,"n":"טרוימן, אברהם מקליש וברסלוי","f":"טוביה","k":"בעל ברכת אברהם","b":"נכד-אבי אמו ר נפתלי צבי מקליש. מחכמי ברסלוי. חיבר גם \"חסד לאברהם\"."},{"i":22254,"n":"טרוכנובסקי, אברהם זאב מסלאוטיץ","b":"רב בסלאוטיץ? חתן ר דוד ניימארק מבריסק-גיסו של \"הגדול ממינסק\". פרסם מאמרים ב\"קול תורה\" - וארשא תרסח."},{"i":22255,"n":"טרולינגן, אפרים העדלן מאיטליה","b":"רב באיטליה בזמן ר יעקב אלפרון מפדובה. תשובה ממנו ב\"נחלת יעקב\" -בענין זמני כניסת שבת - משנת שמו."},{"i":22256,"n":"טרונהים, נחמיה מנחם בריעה","k":"הו\"ל אהל ישכר","b":"נכד ר ישכר דב טורנהים מואלברז. מחכמי לובלין. הו\"ל ספר זקנו \"אהל ישכר\" - לובלין תרצג."},{"i":22257,"n":"טרונק, בנימין בינוש","f":"משה יהודה טרונק","b":"רב בוויערשאב"},{"i":22258,"n":"טרונק, חיים יעקב נפתלי","f":"בנימין בינוש טרונק"},{"i":22259,"n":"טרונק, יחיאל ישעיה מארה\"ב","k":"בעל בלעטער אויפן וינ"},{"i":22260,"n":"טרונק, יצחק יהודה מקוטנא","f":"משה פנחס מקוטנא","k":"בעל מעט צרי","bt":"תרמ","dt":"תרצט - כז אדר","b":"חתן ר שמואל בורשטין בעל \"שם משמואל\". נואם, מרביץ תורה, רב בלובראניץ-פלך וארשא, טשכנוב(=טשעכאנאווא)-פלך פלאצק, קוטנא-תרעב וגיסו ר אברהם מקוטנא על מקומו אחריו. פרסם מאמרים ב\"אור המאיר\" - וארשא תרצו, \"בית אברהם\" - וארשא תרצד, \"בית המדרש החדש\" - גריבה תרפח, \"יגדיל תורה\" - פראגא-וארשא תרפז, \"קובץ דרושים\" - פיעטרקוב תרפג, \"התפוח\" - בנדין תרפח. מקורב למזרחי - והיה מחלוקת בינו לבין חותנו על כך.","bk":[["חסדי אבות [שו\"ת וקונטרסים]",""],["מעט צרי – עהרמב\"ם",""],["מקרא מפורש – עה\"ת",""]]},{"i":22261,"n":"טרונק, ישראל אליהו יהושע מקוטנ","f":"דוד מפלוצק","k":"בעל ישועות ישראל","r":"אב\"ד קוטנא","bt":"תקפא","dt":"תרנג - כה תמוז","b":"חתן ר חיים ליפשיץ מפלוצק. רב בשרנסק-תר, גמבין-תרז, וארקא-תרי, פולטוסק-תריג, קוטנא-תרכא. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה תרנג. מתורתו ב\"כרם בית שמואל\" - פיעטרקוב תרצא, \"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט, \"מציון תצא תורה\" - זאמושט תרפט, \"שערי תורה\" - וארשא תרסג. (שמו המלא ישראל אליהו יהושע - ע\"ש הבעש\"ט, הגר\"א ובעל פני יהושע, נהג לחתום ישראליהושע בלי רווח וכך השם האמצעי אליהו מופיע אף הוא בחתימה).","bk":[["ישועות מלכו","שו\"ת - אחרונים"],["ישועות ישראל הקדמה","מפרשי שו\"ע"],["ישועות ישראל חוקת המשפט","מפרשי שו\"ע"],["ישועות ישראל עין משפט","מפרשי שו\"ע"],["ישועות מלכו","מפרשי רמב\"ם"],["יבין דעת – יו\"ד ושו\"ת",""],["ישועות ישראל – חו\"מ",""],["ישועות מלכו – שו\"ת",""],["ישועות מלכו (ר\"י מקוטנא)",""],["יבין דעת",""],["ישועות ישראל",""]]},{"i":22262,"n":"טרונק, משה פנחס מקוטנא","f":"ישראל יהושע מקוטנא","bt":"תריד","dt":"תרעב - כד אייר","b":"רב בוויסקיט-תרנא, קוטנא-פלך וארשא-תרנג על מקום אביו."},{"i":22263,"n":"טרופ, אברהם חיים יוסף מראדין","f":"נפתלי צבי מראדין","bt":"תרנז","bp":"יאנישוק-ליטא","b":"תלמיד ישיבת ראדין. חתן ר יעקב משה סרטוב מסרטוב ופתח תקוה. ר\"מ בישיבת ראדין-תרץ על מקום אביו, גלה עם הישיבה לאיישישוק-תש ווילנא, אוטיאן-ליטא, נאסר ע\"י הרוסים ושוחרר אחרי שנתיים, עבר לסמרקנד עם משפחתו, הגיע ללודז-תשו, היגר לארה\"ב-תשז וכיהן כראש ישיבה בישיבת \"רבי יצחק אלחנן\" (או \"חפץ חיים\") בניו יורק."},{"i":22264,"n":"טרופ, יוסף חיים מועשינטא","f":"שלמה","bt":"תרלב","dt":"תשג","b":"רב באינטורוק-פלך וילנא-תרנח, וושינטה(=וישינטה)-פלך קובנא וראש ישיבה שם-תרעא, ברעזא קרטוזי."},{"i":22265,"n":"טרופ, ישראל מסויסלאץ","dt":"תרסה","dp":"סוויסלאץ","b":"חתם תורני ומהנדס. פרסם מאמרים ב\"השרון\", \"הכרמל\", ותחת השם - יבי\"ט ב\"הכרם\"."},{"i":22266,"n":"טרופ, משה מגרודנא","b":"מרביץ תורה בגרודנה-תר\"מ"},{"i":22267,"n":"טרופ, נפתלי צבי מראדין","f":"משה מגרודנא","bt":"תרלא","bp":"גרודנא","dt":"תרפט - ג תשרי","dp":"ראדין","b":"תלמיד ישיבות טלז, וסלובודקה, קעלם, סלונים, קלויז אפאטוב בוילנא, התקרב לתנועת המוסר. חתן ר אליעזר יעקב חבס(=חוואס) מיאנישוק. ר\"מ בישיבת \"אורח חיים\" בסלובודקה-תרס מיסודו של ר הרשל לעויטן, ראש ישיבת ראדין-תרסד. גלה עם הישיבה בזמן מלחה\"ע ה-I לרוסיה הלבנה, חזרו לראדין-תרפא. פרסם מאמרים ב\"אהל תורה\" - ברנוביץ תרפד. בניו: ר אברהם מניו יורק, ר ראובן מתל אביב, חתנו - ר יוסף קמינצקי מנאוידווהר הי\"ד, ר איזיק בורלנד-ר\"מ בישיבת החפץ חיים - נספה עם אשתו בסיביר."},{"i":22268,"n":"טרופ, ראובן מליטא ותל אביב","f":"נפתלי צבי מראדין","bt":"תרסד","bp":"יאנישוק-ליטא","dt":"תשיא-ג","dp":"תל אביב","b":"תלמידי ישיבת ראדין, עלה לארץ ולמד בישיבת חברון. ר\"מ בישיבת \"תפארת צבי\". ממיסדי וראש ישיבת הישוב החדש בתל אביב. פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא, \"שערי אמונה\" - ירושלים תרצה."},{"i":22269,"n":"טרופר, משה מנדבורנה","b":"מחכמי נדבורנה - תשובה אליו \"מחנה יהודה\"."},{"i":22270,"n":"טרופר, פיביש מבורשטין","b":"רב בבורשטין-תרכא."},{"i":22271,"n":"טרוצר, אברהם ליב משאק-סעליץ","f":"שמואל","bt":"תרטו","dt":"תרצא - יח סיון","b":"חתן נכדת ר גוטליב פישר משטוהלויסנבורג, גיסו של ר מאיר רייכהרד מקאטה. בצעצע, נעדעד, שוקסלץ(=שאק-סעליץ). פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":22272,"n":"טרושטי, שאול","b":"נזכר בספר החזיונות לר חיים ויטאל."},{"i":22273,"n":"טרושקין, יעקב","b":"מרביץ תורה בלודז-תר\"ע"},{"i":22274,"n":"טרושקין, יעקב חיים משקוד","f":"ברוך","bt":"תרמג","bp":"פאהוסט","dt":"תשא - אב","b":"חתן ר יחיאל מיכל הובשה משקוד, רבה האחרון של שקוד על מקום חותנו. נספה בשואה."},{"i":22275,"n":"טרטוזי, שם טוב מספרד","f":"יצחק הרופא","b":"פילוסוף ורופא מחכמי ספרד-נ', תלמיד ר יצחק הרופא בן ר משולם ממארסילייא. העתיק ספר הנפש לר שלמה ן גבירול. חיבר ספרי רפואה. בספרו מספר כי מחמת טרדותו ברפואה שכח הלכה אחת, ואז השביעו חכם אחד שיחזור ללמודי התורה. יתכן שהוא המחבר \"פרדס רמונים\" המיוחס לר שם טוב ן שפרוט."},{"i":22276,"n":"טרטי, מאיר שלמה מפודהייץ","b":"מחכמי פודהייץ-תרע."},{"i":22277,"n":"טרטין, יחיאל מיכל ממנוסטרישטש","b":"מחכמי מנוסטרישטש-תרכו."},{"i":22278,"n":"טרטיס, אלכסנדר מלונדון","k":"בעל דם ברית","b":"מוהל בלונדון."},{"i":22279,"n":"טרטנר, יחזקאל מקרילוב","k":"בעל דברי יחזקאל","b":"רב בקרילוב-תר\"ע"},{"i":22280,"n":"טרטצקי, אברהם מראדון","b":"פרסם מאמרים ב\"חדרי תורה\" - קראקא תרפו."},{"i":22281,"n":"טרטקובר, יצחק","f":"יוסף מסטרעליסק"},{"i":22282,"n":"טריאסט, גבריאל מאיטליה","bt":"תקמד","bp":"פאדובה","dt":"1880","b":"גביר בפדובה-איטליה, תרם הרבה לצדקה."},{"i":22283,"n":"טריאקה, ידידיה","b":"רב ברודוס-תקי\"ד"},{"i":22284,"n":"טריבוך, יחיאל מיכל מקמניץ וירו","k":"בעל מאירת עינים","b":"ר\"מ בקמניץ-תרס\"ה,רב בנאראווילא-תרע\"ו,עלה לא\"י תרצ\"ד"},{"i":22285,"n":"טריבוש יוסף אליהו בן הלל","bt":"1856","dt":"ה'תש 1940","bk":[["מקרא מפרש",""]]},{"i":22286,"n":"טריבר, דוד מטורקא","k":"בעל הדרת פנים","bt":"תקן","dt":"תקצא","b":"רב בטורקא. חיבר \"הדרת פנים\" - בכתב יד."},{"i":22287,"n":"טריבר, מנחם אפרים מטורקא","f":"דוד","k":"בעל מפתח בית דוד","bt":"תקפה","bp":"טורקא","dt":"תרס - ו שבט","b":"תלמיד ר מאיר מפרימישלן וחתנו ר חיים אברהם ממיקולייב. מגיד מישרים בטורקא-תרכג, סמבור - וכיהן שם כאדמור. על קברו נבנה \"אהל\". חיבר גם \"שמן המאור\"."},{"i":22288,"n":"טריווקס, משה חיים מראדין","b":"רב בראדין-תרמ, מזריטש. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז, \"המאסף\" - ירושלים תרנו, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":22289,"n":"טריטש, וולף","b":"רב בטריטש-תק\"ס"},{"i":22290,"n":"טריטש, יעקב בער מניקלשבורג","dt":"תקפה","b":"רב בפיסלינג,דיין בניקלסבורג"},{"i":22291,"n":"טריטש, יעקב ישי מפרשבורג","dt":"תרם - ה אלול","dp":"פרשבורג","b":"תלמיד החת\"ס."},{"i":22292,"n":"טריטש, משה מפרשבורג","dt":"תקצא - ט תמוז","b":"תלמיד ר יחזקאל לנדא בעל ה\"נודע ביהודה\". מרביץ תורה, דיין בפרשבורג בזמן החת\"ס. חתם על כתב מנוי רבנות לחת\"ס-תקסז. הניח חדושים בכת\"י על גליונות הש\"ס שלו."},{"i":22293,"n":"טרייאקה, יהודה","b":"רב ברודוס-תקי\"א"},{"i":22294,"n":"טרייזין, הלל מסטרדוב","k":"בעל דברי הלל","bt":"תקצב","dt":"תרסה","b":"מצאצאי הגר\"א. נתפרסם כעילוי ובהיותו בן 15 התוכח בהלכה עם רא\"צ איזנשטט בעל \"פתחי תשובה\". רב בסטרדוב בהמלצת האדמור ה\"צמח צדק\" כ-50 שנה ונעזר בגביר ר מרדכי אבאלניק."},{"i":22295,"n":"טרייטל, יהושע הלוי מסוכטשוב","f":"יחיאל","k":"בעל הברכי יהושע","b":"מו\"צ בסוכטשוב. חיבר גם \"חדות יהושע\" -וארשא תרנד. בנו - ר מאיר דב מסקערניויטש הו\"ל את ספרו."},{"i":22296,"n":"טרייסטמן, אליעזר יהודה","b":"רב בראדום,לודז-תרע\"ג"},{"i":22297,"n":"טרייסטמן, שמחה","f":"אליעזריהודה טרייסטמן","bt":"תרנג","dt":"תשג","b":"רב בועד הרבנים בלודז"},{"i":22298,"n":"טרייקו, משה מצפת","b":"תלמיד הארי בצפת."},{"i":22299,"n":"טרילינגן, אפרים הנדיל","f":"מנחם","b":"מחכמי קרימונה-איטליה-שמו, תשובות ממנו ב\"נחלת יעקב\" לר יעקב הלפרין."},{"i":22300,"n":"טרילינגן, שלמה ואשיר","b":"אין פרטים."},{"i":22301,"n":"טרילינגר, אליעזר","f":"יוסף יוזפא","k":"בעל משנת רבי אליעזר","dt":"תמ","dp":"וילנא","b":"רב בקוסטל מורביה, נפטר בדרכו לא\"י."},{"i":22302,"n":"טרילינגר, יוסף יוזפא","f":"אליעזר","b":"מגדולי חכמי אשכנז-תס\"ד. רב בלייפניק תס\"ה"},{"i":22303,"n":"טרינקי, משה מירושלים וצפת","k":"הו\"ל ספר הכוונות","dp":"ירושלים","b":"מחכמי יוון, עלה לצפת-שלב והיה מתלמידי האר\"י, עבר לירושלים, סבל בפרעות אבן פארוך בשנת שפה יחד עם השל\"ה. היה בשליחות בקושטא ודמשק, הוציא לאור \"כוונות האריזל\" ונציה שפד, והחיד\"א ביקר את ספרו ואמר כי הוסיף דברים מדעתו."},{"i":22304,"n":"טריסטמן, אליעזר","b":"רב בלודז-תרע\"ד"},{"i":22305,"n":"טריסטמן, ברוך מרדכי מגור","f":"דוד","k":"בעל ברכת מרדכי","b":"נכד ר מרדכי הכהן מיאנוב (מצאצאי הפרי מגדים)."},{"i":22306,"n":"טריסטר, צבי הירש","f":"יעקב יוסף","b":"רב בזבלטוב, הוסיאטין."},{"i":22307,"n":"טריפקאל, משה מירושלים","k":"טרינקי","b":"מחכמי ירושלים, בשנת שפג חתם על התקנה נגד פירוד, מוזכר ב\"חרבות ירושלים\" בשם טרינקי."},{"i":22308,"n":"טריר, אברהם מפפד\"מ","f":"שמעון","dt":"תקנד - ו ניסן","dp":"פפד\"מ","b":"רב ודיין בפפד\"מ."},{"i":22309,"n":"טריר, זאב וולף","b":"רב במדינת הסן-ת\"מ"},{"i":22310,"n":"טריר, משה מפפד\"מ","b":"מראשי קהילת פפד\"מ-תפ בערך."},{"i":22311,"n":"טריר, שלמה זלמן מפפד\"מ","f":"אברהם","k":"בעל רבנישע גוטאכן","bt":"תקיח","bp":"פפד\"מ","dt":"תרז - יד חשון","dp":"פפד\"מ?","b":"רב ודיין בפפד\"מ-תקנה ור\"מ בישיבה. חיבר מאמרים נגד תנועת הריפורמה, חיבר קונטרס בענין המילה כנגד דעת הריפורמים בשם \"רבנישע גוטאכן איבר די בשאניידונג\". סייעו בידו תלמידו חברו ר בער אדלר, ותלמידו הגר\"א פולד וביחד קבצו מכתבים ותשובות מגדולי אשכנז כנגד הריפורמים. היה מחברי ה\"סנהדרין\" בפריז, עם חברו ר יצחק הילדסהיים. אחר פטירתו גברה יד הריפורמים עד שר שמשון רפאל הירש פרש עם בני עדתו מהקהלה הכללית."},{"i":22312,"n":"טרכטמן, בנימין מארה\"ב","k":"בעל שבט בנימין","b":"רב במישוואקי-אינדיאנה. חיבר \"שבט בנימין\"-תרץ."},{"i":22313,"n":"טרכטנברג, מנחם מנדל מוילנא","f":"דוד","bt":"1799","dt":"1890","b":"למד רפואה בוילנא, והיה הרופא היהודי היחיד בוילנא והיה גם הרופא הראשי בבית החולים היהודי. בעל תואר אצולה מהשלטונות."},{"i":22314,"n":"טרכטנברג, שבתי מירושלים","f":"יוסף","dt":"תרפז - כו אד\"ב","dp":"ירושלים","b":"חתן ר שמואל מרדכי ורשבסקי. עסקן צבור בירושלים."},{"i":22315,"n":"טרלובסקי, יהושע טוביה מאנגליה","k":"בעל טוב טעם","dp":"גרודנא","b":"רב בנוטינגהם."},{"i":22316,"n":"טרלר, מרדכי כץ הכהן מקראקא","bt":"תרד","dt":"תרעו","b":"רב וחזן בקראקא. הוציא לאור \"מודעא ואונס\" מר חיים שבתי - ובסופו חדושים ממנו - פודגורזע תרנח."},{"i":22317,"n":"טרנא, אברהם דב מיאסוין","dt":"תשא","b":"תלמיד ישיבת סלובודקה. רבה האחרון של ייאסווין-ליטא. נספה בשואה."},{"i":22318,"n":"טרנטשינר, אליעזר מנייטרא","b":"דומ\"צ בנייטרא,טשוס-תקצ\"ב"},{"i":22319,"n":"טרנטשינר, פיבל מטיסא-איגאר","dt":"תרכט - ה תמוז","b":"רב בטיסא-איגאר,העוועש-תקפ\"א"},{"i":22320,"n":"טרנטשינר-קורדוירו, א' מזאמושט","k":"בעל פני אריה זוטא","b":"רב בזאמוטש-ת\"פ"},{"i":22321,"n":"טרני ישעיה בן מלי הזקן די","bt":"1180","dt":"ה'י 1250","bk":[["המכריע",""],["ספר המכריע",""],["פירוש ופסקי רי\"ד",""],["תוספות רי\"ד",""],["תוספות ריד",""]]},{"i":22322,"n":"טרני משה בן יוסף הזקן די","bt":"1500","dt":"ה'שמ 1580","bk":[["אגרת דרך ה’",""],["בית אלהים",""],["נחמד",""],["קרית ספר",""],["שאלות ותשובות מהרב משה מטראני",""]]},{"i":22323,"n":"טרני מתתיה נסים","bt":"1745","dt":"ה'תקע 1810","bk":[["מדבר מתנה",""],["מדבר קנאה",""],["שפת אמת",""]]},{"i":22324,"n":"טרני, אברהם מאדרינופול","f":"רחמים מנחם מטראני","b":"רב באדרינופולי-תרל. הדפיס ספר אביו - \"מעם לועז\"."},{"i":22325,"n":"טרני, אברהם נסים משלוניקי","dt":"רעב - כח תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי"},{"i":22326,"n":"טרני, אהרן","b":"רב באדריאנופול"},{"i":22327,"n":"טרני, אהרן מספרד ואדרינופול","k":"בעל התוספות","b":"מצאצאי ר ישעיה מטרני בעל תוס' רי\"ד. מחכמי ספרד, לאחר הגלות התישב בטראנה-מדינת איטליה, רב באדרינופול-רסב, עלה לארץ. תלמיד חבר לר יוסף פאסי. אחיו של ר יוסף-אבי המבי\"ט. כונה בשם ר אהרן בעל התוספות. מתלמידיו - אחיינו המבי\"ט. נזכר ב\"אבקת רוכל\" על מחלוקת שהיתה לו בענין רבנות קהילה באדרינופול עם ר ישראל בן הרא\"ם. היה במחלוקת עם ר יוסף קארו בענין רבנות ר יום טוב הכהן באדרינופול שבעקבותיה עבר לקושטא ומשם עלה לארץ-רצב, (גם ר יוסף קארו עזב לניקופול בעקבות המחלוקת)."},{"i":22328,"n":"טרני, ברוך מאדרינופול","b":"מחכמי אדרינופול-שנות ה-תק'."},{"i":22329,"n":"טרני, ברוך מקירקליסה - הזקן","f":"יצחק","bt":"תקג","bp":"קירקליסה","dp":"ירושלים","b":"מראשי קהלת קירקליסה-מדינת אורמילי-תורכיה. עלה לירושלים בסוף ימיו."},{"i":22330,"n":"טרני, ברוך-בני\"ם - הנכד","f":"יצחק","k":"בעל שמעו בני\"ם","bt":"תרז","bp":"קירקליסה","dt":"תרעט - כג אב","dp":"אדרינופול","b":"נכד(-אבי אמו) ר רחמים יצחק אברהם פוליקאר. חתן ר שלמה ראזון מאדרינופול. מלומד וחוקר, פעל להנחלת השפה העברית. פרסם מאמרים וספרים."},{"i":22331,"n":"טרני, דניאל מאנקונה","k":"בעל עיקרי הד\"ט","bt":"תק","bp":"אנקונה","dt":"תקעד","b":"מגדולי חכמי איטליה, התייתם בילדותו, וגדל אצל זקנו-ר דניאל נחמו, דרשן באנקונה-תקכא, רב ומו\"צ, מלמד בלוגו, רב ואב\"ד פיסארו, אב\"ד ור\"מ פירינצי-תקם, חיבר \"שם עולם\" על התורה, \"מתנת יד\", ועוד."},{"i":22332,"n":"טרני, חיים מקירקליסה","bp":"אדרינופול","b":"מחכמי אדרינופול, רב בקירקליסה-תקלב."},{"i":22333,"n":"טרני, חיים מקנישזא","b":"רב בקנישזא-תק. התכתב עם קרובו ר שלמה בכמוהר\"ר מרדכי מאדרינופול. קרובו גם - ר ברוך טרני מאדרינופול."},{"i":22334,"n":"טרני, יהודה מפיליפופולי","f":"נסים","b":"גביר מחכמי פיליפופולי."},{"i":22335,"n":"טרני, יום טוב מאלכסנדריה","f":"שלמה","b":"רב באלכסנדריה-שנות ה-ש'."},{"i":22336,"n":"טרני, יוסף הזקן","k":"בעל שו\"ת וחדושים","b":"מגדולי הפוסקים בדורו, מגדולי ספרד-רנב, מרביץ תורה באדרינופולי. אביו של ר משה-המבי\"ט."},{"i":22337,"n":"טרני, יוסף מצפת - מהרימ\"ט","f":"משה","k":"בעל צפנת פענח","bt":"שכט (באוצר שכח)","bp":"צפת","dt":"שצט - יד תמוז","dp":"קושטא","b":"חתן ר אברהם די בוטון בעל \"לחם משנה\". מחכמי צפת, התייתם בגיל צעיר וגדל אצל ר שלמה סאגיס שהיה רבו הראשון. בשנת שס בשליחות צפת לאחר מכת ארבה, כשהגיע לקושטא ייסדו עבורו ישיבה שם והוא עמד בראשה., ולאחר זמן התמנה לראש הרבנים בתורכיה ור יום טוב ן' יעיש על מקומו אחריו. אחיו - ר שלמה ממצרים. בניו היו ר משה ור ישעיה. חיבר שו\"ת קושטא תא, \"צפנת פענח\" ונציה תח, ועוד בכתב יד ובדפוס, חלקם אבדו."},{"i":22338,"n":"טרני, יוסף מקושטא","f":"ישעיה","b":"דיין ור\"מ בקושטא-שנות ה-ת'. מתלמידיו ר יהודה רוזניס בעל \"משנה למלך\"."},{"i":22339,"n":"טרני, יצחק","f":"ברוך","dt":"תרלח","dp":"פזרדז'יק-בולגריה","b":"תלמיד וחתן ר רחמים יצחק אברהם פוליקאר מאדרינופול. שו\"ב בפיליפופולי, דרשן בכמה קהלות בבלקן. חיבר דרושים על התורה."},{"i":22340,"n":"טרני, ישעיה הזקן מאיטליה","f":"מאלי","k":"בעל תוספות רי\"ד","b":"רב בטרני-איטליה, עלה לארץ בקבוצה של 300 רבנים מצרפת ואשכנז-ד'תתק\"ל. חיבר \"המכריע\", \"נימוקים\". בנו - ר דוד."},{"i":22341,"n":"טרני, ישעיה מאיטליה - הנכד","f":"אליהו","k":"הריא\"ז","b":"כד(-בן בתו) ר ישעיה בן מאלי הזקן. רב באיטליה. זקנו של המבי\"ט. רב בטרני-שנת פ'. חיבר \"פסקי הלכות\", פירוש לתנ\"ך, פיוטים."},{"i":22342,"n":"טרני, ישעיה מקושטא","f":"מהרימ\"ט","b":"מחכמי קושטא-שנות ה-ת'. לאחר פטירת אביו תמך בו ר יום טוב ן יעש."},{"i":22343,"n":"טרני, מיכאל מפדובה","k":"בעל יסוד עולם","b":"תלמיד הרמח\"ל. דיין אצל ר יעקב חזק בפדובה-[תקם]. חיבר \"יסוד עולם\", ועוד חבורים בכת\"י."},{"i":22344,"n":"טרני, משה מצפת","f":"שלמה מטראני","bp":"צפת","b":"מרבני צפת, ירד עם אביו למצרים."},{"i":22345,"n":"טרני, משה מקושטא","f":"מהרימ\"ט","b":"מחכמי קושטא-שנות ה-ת. נפטר צעיר."},{"i":22346,"n":"טרני, משה-המבי\"ט","f":"יוסף","k":"בעל שו\"ת המבי\"ט","bt":"רס - רסה","bp":"שלוניקי","dt":"שמ - כב ניסן","dp":"צפת","b":"בן למשפחה ממגורשי ספרד שהתייחסו לר ישעיה טרני, בשנת רנז הגיע אביו לשלוניקי ושם נולד בנו משה, תלמיד דודו ר אהרן מטרני באדריאנופול, ר יוסף פאסי, עלה לצפת בגיל 18 ולמד אצל ר יעקב בירב ונסמך על ידו יחד עם ר יוסף קארו. ישב בבית הדין בצפת 54 שנה, השיב תשובות לאלפים לכל תפוצות הגולה, לאחר פטירת ר יוסף קארו היה גם ראב\"ד, בגלות בדמשק-שכה וחזר לצפת. חיבר \"קרית ספר\" ונציה שמא, ועוד. בניו: ר שלמה ממצרים, ר יוסף."},{"i":22347,"n":"טרני, נסים מאדרינופול","k":"התלמוד החי","b":"דיין באדריאנופול אצל ר נסים אלקלעי-תרכ."},{"i":22348,"n":"טרני, עקיבא ממיץ","f":"אליהו","k":"בעל מעין גנים","b":"רב במיץ. חיבר \"מעין גנים\" מיץ תקכז."},{"i":22349,"n":"טרני, רחמים מנחם מאדרינופול","k":"בעל מעם לועז ליהושע","dt":"תרכז - כא שבט","dp":"ירושלים","b":"מחכמי אדרינופול. עלה לירושלים-תרטו. חיבר \"מעם לועז\" על יהושע שלוניקי תריא."},{"i":22350,"n":"טרני, רפאל מאדריאנופול","b":"רב באדריאנופול. נזכר ב\"דברי יוסף\" לר יוסף סמברי."},{"i":22351,"n":"טרני, שלמה מאדרינופול","f":"יצחק","dt":"תרלא - יג תשרי","dp":"אדרינופול","b":"משכיל ומשורר, אחיו של ר ברוך-בני\"ם. שיר שלו התפרסם ב\"החבצלת\"."},{"i":22352,"n":"טרני, שלמה מאיטליה","b":"מגדולי חכמי איטליה-שנת מ'"},{"i":22353,"n":"טרני, שלמה מצפת ומצרים","f":"משה - המבי\"ט","k":"בעל שם שלמה","bt":"תו","bp":"צפת","dt":"שס","b":"מחכמי צפת, תלמיד אביו ור יוסף קארו, רב במצרים-שס ונזכר ב\"טוב מצרים\", דיין עם ר מאיר גביזון ור יעקב לבנה. חיבר ספרים שנשארו בכתב יד וביניהם \"שם שלמה\" הנזכר בשו\"ת המבי\"ט. החל להדפיס את ספרי אביו ונפטר באמצע - בנו ר משה השלים את ההדפסה. נזכר בספר הדרשות לר שמואל ן סיד."},{"i":22354,"n":"טרני, שמואל מקושטא","dt":"תרט - יב כסלו","dp":"ירושלים","b":"מחכמי קושטא-תר, עלה לירושלים וכיהן כרב."},{"i":22355,"n":"טרני, שמואל משלוניקי וצפת","b":"מחכמי שלוניקי-שנות ה-ר'-ש', עלה לצפת."},{"i":22356,"n":"טרניפולר, מאיר","k":"בעל מאור הקטן","b":"רב באיטינגן-ת\"מ"},{"i":22357,"n":"טרנק, אברהם יהושע השל מנוביטנץ","f":"חיים יצחק","bt":"תרס","bp":"נוביטנץ","dt":"תשלז","b":"עבר בילדותו לארה\"ב ולמד בישיבת ר יעקב יוסף."},{"i":22358,"n":"טרנר, יהודה ליבוש מסניאטין","b":"רב בסניאטין - תשובה אליו טוט\"ד."},{"i":22359,"n":"טרסטינצקי, אברהם מסדילוקב","f":"בנימין זאב וולף הלוי","b":"חתן ר שמואל מקאלניבלאט-חתן ר פנחס מקוריץ."},{"i":22360,"n":"טרסטינצקי, בנימין זאב וולף","f":"שמואל הלוי סגל","k":"רבי ועלויל באלטער","dt":"תקפו - כ כסלו","dp":"צפת","b":"תלמיד ר פנחס מקוריץ, ונזכר בכתבי תלמידי ר פנחס. רב בבאלטה, עלה לארץ. מבניו: ר אברהם מסדילוקב, ר ישראל דוד."},{"i":22361,"n":"טרסטינצקי, יוסף מבילהרדקי","f":"גדליה","bt":"תרכה","b":"מצאצאי ר בנימין הלוי מבאלטא, ר שמרל מוארחיווקא ור אשר צבי מקוריץ בעל מעין החכמה. רב בבילורדקי-ווהלין-תרנו."},{"i":22362,"n":"טרסטינצקי, עזריאל מבאלטה","f":"בנימין זאב מבאלטה","k":"אדמור מפודוליה","dt":"תרח","b":"אדמור בפודוליה. בנו ר פנחס ממנוסטרישץ."},{"i":22363,"n":"טרעני, עקיבא","b":"מגדולי חכמי מיץ-תק\"י"},{"i":22364,"n":"טרעפא, יהודה מהורדנא","f":"בנימין וולף מטרפא","b":"רב בבריסק, הורדנא, הסכים-תכד בועד זאבלודובה על \"עמודיה שבעה\"."},{"i":22365,"n":"טרעפא, יעקב מהורדנא","f":"ישראל שמואל בן יושע","dt":"ניסן","dp":"הורדנא","b":"רב בהורדנא-תו על מקום ר ברוך רפפורט (לאחר שר יהודה ליב בן משלם זלמן היה ממלא מקום זמני). חתם-תו בועד ארבע ארצות בסעלץ."},{"i":22366,"n":"טרעפא, ישראל שמואל מליטא","f":"יושע","k":"זליגמן טרפא","b":"גביר מרוזני ליטא, חתם-שפג, שפו, שצג. בנו - ר יעקב מהורדנא."},{"i":22367,"n":"טרפון, יעקב משלוניקי","b":"משורר מחכמי שלוניקי-שפ."},{"i":22368,"n":"טרפשטין, ישראל אלימלך","dt":"תשג","b":"רב בסטאניסלב"},{"i":22369,"n":"טרפשטין, שמעון יהודה","b":"עורך \"הכרם\" - וארשא תרפז."},{"i":22370,"n":"טרק, אברהם","dt":"תקנא - ז ניסן","b":"רב בשטמפן"},{"i":22371,"n":"טרשא, יעקב מרודוס","dp":"רודוס","b":"תלמיד ר חיים שבתי בשלוניקי. מחכמי שלוניקי, רב ברודוס-שפ על מקום ר משה הכהן שעבר לכיאו."},{"i":22372,"n":"טרשנובר, מאיר מגריבוב","dt":"תרפו","b":"רב בגריבוב. גיסו של ר דוד שליסל ממונקטש."},{"i":22373,"n":"טרשנסקי, משה מקרמנצוג","k":"בעל סוד אמונים","bt":"תריח","dt":"תשב - כב טבת","b":"רב פעלים,רב בקרמנצוג"},{"i":22374,"n":"טשוטשקע, אהרן משה מגאיא","f":"מאיר שלמה","dt":"תרמג - בערך","b":"מצאצאי בעל \"עבודת הגרשוני\". תלמיד הכת\"ס, ומהרם שיק. רב בגאיא-תרכה."},{"i":22375,"n":"טשוטשקע, שלמה זלמן מגאיא","f":"אהרן משה מגאיא","b":"תלמיד השב\"ס. חתן ר שמאל שמלקא לוינזון (לוינטל) מניקלשבורג - מצאצאי ר שמואל שמלקא הורביץ מניקלשבורג. מחכמי גאיא. נפטר צעיר."},{"i":22376,"n":"טשטיאל, משה מספרד ופאס","dt":"שלח - בערך","b":"מחכמי ספרד בזמן הגירוש, ועבר לפאס. חתם-שכח על תקנה עם חכמי פאס."},{"i":22377,"n":"טשך, אשר אליקים","dt":"תרפט","b":"רב באברהם,מעזאקרסטש-תר\"ס"},{"i":22378,"n":"טשכנובר, מאיר משוראמין","f":"משה מסיראצק","bt":"תרג","bp":"סערוצק","b":"חתן הגביר ר שלמה יואל כץ ממאקאווא ועבר לשם, ר אלעזר הכהן מפולוטוסק מינהו למלא את מקומו בעת עוזבו את העיר לפרקים. רב בקורדברג(=קידזבארג-יזילין)-תרכז, זיעלין (האם זו קורדברג או עיר אחרת?), יאנובה-תרלא, זוראמן(=זאראמין, זשוראמין)-פלך פלאצק-תרם. מקורב לציונות. הניח חדושים בכת\"י."},{"i":22379,"n":"טשכנובר, משה מסיראצק","dt":"תרכו - ל שבט","b":"רב בסירצק, ניישטאט."},{"i":22380,"n":"טשכנווצה, דוד","dt":"תקעט - ז אייר","b":"רב בטשכנווצה"},{"i":22381,"n":"טשנגרי, מרדכי משימלויא","f":"אברהם מדברצין","bt":"תרי","dt":"תרפח - כא סיון","dp":"שימלויא","b":"תלמיד הכת\"ס. חתן ר יואל מבאן (מחוז סילאדי), ועבר לשם. עסקן מחכמי שימלויא."},{"i":22382,"n":"טשעך, אשר אליקים ממעזא","f":"מנחם הלוי מבודפשט","bt":"תרכו","bp":"בודפשט","dt":"תרפט - ב תשרי","dp":"בורשוד-מעזא-קרעסטש","b":"תלמיד השב\"ס, ור יהודה גרינולד. חתן ר שמואל גינז מאבראהאם. רב באבראהאם (פעלשא-אבראני)-תרנב על מקום חותנו וחתנו ר מנחם צבי פרידמן על מקומו אחריו. מתורתו בשו\"ת \"נטע שורק\"."},{"i":22383,"n":"טשעך, יצחק איזיק הלוי מבודפשט","f":"מנחם","dt":"תשד - טבת","dp":"בודפשט","b":"תלמיד השב\"ס, רב בבודפשט-תרעג."},{"i":22384,"n":"טשעק, שבתי מניו יורק","k":"בעל יורה מלקוש ומרוה","b":"רב בניו יורק-תרסב."},{"i":22385,"n":"טשפלר, יעקב מנחם מארה\"ב","f":"אברהם אבא","bt":"תרלה","bp":"ראדום","dt":"תשח - יח אב","b":"תלמיד האדמור ר יחיאל מאלכסנדר, ועוד. חתן ר צבי זילברפרב. היגר לארה\"ב-תרסה וכיהן כרב קהלת \"תפארת ישראל\" בפאסייק-ניו ג'רסי. חיבר חדושים - בכת\"י. בניו: ר יחיאל מניו יורק, ר יחזקאל אליהו מליברטי, ר יצחק זאב מפאסייק. חתנו - יוסף רודל - עו\"ד בניו יורק."},{"i":22386,"n":"טשרנוביץ, חיים","k":"רב צעיר","bt":"תרלא","dt":"תשט - טז אייר","b":"נואם,חכם,סופר,רב באודיסה-תרנ\"ח,ארה\"ב תרפ\"ג. חיבר \"תולדות ההלכה\"."},{"i":22387,"n":"טשרנוביץ, יעקב יוסף","f":"חיים צ'רנוביץ","b":"רב-שנת תק\"צ"},{"i":22388,"n":"טשרנובסקי, אברהם מארה\"ב","b":"רב בפליינפילד-ניו ג'רסי, חתם-תרפב על כרוז לתרום ל\"קרן היסוד\"."},{"i":22389,"n":"טשרנוטשפקי, דוד מבזדנוב ויאלוב","bt":"תרי","dt":"תרפו - ה אלול","b":"רב בבזדאנוב-תרל\"ו,יאלוב-תרמ\"ג"},{"i":22390,"n":"טשרנוטשפקי, חנוך הניך מגאלין","f":"דוד טשרנוטשאפקיש","b":"רב בגאלין-תרפ. פרסם מאמרים ב\"אסיפת חכמים\" - מלניץ תרפח, \"הבאר\" - זאמושץ-וארשא תרפד, \"המגיד\" - סטמר תרצט, \"הנשר\" - טירנוי תרצג-תשד, \"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":22391,"n":"טשרנחובסקי, שאול מאודסה","bt":"1876","bp":"כפר מיכאלאווקא","b":"משורר. פרסם ב\"המליץ\", \"הדור\", \"השלוח\", ועוד."},{"i":22392,"n":"טשרניחא, ראובן","dt":"תש..","b":"חתן ר חנוך סעדיה האדמור מזיכלין. נספה בשואה."},{"i":22393,"n":"טשרניחוב, יוסף (דניאלי)","k":"בעל אין רעווטריבונאל","bt":"1882","bp":"סלונים-פלך גרודנא","dt":"1941","b":"פעיל בתנועה הסוציאליסטית, שליח המפלגה לארה\"ב, ממיסדי ה\"התאחדות הדמוקרטית\". הופיע כסניגור במשפטים פוליטיים בזמן המהפכה הבולשביקית. מנהל היא\"ס בליטא. עורך \"נייס\", ועוד. חיבר זכרונותיו בשם \"אין רעווטריבונאל, זכרונות פון א פארטיידיקער\" - וילנא 1932. נאסר ע\"י הרוסים ומת בכלא."}];
